{
  "name": "Flyyti Mobile POS",
  "description": "A comprehensive RTL-supported mobile POS system for retail and services, featuring inventory management, detailed reporting, and secure profit distribution tracking.",
  "requestFramePermissions": [
    "camera"
  ]
}

-- Enable RLS
-- Drop existing tables if they exist to avoid conflicts
DROP TABLE IF EXISTS extra_services;
DROP TABLE IF EXISTS invoice_items;
DROP TABLE IF EXISTS invoices;
DROP TABLE IF EXISTS variants;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS expenses;
DROP TABLE IF EXISTS purchases;
DROP TABLE IF EXISTS settings;

-- 1. Categories
CREATE TABLE categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  parent_id UUID REFERENCES categories(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Products
CREATE TABLE products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
  sub_category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
  supplier TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. Variants
CREATE TABLE variants (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id UUID REFERENCES products(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  barcode TEXT UNIQUE,
  cost_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  sale_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  stock_quantity INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. Invoices
CREATE TABLE invoices (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  total_amount DECIMAL(10,2) NOT NULL DEFAULT 0,
  discount DECIMAL(10,2) NOT NULL DEFAULT 0,
  net_amount DECIMAL(10,2) NOT NULL DEFAULT 0,
  total_cost DECIMAL(10,2) NOT NULL DEFAULT 0,
  profit DECIMAL(10,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. Invoice Items
CREATE TABLE invoice_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID REFERENCES invoices(id) ON DELETE CASCADE,
  variant_id UUID REFERENCES variants(id) ON DELETE SET NULL,
  product_name TEXT NOT NULL,
  variant_name TEXT,
  quantity INTEGER NOT NULL DEFAULT 1,
  cost_price DECIMAL(10,2) NOT NULL,
  sale_price DECIMAL(10,2) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 6. Extra Services
CREATE TABLE extra_services (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID REFERENCES invoices(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  cost_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  sale_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  quantity INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 7. Expenses
CREATE TABLE expenses (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  type TEXT NOT NULL,
  amount DECIMAL(10,2) NOT NULL,
  date DATE DEFAULT CURRENT_DATE,
  note TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 8. Purchases
CREATE TABLE purchases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  amount DECIMAL(10,2) NOT NULL,
  supplier TEXT,
  date DATE DEFAULT CURRENT_DATE,
  note TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 9. Settings
CREATE TABLE settings (
  id INTEGER PRIMARY KEY DEFAULT 1,
  username TEXT NOT NULL DEFAULT 'admin',
  password TEXT NOT NULL DEFAULT 'admin',
  page_password TEXT NOT NULL DEFAULT '1234',
  capital DECIMAL(10,2) NOT NULL DEFAULT 0,
  savings DECIMAL(10,2) NOT NULL DEFAULT 0,
  protection_enabled BOOLEAN DEFAULT TRUE,
  page_locks JSONB DEFAULT '{"inventory": true, "categories": true, "expenses": true, "invoices": true, "reports": true, "security": true}'::JSONB,
  profit_shares JSONB DEFAULT '{"mujahed": 60, "abboud": 20, "shop": 10, "special": 10}'::JSONB
);

-- Insert initial settings
INSERT INTO settings (id, username, password, page_password) 
VALUES (1, 'admin', 'admin', '1234')
ON CONFLICT (id) DO NOTHING;

-- Policies (Assuming simplicity for now, enabling authenticated access)
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
ALTER TABLE variants ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoice_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE extra_services ENABLE ROW LEVEL SECURITY;
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY;
ALTER TABLE purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE settings ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public select" ON settings FOR SELECT USING (true);
CREATE POLICY "Allow public update" ON settings FOR UPDATE USING (true);
-- For production, replace 'true' with proper auth checks: auth.role() = 'authenticated'
CREATE POLICY "Full access" ON categories FOR ALL USING (true);
CREATE POLICY "Full access" ON products FOR ALL USING (true);
CREATE POLICY "Full access" ON variants FOR ALL USING (true);
CREATE POLICY "Full access" ON invoices FOR ALL USING (true);
CREATE POLICY "Full access" ON invoice_items FOR ALL USING (true);
CREATE POLICY "Full access" ON extra_services FOR ALL USING (true);
CREATE POLICY "Full access" ON expenses FOR ALL USING (true);
CREATE POLICY "Full access" ON purchases FOR ALL USING (true);

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Category {
  id: string;
  name: string;
  parent_id: string | null;
  created_at: string;
}

export interface Product {
  id: string;
  name: string;
  category_id: string | null;
  sub_category_id: string | null;
  supplier: string | null;
  created_at: string;
  variants?: Variant[];
}

export interface Variant {
  id: string;
  product_id: string;
  name: string;
  barcode: string | null;
  cost_price: number;
  sale_price: number;
  stock_quantity: number;
  created_at: string;
}

export interface Invoice {
  id: string;
  total_amount: number;
  discount: number;
  net_amount: number;
  total_cost: number;
  profit: number;
  created_at: string;
  items?: InvoiceItem[];
  services?: ExtraService[];
}

export interface InvoiceItem {
  id: string;
  invoice_id: string;
  variant_id: string | null;
  product_name: string;
  variant_name: string | null;
  quantity: number;
  cost_price: number;
  sale_price: number;
}

export interface ExtraService {
  id?: string;
  invoice_id?: string;
  name: string;
  cost_price: number;
  sale_price: number;
  quantity: number;
}

export interface Expense {
  id: string;
  type: string;
  amount: number;
  date: string;
  note: string | null;
}

export interface Purchase {
  id: string;
  amount: number;
  supplier: string | null;
  date: string;
  note: string | null;
}

export interface AppSettings {
  id: number;
  username: string;
  password?: string;
  page_password?: string;
  capital: number;
  savings: number;
  protection_enabled: boolean;
  page_locks: Record<string, boolean>;
  profit_shares: {
    mujahed: number;
    abboud: number;
    shop: number;
    special: number;
  };
}

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || '';
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY || '';

if (!supabaseUrl || !supabaseAnonKey) {
  console.warn("Supabase environment variables are missing. Please check your .env or Vercel settings.");
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route, Navigate, Link, useLocation, useNavigate } from 'react-router-dom';
import { 
  LayoutDashboard, 
  ShoppingCart, 
  Package, 
  Tags, 
  Wallet, 
  FileText, 
  PieChart, 
  Lock, 
  Menu, 
  X, 
  LogOut,
  ChevronRight,
  ShieldCheck
} from 'lucide-react';
import { supabase } from './supabase';
import type { AppSettings } from './types';

// Pages
import POS from './pages/POS';
import DailyReports from './pages/DailyReports';
import Inventory from './pages/Inventory';
import Categories from './pages/Categories';
import Expenses from './pages/Expenses';
import Invoices from './pages/Invoices';
import GeneralReports from './pages/GeneralReports';
import Security from './pages/Security';
import Login from './pages/Login';

const SidebarItem: React.FC<{ 
  to: string, 
  icon: React.ReactNode, 
  label: string, 
  onClick?: () => void 
}> = ({ to, icon, label, onClick }) => {
  const location = useLocation();
  const isActive = location.pathname === to;

  return (
    <Link
      to={to}
      onClick={onClick}
      className={`flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${
        isActive 
          ? 'bg-blue-600 text-white' 
          : 'text-gray-600 hover:bg-gray-100'
      }`}
    >
      {icon}
      <span className="font-medium">{label}</span>
    </Link>
  );
};

const PageLockModal: React.FC<{ 
  onSuccess: () => void;
  onCancel: () => void;
  correctPass: string;
}> = ({ onSuccess, onCancel, correctPass }) => {
  const [pass, setPass] = useState('');
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (pass === correctPass) {
      onSuccess();
    } else {
      setError(true);
      setPass('');
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[9999] p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm p-6" dir="rtl">
        <div className="flex flex-col items-center text-center mb-6">
          <div className="bg-amber-100 p-3 rounded-full mb-4">
            <Lock className="w-8 h-8 text-amber-600" />
          </div>
          <h3 className="text-xl font-bold text-gray-900">صفحة محمية</h3>
          <p className="text-gray-500 mt-1">يرجى إدخال كلمة مرور الصفحات للمتابعة</p>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <input
            autoFocus
            type="password"
            value={pass}
            onChange={(e) => {
              setPass(e.target.value);
              setError(false);
            }}
            className={`w-full px-4 py-3 rounded-xl border-2 text-center text-2xl tracking-widest focus:ring-4 focus:ring-blue-100 transition-all ${
              error ? 'border-red-500 bg-red-50' : 'border-gray-200 focus:border-blue-500'
            }`}
            placeholder="••••"
          />
          {error && <p className="text-red-500 text-sm text-center">كلمة المرور غير صحيحة</p>}
          <div className="grid grid-cols-2 gap-3">
            <button
              type="button"
              onClick={onCancel}
              className="px-4 py-3 bg-gray-100 text-gray-700 rounded-xl font-bold hover:bg-gray-200 transition-colors"
            >
              إلغاء
            </button>
            <button
              type="submit"
              className="px-4 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
            >
              دخول
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

const Layout: React.FC<{ children: React.ReactNode, settings: AppSettings | null, refreshSettings: () => void }> = ({ children, settings, refreshSettings }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showLock, setShowLock] = useState(false);
  const [pendingRoute, setPendingRoute] = useState<string | null>(null);
  const navigate = useNavigate();
  const location = useLocation();

  const handleLogout = () => {
    localStorage.removeItem('flyyti_user');
    window.location.reload();
  };

  const checkLock = (to: string) => {
    const pageId = to.replace('/', '') || 'pos';
    const unprotectedPages = ['pos', 'daily-reports'];

    if (settings?.protection_enabled && !unprotectedPages.includes(pageId) && settings.page_locks?.[pageId]) {
      setPendingRoute(to);
      setShowLock(true);
      return false;
    }
    navigate(to);
    return true;
  };

  return (
    <div className="min-h-screen flex bg-gray-50 overflow-hidden">
      {showLock && (
        <PageLockModal 
          correctPass={settings?.page_password || '1234'}
          onCancel={() => {
            setShowLock(false);
            setPendingRoute(null);
          }}
          onSuccess={() => {
            if (pendingRoute) navigate(pendingRoute);
            setShowLock(false);
            setPendingRoute(null);
          }}
        />
      )}

      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/20 z-40 lg:hidden backdrop-blur-sm"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside className={`
        fixed inset-y-0 right-0 z-50 w-72 bg-white border-l border-gray-100 transition-transform lg:relative lg:translate-x-0
        ${sidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full lg:translate-x-0'}
      `}>
        <div className="flex flex-col h-full">
          <div className="p-6 flex items-center justify-between border-b border-gray-50">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-blue-200">
                F
              </div>
              <div>
                <h1 className="text-xl font-extrabold text-gray-900 tracking-tight">Flyyti</h1>
                <p className="text-xs text-blue-600 font-bold uppercase tracking-wider">Mobile POS</p>
              </div>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-gray-400">
              <X size={24} />
            </button>
          </div>

          <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
            <button className="w-full text-right" onClick={() => { setSidebarOpen(false); checkLock('/'); }}>
              <SidebarItem to="/" label="نقطة بيع" icon={<ShoppingCart size={20} />} />
            </button>
            <button className="w-full text-right" onClick={() => { setSidebarOpen(false); checkLock('/daily-reports'); }}>
              <SidebarItem to="/daily-reports" label="تقارير يومية" icon={<LayoutDashboard size={20} />} />
            </button>
            <button className="w-full text-right" onClick={() => { setSidebarOpen(false); checkLock('/inventory'); }}>
              <SidebarItem to="/inventory" label="المخزون" icon={<Package size={20} />} />
            </button>
            <button className="w-full text-right" onClick={() => { setSidebarOpen(false); checkLock('/categories'); }}>
              <SidebarItem to="/categories" label="الأقسام" icon={<Tags size={20} />} />
            </button>
            <button className="w-full text-right" onClick={() => { setSidebarOpen(false); checkLock('/expenses'); }}>
              <SidebarItem to="/expenses" label="المصاريف والمشتريات" icon={<Wallet size={20} />} />
            </button>
            <button className="w-full text-right" onClick={() => { setSidebarOpen(false); checkLock('/invoices'); }}>
              <SidebarItem to="/invoices" label="الفواتير" icon={<FileText size={20} />} />
            </button>
            <button className="w-full text-right" onClick={() => { setSidebarOpen(false); checkLock('/reports'); }}>
              <SidebarItem to="/reports" label="التقارير" icon={<PieChart size={20} />} />
            </button>
            <button className="w-full text-right" onClick={() => { setSidebarOpen(false); checkLock('/security'); }}>
              <SidebarItem to="/security" label="إعدادات الأمان" icon={<ShieldCheck size={20} />} />
            </button>
          </nav>

          <div className="p-4 border-t border-gray-50">
            <button 
              onClick={handleLogout}
              className="flex items-center gap-3 w-full px-4 py-3 text-red-600 hover:bg-red-50 rounded-lg transition-colors font-medium"
            >
              <LogOut size={20} />
              <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 bg-white border-b border-gray-100 flex items-center justify-between px-6 lg:px-8 shrink-0 no-print">
          <button onClick={() => setSidebarOpen(true)} className="lg:hidden text-gray-500">
            <Menu size={24} />
          </button>
          <div className="hidden lg:block">
            <h2 className="text-sm font-medium text-gray-500 flex items-center gap-2">
              Flyyti POS <ChevronRight size={14} /> 
              <span className="text-gray-900 font-bold uppercase">
                {location.pathname === '/' ? 'نقطة بيع' : 
                 location.pathname === '/daily-reports' ? 'تقارير يومية' :
                 location.pathname === '/inventory' ? 'المخزون' :
                 location.pathname === '/categories' ? 'الأقسام' :
                 location.pathname === '/expenses' ? 'المصاريف والمشتريات' :
                 location.pathname === '/invoices' ? 'الفواتير' :
                 location.pathname === '/reports' ? 'التقارير' : 'إعدادات الأمان'}
              </span>
            </h2>
          </div>
          <div className="flex items-center gap-4">
            <div className="text-left">
              <p className="text-xs font-bold text-gray-400 uppercase tracking-widest text-right">المستخدم الحالي</p>
              <p className="text-sm font-bold text-blue-600">{settings?.username || 'أدمن'}</p>
            </div>
            <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center border border-gray-200">
              <ShieldCheck size={20} className="text-gray-400" />
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          {children}
        </div>
      </main>
    </div>
  );
};

const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  const loggedUser = localStorage.getItem('flyyti_user');
  if (!loggedUser) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchSettings = useCallback(async () => {
    const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
    if (!error) {
      setSettings(data);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    fetchSettings();
  }, [fetchSettings]);

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 gap-4">
        <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-gray-500 font-bold animate-pulse">جاري التحميل...</p>
      </div>
    );
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
        <Route path="/*" element={
          <ProtectedRoute settings={settings}>
            <Layout settings={settings} refreshSettings={fetchSettings}>
              <Routes>
                <Route path="/" element={<POS />} />
                <Route path="/daily-reports" element={<DailyReports />} />
                <Route path="/inventory" element={<Inventory />} />
                <Route path="/categories" element={<Categories />} />
                <Route path="/expenses" element={<Expenses />} />
                <Route path="/invoices" element={<Invoices settings={settings} onUpdateSettings={fetchSettings} />} />
                <Route path="/reports" element={<GeneralReports />} />
                <Route path="/security" element={<Security settings={settings} onUpdate={fetchSettings} />} />
              </Routes>
            </Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ShieldCheck, User, Lock, ArrowLeft } from 'lucide-react';
import { supabase } from '../supabase';

const Login: React.FC<{ onLoginSuccess: () => void }> = ({ onLoginSuccess }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    const { data, error: fetchError } = await supabase
      .from('settings')
      .select('username, password')
      .eq('id', 1)
      .single();

    if (fetchError) {
      setError('حدث خطأ في الاتصال بقاعدة البيانات');
      setLoading(false);
      return;
    }

    if (data.username === username && data.password === password) {
      localStorage.setItem('flyyti_user', username);
      onLoginSuccess();
      navigate('/');
    } else {
      setError('اسم المستخدم أو كلمة المرور غير صحيحة');
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-700 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden" dir="rtl">
        <div className="p-8 text-center bg-gray-50 border-b border-gray-100">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-blue-600 rounded-2xl shadow-xl shadow-blue-200 text-white mb-6">
            <ShieldCheck size={40} />
          </div>
          <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Flyyti Mobile POS</h1>
          <p className="text-gray-500 mt-2 font-medium">نظام إدارة المبيعات والمخزون الاحترافي</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleLogin} className="space-y-6">
            {error && (
              <div className="p-4 bg-red-50 border-r-4 border-red-500 text-red-700 text-sm font-bold animate-shake">
                {error}
              </div>
            )}

            <div className="space-y-2">
              <label className="text-sm font-bold text-gray-700 mr-1">اسم المستخدم</label>
              <div className="relative">
                <input
                  type="text"
                  required
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full pl-4 pr-12 py-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 focus:ring-4 focus:ring-blue-50 transition-all outline-none"
                  placeholder="أدخل اسم المستخدم"
                />
                <User className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-bold text-gray-700 mr-1">كلمة المرور</label>
              <div className="relative">
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-4 pr-12 py-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 focus:ring-4 focus:ring-blue-50 transition-all outline-none"
                  placeholder="••••••••"
                />
                <Lock className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-4 bg-blue-600 text-white font-bold rounded-2xl shadow-lg shadow-blue-200 hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center gap-2"
            >
              {loading ? (
                <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <>
                  <span>تسجيل الدخول</span>
                  <ArrowLeft size={20} />
                </>
              )}
            </button>
          </form>

          <div className="mt-8 text-center">
            <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">
              نظام محمي &copy; {new Date().getFullYear()} Flyyti POS
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

