import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ArrowUpRight,
  ChevronLeft,
  ChevronRight
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());
  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    soldItems: [] as any[],
    services: [] as any[]
  });
  const [loading, setLoading] = useState(true);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`
        *,
        invoice_items (*),
        extra_services (*)
      `)
      .gte('created_at', start)
      .lte('created_at', end);

    if (invoices) {
      const stats = invoices.reduce((acc, inv) => {
        acc.totalSales += Number(inv.net_amount);
        acc.totalCost += Number(inv.total_cost);
        acc.totalProfit += Number(inv.profit);
        acc.discounts += Number(inv.discount);

        inv.invoice_items.forEach((item: any) => {
          acc.itemsCount += item.quantity;
          acc.soldItems.push(item);
        });

        inv.extra_services.forEach((ser: any) => {
          acc.itemsCount += ser.quantity;
          acc.services.push(ser);
        });

        return acc;
      }, { totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, soldItems: [], services: [] });

      setData(stats);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchDailyData(selectedDay);
  }, [selectedDay]);

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);

  return (
    <div className="space-y-8" dir="rtl">
      {/* Day Selector */}
      <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm overflow-x-auto scrollbar-hide">
        <div className="flex items-center gap-4">
          <Calendar className="text-blue-600" size={24} />
          <div className="flex gap-2">
            {daysInMonth.map(day => (
              <button
                key={day}
                onClick={() => setSelectedDay(day)}
                className={`min-w-[48px] h-12 rounded-xl font-bold transition-all flex flex-col items-center justify-center ${
                  selectedDay === day 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-200 scale-110' 
                  : 'bg-gray-50 text-gray-500 hover:bg-gray-100'
                }`}
              >
                <span className="text-[10px] opacity-70">يوم</span>
                <span className="text-lg leading-none">{day}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-5 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
          <div className="flex justify-between items-start">
            <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl">
              <TrendingUp size={24} />
            </div>
            <span className="text-xs font-black text-green-500">+12%</span>
          </div>
          <div>
            <p className="text-sm font-bold text-gray-400">إجمالي المبيعات</p>
            <p className="text-2xl font-black text-gray-900">{data.totalSales} ₪</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
          <div className="flex justify-between items-start">
            <div className="p-3 bg-red-50 text-red-600 rounded-2xl">
              <DollarSign size={24} />
            </div>
          </div>
          <div>
            <p className="text-sm font-bold text-gray-400">إجمالي التكلفة</p>
            <p className="text-2xl font-black text-gray-900">{data.totalCost} ₪</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4 ring-2 ring-green-500 ring-offset-4">
          <div className="flex justify-between items-start">
            <div className="p-3 bg-green-50 text-green-600 rounded-2xl">
              <ArrowUpRight size={24} />
            </div>
          </div>
          <div>
            <p className="text-sm font-bold text-gray-400">صافي الأرباح</p>
            <p className="text-2xl font-black text-green-600">{data.totalProfit} ₪</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
