import React, { useState, useEffect } from 'react';
import { 
  Plus, 
  Search, 
  Edit3, 
  Trash2, 
  Copy, 
  MoreVertical, 
  Tag, 
  ChevronDown,
  ChevronUp,
  Package,
  Layers,
  Filter
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Product, Variant, Category } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loading, setLoading] = useState(true);

  const [newProduct, setNewProduct] = useState({
    name: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ name: 'افتراضي', barcode: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*');
    setProducts(prods || []);
    setCategories(cats || []);
    setLoading(false);
  };

  const handleAddVariant = () => {
    setNewProduct({
      ...newProduct,
      variants: [...newProduct.variants, { name: '', barcode: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
  };

  const handleSaveProduct = async () => {
    const { data: prod, error: pError } = await supabase
      .from('products')
      .insert({
        name: newProduct.name,
        supplier: newProduct.supplier,
        category_id: newProduct.category_id || null,
        sub_category_id: newProduct.sub_category_id || null
      })
      .select()
      .single();

    if (pError) return alert("خطأ في إضافة المنتج");

    const variantsToInsert = newProduct.variants.map(v => ({
      ...v,
      product_id: prod.id
    }));

    await supabase.from('variants').insert(variantsToInsert);
    setShowAddModal(false);
    setNewProduct({
      name: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ name: 'افتراضي', barcode: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    fetchData();
  };

  const handleDelete = async (id: string) => {
    if (confirm("هل أنت متأكد من الحذف؟")) {
      await supabase.from('products').delete().eq('id', id);
      fetchData();
    }
  };

  const handleBulkDelete = async () => {
    if (confirm(`هل أنت متأكد من حذف ${selectedIds.length} منتجات؟`)) {
      await supabase.from('products').delete().in('id', selectedIds);
      setSelectedIds([]);
      fetchData();
    }
  };

  const handleDuplicate = async (product: any) => {
    const { data: prod } = await supabase
      .from('products')
      .insert({
        name: `${product.name} (نسخة)`,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      })
      .select()
      .single();

    if (prod) {
      const variants = product.variants.map((v: any) => ({
        name: v.name,
        barcode: v.barcode ? `${v.barcode}-copy` : null,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prod.id
      }));
      await supabase.from('variants').insert(variants);
      fetchData();
    }
  };

  const calculateStockValue = (prods: any[]) => {
    return prods.reduce((sum, p) => {
      const vSum = p.variants.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0);
      return sum + vSum;
    }, 0);
  };

  const filtered = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.variants.some((v: any) => v.barcode && v.barcode.includes(searchTerm))
  );

  return (
    <div className="space-y-6" dir="rtl">
      {/* Top Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-900">المخزون</h2>
        <div className="flex gap-3 w-full md:w-auto">
          <button 
            onClick={() => setShowAddModal(true)}
            className="flex-1 md:flex-none px-6 py-3 bg-blue-600 text-white font-bold rounded-xl flex items-center justify-center gap-2 shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
          {selectedIds.length > 0 && (
            <button 
              onClick={handleBulkDelete}
              className="px-6 py-3 bg-red-100 text-red-600 font-bold rounded-xl flex items-center justify-center gap-2 hover:bg-red-200 transition-all"
            >
              <Trash2 size={20} />
              <span>حذف ({selectedIds.length})</span>
            </button>
          )}
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
            <Package size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">إجمالي الأصناف</p>
            <p className="text-xl font-black text-gray-900">{products.length}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-green-50 text-green-600 rounded-2xl">
            <DollarSign size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">قيمة المخزون (بالتكلفة)</p>
            <p className="text-xl font-black text-green-600">{calculateStockValue(products)} ₪</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-purple-50 text-purple-600 rounded-2xl">
            <Layers size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">إجمالي القطع</p>
            <p className="text-xl font-black text-gray-900">
              {products.reduce((s, p) => s + p.variants.reduce((vs: number, v: any) => vs + v.stock_quantity, 0), 0)}
            </p>
          </div>
        </div>
      </div>

      {/* Search & Table */}
      <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:border-blue-500 outline-none font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button className="p-3 bg-gray-50 text-gray-500 rounded-xl hover:bg-gray-100">
            <Filter size={20} />
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="p-4 w-10">
                  <input 
                    type="checkbox" 
                    onChange={(e) => {
                      if (e.target.checked) setSelectedIds(products.map(p => p.id));
                      else setSelectedIds([]);
                    }}
                    checked={selectedIds.length === products.length && products.length > 0}
                  />
                </th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">الصنف</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">المورد</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">القسم</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filtered.map(p => (
                <React.Fragment key={p.id}>
                  <tr className="hover:bg-gray-50/30 transition-colors">
                    <td className="p-4">
                      <input 
                        type="checkbox" 
                        checked={selectedIds.includes(p.id)}
                        onChange={(e) => {
                          if (e.target.checked) setSelectedIds([...selectedIds, p.id]);
                          else setSelectedIds(selectedIds.filter(id => id !== p.id));
                        }}
                      />
                    </td>
                    <td className="p-4 font-bold text-gray-900">{p.name}</td>
                    <td className="p-4 text-gray-500">{p.supplier || '-'}</td>
                    <td className="p-4">
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-2 py-1 rounded">
                        {categories.find(c => c.id === p.category_id)?.name || 'غير مصنف'}
                      </span>
                    </td>
                    <td className="p-4 text-left">
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={() => handleDuplicate(p)} className="p-2 text-gray-400 hover:text-blue-600"><Copy size={16} /></button>
                        <button className="p-2 text-gray-400 hover:text-blue-600"><Edit3 size={16} /></button>
                        <button onClick={() => handleDelete(p.id)} className="p-2 text-gray-400 hover:text-red-600"><Trash2 size={16} /></button>
                      </div>
                    </td>
                  </tr>
                  {/* Variants Row */}
                  <tr className="bg-gray-50/20">
                    <td colSpan={5} className="p-0">
                      <div className="px-14 pb-4 space-y-2">
                        {p.variants.map((v: any) => (
                          <div key={v.id} className="grid grid-cols-5 gap-4 py-2 px-4 bg-white rounded-xl border border-gray-100 text-xs font-bold text-gray-600 shadow-sm">
                            <span className="text-gray-400">Variant: {v.name}</span>
                            <span>الباركود: <span className="font-mono">{v.barcode || '-'}</span></span>
                            <span>تكلفة: <span className="text-gray-900">{v.cost_price} ₪</span></span>
                            <span>بيع: <span className="text-blue-600">{v.sale_price} ₪</span></span>
                            <span className="text-left">
                              الكمية: 
                              <span className={`mr-2 px-2 py-0.5 rounded ${v.stock_quantity < 5 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                                {v.stock_quantity}
                              </span>
                            </span>
                          </div>
                        ))}
                      </div>
                    </td>
                  </tr>
                </React.Fragment>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={5} className="p-12 text-center text-gray-400 font-bold">لا توجد نتائج بحث</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col">
            <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-blue-50/50">
              <h3 className="text-xl font-black text-blue-900">إضافة صنف جديد</h3>
              <button onClick={() => setShowAddModal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-8">
              {/* Basic Info */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-gray-700 mr-1">اسم الصنف</label>
                  <input 
                    type="text" 
                    className="w-full p-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:border-blue-500" 
                    value={newProduct.name}
                    onChange={(e) => setNewProduct({...newProduct, name: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-gray-700 mr-1">المورد</label>
                  <input 
                    type="text" 
                    className="w-full p-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:border-blue-500" 
                    value={newProduct.supplier}
                    onChange={(e) => setNewProduct({...newProduct, supplier: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-gray-700 mr-1">القسم الرئيسي</label>
                  <select 
                    className="w-full p-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:border-blue-500"
                    value={newProduct.category_id}
                    onChange={(e) => setNewProduct({...newProduct, category_id: e.target.value})}
                  >
                    <option value="">اختر القسم...</option>
                    {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-gray-700 mr-1">القسم الفرعي</label>
                  <select 
                    className="w-full p-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:border-blue-500"
                    value={newProduct.sub_category_id}
                    onChange={(e) => setNewProduct({...newProduct, sub_category_id: e.target.value})}
                  >
                    <option value="">اختر القسم الفرعي...</option>
                    {categories.filter(c => c.parent_id === newProduct.category_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              {/* Variants Section */}
              <div className="space-y-4">
                <div className="flex justify-between items-center">
                  <h4 className="font-black text-gray-900 flex items-center gap-2">
                    <Tag size={18} className="text-blue-600" />
                    الأنواع (Variants)
                  </h4>
                  <button 
                    onClick={handleAddVariant}
                    className="px-4 py-2 bg-blue-50 text-blue-600 font-bold rounded-xl text-sm flex items-center gap-2"
                  >
                    <Plus size={16} /> إغناء Variant
                  </button>
                </div>

                <div className="space-y-3">
                  {newProduct.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-3 p-4 bg-gray-50 rounded-2xl border border-gray-200 relative">
                      <input 
                        placeholder="اسم النوع (مثال: أبيض)" 
                        className="p-3 rounded-xl border border-gray-200 outline-none focus:border-blue-500" 
                        value={v.name}
                        onChange={(e) => {
                          const vs = [...newProduct.variants];
                          vs[idx].name = e.target.value;
                          setNewProduct({...newProduct, variants: vs});
                        }}
                      />
                      <input 
                        placeholder="الباركود" 
                        className="p-3 rounded-xl border border-gray-200 outline-none focus:border-blue-500 font-mono" 
                        value={v.barcode}
                        onChange={(e) => {
                          const vs = [...newProduct.variants];
                          vs[idx].barcode = e.target.value;
                          setNewProduct({...newProduct, variants: vs});
                        }}
                      />
                      <input 
                        type="number" placeholder="سعر التكلفة" 
                        className="p-3 rounded-xl border border-gray-200 outline-none focus:border-blue-500" 
                        value={v.cost_price || ''}
                        onChange={(e) => {
                          const vs = [...newProduct.variants];
                          vs[idx].cost_price = Number(e.target.value);
                          setNewProduct({...newProduct, variants: vs});
                        }}
                      />
                      <input 
                        type="number" placeholder="سعر البيع" 
                        className="p-3 rounded-xl border border-gray-200 outline-none focus:border-blue-500" 
                        value={v.sale_price || ''}
                        onChange={(e) => {
                          const vs = [...newProduct.variants];
                          vs[idx].sale_price = Number(e.target.value);
                          setNewProduct({...newProduct, variants: vs});
                        }}
                      />
                      <div className="flex gap-2">
                        <input 
                          type="number" placeholder="الكمية" 
                          className="flex-1 p-3 rounded-xl border border-gray-200 outline-none focus:border-blue-500" 
                          value={v.stock_quantity || ''}
                          onChange={(e) => {
                            const vs = [...newProduct.variants];
                            vs[idx].stock_quantity = Number(e.target.value);
                            setNewProduct({...newProduct, variants: vs});
                          }}
                        />
                        {idx > 0 && (
                          <button 
                            onClick={() => setNewProduct({...newProduct, variants: newProduct.variants.filter((_, i) => i !== idx)})}
                            className="p-3 text-red-500 hover:bg-red-50 rounded-xl"
                          >
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-6 bg-gray-50 border-t border-gray-100">
              <button 
                onClick={handleSaveProduct}
                className="w-full py-4 bg-blue-600 text-white font-black text-lg rounded-2xl shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all"
              >
                حفظ الصنف
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Plus, Edit3, Trash2, Tag, ChevronDown, ChevronRight, X } from 'lucide-react';
import { supabase } from '../supabase';
import type { Category } from '../types';

const Categories: React.FC = () => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', parent_id: null as string | null });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    setLoading(true);
    const { data } = await supabase.from('categories').select('*').order('name');
    setCategories(data || []);
    setLoading(false);
  };

  const handleAdd = async () => {
    if (!newCat.name) return;
    await supabase.from('categories').insert(newCat);
    setShowAddModal(false);
    setNewCat({ name: '', parent_id: null });
    fetchCategories();
  };

  const handleDelete = async (id: string) => {
    if (confirm("سيتم حذف القسم وكافة الأقسام التابعة له والأصناف المرتبطة به. هل أنت متأكد؟")) {
      await supabase.from('categories').delete().eq('id', id);
      fetchCategories();
    }
  };

  const mainCategories = categories.filter(c => !c.parent_id);

  return (
    <div className="max-w-4xl mx-auto space-y-6" dir="rtl">
      <div className="flex justify-between items-center">
