import React, { useState, useEffect } from 'react';
import { Plus, Wallet, ShoppingCart, Trash2, Calendar, FileText } from 'lucide-react';
import { supabase } from '../supabase';

const Expenses: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'expenses' | 'purchases'>('expenses');
  const [expenses, setExpenses] = useState<any[]>([]);
  const [purchases, setPurchases] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);

  const [form, setForm] = useState({
    type: '',
    amount: 0,
    supplier: '',
    note: '',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    const { data: ex } = await supabase.from('expenses').select('*').order('date', { ascending: false });
    const { data: pu } = await supabase.from('purchases').select('*').order('date', { ascending: false });
    setExpenses(ex || []);
    setPurchases(pu || []);
  };

  const handleSave = async () => {
    if (activeTab === 'expenses') {
      await supabase.from('expenses').insert({
        type: form.type,
        amount: form.amount,
        date: form.date,
        note: form.note
      });
    } else {
      await supabase.from('purchases').insert({
        amount: form.amount,
        supplier: form.supplier,
        date: form.date,
        note: form.note
      });
    }
    setShowModal(false);
    setForm({ type: '', amount: 0, supplier: '', note: '', date: new Date().toISOString().split('T')[0] });
    fetchData();
  };

  const handleDelete = async (id: string, table: string) => {
    if (confirm("هل أنت متأكد؟")) {
      await supabase.from(table).delete().eq('id', id);
      fetchData();
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-6" dir="rtl">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-900">المصاريف والمشتريات</h2>
        <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm w-full md:w-auto">
          <button 
            onClick={() => setActiveTab('expenses')}
            className={`flex-1 md:px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'expenses' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}
          >
            المصاريف
          </button>
          <button 
            onClick={() => setActiveTab('purchases')}
            className={`flex-1 md:px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'purchases' ? 'bg-amber-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}
          >
            المشتريات
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className={`p-6 rounded-3xl border flex items-center gap-4 shadow-sm ${activeTab === 'expenses' ? 'bg-blue-50 border-blue-100' : 'bg-amber-50 border-amber-100'}`}>
          <div className={`p-4 rounded-2xl ${activeTab === 'expenses' ? 'bg-blue-600 text-white' : 'bg-amber-600 text-white'}`}>
            {activeTab === 'expenses' ? <Wallet size={24} /> : <ShoppingCart size={24} />}
          </div>
          <div>
            <p className="text-xs font-bold text-gray-500">إجمالي {activeTab === 'expenses' ? 'المصاريف' : 'المشتريات'}</p>
            <p className="text-2xl font-black text-gray-900">
              {(activeTab === 'expenses' ? expenses : purchases).reduce((s, i) => s + Number(i.amount), 0)} ₪
            </p>
          </div>
          <button 
            onClick={() => setShowModal(true)}
            className={`mr-auto px-6 py-3 rounded-xl font-bold text-white shadow-lg transition-all ${activeTab === 'expenses' ? 'bg-blue-600 hover:bg-blue-700 shadow-blue-100' : 'bg-amber-600 hover:bg-amber-700 shadow-amber-100'}`}
          >
            إضافة {activeTab === 'expenses' ? 'مصروف' : 'مشتريات'}
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">{activeTab === 'expenses' ? 'النوع' : 'المورد'}</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">المبلغ</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">التاريخ</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">ملاحظات</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {(activeTab === 'expenses' ? expenses : purchases).map(item => (
                <tr key={item.id} className="hover:bg-gray-50/50 transition-colors">
                  <td className="p-4 font-bold text-gray-900">{activeTab === 'expenses' ? item.type : item.supplier || '-'}</td>
                  <td className={`p-4 font-black ${activeTab === 'expenses' ? 'text-red-500' : 'text-amber-600'}`}>{item.amount} ₪</td>
                  <td className="p-4 text-gray-500 text-sm">{item.date}</td>
                  <td className="p-4 text-gray-400 text-xs italic">{item.note || '-'}</td>
                  <td className="p-4 text-left">
                    <button onClick={() => handleDelete(item.id, activeTab)} className="text-gray-300 hover:text-red-500"><Trash2 size={18} /></button>
                  </td>
                </tr>
              ))}
              {(activeTab === 'expenses' ? expenses : purchases).length === 0 && (
                <tr><td colSpan={5} className="p-12 text-center text-gray-400 font-bold">لا توجد سجلات</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className={`p-6 border-b border-gray-100 flex items-center justify-between ${activeTab === 'expenses' ? 'bg-blue-50' : 'bg-amber-50'}`}>
              <h3 className="text-xl font-black">إضافة {activeTab === 'expenses' ? 'مصروف جديد' : 'مشتريات جديدة'}</h3>
              <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700 mr-1">{activeTab === 'expenses' ? 'نوع المصروف' : 'اسم المورد'}</label>
                <input 
                  type="text" 
                  className="w-full p-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:border-blue-500" 
                  value={activeTab === 'expenses' ? form.type : form.supplier}
                  onChange={(e) => setForm({...form, [activeTab === 'expenses' ? 'type' : 'supplier']: e.target.value})}
                  placeholder={activeTab === 'expenses' ? "مثال: كهرباء، إيجار..." : "اسم التاجر"}
                />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700 mr-1">المبلغ</label>
                <input 
                  type="number" 
                  className="w-full p-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:border-blue-500" 
                  value={form.amount || ''}
                  onChange={(e) => setForm({...form, amount: Number(e.target.value)})}
                />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700 mr-1">التاريخ</label>
                <input 
                  type="date" 
                  className="w-full p-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:border-blue-500" 
                  value={form.date}
                  onChange={(e) => setForm({...form, date: e.target.value})}
