              </div>
              <button 
                onClick={handleSave}
                className={`w-full py-4 text-white font-black text-lg rounded-2xl shadow-xl transition-all ${activeTab === 'expenses' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-amber-600 hover:bg-amber-700'}`}
              >
                حفظ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Expenses;

import React, { useState, useEffect } from 'react';
import { FileText, Edit2, Trash2, Printer, Search, PieChart, TrendingUp, Save, Percent } from 'lucide-react';
