      fetchInvoices();
    }
  };

  const handleUpdateSettings = async () => {
    const { error } = await supabase
      .from('settings')
      .update(tempSettings)
      .eq('id', 1);

    if (!error) {
      onUpdateSettings();
      setEditMode(null);
    }
  };

  const totalInvoicesProfit = invoices.reduce((s, i) => s + Number(i.profit), 0);
  const netProfit = totalInvoicesProfit; // Simplified, in real case we deduct expenses in reports

  return (
