              <Edit2 size={16} />
            </button>
          </div>

          <div className="grid grid-cols-3 gap-6 mt-8 relative">
            <div className="space-y-1">
              <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">رأس المال</p>
              <p className="text-xl font-black text-gray-900">{settings?.capital} ₪</p>
