                  value={tempSettings.capital}
                  onChange={(e) => setTempSettings({...tempSettings, capital: Number(e.target.value)})}
                />
                <input 
                  type="number" 
                  className="p-3 bg-white border border-gray-200 rounded-xl outline-none" 
                  placeholder="الادخار" 
                  value={tempSettings.savings}
                  onChange={(e) => setTempSettings({...tempSettings, savings: Number(e.target.value)})}
