                <button onClick={handleUpdateSettings} className="flex-1 py-2 bg-blue-600 text-white font-bold rounded-xl flex items-center justify-center gap-2"><Save size={16} /> حفظ</button>
                <button onClick={() => setEditMode(null)} className="px-6 py-2 bg-gray-200 text-gray-700 font-bold rounded-xl">إلغاء</button>
