          </div>
          <div className="p-6">
            <div className="space-y-4">
              {stats.topItems.map((it, idx) => (
                <div key={idx} className="flex items-center justify-between group">
                  <div className="flex items-center gap-4">
                    <span className="w-8 h-8 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center font-black text-xs">{idx + 1}</span>
                    <div>
                      <p className="font-bold text-gray-900 group-hover:text-blue-600 transition-colors">{it.name}</p>
                      <p className="text-xs text-gray-400">{it.variant}</p>
                    </div>
                  </div>
                  <div className="text-left">
                    <p className="font-black text-gray-900">{it.qty}</p>
                    <p className="text-[10px] text-gray-400 font-bold uppercase">قطعة</p>
