              </div>

              <button 
                disabled={!protectionEnabled}
                onClick={() => handleToggleLock(page.id)}
                className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none ${locks[page.id] && protectionEnabled ? 'bg-amber-600' : 'bg-gray-200'} ${!protectionEnabled && 'opacity-30 cursor-not-allowed'}`}
              >
                <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${locks[page.id] ? '-translate-x-6' : '-translate-x-1'}`} />
