import React, { useState, useEffect, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  PlusCircle, 
  Printer, 
  CheckCircle2, 
  ShoppingBag,
  Info,
  X
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, ExtraService } from '../types';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [cart, setCart] = useState<any[]>([]);
  const [discount, setDiscount] = useState(0);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [extraService, setExtraService] = useState<ExtraService>({
    name: '',
    cost_price: 0,
    sale_price: 0,
    quantity: 1
  });
  const [loading, setLoading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<any>(null);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchProducts();
    barcodeInputRef.current?.focus();
  }, []);

  const fetchProducts = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('products')
      .select(`
        *,
        variants (*)
      `);
    if (!error) setProducts(data || []);
    setLoading(false);
  };

  const addToCart = (variant: Variant, product: any) => {
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, {
        variant_id: variant.id,
        product_name: product.name,
        variant_name: variant.name,
        cost_price: variant.cost_price,
        sale_price: variant.sale_price,
        quantity: 1,
        type: 'product'
      }];
    });
    setSearchTerm('');
  };

  const addExtraToCart = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setCart(prev => [...prev, {
      ...extraService,
      type: 'service',
      id: Math.random().toString(36).substr(2, 9)
    }]);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
    setShowExtraModal(false);
  };

  const updateQuantity = (id: string, type: 'product' | 'service', delta: number) => {
    setCart(prev => prev.map(item => {
      const itemId = type === 'product' ? item.variant_id : item.id;
      if (itemId === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'product' | 'service') => {
    setCart(prev => prev.filter(item => {
      const itemId = type === 'product' ? item.variant_id : item.id;
      return itemId !== id;
    }));
  };

  const calculateTotal = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    return Math.max(0, subtotal - discount);
  };

  const calculateCost = () => {
    return cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);
  };

  const filteredProducts = products.flatMap(p => 
    (p.variants || []).map((v: Variant) => ({ ...v, productName: p.name, supplier: p.supplier }))
  ).filter(v => 
    v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (v.barcode && v.barcode.includes(searchTerm))
  );

  const handleCheckout = async () => {
    if (cart.length === 0) return;
    setIsProcessing(true);

    const net_amount = calculateTotal();
    const total_cost = calculateCost();
    const profit = net_amount - total_cost;

    const { data: invoice, error: invError } = await supabase
      .from('invoices')
      .insert({
        total_amount: net_amount + discount,
        discount,
        net_amount,
        total_cost,
        profit
      })
      .select()
      .single();

    if (invError) {
      alert("خطأ في حفظ الفاتورة");
      setIsProcessing(false);
      return;
    }

    const items = cart.filter(i => i.type === 'product').map(i => ({
      invoice_id: invoice.id,
      variant_id: i.variant_id,
      product_name: i.product_name,
      variant_name: i.variant_name,
      quantity: i.quantity,
      cost_price: i.cost_price,
      sale_price: i.sale_price
    }));

    const services = cart.filter(i => i.type === 'service').map(i => ({
      invoice_id: invoice.id,
      name: i.name,
      cost_price: i.cost_price,
      sale_price: i.sale_price,
      quantity: i.quantity
    }));

    if (items.length > 0) await supabase.from('invoice_items').insert(items);
    if (services.length > 0) await supabase.from('extra_services').insert(services);

    // Update Inventory
    for (const item of items) {
      const { data: variant } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
      if (variant) {
        await supabase.from('variants').update({ stock_quantity: variant.stock_quantity - item.quantity }).eq('id', item.variant_id);
      }
    }

    setLastInvoice({ ...invoice, items: cart });
    setCart([]);
    setDiscount(0);
    setIsProcessing(false);

    // Auto print trigger
    setTimeout(() => window.print(), 500);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full relative" dir="rtl">
      {/* Product Selection */}
      <div className="flex-1 flex flex-col gap-4 no-print">
        <div className="relative">
          <input
            ref={barcodeInputRef}
            type="text"
            placeholder="بحث بالاسم أو الباركود..."
            className="w-full pr-12 pl-4 py-4 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 focus:ring-4 focus:ring-blue-50 transition-all outline-none text-lg font-medium shadow-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && filteredProducts.length === 1) {
                const p = products.find(prod => prod.id === filteredProducts[0].product_id);
                addToCart(filteredProducts[0], p);
              }
            }}
          />
          <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={24} />
        </div>

        <div className="flex-1 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 p-1">
          {filteredProducts.map(v => (
            <button
              key={v.id}
              onClick={() => {
                const p = products.find(prod => prod.id === v.product_id);
                addToCart(v, p);
              }}
              className="group bg-white p-4 rounded-2xl border-2 border-transparent hover:border-blue-500 hover:shadow-xl transition-all text-right flex flex-col gap-2 relative overflow-hidden shadow-sm"
            >
              <div className="flex justify-between items-start">
                <span className="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-lg">
                  {v.stock_quantity} في المخزن
                </span>
                {v.barcode && <span className="text-[10px] text-gray-400 font-mono">{v.barcode}</span>}
              </div>
              <h3 className="font-bold text-gray-900 truncate">{v.productName}</h3>
              <p className="text-sm text-gray-500 truncate">{v.name}</p>
              <p className="text-xl font-black text-blue-600 mt-2">{v.sale_price} ₪</p>
              <div className="absolute bottom-0 right-0 p-2 bg-blue-600 text-white translate-y-full group-hover:translate-y-0 transition-transform rounded-tr-xl">
                <Plus size={16} />
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className="w-full lg:w-96 flex flex-col bg-white rounded-3xl border border-gray-100 shadow-xl overflow-hidden no-print">
        <div className="p-6 bg-gray-50 border-b border-gray-100 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-600 text-white rounded-xl">
              <ShoppingBag size={20} />
            </div>
            <h2 className="text-lg font-extrabold text-gray-900">سلة البيع</h2>
          </div>
          <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-black">
            {cart.length} أصناف
          </span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400 gap-4 opacity-50">
              <ShoppingBag size={64} />
              <p className="font-bold">السلة فارغة</p>
            </div>
          ) : (
            cart.map((item) => (
              <div key={item.type === 'product' ? item.variant_id : item.id} className="flex flex-col gap-2 p-4 bg-gray-50 rounded-2xl border border-gray-100 group">
                <div className="flex justify-between items-start">
                  <div>
                    <h4 className="font-bold text-gray-900 text-sm">{item.product_name || item.name}</h4>
                    {item.variant_name && <p className="text-xs text-gray-500">{item.variant_name}</p>}
                    {item.type === 'service' && <span className="text-[10px] font-bold text-amber-600 bg-amber-50 px-2 rounded">خدمة إضافية</span>}
                  </div>
                  <button 
                    onClick={() => removeFromCart(item.type === 'product' ? item.variant_id : item.id, item.type)}
                    className="text-gray-400 hover:text-red-500 transition-colors"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
                <div className="flex items-center justify-between mt-2">
                  <div className="flex items-center gap-3 bg-white p-1 rounded-xl border border-gray-100">
                    <button 
                      onClick={() => updateQuantity(item.type === 'product' ? item.variant_id : item.id, item.type, -1)}
                      className="p-1 hover:bg-gray-100 rounded-lg transition-colors"
                    >
                      <Minus size={14} />
                    </button>
                    <span className="font-black text-gray-900 min-w-[20px] text-center">{item.quantity}</span>
                    <button 
                      onClick={() => updateQuantity(item.type === 'product' ? item.variant_id : item.id, item.type, 1)}
                      className="p-1 hover:bg-gray-100 rounded-lg transition-colors"
                    >
                      <Plus size={14} />
                    </button>
                  </div>
                  <p className="font-black text-blue-600">{item.sale_price * item.quantity} ₪</p>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-gray-50 border-t border-gray-100 space-y-4">
          <div className="flex gap-2">
            <button 
              onClick={() => setShowExtraModal(true)}
              className="flex-1 py-3 bg-amber-100 text-amber-700 font-bold rounded-xl flex items-center justify-center gap-2 hover:bg-amber-200 transition-colors"
            >
              <PlusCircle size={18} />
              <span>خدمة إضافية</span>
            </button>
            <div className="flex-1 relative">
              <input 
                type="number" 
                placeholder="خصم ₪"
                className="w-full py-3 pr-4 pl-10 bg-white border border-gray-200 rounded-xl focus:border-blue-500 outline-none font-bold text-center"
                value={discount || ''}
                onChange={(e) => setDiscount(Number(e.target.value))}
              />
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-sm font-bold">₪</span>
            </div>
          </div>

          <div className="space-y-2 pt-2 border-t border-gray-200">
            <div className="flex justify-between text-gray-500 font-bold text-sm">
              <span>المجموع الفرعي</span>
              <span>{cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0)} ₪</span>
            </div>
            {discount > 0 && (
              <div className="flex justify-between text-red-500 font-bold text-sm">
                <span>الخصم</span>
                <span>-{discount} ₪</span>
              </div>
            )}
            <div className="flex justify-between items-center pt-2">
              <span className="text-xl font-extrabold text-gray-900">الإجمالي</span>
              <span className="text-3xl font-black text-blue-600">{calculateTotal()} ₪</span>
            </div>
          </div>

          <button
            onClick={handleCheckout}
            disabled={isProcessing || cart.length === 0}
            className="w-full py-4 bg-blue-600 text-white font-black text-lg rounded-2xl shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center gap-3 disabled:bg-gray-300 disabled:shadow-none"
          >
            {isProcessing ? (
              <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <>
                <CheckCircle2 size={24} />
                <span>إتمام عملية البيع</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Extra Service Modal */}
      {showExtraModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4 no-print">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="p-6 bg-amber-50 border-b border-amber-100 flex items-center justify-between">
              <h3 className="text-xl font-extrabold text-amber-900">إضافة خدمة إضافية</h3>
              <button onClick={() => setShowExtraModal(false)} className="text-amber-400 hover:text-amber-600">
                <X size={24} />
              </button>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700">اسم الخدمة</label>
                <input
                  autoFocus
                  type="text"
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:border-amber-500 outline-none"
                  value={extraService.name}
                  onChange={(e) => setExtraService({ ...extraService, name: e.target.value })}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-gray-700">سعر التكلفة</label>
                  <input
                    type="number"
                    className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:border-amber-500 outline-none"
                    value={extraService.cost_price || ''}
                    onChange={(e) => setExtraService({ ...extraService, cost_price: Number(e.target.value) })}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-gray-700">سعر البيع</label>
                  <input
                    type="number"
                    className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:border-amber-500 outline-none"
                    value={extraService.sale_price || ''}
                    onChange={(e) => setExtraService({ ...extraService, sale_price: Number(e.target.value) })}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700">الكمية</label>
                <input
                  type="number"
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:border-amber-500 outline-none"
                  value={extraService.quantity || ''}
                  onChange={(e) => setExtraService({ ...extraService, quantity: Number(e.target.value) })}
                />
              </div>
              <button
                onClick={addExtraToCart}
                className="w-full py-4 bg-amber-600 text-white font-bold rounded-2xl shadow-lg shadow-amber-100 hover:bg-amber-700 transition-all"
              >
                إضافة للسلة
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Print View (58mm Thermal) */}
      <div className="print-only" dir="rtl">
        <div style={{ textAlign: 'center', marginBottom: '10px' }}>
          <h2 style={{ fontSize: '18px', fontWeight: 'bold', margin: '0' }}>Flyyti Mobile POS</h2>
          <p style={{ fontSize: '10px', color: '#666' }}>فاتورة مبيعات</p>
        </div>
        <div style={{ borderBottom: '1px dashed #000', margin: '10px 0', fontSize: '10px' }}>
          <p>التاريخ: {new Date().toLocaleDateString('ar-EG')}</p>
          <p>الوقت: {new Date().toLocaleTimeString('ar-EG')}</p>
          <p>رقم الفاتورة: {lastInvoice?.id?.slice(0, 8)}</p>
        </div>
        <table style={{ width: '100%', fontSize: '11px', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #000' }}>
              <th style={{ textAlign: 'right', padding: '5px 0' }}>الصنف</th>
              <th style={{ textAlign: 'center', padding: '5px 0' }}>كمية</th>
              <th style={{ textAlign: 'left', padding: '5px 0' }}>سعر</th>
            </tr>
          </thead>
          <tbody>
            {lastInvoice?.items?.map((item: any, idx: number) => (
              <tr key={idx}>
                <td style={{ padding: '5px 0' }}>{item.product_name || item.name} {item.variant_name ? `(${item.variant_name})` : ''}</td>
                <td style={{ textAlign: 'center' }}>{item.quantity}</td>
                <td style={{ textAlign: 'left' }}>{item.sale_price * item.quantity} ₪</td>
              </tr>
            ))}
          </tbody>
        </table>
        <div style={{ borderTop: '1px dashed #000', marginTop: '10px', paddingTop: '10px', fontSize: '12px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            <span>المجموع:</span>
            <span>{lastInvoice?.net_amount + lastInvoice?.discount} ₪</span>
          </div>
          {lastInvoice?.discount > 0 && (
            <div style={{ display: 'flex', justifyContent: 'space-between', color: '#000' }}>
              <span>الخصم:</span>
              <span>-{lastInvoice?.discount} ₪</span>
            </div>
          )}
          <div style={{ display: 'flex', justifyContent: 'space-between', fontWeight: 'bold', fontSize: '14px', marginTop: '5px' }}>
            <span>الإجمالي:</span>
            <span>{lastInvoice?.net_amount} ₪</span>
          </div>
        </div>
        <div style={{ textAlign: 'center', marginTop: '20px', fontSize: '10px' }}>
          <p>شكراً لزيارتكم!</p>
          <p>Flyyti POS Systems</p>
        </div>
      </div>
    </div>
  );
};

export default POS;

import React, { useState, useEffect } from 'react';
import { 
  Plus, 
  Search, 
  Edit3, 
  Trash2, 
  Copy, 
  MoreVertical, 
  Tag, 
  ChevronDown,
  ChevronUp,
  Package,
  Layers,
  Filter,
  X,
  DollarSign
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Product, Variant, Category } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loading, setLoading] = useState(true);

  const [newProduct, setNewProduct] = useState({
    name: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ name: 'افتراضي', barcode: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*');
    setProducts(prods || []);
    setCategories(cats || []);
    setLoading(false);
  };

  const handleAddVariant = () => {
    setNewProduct({
      ...newProduct,
      variants: [...newProduct.variants, { name: '', barcode: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
  };

  const handleSaveProduct = async () => {
    const { data: prod, error: pError } = await supabase
      .from('products')
      .insert({
        name: newProduct.name,
        supplier: newProduct.supplier,
        category_id: newProduct.category_id || null,
        sub_category_id: newProduct.sub_category_id || null
      })
      .select()
      .single();

    if (pError) return alert("خطأ في إضافة المنتج");

    const variantsToInsert = newProduct.variants.map(v => ({
      ...v,
      product_id: prod.id
    }));

    await supabase.from('variants').insert(variantsToInsert);
    setShowAddModal(false);
    setNewProduct({
      name: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ name: 'افتراضي', barcode: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    fetchData();
  };

  const handleDelete = async (id: string) => {
    if (confirm("هل أنت متأكد من الحذف؟")) {
      await supabase.from('products').delete().eq('id', id);
      fetchData();
    }
  };

  const handleBulkDelete = async () => {
    if (confirm(`هل أنت متأكد من حذف ${selectedIds.length} منتجات؟`)) {
      await supabase.from('products').delete().in('id', selectedIds);
      setSelectedIds([]);
      fetchData();
    }
  };

  const handleDuplicate = async (product: any) => {
    const { data: prod } = await supabase
      .from('products')
      .insert({
        name: `${product.name} (نسخة)`,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      })
      .select()
      .single();

    if (prod) {
      const variants = product.variants.map((v: any) => ({
        name: v.name,
        barcode: v.barcode ? `${v.barcode}-copy` : null,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prod.id
      }));
      await supabase.from('variants').insert(variants);
      fetchData();
    }
  };

  const calculateStockValue = (prods: any[]) => {
    return prods.reduce((sum, p) => {
      const vSum = p.variants.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0);
      return sum + vSum;
    }, 0);
  };

  const filtered = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.variants.some((v: any) => v.barcode && v.barcode.includes(searchTerm))
  );

  return (
    <div className="space-y-6" dir="rtl">
      {/* Top Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-900">المخزون</h2>
        <div className="flex gap-3 w-full md:w-auto">
          <button 
            onClick={() => setShowAddModal(true)}
            className="flex-1 md:flex-none px-6 py-3 bg-blue-600 text-white font-bold rounded-xl flex items-center justify-center gap-2 shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
          {selectedIds.length > 0 && (
            <button 
              onClick={handleBulkDelete}
              className="px-6 py-3 bg-red-100 text-red-600 font-bold rounded-xl flex items-center justify-center gap-2 hover:bg-red-200 transition-all"
            >
              <Trash2 size={20} />
              <span>حذف ({selectedIds.length})</span>
            </button>
          )}
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
            <Package size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">إجمالي الأصناف</p>
            <p className="text-xl font-black text-gray-900">{products.length}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-green-50 text-green-600 rounded-2xl">
            <DollarSign size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">قيمة المخزون (بالتكلفة)</p>
            <p className="text-xl font-black text-green-600">{calculateStockValue(products)} ₪</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-purple-50 text-purple-600 rounded-2xl">
            <Layers size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">إجمالي القطع</p>
            <p className="text-xl font-black text-gray-900">
              {products.reduce((s, p) => s + p.variants.reduce((vs: number, v: any) => vs + v.stock_quantity, 0), 0)}
            </p>
          </div>
        </div>
      </div>

      {/* Search & Table */}
      <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:border-blue-500 outline-none font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button className="p-3 bg-gray-50 text-gray-500 rounded-xl hover:bg-gray-100">
            <Filter size={20} />
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="p-4 w-10">
                  <input 
                    type="checkbox" 
                    onChange={(e) => {
                      if (e.target.checked) setSelectedIds(products.map(p => p.id));
                      else setSelectedIds([]);
                    }}
                    checked={selectedIds.length === products.length && products.length > 0}
                  />
                </th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">الصنف</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">المورد</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">القسم</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filtered.map(p => (
                <React.Fragment key={p.id}>
                  <tr className="hover:bg-gray-50/30 transition-colors">
                    <td className="p-4">
                      <input 
                        type="checkbox" 
                        checked={selectedIds.includes(p.id)}
                        onChange={(e) => {
                          if (e.target.checked) setSelectedIds([...selectedIds, p.id]);
                          else setSelectedIds(selectedIds.filter(id => id !== p.id));
                        }}
                      />
                    </td>
                    <td className="p-4 font-bold text-gray-900">{p.name}</td>
                    <td className="p-4 text-gray-500">{p.supplier || '-'}</td>
                    <td className="p-4">
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-2 py-1 rounded">
                        {categories.find(c => c.id === p.category_id)?.name || 'غير مصنف'}
                      </span>
                    </td>
                    <td className="p-4 text-left">
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={() => handleDuplicate(p)} className="p-2 text-gray-400 hover:text-blue-600"><Copy size={16} /></button>
                        <button className="p-2 text-gray-400 hover:text-blue-600"><Edit3 size={16} /></button>
                        <button onClick={() => handleDelete(p.id)} className="p-2 text-gray-400 hover:text-red-600"><Trash2 size={16} /></button>
                      </div>
                    </td>
