import React, { useState, useEffect } from 'react';
import { 
  BarChart3, 
  Calendar, 
  ChevronDown, 
  ArrowUpRight, 
  ArrowDownRight, 
  Package, 
  ShoppingCart,
  Zap,
  Filter,
  FileText
} from 'lucide-react';
import { supabase } from '../supabase';

const GeneralReports: React.FC = () => {
  const [period, setPeriod] = useState<'day' | 'month' | 'year' | 'custom'>('day');
  const [dateRange, setDateRange] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date().toISOString().split('T')[0] 
  });
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    netProfit: 0,
    itemsSold: 0,
    totalDiscount: 0,
    topItems: [] as any[],
    services: [] as any[]
  });

  const fetchData = async () => {
    setLoading(true);
    let start = new Date(dateRange.start + 'T00:00:00Z').toISOString();
    let end = new Date(dateRange.end + 'T23:59:59Z').toISOString();

    const { data: invoices } = await supabase.from('invoices').select('*, invoice_items(*), extra_services(*)').gte('created_at', start).lte('created_at', end);
    const { data: expenses } = await supabase.from('expenses').select('*').gte('date', dateRange.start).lte('date', dateRange.end);
    const { data: purchases } = await supabase.from('purchases').select('*').gte('date', dateRange.start).lte('date', dateRange.end);
    const { data: settings } = await supabase.from('settings').select('savings').eq('id', 1).single();

    if (invoices) {
      let s = {
        totalSales: 0,
        totalCost: 0,
        totalProfit: 0,
        itemsSold: 0,
        totalDiscount: 0,
        topItems: [] as any[],
        services: [] as any[]
      };

      const itemCounts: Record<string, any> = {};

      invoices.forEach(inv => {
        s.totalSales += Number(inv.net_amount);
        s.totalCost += Number(inv.total_cost);
        s.totalProfit += Number(inv.profit);
        s.totalDiscount += Number(inv.discount);

        inv.invoice_items.forEach((it: any) => {
          s.itemsSold += it.quantity;
          const key = `${it.product_name}-${it.variant_name}`;
          if (!itemCounts[key]) itemCounts[key] = { name: it.product_name, variant: it.variant_name, qty: 0 };
          itemCounts[key].qty += it.quantity;
        });

        inv.extra_services.forEach((ser: any) => {
          s.services.push({ ...ser, created_at: inv.created_at });
        });
      });

      const totalExpenses = expenses?.reduce((sum, e) => sum + Number(e.amount), 0) || 0;
      const totalPurchases = purchases?.reduce((sum, p) => sum + Number(p.amount), 0) || 0;
      const savings = Number(settings?.savings || 0);

      setStats({
        ...s,
        netProfit: s.totalProfit - totalExpenses,
        totalSales: s.totalSales - totalPurchases + savings, // Logic as per request
        topItems: Object.values(itemCounts).sort((a, b) => b.qty - a.qty).slice(0, 10),
        services: s.services
      });
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, [dateRange]);

  const handlePeriodChange = (p: typeof period) => {
    setPeriod(p);
    const now = new Date();
    if (p === 'day') {
      const d = now.toISOString().split('T')[0];
      setDateRange({ start: d, end: d });
    } else if (p === 'month') {
      const start = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
      const end = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
      setDateRange({ start, end });
    } else if (p === 'year') {
      const start = new Date(now.getFullYear(), 0, 1).toISOString().split('T')[0];
      const end = new Date(now.getFullYear(), 11, 31).toISOString().split('T')[0];
      setDateRange({ start, end });
    }
  };

  return (
    <div className="space-y-8" dir="rtl">
      {/* Period Selection */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
        <div className="flex bg-gray-50 p-1 rounded-2xl border border-gray-100 w-full md:w-auto">
          {['day', 'month', 'year', 'custom'].map((p: any) => (
            <button 
              key={p} 
              onClick={() => handlePeriodChange(p)}
              className={`flex-1 px-4 py-2 rounded-xl text-sm font-bold transition-all ${period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
            >
              {p === 'day' ? 'يومي' : p === 'month' ? 'شهري' : p === 'year' ? 'سنوي' : 'مخصص'}
            </button>
          ))}
        </div>

        {period === 'custom' && (
          <div className="flex items-center gap-3 w-full md:w-auto">
            <input 
              type="date" 
              className="flex-1 p-2 bg-gray-50 border border-gray-100 rounded-xl outline-none text-sm" 
              value={dateRange.start}
              onChange={(e) => setDateRange({...dateRange, start: e.target.value})}
            />
            <span className="text-gray-400">إلى</span>
            <input 
              type="date" 
              className="flex-1 p-2 bg-gray-50 border border-gray-100 rounded-xl outline-none text-sm" 
              value={dateRange.end}
              onChange={(e) => setDateRange({...dateRange, end: e.target.value})}
            />
          </div>
        )}
      </div>

      {/* Main Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">إجمالي المبيعات</p>
          <div className="flex items-baseline gap-2">
            <span className="text-3xl font-black text-gray-900">{stats.totalSales.toFixed(2)} ₪</span>
            <span className="text-[10px] text-gray-400">بعد التعديلات</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">إجمالي الربح</p>
          <p className="text-3xl font-black text-blue-600">{stats.totalProfit.toFixed(2)} ₪</p>
        </div>
