import { createClient } from '@supabase/supabase-js';

// Robust environment variable access for different build tools and environments
const getEnv = (key: string): string => {
  // Try import.meta.env (Vite standard)
  if (typeof import.meta !== 'undefined' && (import.meta as any).env) {
    const val = (import.meta as any).env[key];
    if (val) return val;
  }

  // Try process.env (Node/Webpack/Some CI environments)
  if (typeof process !== 'undefined' && process.env) {
    const val = process.env[key];
    if (val) return val;
  }

  return '';
};

const supabaseUrl = getEnv('VITE_SUPABASE_URL');
const supabaseAnonKey = getEnv('VITE_SUPABASE_ANON_KEY');

// We use a fallback empty string for the values to satisfy the type checker, 
// but we only call createClient if we have valid-looking inputs.
// If missing, we'll log a clear error instead of letting the library throw a generic one.
if (!supabaseUrl || !supabaseAnonKey) {
  console.error(
    "Supabase configuration missing! Please ensure VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY " +
    "are set in your environment variables. The app will likely fail to perform database operations."
  );
}

export const supabase = createClient(
  supabaseUrl || 'https://placeholder-url.supabase.co', 
  supabaseAnonKey || 'placeholder-key'
);

import { createClient } from '@supabase/supabase-js';

/**
 * Safely retrieves environment variables from common storage locations.
 * Checks both `process.env` (Node/Vercel standard) and `import.meta.env` (Vite standard).
 */
const getSafeEnv = (key: string): string => {
  // Try process.env first (standard for most cloud environments like Vercel)
  if (typeof process !== 'undefined' && process.env && process.env[key]) {
    return process.env[key] as string;
  }

  // Try import.meta.env (standard for Vite)
  // We use a try-catch because accessing import.meta in non-ESM environments can throw
  try {
    if (typeof import.meta !== 'undefined' && (import.meta as any).env) {
      const val = (import.meta as any).env[key];
      if (val) return val;
    }
  } catch (e) {
    // Ignore error
  }

  // Fallback for some specific web previewers that might put it on window
  if (typeof window !== 'undefined' && (window as any).process?.env?.[key]) {
    return (window as any).process.env[key];
  }

  return '';
};

// Check for both prefixed and non-prefixed versions as Vercel/Supabase users 
// often use different naming conventions.
const supabaseUrl = getSafeEnv('VITE_SUPABASE_URL') || getSafeEnv('SUPABASE_URL');
const supabaseAnonKey = getSafeEnv('VITE_SUPABASE_ANON_KEY') || getSafeEnv('SUPABASE_ANON_KEY');

// Logic for a graceful failure if keys are missing
const isConfigValid = !!(supabaseUrl && supabaseAnonKey);

if (!isConfigValid) {
  console.error(
    "Critical Error: Supabase configuration is missing.\n" +
    "Please set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in your Environment Variables.\n" +
    "The application will not be able to connect to the database."
  );
}

// Initialize the client. We provide dummy strings if keys are missing to prevent 
// the library from throwing an immediate "url is required" exception, allowing 
// the app to render and show an error state if needed.
export const supabase = createClient(
  supabaseUrl || 'https://missing-url.supabase.co',
  supabaseAnonKey || 'missing-key'
);

