    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) {
        setSettings(data);
      } else {
        // If error code is 404 or specific supabase errors, it might be due to missing setup
        console.error("Database error:", error);
      }
