import { createClient, SupabaseClient } from '@supabase/supabase-js';

/**
 * Robustly retrieves configuration values from multiple possible sources:
 * 1. process.env (Node/Sandboxes)
 * 2. import.meta.env (Vite/ESM)
 * 3. window (Global scope)
 * 4. localStorage (User manual override)
 */
const getConfigValue = (key: string): string => {
  const viteKey = `VITE_${key}`;

  const sources = [
    // Standard process.env
    () => typeof process !== 'undefined' ? (process.env?.[viteKey] || process.env?.[key]) : null,
    // ESM import.meta.env
    () => {
      try {
        return (import.meta as any).env?.[viteKey] || (import.meta as any).env?.[key];
      } catch { return null; }
    },
    // Window globals
    () => typeof window !== 'undefined' ? ((window as any)[viteKey] || (window as any)[key] || (window as any).process?.env?.[viteKey] || (window as any).process?.env?.[key]) : null,
    // LocalStorage fallback (useful for manual setup in-browser)
    () => typeof localStorage !== 'undefined' ? (localStorage.getItem(viteKey) || localStorage.getItem(key)) : null
  ];

  for (const get of sources) {
    const val = get();
    if (val && typeof val === 'string') return val;
  }

  return '';
};

export const getSupabaseConfig = () => ({
  url: getConfigValue('SUPABASE_URL'),
  key: getConfigValue('SUPABASE_ANON_KEY'),
  isValid: !!(getConfigValue('SUPABASE_URL') && getConfigValue('SUPABASE_ANON_KEY'))
});

const config = getSupabaseConfig();

// Initialize client with whatever we found. 
// If nothing was found, we use placeholders to avoid library crashes on startup.
export const supabase: SupabaseClient = createClient(
  config.url || 'https://missing-supabase-url.supabase.co',
  config.key || 'missing-supabase-anon-key'
);

/**
 * Helper to manually set config in localStorage and reload
 */
export const saveSupabaseConfig = (url: string, key: string) => {
  localStorage.setItem('VITE_SUPABASE_URL', url);
  localStorage.setItem('VITE_SUPABASE_ANON_KEY', key);
  window.location.reload();
};

