const SidebarItem: React.FC<{ 
  to: string, 
  icon: React.ReactNode, 
  label: string, 
  onClick?: () => void 
}> = ({ to, icon, label, onClick }) => {
  const location = useLocation();
  const isActive = location.pathname === to;

  return (
    <Link
      to={to}
      onClick={onClick}
      className={`flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${
        isActive 
          ? 'bg-blue-600 text-white' 
          : 'text-gray-600 hover:bg-gray-100'
      }`}
    >
      {icon}
      <span className="font-medium">{label}</span>
    </Link>
  );
};

const PageLockModal: React.FC<{ 
  onSuccess: () => void;
  onCancel: () => void;
  correctPass: string;
}> = ({ onSuccess, onCancel, correctPass }) => {
  const [pass, setPass] = useState('');
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (pass === correctPass) {
      onSuccess();
    } else {
      setError(true);
      setPass('');
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[9999] p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm p-6" dir="rtl">
        <div className="flex flex-col items-center text-center mb-6">
          <div className="bg-amber-100 p-3 rounded-full mb-4">
            <Lock className="w-8 h-8 text-amber-600" />
          </div>
          <h3 className="text-xl font-bold text-gray-900">صفحة محمية</h3>
          <p className="text-gray-500 mt-1">يرجى إدخال كلمة مرور الصفحات للمتابعة</p>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <input
            autoFocus
            type="password"
            value={pass}
            onChange={(e) => {
              setPass(e.target.value);
              setError(false);
            }}
            className={`w-full px-4 py-3 rounded-xl border-2 text-center text-2xl tracking-widest focus:ring-4 focus:ring-blue-100 transition-all ${
              error ? 'border-red-500 bg-red-50' : 'border-gray-200 focus:border-blue-500'
            }`}
            placeholder="••••"
          />
          {error && <p className="text-red-500 text-sm text-center">كلمة المرور غير صحيحة</p>}
          <div className="grid grid-cols-2 gap-3">
            <button
              type="button"
              onClick={onCancel}
              className="px-4 py-3 bg-gray-100 text-gray-700 rounded-xl font-bold hover:bg-gray-200 transition-colors"
            >
              إلغاء
            </button>
            <button
              type="submit"
              className="px-4 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
            >
              دخول
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

