};

const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  const loggedUser = localStorage.getItem('flyyti_user');
  if (!loggedUser) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const SupabaseSetup: React.FC = () => {
  const [url, setUrl] = useState('');
  const [key, setKey] = useState('');

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (url && key) {
      saveSupabaseConfig(url, key);
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 p-6 text-center" dir="rtl">
      <div className="bg-white p-8 rounded-3xl shadow-xl max-w-lg w-full border-2 border-blue-50">
        <div className="bg-blue-50 p-4 rounded-full inline-block mb-6">
          <Database className="w-12 h-12 text-blue-600" />
        </div>
        <h1 className="text-2xl font-black text-gray-900 mb-2">إعداد الاتصال بقاعدة البيانات</h1>
        <p className="text-gray-500 mb-8 leading-relaxed">
          نظام Flyyti يتطلب الاتصال بـ <span className="text-blue-600 font-bold">Supabase</span> للعمل. يرجى إدخال بيانات المشروع أدناه.
        </p>

        <form onSubmit={handleSave} className="space-y-4 text-right">
          <div className="space-y-1">
            <label className="text-sm font-bold text-gray-700">Project URL</label>
            <input 
              type="text" 
              placeholder="https://your-id.supabase.co"
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-blue-500 outline-none"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              required
            />
          </div>
          <div className="space-y-1">
            <label className="text-sm font-bold text-gray-700">Anon Key</label>
            <input 
              type="password" 
              placeholder="eyJhbGciOiJIUzI1NiIsInR..."
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-blue-500 outline-none"
              value={key}
              onChange={(e) => setKey(e.target.value)}
              required
            />
          </div>

          <div className="pt-4">
            <button 
              type="submit"
              className="w-full py-4 bg-blue-600 text-white font-black text-lg rounded-2xl shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
            >
              حفظ والاتصال
              <ArrowRight size={20} className="rotate-180" />
            </button>
          </div>
        </form>

        <div className="mt-8 pt-6 border-t border-gray-100 flex items-center justify-center gap-4 text-xs font-bold text-gray-400">
          <a href="https://supabase.com" target="_blank" rel="noreferrer" className="hover:text-blue-600 flex items-center gap-1">
            Supabase.com <ExternalLink size={12} />
          </a>
          <span>•</span>
          <p>سيتم حفظ البيانات محلياً في متصفحك</p>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) {
        setSettings(data);
      } else {
        console.error("Database error:", error);
      }
    } catch (err) {
      console.error("Failed to connect to Supabase:", err);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) {
      setConfigMissing(true);
      setLoading(false);
    } else {
      fetchSettings();
    }
  }, [fetchSettings]);

  if (configMissing) {
    return <SupabaseSetup />;
  }

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 gap-4">
        <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-gray-500 font-bold animate-pulse">جاري التحميل...</p>
      </div>
    );
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
        <Route path="/*" element={
          <ProtectedRoute settings={settings}>
            <Layout settings={settings} refreshSettings={fetchSettings}>
              <Routes>
                <Route path="/" element={<POS />} />
                <Route path="/daily-reports" element={<DailyReports />} />
                <Route path="/inventory" element={<Inventory />} />
                <Route path="/categories" element={<Categories />} />
                <Route path="/expenses" element={<Expenses />} />
                <Route path="/invoices" element={<Invoices settings={settings} onUpdateSettings={fetchSettings} />} />
                <Route path="/reports" element={<GeneralReports />} />
                <Route path="/security" element={<Security settings={settings} onUpdate={fetchSettings} />} />
              </Routes>
            </Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

export default App;

payload.text:
لإعداد قاعدة البيانات الخاصة بنظام **Flyyti Mobile POS**، يجب عليك نسخ الكود الموجود في ملف `database.sql` ولصقه في **Supabase SQL Editor**.

إليك الكود كاملًا وجاهزًا للنسخ:

```sql
-- 1. حذف الجداول إذا كانت موجودة (للبدء من جديد)
DROP TABLE IF EXISTS extra_services;
DROP TABLE IF EXISTS invoice_items;
DROP TABLE IF EXISTS invoices;
DROP TABLE IF EXISTS variants;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS expenses;
DROP TABLE IF EXISTS purchases;
DROP TABLE IF EXISTS settings;

-- 2. جدول الأقسام
CREATE TABLE categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  parent_id UUID REFERENCES categories(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. جدول المنتجات
CREATE TABLE products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
  sub_category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
  supplier TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. جدول الأنواع (Variants)
CREATE TABLE variants (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id UUID REFERENCES products(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  barcode TEXT UNIQUE,
  cost_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  sale_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  stock_quantity INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. جدول الفواتير
CREATE TABLE invoices (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  total_amount DECIMAL(10,2) NOT NULL DEFAULT 0,
  discount DECIMAL(10,2) NOT NULL DEFAULT 0,
  net_amount DECIMAL(10,2) NOT NULL DEFAULT 0,
  total_cost DECIMAL(10,2) NOT NULL DEFAULT 0,
  profit DECIMAL(10,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 6. جدول بنود الفاتورة
CREATE TABLE invoice_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID REFERENCES invoices(id) ON DELETE CASCADE,
  variant_id UUID REFERENCES variants(id) ON DELETE SET NULL,
  product_name TEXT NOT NULL,
  variant_name TEXT,
  quantity INTEGER NOT NULL DEFAULT 1,
  cost_price DECIMAL(10,2) NOT NULL,
  sale_price DECIMAL(10,2) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 7. جدول الخدمات الإضافية
CREATE TABLE extra_services (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID REFERENCES invoices(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  cost_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  sale_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  quantity INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 8. جدول المصاريف
CREATE TABLE expenses (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  type TEXT NOT NULL,
  amount DECIMAL(10,2) NOT NULL,
  date DATE DEFAULT CURRENT_DATE,
  note TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 9. جدول المشتريات
CREATE TABLE purchases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  amount DECIMAL(10,2) NOT NULL,
  supplier TEXT,
  date DATE DEFAULT CURRENT_DATE,
  note TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 10. جدول الإعدادات والحماية
CREATE TABLE settings (
  id INTEGER PRIMARY KEY DEFAULT 1,
  username TEXT NOT NULL DEFAULT 'admin',
  password TEXT NOT NULL DEFAULT 'admin',
  page_password TEXT NOT NULL DEFAULT '1234',
  capital DECIMAL(10,2) NOT NULL DEFAULT 0,
  savings DECIMAL(10,2) NOT NULL DEFAULT 0,
  protection_enabled BOOLEAN DEFAULT TRUE,
  page_locks JSONB DEFAULT '{"inventory": true, "categories": true, "expenses": true, "invoices": true, "reports": true, "security": true}'::JSONB,
  profit_shares JSONB DEFAULT '{"mujahed": 60, "abboud": 20, "shop": 10, "special": 10}'::JSONB
);

-- 11. إضافة البيانات الافتراضية للإعدادات
INSERT INTO settings (id, username, password, page_password) 
VALUES (1, 'admin', 'admin', '1234')
ON CONFLICT (id) DO NOTHING;

-- 12. تفعيل الحماية (RLS) وسياسات الوصول
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
ALTER TABLE variants ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoice_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE extra_services ENABLE ROW LEVEL SECURITY;
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY;
ALTER TABLE purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE settings ENABLE ROW LEVEL SECURITY;

-- سياسات وصول عامة (للتطوير)
CREATE POLICY "Full access" ON categories FOR ALL USING (true);
CREATE POLICY "Full access" ON products FOR ALL USING (true);
CREATE POLICY "Full access" ON variants FOR ALL USING (true);
CREATE POLICY "Full access" ON invoices FOR ALL USING (true);
CREATE POLICY "Full access" ON invoice_items FOR ALL USING (true);
CREATE POLICY "Full access" ON extra_services FOR ALL USING (true);
CREATE POLICY "Full access" ON expenses FOR ALL USING (true);
CREATE POLICY "Full access" ON purchases FOR ALL USING (true);
CREATE POLICY "Full access" ON settings FOR ALL USING (true);
```

### الخطوات:
1. انسخ الكود أعلاه.
2. اذهب إلى لوحة تحكم **Supabase**.
3. من القائمة الجانبية اليسرى، اختر **SQL Editor**.
4. انقر على **New Query**.
5. الصق الكود في المحرر.
6. اضغط على زر **Run** (أو `Ctrl + Enter`).

بعد التنفيذ بنجاح، ستكون جميع الجداول جاهزة، ويمكنك تسجيل الدخول بـ `admin` وكلمة مرور `admin`.

