const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) {
        setSettings(data);
      } else {
        console.error("Database error:", error);
      }
    } catch (err) {
      console.error("Failed to connect to Supabase:", err);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) {
      setConfigMissing(true);
      setLoading(false);
    } else {
      fetchSettings();
    }
  }, [fetchSettings]);

  if (configMissing) {
    return <SupabaseSetup />;
  }

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 gap-6">
        <div className="relative">
          <div className="w-20 h-20 border-8 border-indigo-100 rounded-full"></div>
          <div className="w-20 h-20 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin absolute top-0 left-0"></div>
        </div>
        <p className="text-slate-900 font-black text-xl animate-pulse tracking-tight">Flyyti POS تجري الآن مزامنة بياناتك...</p>
      </div>
    );
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
        <Route path="/*" element={
          <ProtectedRoute settings={settings}>
            <Layout settings={settings} refreshSettings={fetchSettings}>
              <Routes>
                <Route path="/" element={<POS />} />
                <Route path="/daily-reports" element={<DailyReports />} />
                <Route path="/inventory" element={<Inventory />} />
                <Route path="/categories" element={<Categories />} />
                <Route path="/expenses" element={<Expenses />} />
                <Route path="/invoices" element={<Invoices settings={settings} onUpdateSettings={fetchSettings} />} />
                <Route path="/reports" element={<GeneralReports />} />
                <Route path="/security" element={<Security settings={settings} onUpdate={fetchSettings} />} />
              </Routes>
            </Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  PlusCircle, 
  Printer, 
  CheckCircle2, 
  ShoppingBag,
  Info,
  X,
  CreditCard
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, ExtraService } from '../types';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [cart, setCart] = useState<any[]>([]);
  const [discount, setDiscount] = useState(0);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [extraService, setExtraService] = useState<ExtraService>({
    name: '',
    cost_price: 0,
    sale_price: 0,
    quantity: 1
  });
  const [loading, setLoading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<any>(null);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchProducts();
    barcodeInputRef.current?.focus();
  }, []);

  const fetchProducts = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('products')
      .select(`
        *,
        variants (*)
      `);
    if (!error) setProducts(data || []);
    setLoading(false);
  };

  const addToCart = (variant: Variant, product: any) => {
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, {
        variant_id: variant.id,
        product_name: product.name,
        variant_name: variant.name,
        cost_price: variant.cost_price,
        sale_price: variant.sale_price,
        quantity: 1,
        type: 'product'
      }];
    });
    setSearchTerm('');
  };

  const addExtraToCart = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setCart(prev => [...prev, {
      ...extraService,
      type: 'service',
      id: Math.random().toString(36).substr(2, 9)
    }]);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
    setShowExtraModal(false);
  };

  const updateQuantity = (id: string, type: 'product' | 'service', delta: number) => {
    setCart(prev => prev.map(item => {
      const itemId = type === 'product' ? item.variant_id : item.id;
      if (itemId === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'product' | 'service') => {
    setCart(prev => prev.filter(item => {
      const itemId = type === 'product' ? item.variant_id : item.id;
      return itemId !== id;
    }));
  };

  const calculateTotal = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    return Math.max(0, subtotal - discount);
  };

  const calculateCost = () => {
    return cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);
  };

  const filteredProducts = products.flatMap(p => 
    (p.variants || []).map((v: Variant) => ({ ...v, productName: p.name, supplier: p.supplier }))
  ).filter(v => 
    v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (v.barcode && v.barcode.includes(searchTerm))
  );

  const handleCheckout = async () => {
    if (cart.length === 0) return;
    setIsProcessing(true);

    const net_amount = calculateTotal();
    const total_cost = calculateCost();
    const profit = net_amount - total_cost;

    const { data: invoice, error: invError } = await supabase
      .from('invoices')
      .insert({
        total_amount: net_amount + discount,
        discount,
        net_amount,
        total_cost,
        profit
      })
      .select()
      .single();

    if (invError) {
      alert("خطأ في حفظ الفاتورة");
      setIsProcessing(false);
      return;
    }

    const items = cart.filter(i => i.type === 'product').map(i => ({
      invoice_id: invoice.id,
      variant_id: i.variant_id,
      product_name: i.product_name,
      variant_name: i.variant_name,
      quantity: i.quantity,
      cost_price: i.cost_price,
      sale_price: i.sale_price
    }));

    const services = cart.filter(i => i.type === 'service').map(i => ({
      invoice_id: invoice.id,
      name: i.name,
      cost_price: i.cost_price,
      sale_price: i.sale_price,
      quantity: i.quantity
    }));

    if (items.length > 0) await supabase.from('invoice_items').insert(items);
    if (services.length > 0) await supabase.from('extra_services').insert(services);

    // Update Inventory
    for (const item of items) {
      const { data: variant } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
      if (variant) {
        await supabase.from('variants').update({ stock_quantity: variant.stock_quantity - item.quantity }).eq('id', item.variant_id);
      }
    }

    setLastInvoice({ ...invoice, items: cart });
    setCart([]);
    setDiscount(0);
    setIsProcessing(false);

    // Auto print trigger
    setTimeout(() => window.print(), 500);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-full relative" dir="rtl">
      {/* Product Selection Area */}
      <div className="flex-1 flex flex-col gap-6 no-print">
        <div className="relative group">
          <input
            ref={barcodeInputRef}
            type="text"
            placeholder="ابحث بالاسم، المورد، أو امسح الباركود..."
            className="w-full pr-14 pl-6 py-5 bg-white border-2 border-slate-200 rounded-[1.5rem] focus:border-indigo-600 focus:ring-8 focus:ring-indigo-50 transition-all outline-none text-xl font-bold shadow-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors" size={28} />
        </div>

        <div className="flex-1 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-5 p-1">
          {filteredProducts.map(v => (
            <button
              key={v.id}
              onClick={() => {
                const p = products.find(prod => prod.id === v.product_id);
                addToCart(v, p);
              }}
              className="group bg-white p-5 rounded-[2rem] border-2 border-transparent hover:border-indigo-600 hover:shadow-2xl hover:-translate-y-1 transition-all text-right flex flex-col gap-3 relative overflow-hidden shadow-sm border-slate-100"
            >
              <div className="flex justify-between items-start">
                <span className={`text-[10px] font-black px-3 py-1 rounded-xl uppercase tracking-tighter ${v.stock_quantity > 0 ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'}`}>
                  {v.stock_quantity > 0 ? `${v.stock_quantity} متوفر` : 'نفذت'}
                </span>
                {v.barcode && <span className="text-[10px] text-slate-400 font-mono tracking-tighter">{v.barcode}</span>}
              </div>
              <div>
                <h3 className="font-black text-slate-900 text-lg truncate leading-tight">{v.productName}</h3>
                <p className="text-sm text-slate-500 font-bold truncate">{v.name}</p>
              </div>
              <p className="text-2xl font-black text-indigo-600 mt-2">{v.sale_price} <span className="text-sm">₪</span></p>

              <div className="absolute bottom-0 right-0 p-3 bg-indigo-600 text-white translate-y-full group-hover:translate-y-0 transition-transform rounded-tr-[1.5rem]">
                <Plus size={20} />
              </div>
            </button>
          ))}
          {filteredProducts.length === 0 && !loading && (
            <div className="col-span-full py-20 flex flex-col items-center text-slate-400">
              <div className="bg-slate-100 p-6 rounded-full mb-4">
                <Search size={40} />
              </div>
              <p className="font-black text-xl">لا توجد منتجات مطابقة للبحث</p>
            </div>
          )}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className="w-full lg:w-[420px] flex flex-col bg-white rounded-[2.5rem] border border-slate-200 shadow-2xl overflow-hidden no-print">
        <div className="p-8 bg-slate-900 text-white flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-900/50">
              <ShoppingBag size={24} />
            </div>
            <h2 className="text-xl font-black tracking-tight">قائمة الطلبات</h2>
          </div>
          <span className="bg-white/10 text-white px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest">
            {cart.length} أصناف
          </span>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-5 bg-slate-50/50">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-6 opacity-40">
              <ShoppingBag size={80} />
              <p className="font-black text-2xl">السلة فارغة حالياً</p>
            </div>
          ) : (
            cart.map((item) => (
              <div key={item.type === 'product' ? item.variant_id : item.id} className="flex flex-col gap-3 p-5 bg-white rounded-3xl border border-slate-100 group shadow-sm hover:shadow-md transition-shadow">
                <div className="flex justify-between items-start">
                  <div className="max-w-[70%]">
                    <h4 className="font-black text-slate-900 leading-none mb-1">{item.product_name || item.name}</h4>
                    {item.variant_name && <p className="text-xs text-slate-500 font-bold">{item.variant_name}</p>}
                    {item.type === 'service' && <span className="inline-block mt-1 text-[9px] font-black text-amber-700 bg-amber-100 px-2 py-0.5 rounded-lg uppercase tracking-widest">Extra Service</span>}
                  </div>
                  <button 
                    onClick={() => removeFromCart(item.type === 'product' ? item.variant_id : item.id, item.type)}
                    className="p-2 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
                <div className="flex items-center justify-between pt-2 border-t border-slate-50">
                  <div className="flex items-center gap-4 bg-slate-100 p-1 rounded-2xl">
                    <button 
                      onClick={() => updateQuantity(item.type === 'product' ? item.variant_id : item.id, item.type, -1)}
                      className="w-10 h-10 flex items-center justify-center bg-white text-slate-900 rounded-xl shadow-sm hover:bg-indigo-50 hover:text-indigo-600 transition-all"
                    >
                      <Minus size={18} />
                    </button>
                    <span className="font-black text-slate-900 text-lg min-w-[30px] text-center">{item.quantity}</span>
                    <button 
                      onClick={() => updateQuantity(item.type === 'product' ? item.variant_id : item.id, item.type, 1)}
                      className="w-10 h-10 flex items-center justify-center bg-white text-slate-900 rounded-xl shadow-sm hover:bg-indigo-50 hover:text-indigo-600 transition-all"
                    >
                      <Plus size={18} />
                    </button>
                  </div>
                  <p className="font-black text-indigo-700 text-xl">{item.sale_price * item.quantity} ₪</p>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-8 bg-white border-t border-slate-100 space-y-6">
          <div className="flex gap-4">
            <button 
              onClick={() => setShowExtraModal(true)}
              className="flex-1 py-4 bg-amber-50 text-amber-800 font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-amber-100 transition-colors border border-amber-100 shadow-sm"
            >
              <PlusCircle size={20} />
              <span>خدمة إضافية</span>
            </button>
            <div className="flex-1 relative">
              <input 
                type="number" 
                placeholder="خصم ₪"
                className="w-full py-4 pr-6 pl-12 bg-slate-50 border border-slate-200 rounded-2xl focus:border-indigo-600 outline-none font-black text-xl text-center"
                value={discount || ''}
                onChange={(e) => setDiscount(Number(e.target.value))}
              />
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 text-sm font-black">₪</span>
            </div>
          </div>

          <div className="space-y-3 pt-4 border-t border-slate-100">
            <div className="flex justify-between text-slate-500 font-bold">
              <span>المجموع الفرعي</span>
              <span>{cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0)} ₪</span>
            </div>
            {discount > 0 && (
              <div className="flex justify-between text-red-600 font-black">
                <span>إجمالي الخصم</span>
                <span>-{discount} ₪</span>
              </div>
            )}
            <div className="flex justify-between items-center pt-4">
              <span className="text-2xl font-black text-slate-900">إجمالي الصافي</span>
              <span className="text-4xl font-black text-indigo-600">{calculateTotal()} <span className="text-xl">₪</span></span>
            </div>
          </div>

          <button
            onClick={handleCheckout}
            disabled={isProcessing || cart.length === 0}
            className="w-full py-5 bg-indigo-600 text-white font-black text-2xl rounded-[1.5rem] shadow-2xl shadow-indigo-200 hover:bg-indigo-700 active:scale-[0.98] transition-all flex items-center justify-center gap-4 disabled:bg-slate-200 disabled:text-slate-400 disabled:shadow-none"
          >
            {isProcessing ? (
              <div className="w-8 h-8 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <>
                <CreditCard size={28} />
                <span>إتمام الدفع وطباعة</span>
              </>
            )}
          </button>
        </div>
      </div>
      {/* Modals and Printing View follow the same updated visual style... */}
    </div>
  );
};

