import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ArrowUpRight,
  ChevronLeft,
  ChevronRight,
  Target
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());
  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    soldItems: [] as any[],
    services: [] as any[]
  });
  const [loading, setLoading] = useState(true);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`
        *,
        invoice_items (*),
        extra_services (*)
      `)
      .gte('created_at', start)
      .lte('created_at', end);

    if (invoices) {
      const stats = invoices.reduce((acc, inv) => {
        acc.totalSales += Number(inv.net_amount);
        acc.totalCost += Number(inv.total_cost);
        acc.totalProfit += Number(inv.profit);
        acc.discounts += Number(inv.discount);

        inv.invoice_items.forEach((item: any) => {
          acc.itemsCount += item.quantity;
          acc.soldItems.push(item);
        });

        inv.extra_services.forEach((ser: any) => {
          acc.itemsCount += ser.quantity;
          acc.services.push(ser);
        });

        return acc;
      }, { totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, soldItems: [], services: [] });

      setData(stats);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchDailyData(selectedDay);
  }, [selectedDay]);

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);

  return (
    <div className="space-y-10" dir="rtl">
      {/* Advanced Day Selector */}
      <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-xl overflow-x-auto scrollbar-hide">
        <div className="flex items-center gap-6">
          <div className="p-4 bg-indigo-600 text-white rounded-[1.2rem] shadow-lg shadow-indigo-100">
            <Calendar size={28} />
          </div>
          <div className="flex gap-3">
            {daysInMonth.map(day => (
              <button
                key={day}
                onClick={() => setSelectedDay(day)}
                className={`min-w-[60px] h-16 rounded-2xl font-black transition-all flex flex-col items-center justify-center ${
                  selectedDay === day 
                  ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-200 -translate-y-1' 
                  : 'bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-600'
                }`}
              >
                <span className="text-[10px] opacity-70 mb-1 uppercase tracking-tighter">اليوم</span>
                <span className="text-xl leading-none">{day}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Financial Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-6">
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm space-y-6 hover:shadow-lg transition-shadow">
          <div className="flex justify-between items-center">
            <div className="p-4 bg-indigo-50 text-indigo-700 rounded-2xl">
