import React, { useState } from 'react';
import { Lock, Shield, User, Key, Save, CheckCircle2, ShieldOff } from 'lucide-react';
import { supabase } from '../supabase';
import type { AppSettings } from '../types';

const Security: React.FC<{ settings: AppSettings | null, onUpdate: () => void }> = ({ settings, onUpdate }) => {
  const [form, setForm] = useState({
    username: settings?.username || '',
    password: '',
    confirmPassword: '',
    page_password: settings?.page_password || '',
  });
  const [locks, setLocks] = useState<Record<string, boolean>>(settings?.page_locks || {});
  const [protectionEnabled, setProtectionEnabled] = useState(settings?.protection_enabled ?? true);
  const [saving, setSaving] = useState(false);

  const pages = [
    { id: 'inventory', label: 'المستودع والمخازن' },
    { id: 'categories', label: 'تصنيفات الأصناف' },
    { id: 'expenses', label: 'إدارة المصاريف' },
    { id: 'invoices', label: 'سجل الفواتير' },
    { id: 'reports', label: 'التقارير المالية' },
    { id: 'security', label: 'إعدادات النظام' },
  ];

  const handleSaveCredentials = async (e: React.FormEvent) => {
    e.preventDefault();
    if (form.password && form.password !== form.confirmPassword) {
      alert("كلمات المرور غير متطابقة");
      return;
    }

    setSaving(true);
    const updateData: any = { username: form.username, page_password: form.page_password };
    if (form.password) updateData.password = form.password;

    await supabase.from('settings').update(updateData).eq('id', 1);
    onUpdate();
    setSaving(false);
    alert("تم تحديث إعدادات الوصول بنجاح");
  };

  const handleToggleLock = async (pageId: string) => {
    const newLocks = { ...locks, [pageId]: !locks[pageId] };
    setLocks(newLocks);
    await supabase.from('settings').update({ page_locks: newLocks }).eq('id', 1);
    onUpdate();
  };

  const handleToggleProtection = async () => {
    const newVal = !protectionEnabled;
    setProtectionEnabled(newVal);
    await supabase.from('settings').update({ protection_enabled: newVal }).eq('id', 1);
    onUpdate();
  };

  return (
    <div className="max-w-4xl mx-auto space-y-10 pb-20" dir="rtl">
      {/* User Access Settings */}
      <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-xl space-y-10">
        <div className="flex items-center gap-6">
          <div className="p-5 bg-indigo-600 text-white rounded-[1.5rem] shadow-xl shadow-indigo-100">
            <User size={32} />
          </div>
          <div>
            <h3 className="text-2xl font-black text-slate-900 tracking-tight">إعدادات الهوية والوصول</h3>
            <p className="text-slate-500 font-bold">إدارة بيانات الدخول وكلمات المرور للنظام</p>
          </div>
        </div>

        <form onSubmit={handleSaveCredentials} className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-3">
            <label className="text-sm font-black text-slate-700 mr-2 uppercase tracking-widest">اسم المستخدم الأساسي</label>
            <div className="relative group">
              <input 
                type="text" 
                className="w-full p-5 pr-14 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 focus:bg-white outline-none font-bold transition-all" 
                value={form.username}
                onChange={(e) => setForm({...form, username: e.target.value})}
              />
              <User className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-600" size={24} />
            </div>
          </div>
          <div className="space-y-3">
            <label className="text-sm font-black text-slate-700 mr-2 uppercase tracking-widest">رمز حماية الصفحات (PIN)</label>
            <div className="relative group">
              <input 
                type="text" 
                className="w-full p-5 pr-14 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 focus:bg-white outline-none font-black text-2xl tracking-[0.3em] transition-all" 
                value={form.page_password}
                onChange={(e) => setForm({...form, page_password: e.target.value})}
              />
              <Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-600" size={24} />
            </div>
          </div>
          <div className="space-y-3">
            <label className="text-sm font-black text-slate-700 mr-2 uppercase tracking-widest">كلمة مرور جديدة</label>
            <div className="relative group">
              <input 
                type="password" 
                className="w-full p-5 pr-14 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 focus:bg-white outline-none font-bold transition-all" 
                placeholder="تجاهل لعدم التغيير"
                value={form.password}
                onChange={(e) => setForm({...form, password: e.target.value})}
              />
              <Key className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-600" size={24} />
            </div>
          </div>
          <div className="space-y-3">
            <label className="text-sm font-black text-slate-700 mr-2 uppercase tracking-widest">تأكيد كلمة المرور</label>
            <div className="relative group">
              <input 
                type="password" 
                className="w-full p-5 pr-14 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 focus:bg-white outline-none font-bold transition-all" 
                value={form.confirmPassword}
                onChange={(e) => setForm({...form, confirmPassword: e.target.value})}
              />
              <CheckCircle2 className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-600" size={24} />
            </div>
          </div>
          <div className="md:col-span-2 pt-6">
            <button 
              disabled={saving}
              type="submit"
              className="w-full py-5 bg-indigo-600 text-white font-black text-xl rounded-[1.5rem] shadow-2xl shadow-indigo-200 hover:bg-indigo-700 hover:-translate-y-1 active:translate-y-0 transition-all flex items-center justify-center gap-4 disabled:bg-slate-200 disabled:shadow-none"
            >
              <Save size={28} />
              تحديث إعدادات الأمان
            </button>
          </div>
        </form>
      </div>

      {/* Page Protection Logic */}
      <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-xl space-y-10">
        <div className="flex items-center justify-between flex-wrap gap-6">
          <div className="flex items-center gap-6">
            <div className={`p-5 rounded-[1.5rem] shadow-xl transition-all ${protectionEnabled ? 'bg-amber-100 text-amber-700 shadow-amber-50' : 'bg-slate-100 text-slate-300 shadow-none'}`}>
              <Shield size={32} />
            </div>
            <div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight">نظام حماية الواجهات</h3>
              <p className="text-slate-500 font-bold">التحكم في الأقسام التي تتطلب رمز PIN للوصول</p>
            </div>
          </div>
          <button 
            onClick={handleToggleProtection}
            className={`px-8 py-3 rounded-2xl font-black transition-all flex items-center gap-3 border-2 ${protectionEnabled ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-slate-50 border-slate-200 text-slate-400'}`}
          >
            {protectionEnabled ? <Shield size={20} /> : <ShieldOff size={20} />}
            {protectionEnabled ? 'نظام الحماية: مفعل' : 'نظام الحماية: معطل'}
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {pages.map(page => (
            <div 
              key={page.id} 
              className={`p-6 rounded-[1.5rem] border-2 transition-all flex items-center justify-between group ${locks[page.id] && protectionEnabled ? 'bg-indigo-50/50 border-indigo-200 shadow-inner' : 'bg-slate-50 border-slate-100'}`}
            >
              <div className="flex items-center gap-5">
                <div className={`p-4 rounded-2xl transition-all ${locks[page.id] && protectionEnabled ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-white text-slate-200 shadow-sm border border-slate-100'}`}>
                  <Lock size={22} />
                </div>
                <span className={`font-black text-lg ${locks[page.id] && protectionEnabled ? 'text-indigo-900' : 'text-slate-400'}`}>{page.label}</span>
              </div>

              <button 
                disabled={!protectionEnabled}
                onClick={() => handleToggleLock(page.id)}
                className={`relative inline-flex h-8 w-14 items-center rounded-full transition-all focus:outline-none ${locks[page.id] && protectionEnabled ? 'bg-indigo-600' : 'bg-slate-300'} ${!protectionEnabled && 'opacity-20 cursor-not-allowed'}`}
              >
                <span className={`inline-block h-6 w-6 transform rounded-full bg-white transition-all shadow-md ${locks[page.id] ? '-translate-x-7' : '-translate-x-1'}`} />
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Security;

