  const [products, setProducts] = useState<any[]>([]);
  const [cart, setCart] = useState<any[]>([]);
  const [discount, setDiscount] = useState(0);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [extraService, setExtraService] = useState<ExtraService>({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });

  const fetchProducts = async () => {
    const { data } = await supabase.from('products').select('*, variants(*)');
    setProducts(data || []);
  };

  useEffect(() => { fetchProducts(); }, []);

  const addToCart = (variant: Variant, product: any) => {
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) return prev.map(item => item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { variant_id: variant.id, product_name: product.name, variant_name: variant.name, cost_price: variant.cost_price, sale_price: variant.sale_price, quantity: 1, type: 'product' }];
    });
  };

  const calculateTotal = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    return Math.max(0, subtotal - discount);
  };

  const filteredProducts = products.flatMap(p => (p.variants || []).map((v: any) => ({ ...v, productName: p.name })))
    .filter(v => v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || (v.barcode && v.barcode.includes(searchTerm)));

