            <Calendar size={28} />
          </div>
          <div className="flex gap-3">
            {daysInMonth.map(day => (
              <button
                key={day}
                onClick={() => setSelectedDay(day)}
                className={`min-w-[64px] h-16 rounded-2xl font-black transition-all flex flex-col items-center justify-center ${
                  selectedDay === day 
                  ? 'bg-emerald-600 text-white shadow-xl shadow-emerald-900/40 -translate-y-1' 
                  : 'bg-white/5 text-slate-400 hover:bg-white/10 hover:text-white'
                }`}
              >
                <span className="text-[10px] opacity-60 mb-1 uppercase tracking-tighter">اليوم</span>
                <span className="text-xl leading-none">{day}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Stats Cards (Luxury Emerald & Midnight) */}
      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-5 gap-6">
        {[
          { label: 'إجمالي المبيعات', value: data.totalSales, icon: TrendingUp, color: 'emerald' },
          { label: 'إجمالي التكاليف', value: data.totalCost, icon: DollarSign, color: 'slate' },
          { label: 'صافي الأرباح', value: data.totalProfit, icon: Target, color: 'emerald', highlight: true },
          { label: 'القطع المباعة', value: data.itemsCount, icon: Package, color: 'slate' },
          { label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'rose' }
        ].map((stat, i) => (
          <div key={i} className={`p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-4 hover:shadow-xl transition-all ${stat.highlight ? 'bg-[#0f172a] text-white ring-4 ring-emerald-600/20' : 'bg-white text-slate-900'}`}>
            <div className={`p-4 inline-block rounded-2xl ${stat.highlight ? 'bg-emerald-600 text-white' : 'bg-slate-50 text-slate-400'}`}>
