                    {(item.sale_price - item.cost_price) * item.quantity} ₪
                  </td>
                </tr>
              ))}
              {data.soldItems.length === 0 && (
                <tr><td colSpan={5} className="p-20 text-center text-slate-300 font-black text-xl opacity-50">لا توجد مبيعات في هذا اليوم</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

