            className="px-8 py-5 bg-emerald-600 text-white font-black rounded-3xl shadow-lg shadow-emerald-900/20 hover:bg-emerald-500 transition-all flex items-center justify-center gap-2 whitespace-nowrap"
          >
            <PlusCircle size={24} />
            إضافة خدمة
          </button>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 lg:gap-6 overflow-y-auto custom-scrollbar pr-1">
          {filteredProducts.map(v => (
            <button 
              key={v.id} 
              onClick={() => { const p = products.find(prod => prod.id === v.product_id); addToCart(v, p); }}
              className="group bg-white p-5 rounded-[2.5rem] border-2 border-transparent hover:border-emerald-600 hover:shadow-2xl transition-all text-right flex flex-col gap-3 relative overflow-hidden shadow-sm active:scale-95 border-slate-50"
            >
              <div className="flex justify-between items-start">
                <span className={`text-[10px] font-black px-3 py-1 rounded-xl uppercase tracking-tighter ${v.stock_quantity > 0 ? 'bg-emerald-50 text-emerald-700' : 'bg-rose-50 text-rose-700'}`}>
                  {v.stock_quantity > 0 ? `${v.stock_quantity} متاح` : 'نافذ'}
                </span>
                {v.barcode && <span className="text-[10px] text-slate-300 font-mono">{v.barcode}</span>}
              </div>
              <div>
                <h3 className="font-black text-slate-900 text-base leading-tight truncate">{v.productName}</h3>
                <p className="text-xs text-slate-400 font-bold truncate">{v.name}</p>
              </div>
              <p className="text-2xl font-black text-emerald-600 mt-2">{v.sale_price} <span className="text-sm font-bold">₪</span></p>
              <div className="absolute bottom-0 left-0 p-3 bg-emerald-600 text-white translate-x-full group-hover:translate-x-0 transition-transform rounded-tr-3xl">
                <Plus size={20} />
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className={`w-full lg:w-[440px] bg-white rounded-[3rem] border border-slate-100 shadow-2xl flex flex-col overflow-hidden ${activeTab === 'products' ? 'hidden lg:flex' : 'flex'}`}>
        <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-emerald-600 rounded-2xl shadow-lg shadow-emerald-900/30">
               <ShoppingBag size={24} />
            </div>
            <span className="font-black text-xl tracking-tight">تفاصيل الفاتورة</span>
          </div>
          <span className="bg-white/10 px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest">{cart.length} أصناف</span>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 opacity-60 py-20">
              <ShoppingBag size={80} className="mb-6 stroke-[1.5]" />
              <p className="font-black text-2xl text-slate-900">سلتك فارغة</p>
              <p className="text-sm font-bold mt-2">ابدأ بإضافة منتجات للبيع</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col gap-3 group">
                <div className="flex justify-between items-start">
                  <div className="max-w-[70%]">
                    <h4 className="font-black text-slate-900 text-base leading-tight">{item.product_name}</h4>
                    <p className="text-xs text-slate-400 font-bold">{item.variant_name}</p>
                  </div>
                  <p className="font-black text-emerald-600 text-lg">{item.sale_price * item.quantity} ₪</p>
                </div>
                <div className="flex items-center justify-between pt-2 border-t border-slate-50">
                  <div className="flex items-center gap-4 bg-slate-50 p-1.5 rounded-2xl">
                    <button 
                      onClick={() => updateQuantity(item.variant_id, -1, idx)}
                      className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-900 hover:text-emerald-600 transition-all active:scale-90"
                    >
                      <Minus size={18} />
                    </button>
                    <span className="font-black text-lg min-w-[30px] text-center">{item.quantity}</span>
                    <button 
                      onClick={() => updateQuantity(item.variant_id, 1, idx)}
                      className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-900 hover:text-emerald-600 transition-all active:scale-90"
                    >
                      <Plus size={18} />
                    </button>
                  </div>
                  <button 
                    onClick={() => removeFromCart(idx)}
                    className="p-3 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                  >
                    <Trash2 size={20} />
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-8 bg-white border-t border-slate-100 space-y-6 shrink-0">
          <div className="flex gap-4">
             <div className="flex-1 space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-2">تطبيق خصم مباشر</label>
                <div className="relative">
                  <input type="number" placeholder="0" className="w-full py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none text-center font-black text-lg focus:border-emerald-600 transition-all" onChange={(e) => setDiscount(Number(e.target.value))} />
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 font-black text-sm">₪</span>
                </div>
             </div>
          </div>

          <div className="space-y-3 pt-2">
            <div className="flex justify-between items-center px-2">
              <span className="text-slate-400 font-black text-xs uppercase tracking-widest">إجمالي المبلغ</span>
              <span className="text-slate-900 font-black text-xl">{calculateTotal() + discount} ₪</span>
            </div>
            {discount > 0 && (
              <div className="flex justify-between items-center px-2">
                <span className="text-rose-500 font-black text-xs uppercase tracking-widest">خصم مطبق</span>
                <span className="text-rose-500 font-black text-xl">-{discount} ₪</span>
              </div>
            )}
            <div className="flex justify-between items-center pt-4 border-t border-slate-50 px-2">
              <span className="text-slate-900 font-black text-sm uppercase tracking-widest">المبلغ الصافي</span>
              <span className="text-4xl font-black text-emerald-600 leading-none">{calculateTotal()} <span className="text-base">₪</span></span>
            </div>
          </div>

          <button className="w-full py-5 bg-emerald-600 text-white font-black text-2xl rounded-[1.75rem] shadow-2xl shadow-emerald-900/30 hover:bg-emerald-500 active:scale-[0.98] transition-all flex items-center justify-center gap-4">
             <CreditCard size={28} />
             <span>إتمام الطلب</span>
          </button>
        </div>
      </div>

      {/* Extra Service Modal */}
      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/80 backdrop-blur-md flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg overflow-hidden border border-slate-100 animate-slide-in-right">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-emerald-600 rounded-2xl"><PlusCircle size={24} /></div>
                <h3 className="text-xl font-black">إضافة خدمة خارجية</h3>
              </div>
              <button onClick={() => setShowExtraModal(false)} className="p-2 bg-white/10 rounded-xl hover:bg-white/20 transition-all"><X size={20} /></button>
            </div>

            <div className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-700 mr-2">اسم الخدمة</label>
                <input 
                  type="text" 
                  className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" 
                  placeholder="مثال: توصيل، تركيب..."
                  value={extraService.name}
                  onChange={(e) => setExtraService({...extraService, name: e.target.value})}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">سعر التكلفة</label>
                  <input 
                    type="number" 
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" 
                    value={extraService.cost_price || ''}
                    onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">سعر البيع</label>
                  <input 
                    type="number" 
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" 
                    value={extraService.sale_price || ''}
                    onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})}
                  />
                </div>
              </div>

              <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-start gap-3">
                <AlertCircle className="text-emerald-600 shrink-0 mt-0.5" size={18} />
                <p className="text-xs text-emerald-800 font-bold leading-relaxed">الخدمات الخارجية يتم تسجيلها في الفاتورة وحساب أرباحها بشكل منفصل عن المخزون.</p>
              </div>

              <button 
                onClick={handleAddExtraService}
                disabled={!extraService.name || extraService.sale_price <= 0}
                className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl shadow-emerald-900/20 hover:bg-emerald-500 transition-all disabled:bg-slate-200 disabled:shadow-none"
              >
                إضافة للسلة
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  PlusCircle, 
  ShoppingBag,
  CreditCard,
  X,
  AlertCircle,
  LayoutGrid,
  ChevronLeft,
  CheckCircle2,
  Loader2
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, ExtraService, Category } from '../types';

const POS: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cart'>('products');
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);

  // Persistent Cart Logic
  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(0);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const addToCart = (variant: Variant, product: any) => {
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);
    const netAmount = Math.max(0, subtotal - discount);
    const profit = netAmount - totalCost;
    return { subtotal, totalCost, netAmount, profit };
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);

    try {
      const { netAmount, totalCost, profit, subtotal } = calculateTotals();

      // 1. Create Invoice
      const { data: invoice, error: invError } = await supabase
        .from('invoices')
        .insert({
          total_amount: subtotal,
          discount: discount,
          net_amount: netAmount,
          total_cost: totalCost,
          profit: profit
        })
        .select()
        .single();

      if (invError) throw invError;

      // 2. Insert Items and Services
      const productsInCart = cart.filter(c => c.type === 'product');
      const servicesInCart = cart.filter(c => c.type === 'service');

      if (productsInCart.length > 0) {
        const itemsToInsert = productsInCart.map(item => ({
          invoice_id: invoice.id,
          variant_id: item.variant_id,
          product_name: item.product_name,
          variant_name: item.variant_name,
          quantity: item.quantity,
          cost_price: item.cost_price,
          sale_price: item.sale_price
        }));
        await supabase.from('invoice_items').insert(itemsToInsert);

        // Update Stock
        for (const item of productsInCart) {
          const { data: variant } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (variant) {
            await supabase.from('variants').update({ stock_quantity: variant.stock_quantity - item.quantity }).eq('id', item.variant_id);
          }
        }
      }

      if (servicesInCart.length > 0) {
        const servicesToInsert = servicesInCart.map(ser => ({
          invoice_id: invoice.id,
          name: ser.product_name,
          cost_price: ser.cost_price,
          sale_price: ser.sale_price,
          quantity: ser.quantity
        }));
        await supabase.from('extra_services').insert(servicesToInsert);
      }

      // Success Reset
      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
      fetchData(); // Refresh stock in UI
    } catch (error) {
      console.error(error);
      alert("حدث خطأ أثناء إتمام الطلب");
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = products.flatMap(p => (p.variants || []).map((v: any) => ({ 
    ...v, 
    productName: p.name, 
    categoryId: p.category_id, 
    subCategoryId: p.sub_category_id 
  })))
    .filter(v => {
      const matchSearch = v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || (v.barcode && v.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? v.categoryId === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? v.subCategoryId === selectedSubCat : true;
      return matchSearch && matchMainCat && matchSubCat;
    });

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);

  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full font-['Tajawal']" dir="rtl">

      {/* Category Sidebar - Desktop */}
      <aside className="hidden lg:flex flex-col w-64 bg-white border border-slate-100 rounded-[2.5rem] shadow-sm overflow-hidden shrink-0">
        <div className="p-6 bg-[#0f172a] text-white flex items-center gap-3">
          <LayoutGrid size={20} className="text-emerald-500" />
          <span className="font-black">الأقسام</span>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
          <button 
            onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }}
            className={`w-full text-right p-4 rounded-2xl font-black text-sm transition-all ${!selectedMainCat ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            الكل
          </button>
          {mainCategories.map(cat => (
            <div key={cat.id} className="space-y-1">
              <button 
                onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
                className={`w-full text-right p-4 rounded-2xl font-black text-sm transition-all flex items-center justify-between ${selectedMainCat === cat.id ? 'bg-[#0f172a] text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                {cat.name}
                <ChevronLeft size={16} className={`transition-transform ${selectedMainCat === cat.id ? 'rotate-[-90deg]' : ''}`} />
              </button>

              {selectedMainCat === cat.id && subCategories.length > 0 && (
                <div className="mr-4 space-y-1 border-r-2 border-slate-100 pr-2 py-1">
                  {subCategories.map(sub => (
                    <button 
                      key={sub.id}
                      onClick={() => setSelectedSubCat(sub.id)}
                      className={`w-full text-right p-3 rounded-xl text-xs font-black transition-all ${selectedSubCat === sub.id ? 'bg-emerald-50 text-emerald-700' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                      {sub.name}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      </aside>

      {/* Main Content Area */}
      <div className={`flex-1 flex flex-col gap-6 ${activeTab === 'cart' ? 'hidden lg:flex' : 'flex'}`}>
        {/* Search & Extra Service */}
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="relative flex-1 group">
            <input 
              type="text" 
              placeholder="ابحث بالاسم أو الباركود..." 
              className="w-full pr-14 pl-6 py-5 bg-white border-2 border-slate-100 rounded-[2rem] focus:border-emerald-600 transition-all outline-none font-black text-xl text-slate-900 shadow-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-600" size={24} />
          </div>
          <button 
            onClick={() => setShowExtraModal(true)}
            className="px-8 py-5 bg-emerald-600 text-white font-black rounded-[2rem] shadow-lg shadow-emerald-900/20 hover:bg-emerald-500 transition-all flex items-center justify-center gap-2 whitespace-nowrap active:scale-95"
          >
            <PlusCircle size={24} />
            إضافة خدمة خارجية
          </button>
        </div>

        {/* Product Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar pr-1 pb-10">
          {filteredProducts.map(v => (
            <button 
              key={v.id} 
              onClick={() => { const p = products.find(prod => prod.id === v.product_id); addToCart(v, p); }}
              className="group bg-white p-5 rounded-[2.5rem] border-2 border-transparent hover:border-emerald-600 hover:shadow-xl transition-all text-right flex flex-col gap-3 relative overflow-hidden shadow-sm active:scale-95 border-slate-50"
            >
              <span className={`self-start text-[10px] font-black px-3 py-1 rounded-xl ${v.stock_quantity > 0 ? 'bg-emerald-50 text-emerald-700' : 'bg-rose-50 text-rose-700'}`}>
                {v.stock_quantity > 0 ? `${v.stock_quantity} قطعة` : 'نافذ'}
              </span>
              <div>
                <h3 className="font-black text-slate-900 text-base leading-tight truncate">{v.productName}</h3>
                <p className="text-[10px] text-slate-400 font-bold truncate mt-1">{v.name}</p>
              </div>
              <p className="text-2xl font-black text-emerald-600">{v.sale_price} ₪</p>
              <div className="absolute bottom-0 left-0 p-3 bg-emerald-600 text-white translate-x-full group-hover:translate-x-0 transition-transform rounded-tr-3xl">
                <Plus size={20} />
              </div>
            </button>
          ))}
          {filteredProducts.length === 0 && (
            <div className="col-span-full py-20 text-center opacity-30 font-black text-xl">لا توجد نتائج</div>
          )}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className={`w-full lg:w-[420px] bg-white rounded-[3rem] border border-slate-100 shadow-2xl flex flex-col overflow-hidden ${activeTab === 'products' ? 'hidden lg:flex' : 'flex'}`}>
        <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-emerald-600 rounded-2xl shadow-lg shadow-emerald-900/30">
               <ShoppingBag size={24} />
            </div>
            <span className="font-black text-xl tracking-tight">الفاتورة الحالية</span>
          </div>
          <span className="bg-white/10 px-4 py-1.5 rounded-full text-xs font-black">{cart.length} أصناف</span>
        </div>

        {/* Cart Items List */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 py-20 opacity-40">
              <ShoppingBag size={80} className="mb-4" />
              <p className="font-black text-xl">السلة فارغة</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col gap-3 group animate-slide-in-right">
                <div className="flex justify-between items-start">
                  <div className="max-w-[70%]">
                    <h4 className="font-black text-slate-900 text-sm leading-tight">{item.product_name}</h4>
                    <p className="text-[10px] text-slate-400 font-bold">{item.variant_name}</p>
                  </div>
                  <p className="font-black text-emerald-600 text-lg">{item.sale_price * item.quantity} ₪</p>
                </div>
                <div className="flex items-center justify-between pt-2 border-t border-slate-50">
                  <div className="flex items-center gap-4 bg-slate-100 p-1 rounded-xl">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-8 h-8 bg-white rounded-lg shadow-sm flex items-center justify-center text-slate-900 hover:text-emerald-600 active:scale-90"><Minus size={14} /></button>
                    <span className="font-black text-sm min-w-[20px] text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-8 h-8 bg-white rounded-lg shadow-sm flex items-center justify-center text-slate-900 hover:text-emerald-600 active:scale-90"><Plus size={14} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="p-3 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Footer Actions */}
        <div className="p-8 bg-white border-t border-slate-100 space-y-6 shrink-0 shadow-[0_-10px_40px_rgba(0,0,0,0.02)]">
          <div className="flex gap-4">
             <div className="flex-1 space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-2">تطبيق خصم مباشر</label>
                <div className="relative">
                  <input type="number" placeholder="0" className="w-full py-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none text-center font-black text-lg focus:border-emerald-600" value={discount || ''} onChange={(e) => setDiscount(Number(e.target.value))} />
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 font-black text-sm">₪</span>
                </div>
             </div>
          </div>

          <div className="space-y-3">
            <div className="flex justify-between items-center text-slate-400 font-black text-xs px-2">
              <span>الإجمالي قبل الخصم</span>
              <span>{subtotal} ₪</span>
            </div>
            <div className="flex justify-between items-center pt-4 border-t border-slate-100 px-2">
              <span className="text-slate-900 font-black text-sm uppercase tracking-widest">المبلغ الصافي</span>
              <span className="text-4xl font-black text-emerald-600 leading-none">{netAmount} <span className="text-base font-bold">₪</span></span>
            </div>
          </div>

          <button 
            onClick={handleFinishOrder}
            disabled={cart.length === 0 || isProcessing}
            className="w-full py-5 bg-emerald-600 text-white font-black text-2xl rounded-[2rem] shadow-2xl shadow-emerald-900/30 hover:bg-emerald-500 active:scale-[0.98] transition-all flex items-center justify-center gap-4 disabled:bg-slate-200 disabled:shadow-none"
          >
             {isProcessing ? <Loader2 className="animate-spin" size={28} /> : <CreditCard size={28} />}
             <span>{isProcessing ? 'جاري الحفظ...' : 'إتمام الطلب'}</span>
          </button>
        </div>
      </div>

      {/* Modals & Toasts */}
      {showSuccess && (
        <div className="fixed top-10 left-1/2 -translate-x-1/2 bg-[#0f172a] text-white px-8 py-4 rounded-[2rem] shadow-2xl z-[200] flex items-center gap-4 border border-emerald-500/30 animate-slide-in-right">
          <div className="bg-emerald-500 p-2 rounded-full"><CheckCircle2 size={24} /></div>
          <p className="font-black text-lg">تم حفظ الفاتورة بنجاح!</p>
        </div>
      )}

      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/80 backdrop-blur-md flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-lg overflow-hidden animate-slide-in-right">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-emerald-600 rounded-2xl"><PlusCircle size={24} /></div>
                <h3 className="text-xl font-black">خدمة خارجية</h3>
              </div>
              <button onClick={() => setShowExtraModal(false)} className="p-2 bg-white/10 rounded-xl hover:bg-white/20 transition-all"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-700 mr-2">اسم الخدمة</label>
                <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" placeholder="توصيل، تركيب، صيانة..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">سعر التكلفة</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})} />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">سعر البيع</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})} />
                </div>
              </div>
              <button onClick={handleAddExtraService} disabled={!extraService.name || extraService.sale_price <= 0} className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-500 transition-all disabled:bg-slate-200">إضافة للسلة</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  PlusCircle, 
  ShoppingBag,
  CreditCard,
  X,
  AlertCircle,
  LayoutGrid,
  ChevronLeft,
  CheckCircle2,
  Loader2,
  Package,
  Layers,
  ArrowRightLeft
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, ExtraService, Category } from '../types';

const POS: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cart'>('products');
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(0);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const addToCart = (variant: Variant, product: any) => {
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);
    const netAmount = Math.max(0, subtotal - discount);
    const profit = netAmount - totalCost;
    return { subtotal, totalCost, netAmount, profit };
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);

    try {
      const { netAmount, totalCost, profit, subtotal } = calculateTotals();
      const { data: invoice, error: invError } = await supabase
        .from('invoices')
        .insert({
          total_amount: subtotal,
          discount: discount,
          net_amount: netAmount,
          total_cost: totalCost,
          profit: profit
        })
        .select().single();

      if (invError) throw invError;

      const productsInCart = cart.filter(c => c.type === 'product');
      const servicesInCart = cart.filter(c => c.type === 'service');

      if (productsInCart.length > 0) {
        await supabase.from('invoice_items').insert(productsInCart.map(item => ({
          invoice_id: invoice.id,
          variant_id: item.variant_id,
          product_name: item.product_name,
          variant_name: item.variant_name,
          quantity: item.quantity,
          cost_price: item.cost_price,
          sale_price: item.sale_price
        })));

        for (const item of productsInCart) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }

      if (servicesInCart.length > 0) {
        await supabase.from('extra_services').insert(servicesInCart.map(ser => ({
          invoice_id: invoice.id,
          name: ser.product_name,
          cost_price: ser.cost_price,
          sale_price: ser.sale_price,
          quantity: ser.quantity
        })));
      }

      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
      fetchData();
    } catch (error) {
      console.error(error);
      alert("حدث خطأ أثناء إتمام الطلب");
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = useMemo(() => {
    return products.flatMap(p => (p.variants || []).map((v: any) => ({ 
      ...v, 
      productName: p.name, 
      categoryId: p.category_id, 
      subCategoryId: p.sub_category_id 
    }))).filter(v => {
      const matchSearch = v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || (v.barcode && v.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? v.categoryId === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? v.subCategoryId === selectedSubCat : true;
      return matchSearch && matchMainCat && matchSubCat;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);

  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row gap-4 h-full font-['Tajawal'] bg-[#f8fafc] -m-4 lg:-m-10 p-4 lg:p-10" dir="rtl">

      {/* 1. Slim Vertical Sidebar (Main Categories) */}
      <aside className="hidden lg:flex flex-col w-20 bg-[#0f172a] rounded-[2.5rem] shadow-2xl overflow-hidden shrink-0 py-8 gap-6 items-center">
        <button 
          onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }}
          className={`group relative w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-300 ${!selectedMainCat ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/40 scale-110' : 'text-slate-500 hover:bg-white/10 hover:text-white'}`}
          title="الكل"
        >
          <LayoutGrid size={24} />
          {!selectedMainCat && <div className="absolute -right-2 w-1.5 h-6 bg-emerald-500 rounded-l-full" />}
        </button>

        <div className="w-8 h-px bg-white/10" />

        <div className="flex-1 flex flex-col gap-4 overflow-y-auto custom-scrollbar w-full items-center px-2">
          {mainCategories.map(cat => (
            <button 
              key={cat.id}
              onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
              className={`group relative w-12 h-12 min-h-[48px] rounded-2xl flex items-center justify-center transition-all duration-300 ${selectedMainCat === cat.id ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/40 scale-110' : 'text-slate-500 hover:bg-white/10 hover:text-white'}`}
              title={cat.name}
            >
              <Package size={22} />
              <span className="absolute right-14 bg-[#0f172a] text-white px-3 py-1.5 rounded-xl text-xs font-black whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none shadow-xl border border-white/5">
                {cat.name}
              </span>
              {selectedMainCat === cat.id && <div className="absolute -right-2 w-1.5 h-6 bg-emerald-500 rounded-l-full" />}
            </button>
          ))}
        </div>
      </aside>

      {/* 2. Main Work Area */}
      <div className={`flex-1 flex flex-col gap-6 ${activeTab === 'cart' ? 'hidden lg:flex' : 'flex'}`}>

        {/* Top Header Section */}
        <div className="flex flex-col gap-4">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input 
                type="text" 
                placeholder="ابحث بالاسم أو امسح الباركود..." 
                className="w-full pr-14 pl-6 py-5 bg-white border-2 border-slate-100 rounded-[2rem] focus:border-emerald-600 transition-all outline-none font-black text-xl text-slate-900 shadow-sm"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-600" size={24} />
            </div>
            <button 
              onClick={() => setShowExtraModal(true)}
              className="w-full sm:w-auto px-8 py-5 bg-emerald-600 text-white font-black rounded-[2rem] shadow-lg shadow-emerald-900/20 hover:bg-emerald-500 transition-all flex items-center justify-center gap-3 active:scale-95 whitespace-nowrap"
            >
              <PlusCircle size={22} />
              <span>خدمة إضافية</span>
            </button>
          </div>

          {/* 3. Horizontal Sub-Categories Bar */}
          <div className="flex items-center gap-3 overflow-x-auto pb-2 px-1 custom-scrollbar no-scrollbar">
            <button 
              onClick={() => setSelectedSubCat(null)}
              className={`px-6 py-3 rounded-2xl font-black text-xs whitespace-nowrap transition-all border-2 ${!selectedSubCat ? 'bg-white border-emerald-600 text-emerald-700 shadow-md' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'}`}
            >
              الكل في {selectedMainCat ? mainCategories.find(c => c.id === selectedMainCat)?.name : 'النظام'}
            </button>
            {subCategories.map(sub => (
              <button 
                key={sub.id}
                onClick={() => setSelectedSubCat(sub.id)}
                className={`px-6 py-3 rounded-2xl font-black text-xs whitespace-nowrap transition-all border-2 ${selectedSubCat === sub.id ? 'bg-white border-emerald-600 text-emerald-700 shadow-md' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'}`}
              >
                {sub.name}
              </button>
            ))}
          </div>
        </div>

        {/* Product Grid Area */}
        <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar pr-1 pb-10 flex-1">
          {filteredProducts.map(v => (
            <button 
              key={v.id} 
              onClick={() => { const p = products.find(prod => prod.id === v.product_id); addToCart(v, p); }}
              className="group bg-white p-5 rounded-[2.5rem] border-2 border-transparent hover:border-emerald-600 hover:shadow-xl transition-all duration-300 text-right flex flex-col gap-3 relative overflow-hidden shadow-sm active:scale-95 border-slate-50"
            >
              <span className={`self-start text-[9px] font-black px-3 py-1.5 rounded-xl uppercase tracking-widest ${v.stock_quantity > 0 ? 'bg-emerald-50 text-emerald-700' : 'bg-rose-50 text-rose-700'}`}>
                {v.stock_quantity > 0 ? `${v.stock_quantity} متاح` : 'نافذ'}
              </span>
              <div className="min-h-[60px]">
                <h3 className="font-black text-slate-900 text-base leading-tight group-hover:text-emerald-700 transition-colors line-clamp-2">{v.productName}</h3>
                <p className="text-[10px] text-slate-400 font-bold mt-1">{v.name}</p>
              </div>
              <div className="mt-auto pt-2 flex items-end justify-between">
                <p className="text-2xl font-black text-emerald-600 leading-none">{v.sale_price} <span className="text-xs">₪</span></p>
                <div className="p-2 bg-slate-50 rounded-xl text-slate-300 group-hover:bg-emerald-600 group-hover:text-white transition-all">
                  <Plus size={18} />
                </div>
              </div>
            </button>
          ))}
          {filteredProducts.length === 0 && (
            <div className="col-span-full py-20 flex flex-col items-center justify-center opacity-20">
              <Search size={80} className="mb-4" />
              <p className="font-black text-2xl">لا توجد منتجات مطابقة</p>
            </div>
          )}
        </div>
      </div>

      {/* 4. Cart Sidebar (Persistent & Elegant) */}
      <div className={`w-full lg:w-[420px] bg-white rounded-[3rem] border border-slate-100 shadow-2xl flex flex-col overflow-hidden transition-all duration-500 ${activeTab === 'products' ? 'hidden lg:flex' : 'flex'}`}>
        <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-emerald-600 rounded-2xl shadow-lg shadow-emerald-900/30">
               <ShoppingBag size={24} />
            </div>
            <span className="font-black text-xl tracking-tight">سلة الطلب</span>
          </div>
          <button 
            onClick={() => { if(confirm('هل تريد مسح السلة بالكامل؟')) setCart([]); }}
            className="p-2.5 text-slate-400 hover:text-rose-500 hover:bg-white/5 rounded-xl transition-all"
          >
            <Trash2 size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/30 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 py-20 opacity-30">
              <ShoppingBag size={80} strokeWidth={1} className="mb-4" />
              <p className="font-black text-xl">بانتظار طلبك الأول...</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-5 rounded-[2.2rem] border border-slate-100 shadow-sm flex flex-col gap-3 group animate-slide-in-right">
                <div className="flex justify-between items-start gap-4">
                  <div className="flex-1">
                    <h4 className="font-black text-slate-900 text-sm leading-tight line-clamp-2">{item.product_name}</h4>
                    <span className="inline-block mt-1 px-2 py-0.5 bg-slate-50 text-slate-400 text-[9px] font-black rounded-lg">{item.variant_name}</span>
                  </div>
                  <p className="font-black text-emerald-600 text-lg whitespace-nowrap">{item.sale_price * item.quantity} ₪</p>
                </div>
                <div className="flex items-center justify-between pt-3 border-t border-slate-50">
                  <div className="flex items-center gap-3 bg-slate-100/80 p-1.5 rounded-2xl">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-8 h-8 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-900 hover:text-emerald-600 active:scale-90 transition-all"><Minus size={14} /></button>
                    <span className="font-black text-sm min-w-[24px] text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-8 h-8 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-900 hover:text-emerald-600 active:scale-90 transition-all"><Plus size={14} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="p-3 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-8 bg-white border-t border-slate-100 space-y-6 shrink-0 shadow-[0_-15px_40px_rgba(0,0,0,0.03)]">
          <div className="flex gap-4">
             <div className="flex-1 space-y-2">
                <div className="flex justify-between items-center mr-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">تطبيق خصم</label>
                  {discount > 0 && <button onClick={() => setDiscount(0)} className="text-[10px] font-black text-rose-500">إلغاء</button>}
                </div>
                <div className="relative group">
                  <input type="number" placeholder="0.00" className="w-full py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl outline-none text-center font-black text-lg focus:border-emerald-600 focus:bg-white transition-all" value={discount || ''} onChange={(e) => setDiscount(Number(e.target.value))} />
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 font-black text-sm">₪</span>
                </div>
             </div>
          </div>

          <div className="space-y-3 px-2">
            <div className="flex justify-between items-center text-slate-400 font-black text-xs">
              <span>المجموع الفرعي</span>
              <span>{subtotal} ₪</span>
            </div>
            {discount > 0 && (
              <div className="flex justify-between items-center text-rose-500 font-black text-xs">
                <span>الخصم المطبق</span>
                <span>-{discount} ₪</span>
              </div>
            )}
            <div className="flex justify-between items-center pt-4 border-t border-slate-100">
              <span className="text-slate-900 font-black text-sm uppercase tracking-widest">المبلغ النهائي</span>
              <span className="text-4xl font-black text-emerald-600 leading-none">{netAmount} <span className="text-base font-bold">₪</span></span>
            </div>
          </div>

          <button 
            onClick={handleFinishOrder}
            disabled={cart.length === 0 || isProcessing}
            className="w-full py-5 bg-emerald-600 text-white font-black text-2xl rounded-[2.2rem] shadow-2xl shadow-emerald-900/30 hover:bg-emerald-500 active:scale-[0.98] transition-all flex items-center justify-center gap-4 disabled:bg-slate-200 disabled:shadow-none"
          >
             {isProcessing ? <Loader2 className="animate-spin" size={28} /> : <CreditCard size={28} />}
             <span>{isProcessing ? 'جاري الحفظ...' : 'إتمام الطلب'}</span>
          </button>
        </div>
      </div>

      {/* Success Notification */}
      {showSuccess && (
        <div className="fixed top-10 left-1/2 -translate-x-1/2 bg-[#0f172a] text-white px-8 py-5 rounded-[2.5rem] shadow-2xl z-[200] flex items-center gap-4 border border-emerald-500/30 animate-slide-in-right">
          <div className="bg-emerald-500 p-2.5 rounded-full shadow-lg shadow-emerald-500/20"><CheckCircle2 size={28} /></div>
          <div>
            <p className="font-black text-xl">تمت العملية!</p>
            <p className="text-xs text-slate-400 font-bold">تم حفظ الفاتورة وتحديث المخزون</p>
          </div>
        </div>
      )}

      {/* Extra Service Modal */}
      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-lg overflow-hidden animate-slide-in-right border border-white/10">
            <div className="p-10 bg-[#0f172a] text-white flex items-center justify-between">
              <div className="flex items-center gap-5">
                <div className="p-4 bg-emerald-600 rounded-3xl shadow-xl shadow-emerald-900/20"><PlusCircle size={28} /></div>
                <div>
                  <h3 className="text-2xl font-black">خدمة خارجية</h3>
                  <p className="text-xs text-slate-400 font-bold">إضافة خدمات غير مدرجة بالمخزون</p>
                </div>
              </div>
              <button onClick={() => setShowExtraModal(false)} className="p-3 bg-white/5 rounded-2xl hover:bg-white/10 transition-all"><X size={24} /></button>
            </div>
            <div className="p-10 space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-700 mr-2">وصف الخدمة</label>
                <input type="text" autoFocus className="w-full p-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] outline-none focus:border-emerald-600 focus:bg-white font-bold transition-all" placeholder="توصيل، تركيب، صيانة..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">التكلفة</label>
                  <input type="number" className="w-full p-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] outline-none focus:border-emerald-600 focus:bg-white font-bold transition-all" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})} />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">سعر البيع</label>
                  <input type="number" className="w-full p-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] outline-none focus:border-emerald-600 focus:bg-white font-bold transition-all" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})} />
                </div>
              </div>
              <button onClick={handleAddExtraService} disabled={!extraService.name || extraService.sale_price <= 0} className="w-full py-6 bg-emerald-600 text-white font-black text-xl rounded-[1.5rem] shadow-2xl shadow-emerald-900/20 hover:bg-emerald-500 transition-all disabled:bg-slate-200 disabled:shadow-none">إضافة للسلة</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  PlusCircle, 
  ShoppingBag,
  CreditCard,
  X,
  LayoutGrid,
  CheckCircle2,
  Loader2,
  Package,
  Maximize2,
  Minimize2,
  Zap
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, ExtraService, Category } from '../types';

const POS: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cart'>('products');
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  // Persistent Cart Logic
  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(0);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
  }, []);

  // Guarantee persistence on every change
  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const addToCart = (variant: Variant, product: any) => {
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);
    const netAmount = Math.max(0, subtotal - discount);
    const profit = netAmount - totalCost;
    return { subtotal, totalCost, netAmount, profit };
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);

    try {
      const { netAmount, totalCost, profit, subtotal } = calculateTotals();
      const { data: invoice, error: invError } = await supabase
        .from('invoices')
        .insert({
          total_amount: subtotal,
          discount: discount,
          net_amount: netAmount,
          total_cost: totalCost,
          profit: profit
        })
        .select().single();

      if (invError) throw invError;

      const productsInCart = cart.filter(c => c.type === 'product');
      const servicesInCart = cart.filter(c => c.type === 'service');

      if (productsInCart.length > 0) {
        await supabase.from('invoice_items').insert(productsInCart.map(item => ({
          invoice_id: invoice.id,
          variant_id: item.variant_id,
          product_name: item.product_name,
          variant_name: item.variant_name,
          quantity: item.quantity,
          cost_price: item.cost_price,
          sale_price: item.sale_price
        })));

        for (const item of productsInCart) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }

      if (servicesInCart.length > 0) {
        await supabase.from('extra_services').insert(servicesInCart.map(ser => ({
          invoice_id: invoice.id,
          name: ser.product_name,
          cost_price: ser.cost_price,
          sale_price: ser.sale_price,
          quantity: ser.quantity
        })));
      }

      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
      fetchData();
    } catch (error) {
      console.error(error);
      alert("حدث خطأ أثناء إتمام الطلب");
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = useMemo(() => {
    return products.flatMap(p => (p.variants || []).map((v: any) => ({ 
      ...v, 
      productName: p.name, 
      categoryId: p.category_id, 
      subCategoryId: p.sub_category_id 
    }))).filter(v => {
      const matchSearch = v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || (v.barcode && v.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? v.categoryId === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? v.subCategoryId === selectedSubCat : true;
      return matchSearch && matchMainCat && matchSubCat;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);

  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row gap-4 h-full font-['Tajawal'] bg-[#f8fafc] -m-4 lg:-m-10 p-4 lg:p-6" dir="rtl">

      {/* 1. SLIM VERTICAL SIDEBAR (Icons Only) */}
      <aside className="hidden lg:flex flex-col w-20 bg-[#0f172a] rounded-[2.5rem] shadow-2xl overflow-hidden shrink-0 py-6 gap-6 items-center border border-white/5">
        <button 
          onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }}
          className={`group relative w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-300 ${!selectedMainCat ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/40 scale-110' : 'text-slate-500 hover:bg-white/10 hover:text-white'}`}
          title="الكل"
        >
          <Zap size={24} />
          {!selectedMainCat && <div className="absolute -right-2 w-1.5 h-8 bg-emerald-500 rounded-l-full shadow-[0_0_15px_rgba(16,185,129,1)]" />}
        </button>

        <div className="w-8 h-px bg-white/10" />

        <div className="flex-1 flex flex-col gap-5 overflow-y-auto custom-scrollbar w-full items-center px-2">
          {mainCategories.map(cat => (
            <button 
              key={cat.id}
              onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
              className={`group relative w-12 h-12 min-h-[48px] rounded-2xl flex items-center justify-center transition-all duration-300 ${selectedMainCat === cat.id ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/40 scale-110' : 'text-slate-500 hover:bg-white/10 hover:text-white'}`}
            >
              <Package size={22} />
              {/* Tooltip */}
              <span className="absolute right-14 bg-[#0f172a] text-white px-3 py-1.5 rounded-xl text-xs font-black whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none shadow-2xl border border-white/10 z-[100]">
                {cat.name}
              </span>
              {selectedMainCat === cat.id && <div className="absolute -right-2 w-1.5 h-8 bg-emerald-500 rounded-l-full shadow-[0_0_15px_rgba(16,185,129,1)]" />}
            </button>
          ))}
        </div>
      </aside>

      {/* 2. MAIN WORKSPACE */}
      <div className={`flex-1 flex flex-col gap-4 ${activeTab === 'cart' ? 'hidden lg:flex' : 'flex'}`}>

        {/* Header: Search & Fullscreen */}
        <div className="flex flex-col gap-4 bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100">
          <div className="flex flex-col sm:flex-row gap-3 items-center">
            <div className="relative flex-1 group w-full">
              <input 
                type="text" 
                placeholder="ابحث بالاسم أو الباركود..." 
                className="w-full pr-14 pl-6 py-4 bg-slate-50 border-2 border-transparent focus:border-emerald-500 focus:bg-white rounded-[1.8rem] transition-all outline-none font-bold text-lg text-slate-900 shadow-inner"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-600" size={20} />
            </div>

            <div className="flex gap-2 w-full sm:w-auto">
              <button 
                onClick={toggleFullscreen}
                className="p-4 bg-slate-100 text-slate-600 rounded-2xl hover:bg-slate-200 transition-all flex items-center justify-center"
                title="ملء الشاشة"
              >
                {isFullscreen ? <Minimize2 size={22} /> : <Maximize2 size={22} />}
              </button>

              <button 
                onClick={() => setShowExtraModal(true)}
                className="flex-1 sm:flex-none px-6 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-lg shadow-emerald-500/20 hover:bg-emerald-500 transition-all flex items-center justify-center gap-2 active:scale-95 whitespace-nowrap"
              >
                <PlusCircle size={20} />
                <span>خدمة إضافية</span>
              </button>
            </div>
          </div>

          {/* HORIZONTAL SUB-CATEGORIES */}
          {selectedMainCat && (
            <div className="flex items-center gap-2 overflow-x-auto pb-1 px-1 custom-scrollbar no-scrollbar border-t border-slate-50 pt-3">
              <button 
                onClick={() => setSelectedSubCat(null)}
                className={`px-5 py-2.5 rounded-xl font-black text-xs whitespace-nowrap transition-all border-2 ${!selectedSubCat ? 'bg-emerald-600 border-emerald-600 text-white shadow-md' : 'bg-slate-50 border-transparent text-slate-400 hover:bg-slate-100'}`}
              >
                كل {mainCategories.find(c => c.id === selectedMainCat)?.name}
              </button>
              {subCategories.map(sub => (
                <button 
                  key={sub.id}
                  onClick={() => setSelectedSubCat(sub.id)}
                  className={`px-5 py-2.5 rounded-xl font-black text-xs whitespace-nowrap transition-all border-2 ${selectedSubCat === sub.id ? 'bg-emerald-600 border-emerald-600 text-white shadow-md' : 'bg-slate-50 border-transparent text-slate-400 hover:bg-slate-100'}`}
                >
                  {sub.name}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Product Grid Area */}
        <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-3 overflow-y-auto custom-scrollbar pr-1 pb-10 flex-1">
          {filteredProducts.map(v => (
            <button 
              key={v.id} 
              onClick={() => { const p = products.find(prod => prod.id === v.product_id); addToCart(v, p); }}
              className="group bg-white p-4 rounded-[2rem] border-2 border-transparent hover:border-emerald-500 hover:shadow-xl transition-all duration-300 text-right flex flex-col gap-2 relative overflow-hidden shadow-sm active:scale-95 border-slate-50"
            >
              <div className="flex justify-between items-start mb-1">
                <span className={`text-[8px] font-black px-2 py-1 rounded-lg uppercase tracking-wider ${v.stock_quantity > 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                  {v.stock_quantity > 0 ? `${v.stock_quantity} قطعة` : 'نافذ'}
                </span>
                <div className="p-1.5 bg-slate-50 rounded-lg text-slate-300 group-hover:bg-emerald-500 group-hover:text-white transition-all shadow-sm">
                  <Plus size={14} />
                </div>
              </div>

              <div className="flex-1 min-h-[44px]">
                <h3 className="font-black text-slate-900 text-sm leading-tight line-clamp-2">{v.productName}</h3>
                <p className="text-[9px] text-slate-400 font-bold mt-0.5">{v.name}</p>
              </div>

              <div className="pt-2 border-t border-slate-50">
                <p className="text-xl font-black text-emerald-600 leading-none">{v.sale_price} <span className="text-[10px] font-bold">₪</span></p>
              </div>
            </button>
          ))}
          {filteredProducts.length === 0 && (
            <div className="col-span-full py-20 flex flex-col items-center justify-center opacity-10">
              <Package size={100} strokeWidth={1} />
              <p className="font-black text-xl">لا توجد منتجات</p>
            </div>
          )}
        </div>
      </div>

      {/* 3. CART SIDEBAR */}
      <div className={`w-full lg:w-[380px] bg-white rounded-[2.8rem] border border-slate-200 shadow-2xl flex flex-col overflow-hidden transition-all duration-500 ${activeTab === 'products' ? 'hidden lg:flex' : 'flex'}`}>
        <div className="p-6 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-emerald-600 rounded-xl shadow-lg shadow-emerald-500/20">
               <ShoppingBag size={20} />
            </div>
            <span className="font-black text-lg">سلة الطلب</span>
          </div>
          <button 
            onClick={() => { if(confirm('تفريغ السلة؟')) setCart([]); }}
            className="p-2 text-slate-500 hover:text-rose-500 transition-all"
          >
            <Trash2 size={18} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 space-y-3 bg-slate-50/20 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 py-10 opacity-20">
              <ShoppingBag size={60} strokeWidth={1} />
              <p className="font-black text-sm mt-3">اختر منتجاً للبدء</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-4 rounded-[1.8rem] border border-slate-100 shadow-sm flex flex-col gap-2 group animate-slide-in-right">
                <div className="flex justify-between items-start gap-3">
                  <div className="flex-1">
                    <h4 className="font-black text-slate-800 text-xs leading-tight line-clamp-2">{item.product_name}</h4>
                    <span className="inline-block mt-0.5 px-2 py-0.5 bg-slate-50 text-slate-400 text-[8px] font-black rounded-md">{item.variant_name}</span>
                  </div>
                  <p className="font-black text-emerald-600 text-sm">{item.sale_price * item.quantity} ₪</p>
                </div>
                <div className="flex items-center justify-between pt-2 border-t border-slate-50">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-xl">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-7 h-7 bg-white rounded-lg shadow-sm flex items-center justify-center text-slate-700 hover:text-emerald-600 active:scale-90 transition-all"><Minus size={12} /></button>
                    <span className="font-black text-xs min-w-[20px] text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-7 h-7 bg-white rounded-lg shadow-sm flex items-center justify-center text-slate-700 hover:text-emerald-600 active:scale-90 transition-all"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="p-2 text-slate-300 hover:text-rose-500 transition-all"><Trash2 size={16} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Totals Area */}
        <div className="p-6 bg-white border-t border-slate-100 space-y-4 shrink-0 shadow-[0_-10px_40px_rgba(0,0,0,0.02)]">
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 mr-2 uppercase tracking-tighter">الخصم (₪)</label>
            <input 
              type="number" 
              placeholder="0" 
              className="w-full py-3 bg-slate-50 border border-transparent focus:border-emerald-500 focus:bg-white rounded-xl outline-none text-center font-black text-base transition-all" 
              value={discount || ''} 
              onChange={(e) => setDiscount(Number(e.target.value))} 
            />
          </div>

          <div className="space-y-2 px-2">
            <div className="flex justify-between items-center text-slate-400 font-bold text-[10px]">
              <span>المجموع قبل الخصم</span>
              <span>{subtotal} ₪</span>
            </div>
            <div className="flex justify-between items-center pt-2 border-t border-slate-100">
              <span className="text-slate-900 font-black text-sm uppercase">المبلغ الصافي</span>
              <span className="text-3xl font-black text-emerald-600 tracking-tighter">{netAmount} <span className="text-xs">₪</span></span>
            </div>
          </div>

          <button 
            onClick={handleFinishOrder}
            disabled={cart.length === 0 || isProcessing}
            className="w-full py-4 bg-emerald-600 text-white font-black text-xl rounded-[1.6rem] shadow-xl shadow-emerald-500/20 hover:bg-emerald-500 active:scale-[0.98] transition-all flex items-center justify-center gap-3 disabled:bg-slate-200 disabled:shadow-none"
          >
             {isProcessing ? <Loader2 className="animate-spin" size={24} /> : <CreditCard size={24} />}
             <span>إتمام الطلب</span>
          </button>
        </div>
      </div>

      {/* SUCCESS POPUP */}
      {showSuccess && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 bg-[#0f172a] text-white px-8 py-4 rounded-[2rem] shadow-2xl z-[200] flex items-center gap-4 border border-emerald-500/30 animate-slide-in-right">
          <div className="bg-emerald-500 p-2 rounded-full"><CheckCircle2 size={24} /></div>
          <p className="font-black text-lg">تم حفظ الفاتورة بنجاح!</p>
        </div>
      )}

      {/* EXTRA SERVICE MODAL */}
      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/90 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-slide-in-right">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-2.5 bg-emerald-600 rounded-xl"><PlusCircle size={24} /></div>
