            <div className="p-8 space-y-5">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-700 mr-1">وصف الخدمة</label>
                <input type="text" autoFocus className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 focus:bg-white font-bold transition-all" placeholder="توصيل، تركيب..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-1">التكلفة (₪)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 focus:bg-white font-bold transition-all" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})} />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-1">البيع (₪)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 focus:bg-white font-bold transition-all" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})} />
