          className={`px-6 py-5 text-right font-black transition-all border-r-4 ${!selectedMainCat ? 'bg-emerald-600 text-white border-white' : 'text-slate-400 hover:bg-white/5 border-transparent'}`}
        >
          كافة الأصناف
        </button>
        {mainCategories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
            className={`px-6 py-5 text-right font-black transition-all border-r-4 text-sm ${selectedMainCat === cat.id ? 'bg-emerald-600 text-white border-white' : 'text-slate-400 hover:bg-white/5 border-transparent'}`}
          >
            {cat.name}
          </button>
        ))}
      </aside>

      {/* 2. MAIN WORK AREA */}
      <div className="flex-1 flex flex-col gap-0 bg-[#f4f4f4] relative">

        {/* Top Header */}
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm z-10">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input 
                type="text" 
                placeholder="ابحث بالاسم أو الباركود..." 
                className="w-full pr-14 pl-6 py-4 bg-white border-2 border-slate-300 focus:border-black rounded-2xl transition-all outline-none font-black text-lg text-black placeholder:text-slate-300 shadow-sm"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-black" size={24} />
            </div>

            <div className="flex gap-2">
              <button onClick={toggleFullscreen} className="p-4 bg-white border-2 border-slate-300 text-black rounded-2xl hover:border-black transition-all">
                {isFullscreen ? <Minimize2 size={24} /> : <Maximize2 size={24} />}
              </button>
              <button 
                onClick={() => setIsCartOpen(!isCartOpen)} 
                className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-black text-white border-black' : 'bg-white text-black border-slate-300'}`}
              >
                <ShoppingBag size={24} />
                <span className="hidden sm:inline">{isCartOpen ? 'إخفاء السلة' : 'عرض السلة'}</span>
              </button>
            </div>
          </div>

          {/* Sub-Categories Horizontal Bar */}
          {selectedMainCat && (
            <div className="flex items-center gap-3 overflow-x-auto mt-4 pb-2 no-scrollbar border-t border-slate-100 pt-4">
              <button 
                onClick={() => setSelectedSubCat(null)}
                className={`px-6 py-3 rounded-xl font-black text-xs whitespace-nowrap border-2 ${!selectedSubCat ? 'bg-black text-white border-black' : 'bg-white text-slate-500 border-slate-200 hover:border-slate-400'}`}
              >
                الكل
              </button>
              {subCategories.map(sub => (
                <button 
                  key={sub.id}
                  onClick={() => setSelectedSubCat(sub.id)}
                  className={`px-6 py-3 rounded-xl font-black text-xs whitespace-nowrap border-2 ${selectedSubCat === sub.id ? 'bg-black text-white border-black' : 'bg-white text-slate-500 border-slate-200 hover:border-slate-400'}`}
                >
                  {sub.name}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Product Grid */}
        <div className="p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar flex-1 pb-20">
          {filteredProducts.map(v => (
            <button 
              key={v.id} 
              onClick={() => { const p = products.find(prod => prod.id === v.product_id); addToCart(v, p); }}
              className="group bg-white p-5 rounded-3xl border-2 border-slate-300 hover:border-black hover:shadow-2xl transition-all duration-300 text-right flex flex-col gap-3 relative active:scale-95"
            >
              <div className="flex justify-between items-center">
                <span className={`text-[10px] font-black px-2 py-1 rounded-lg ${v.stock_quantity > 0 ? 'bg-black text-white' : 'bg-rose-600 text-white'}`}>
                  المتوفر: {v.stock_quantity}
