                <Plus size={18} className="text-slate-200 group-hover:text-black" />
              </div>
              <div className="flex-1">
                <h3 className="font-black text-black text-lg leading-tight line-clamp-2">{v.productName}</h3>
              </div>
              <div className="pt-3 border-t border-slate-100 flex items-center justify-between">
                <span className="text-[10px] font-bold text-slate-400 tracking-widest uppercase">السعر</span>
                <p className="text-2xl font-black text-emerald-600 leading-none">{v.sale_price} <span className="text-sm">₪</span></p>
              </div>
            </button>
