      <div className={`fixed lg:relative inset-y-0 left-0 bg-white border-r border-slate-300 shadow-2xl transition-all duration-500 z-50 overflow-hidden flex flex-col ${isCartOpen ? 'w-[320px]' : 'w-0'}`}>
