          <div className="flex items-center gap-3">
            <ShoppingBag size={22} className="text-emerald-500" />
            <span className="font-black text-xl">الفاتورة</span>
          </div>
          <button onClick={() => setIsCartOpen(false)} className="lg:hidden"><X /></button>
        </div>

