            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-4 rounded-2xl border-2 border-slate-200 flex flex-col gap-2">
                <div className="flex justify-between items-start">
                  <h4 className="font-black text-black text-xs leading-tight line-clamp-2 flex-1">{item.product_name}</h4>
                  <p className="font-black text-emerald-600 text-sm mr-2">{item.sale_price * item.quantity} ₪</p>
                </div>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-black shadow-sm"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-black shadow-sm"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={16} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-white border-t-2 border-slate-200 space-y-4 shrink-0 shadow-inner">
          <div className="space-y-1">
            <div className="flex justify-between text-[10px] font-black text-slate-500 mb-1 px-1 uppercase tracking-widest">
              <span>الخصم المسموح</span>
              <span>حد أقصى: {subtotal}</span>
            </div>
            <input 
              type="number" 
              className="w-full py-3 bg-slate-50 border-2 border-slate-200 focus:border-black rounded-xl outline-none text-center font-black text-lg transition-all" 
              value={discount || ''} 
              placeholder="0.00"
              onChange={(e) => handleDiscountChange(Number(e.target.value))} 
            />
          </div>

          <div className="pt-2 border-t border-slate-100 flex justify-between items-center">
            <span className="text-black font-black text-sm">الإجمالي الصافي</span>
            <span className="text-3xl font-black text-emerald-600 tracking-tighter">{netAmount} <span className="text-xs">₪</span></span>
          </div>

          <button 
            onClick={handleFinishOrder}
            disabled={cart.length === 0 || isProcessing}
            className="w-full py-4 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-700 active:scale-95 transition-all disabled:bg-slate-200"
          >
             {isProcessing ? <Loader2 className="animate-spin mx-auto" /> : 'إتمام الطلب ₪'}
          </button>
        </div>
      </div>

      {/* Floating Cart Button for Mobile */}
      {!isCartOpen && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-24 left-6 w-16 h-16 bg-black text-white rounded-full shadow-2xl flex items-center justify-center z-[60] animate-bounce"
        >
          <ShoppingBag />
          <span className="absolute -top-1 -right-1 bg-emerald-500 text-white text-[10px] w-6 h-6 rounded-full flex items-center justify-center font-black border-2 border-black">{cart.length}</span>
        </button>
      )}

      {showSuccess && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 bg-black text-white px-8 py-4 rounded-2xl shadow-2xl z-[200] flex items-center gap-4 border-2 border-emerald-500 animate-slide-in-right">
          <CheckCircle2 className="text-emerald-500" />
          <p className="font-black text-lg tracking-tight">تم الحفظ بنجاح!</p>
        </div>
      )}
    </div>
  );
};

