        >
          كل الأصناف
        </button>
        {mainCategories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
            className={`w-full px-5 py-4 text-right font-black text-sm rounded-xl transition-all ${selectedMainCat === cat.id ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/40 scale-[1.02]' : 'bg-[#1e293b] text-slate-400 hover:bg-[#334155] hover:text-white'}`}
          >
            {cat.name}
          </button>
        ))}
      </aside>

      {/* 2. MAIN WORKSPACE */}
      <div className="flex-1 flex flex-col gap-0 bg-[#f8fafc] relative overflow-hidden">

        {/* Search Header */}
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm z-10">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input 
                type="text" 
                placeholder="ابحث بالاسم أو الباركود..." 
                className="w-full pr-14 pl-6 py-4 bg-slate-50 border-2 border-slate-300 focus:border-[#0f172a] rounded-2xl transition-all outline-none font-black text-lg text-[#0f172a] placeholder:text-slate-400"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-[#0f172a]" size={24} />
            </div>

            <div className="flex gap-2">
