                {isFullscreen ? <Minimize2 size={24} /> : <Maximize2 size={24} />}
              </button>
              <button 
                onClick={() => setIsCartOpen(!isCartOpen)} 
                className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-[#0f172a] text-white border-[#0f172a]' : 'bg-white text-[#0f172a] border-slate-300'}`}
              >
