                <div className="flex items-center justify-between mt-1">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-[#0f172a] shadow-sm"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-[#0f172a] shadow-sm"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="text-slate-300 hover:text-rose-500"><Trash2 size={16} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Totals Section */}
        <div className="p-6 bg-white border-t-2 border-slate-200 space-y-4 shrink-0 shadow-[0_-4px_20px_rgba(0,0,0,0.05)]">
          <div className="space-y-1">
            <div className="flex justify-between text-[10px] font-black text-slate-500 mb-1 px-1 uppercase">
              <span>الخصم</span>
              <span>الحد: {subtotal} ₪</span>
            </div>
            <input 
              type="number" 
              className="w-full py-3 bg-slate-50 border-2 border-slate-200 focus:border-[#0f172a] rounded-xl outline-none text-center font-black text-lg transition-all" 
              value={discount || ''} 
              placeholder="0.00"
              onChange={(e) => handleDiscountChange(Number(e.target.value))} 
            />
          </div>

          <div className="pt-2 flex justify-between items-center border-t border-slate-50">
            <span className="text-[#0f172a] font-black text-xs">الصافي</span>
            <span className="text-2xl font-black text-emerald-600">{netAmount} ₪</span>
          </div>

          <button 
            onClick={handleFinishOrder}
            disabled={cart.length === 0 || isProcessing}
            className="w-full py-4 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl shadow-emerald-500/20 hover:bg-emerald-700 active:scale-95 transition-all disabled:bg-slate-200 disabled:shadow-none"
          >
             {isProcessing ? <Loader2 className="animate-spin mx-auto" /> : 'إتمام الفاتورة'}
          </button>
        </div>
      </div>

      {/* Floating Toggle Button (visible when cart closed) */}
      {!isCartOpen && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="fixed bottom-10 left-10 w-16 h-16 bg-[#0f172a] text-white rounded-full shadow-2xl flex items-center justify-center z-[60] animate-bounce lg:hidden"
        >
          <div className="relative">
            <ShoppingBag />
            <span className="absolute -top-3 -right-3 bg-emerald-500 text-white text-[10px] w-6 h-6 rounded-full flex items-center justify-center font-black border-2 border-[#0f172a]">{cart.length}</span>
          </div>
        </button>
      )}

      {showSuccess && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 bg-[#0f172a] text-white px-8 py-4 rounded-2xl shadow-2xl z-[200] flex items-center gap-4 border-2 border-emerald-500 animate-slide-in-right">
          <CheckCircle2 className="text-emerald-500" />
          <p className="font-black text-lg">تم حفظ الفاتورة!</p>
        </div>
      )}
    </div>
  );
};

