const NavItem: React.FC<{ to: string, icon: any, label: string, mobile?: boolean, collapsed?: boolean, onClick?: () => void }> = ({ to, icon: Icon, label, mobile, collapsed, onClick }) => {
  const location = useLocation();
  const isActive = location.pathname === to;

  if (mobile) {
    return (
      <Link to={to} onClick={onClick} className={`flex flex-col items-center justify-center flex-1 py-3 gap-1 transition-all ${isActive ? 'text-emerald-500' : 'text-slate-400'}`}>
