  return (
    <Link to={to} onClick={onClick} className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all duration-300 group ${isActive ? 'bg-emerald-600 text-white shadow-xl shadow-emerald-900/20' : 'text-slate-400 hover:bg-white/10 hover:text-white'}`}>
