const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  const loggedUser = localStorage.getItem('flyyti_user');
  if (!loggedUser) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) setSettings(data);
    } catch (err) { console.error(err); }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) setConfigMissing(true);
    else fetchSettings();
  }, [fetchSettings]);

  if (configMissing) return <SupabaseSetup />;
  if (loading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-[#0f172a] gap-6">
      <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
      <p className="text-white font-black text-lg animate-pulse">جاري التحميل...</p>
    </div>
  );

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
        <Route path="/*" element={
          <ProtectedRoute settings={settings}>
            <Layout settings={settings}>
              <Routes>
                <Route path="/" element={<POS />} />
                <Route path="/daily-reports" element={<DailyReports />} />
                <Route path="/inventory" element={<Inventory />} />
                <Route path="/categories" element={<Categories />} />
                <Route path="/expenses" element={<Expenses />} />
                <Route path="/invoices" element={<Invoices settings={settings} onUpdateSettings={fetchSettings} />} />
                <Route path="/reports" element={<GeneralReports />} />
                <Route path="/security" element={<Security settings={settings} onUpdate={fetchSettings} />} />
              </Routes>
            </Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingBag,
  X,
  CheckCircle2,
  Loader2,
  Maximize2,
  Minimize2,
  PlusCircle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(true);
  const [showExtraModal, setShowExtraModal] = useState(false);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const addToCart = (variant: Variant, product: any) => {
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const netAmount = Math.max(0, subtotal - discount);
    return { subtotal, netAmount };
  };

  const handleDiscountChange = (val: number) => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    if (val > subtotal) {
      setDiscount(subtotal);
    } else {
      setDiscount(val);
    }
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    try {
      const { subtotal, netAmount } = calculateTotals();
      const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);

      const { data: invoice, error: invError } = await supabase
        .from('invoices')
        .insert({
          total_amount: subtotal,
          discount: discount,
          net_amount: netAmount,
          total_cost: totalCost,
          profit: netAmount - totalCost
        })
        .select().single();

      if (invError) throw invError;

      const items = cart.filter(c => c.type === 'product');
      const services = cart.filter(c => c.type === 'service');

      if (items.length > 0) {
        await supabase.from('invoice_items').insert(items.map(item => ({
          invoice_id: invoice.id,
          variant_id: item.variant_id,
          product_name: item.product_name,
          variant_name: item.variant_name,
          quantity: item.quantity,
          cost_price: item.cost_price,
          sale_price: item.sale_price
        })));
        for (const item of items) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }

      if (services.length > 0) {
        await supabase.from('extra_services').insert(services.map(ser => ({
          invoice_id: invoice.id,
          name: ser.product_name,
          cost_price: ser.cost_price,
          sale_price: ser.sale_price,
          quantity: ser.quantity
        })));
      }

      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
      fetchData();
    } catch (error) {
      console.error(error);
      alert("خطأ في إتمام الطلب");
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = useMemo(() => {
    return products.flatMap(p => (p.variants || []).map((v: any) => ({ 
      ...v, 
      productName: p.name, 
      categoryId: p.category_id, 
      subCategoryId: p.sub_category_id 
    }))).filter(v => {
      const matchSearch = v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || (v.barcode && v.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? v.categoryId === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? v.subCategoryId === selectedSubCat : true;
      return matchSearch && matchMainCat && matchSubCat;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);
  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row h-full font-['Tajawal'] bg-[#f8fafc] overflow-hidden" dir="rtl">

      {/* 1. SECTIONS SIDEBAR - Fixed width, independent scroll */}
      <aside className="hidden lg:flex flex-col w-48 shrink-0 overflow-y-auto custom-scrollbar p-6 gap-3 z-10">
        <div className="mb-2 px-1 shrink-0">
          <p className="text-[#0f172a] font-black text-[10px] uppercase tracking-widest opacity-40">الأقسام</p>
        </div>
        <button 
          onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }}
          className={`w-full px-5 py-3 text-right font-black text-xs rounded-xl transition-all border-2 shrink-0 ${!selectedMainCat ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl shadow-emerald-500/20' : 'bg-white border-slate-200 text-slate-400 hover:border-slate-400'}`}
        >
          الكل
        </button>
        {mainCategories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
            className={`w-full px-5 py-3 text-right font-black text-xs rounded-xl transition-all border-2 shrink-0 ${selectedMainCat === cat.id ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl shadow-emerald-500/20' : 'bg-white border-slate-200 text-slate-400 hover:border-slate-400'}`}
          >
            {cat.name}
          </button>
        ))}
      </aside>

      {/* 2. MAIN WORKSPACE */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] border-r border-slate-200 overflow-hidden relative">

        {/* Search & Tool Header - Shrink 0 to stay at top */}
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm shrink-0">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input 
                type="text" 
                placeholder="البحث بالاسم أو الباركود..." 
                className="w-full pr-14 pl-6 py-4 bg-slate-50 border-2 border-slate-300 focus:border-[#0f172a] rounded-[1.5rem] transition-all outline-none font-black text-lg text-[#0f172a]"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-[#0f172a]" size={24} />
            </div>

            <div className="flex gap-2 w-full sm:w-auto">
              <button 
                onClick={() => setShowExtraModal(true)}
                className="px-6 py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-all flex-1 sm:flex-none active:scale-95 shadow-lg"
              >
                <PlusCircle size={20} />
                <span>خدمة إضافية</span>
              </button>
              <button onClick={toggleFullscreen} className="p-4 bg-white border-2 border-slate-300 text-[#0f172a] rounded-2xl hover:border-[#0f172a] transition-all">
                {isFullscreen ? <Minimize2 size={24} /> : <Maximize2 size={24} />}
              </button>
              <button 
                onClick={() => setIsCartOpen(!isCartOpen)} 
                className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-white text-[#0f172a] border-slate-300'}`}
              >
                <ShoppingBag size={24} />
              </button>
            </div>
          </div>

          {/* Sub-Categories Horizontal */}
          {selectedMainCat && (
            <div className="flex items-center gap-2 overflow-x-auto mt-4 pb-2 no-scrollbar border-t border-slate-100 pt-4">
              {subCategories.map(sub => (
                <button 
                  key={sub.id}
                  onClick={() => setSelectedSubCat(sub.id)}
                  className={`px-5 py-2.5 rounded-xl font-black text-[10px] whitespace-nowrap border-2 transition-all ${selectedSubCat === sub.id ? 'bg-[#0f172a] text-white border-[#0f172a]' : 'bg-slate-50 text-slate-500 border-slate-200 hover:border-slate-400'}`}
                >
                  {sub.name}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Product Grid - Independent Scroll Area with Side Scrollbar */}
        <div className="p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar flex-1">
          {filteredProducts.map(v => (
            <button 
              key={v.id} 
              onClick={() => { const p = products.find(prod => prod.id === v.product_id); addToCart(v, p); }}
              className="group bg-white p-5 rounded-[1.8rem] border-2 border-slate-200 hover:border-emerald-600 hover:shadow-2xl transition-all duration-300 text-right flex flex-col gap-3 relative h-fit active:scale-95"
            >
              <div className="flex justify-between items-center">
                <span className={`text-[10px] font-black px-2 py-1 rounded-lg ${v.stock_quantity > 0 ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-rose-50 text-rose-600 border border-rose-100'}`}>
                  المخزون: {v.stock_quantity}
                </span>
                <Plus size={18} className="text-slate-300 group-hover:text-emerald-600" />
              </div>
              <div className="flex-1">
                <h3 className="font-black text-[#0f172a] text-base leading-tight line-clamp-2">{v.productName}</h3>
                <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase">{v.name}</p>
              </div>
              <div className="pt-3 border-t border-slate-100 flex items-center justify-between">
                 <span className="text-xl font-black text-[#0f172a]">{v.sale_price} <span className="text-xs">₪</span></span>
              </div>
            </button>
          ))}
          {filteredProducts.length === 0 && (
             <div className="col-span-full py-20 text-center opacity-20 flex flex-col items-center">
                <Search size={64} />
                <p className="font-black mt-4">لا توجد منتجات مطابقة</p>
             </div>
          )}
        </div>
      </div>

      {/* 3. CART SIDEBAR (Scrollable Items + FIXED Footer) */}
      <div className={`fixed lg:relative inset-y-0 left-0 bg-white border-r border-slate-300 shadow-2xl transition-all duration-500 z-[80] overflow-hidden flex flex-col h-full ${isCartOpen ? 'w-[300px]' : 'w-0'}`}>
        {/* Cart Header - Fixed at Top */}
        <div className="p-6 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <ShoppingBag size={20} className="text-emerald-500" />
            <span className="font-black text-lg">الفاتورة</span>
          </div>
          <button onClick={() => setIsCartOpen(false)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
        </div>

        {/* Scrollable Items Container - This will take all available space and scroll */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-10 py-10">
              <ShoppingBag size={50} />
              <p className="font-black mt-4 text-sm">أضف منتجات</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-4 rounded-2xl border-2 border-slate-200 flex flex-col gap-2 shadow-sm animate-slide-in-right">
                <div className="flex justify-between items-start gap-2">
                  <h4 className="font-black text-[#0f172a] text-[11px] leading-tight line-clamp-2 flex-1">{item.product_name}</h4>
                  <p className="font-black text-emerald-600 text-[12px]">{item.sale_price * item.quantity} ₪</p>
                </div>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-[#0f172a] shadow-sm"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-[#0f172a] shadow-sm"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="text-slate-300 hover:text-rose-500"><Trash2 size={16} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* FIXED FOOTER - This will always be at the bottom and never move */}
        <div className="p-6 bg-white border-t-2 border-slate-200 space-y-4 shrink-0 shadow-[0_-10px_40px_rgba(0,0,0,0.05)] mt-auto">
          <div className="space-y-2">
            <div className="flex justify-between text-[10px] font-black text-slate-500 px-1 uppercase tracking-tight">
              <span>الخصم المسموح</span>
              <span>الحد: {subtotal} ₪</span>
            </div>
            <input 
              type="number" 
              className="w-full py-3 bg-slate-50 border-2 border-slate-200 focus:border-[#0f172a] rounded-xl outline-none text-center font-black text-lg transition-all" 
              value={discount || ''} 
              placeholder="0.00"
              onChange={(e) => handleDiscountChange(Number(e.target.value))} 
            />
          </div>

          <div className="pt-2 flex justify-between items-center border-t border-slate-100">
            <span className="text-[#0f172a] font-black text-sm uppercase">المجموع الصافي</span>
            <span className="text-2xl font-black text-emerald-600 tracking-tighter leading-none">{netAmount} ₪</span>
          </div>

          <button 
            onClick={handleFinishOrder}
            disabled={cart.length === 0 || isProcessing}
            className="w-full py-4 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl shadow-emerald-500/20 hover:bg-emerald-500 active:scale-[0.98] transition-all disabled:bg-slate-200"
          >
             {isProcessing ? <Loader2 className="animate-spin mx-auto" /> : 'إتمام الفاتورة ₪'}
          </button>
        </div>
      </div>

      {/* Floating Toggle Button (mobile only fallback) */}
      {!isCartOpen && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-10 left-10 w-16 h-16 bg-[#0f172a] text-white rounded-full shadow-2xl flex items-center justify-center z-[60] animate-bounce"
        >
          <div className="relative">
            <ShoppingBag />
            <span className="absolute -top-3 -right-3 bg-emerald-500 text-white text-[10px] w-6 h-6 rounded-full flex items-center justify-center font-black border-2 border-[#0f172a]">{cart.length}</span>
          </div>
        </button>
      )}

      {/* MODALS & NOTIFICATIONS */}
      {showSuccess && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 bg-[#0f172a] text-white px-8 py-4 rounded-2xl shadow-2xl z-[200] flex items-center gap-4 border-2 border-emerald-500 animate-slide-in-right">
          <CheckCircle2 className="text-emerald-500" size={24} />
          <p className="font-black text-lg">تم حفظ الفاتورة بنجاح!</p>
        </div>
      )}

      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/90 backdrop-blur-sm flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-slide-in-right h-fit">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-2.5 bg-emerald-600 rounded-xl"><PlusCircle size={24} /></div>
                <h3 className="text-xl font-black">إضافة خدمة خارجية</h3>
              </div>
              <button onClick={() => setShowExtraModal(false)} className="p-2 bg-white/10 rounded-lg hover:bg-white/20 transition-all"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-5">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-700 mr-1">نوع الخدمة</label>
                <input type="text" autoFocus className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all" placeholder="مثال: توصيل، تركيب..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-1">التكلفة (₪)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})} />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-1">البيع (₪)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})} />
                </div>
              </div>
              <button onClick={handleAddExtraService} disabled={!extraService.name || extraService.sale_price <= 0} className="w-full py-4 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-500 transition-all disabled:bg-slate-200">إضافة للفاتورة</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingBag,
  X,
  CheckCircle2,
  Loader2,
  Maximize2,
  Minimize2,
  PlusCircle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(true);
  const [showExtraModal, setShowExtraModal] = useState(false);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const addToCart = (variant: Variant, product: any) => {
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const netAmount = Math.max(0, subtotal - discount);
    return { subtotal, netAmount };
  };

  const handleDiscountChange = (val: number) => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    if (val > subtotal) {
      setDiscount(subtotal);
    } else {
      setDiscount(val);
    }
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    try {
      const { subtotal, netAmount } = calculateTotals();
      const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);

      const { data: invoice, error: invError } = await supabase
        .from('invoices')
        .insert({
          total_amount: subtotal,
          discount: discount,
          net_amount: netAmount,
          total_cost: totalCost,
          profit: netAmount - totalCost
        })
        .select().single();

      if (invError) throw invError;

      const items = cart.filter(c => c.type === 'product');
      const services = cart.filter(c => c.type === 'service');

      if (items.length > 0) {
        await supabase.from('invoice_items').insert(items.map(item => ({
          invoice_id: invoice.id,
          variant_id: item.variant_id,
          product_name: item.product_name,
          variant_name: item.variant_name,
          quantity: item.quantity,
          cost_price: item.cost_price,
          sale_price: item.sale_price
        })));
        for (const item of items) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }

      if (services.length > 0) {
        await supabase.from('extra_services').insert(services.map(ser => ({
          invoice_id: invoice.id,
          name: ser.product_name,
          cost_price: ser.cost_price,
          sale_price: ser.sale_price,
          quantity: ser.quantity
        })));
      }

      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
      fetchData();
    } catch (error) {
      console.error(error);
      alert("خطأ في إتمام الطلب");
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = useMemo(() => {
    return products.flatMap(p => (p.variants || []).map((v: any) => ({ 
      ...v, 
      productName: p.name, 
      categoryId: p.category_id, 
      subCategoryId: p.sub_category_id 
    }))).filter(v => {
      const matchSearch = v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || (v.barcode && v.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? v.categoryId === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? v.subCategoryId === selectedSubCat : true;
      return matchSearch && matchMainCat && matchSubCat;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);
  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row h-full font-['Tajawal'] bg-[#f8fafc] overflow-hidden" dir="rtl">

      {/* 1. SECTIONS SIDEBAR - No background, small buttons, fixed width */}
      <aside className="hidden lg:flex flex-col w-44 shrink-0 overflow-y-auto custom-scrollbar p-5 gap-2 z-10">
        <div className="mb-2 px-1 shrink-0">
          <p className="text-[#0f172a] font-black text-[9px] uppercase tracking-widest opacity-30">الأقسام</p>
        </div>
        <button 
          onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }}
          className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${!selectedMainCat ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'bg-transparent border-slate-200 text-slate-500 hover:border-slate-400'}`}
        >
          كافة الأصناف
        </button>
        {mainCategories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
            className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${selectedMainCat === cat.id ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'bg-transparent border-slate-200 text-slate-500 hover:border-slate-400'}`}
          >
            {cat.name}
          </button>
        ))}
      </aside>

      {/* 2. MAIN WORKSPACE */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] border-r border-slate-200 overflow-hidden relative">

        {/* Search & Tool Header */}
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm shrink-0">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input 
                type="text" 
                placeholder="البحث بالاسم أو الباركود..." 
                className="w-full pr-14 pl-6 py-4 bg-slate-50 border-2 border-slate-300 focus:border-[#0f172a] rounded-[1.5rem] transition-all outline-none font-black text-lg text-[#0f172a]"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-[#0f172a]" size={24} />
            </div>

            <div className="flex gap-2 w-full sm:w-auto">
              <button 
                onClick={() => setShowExtraModal(true)}
                className="px-6 py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-all flex-1 sm:flex-none active:scale-95 shadow-lg"
              >
                <PlusCircle size={20} />
                <span>خدمة إضافية</span>
              </button>
              <button onClick={toggleFullscreen} className="p-4 bg-white border-2 border-slate-300 text-[#0f172a] rounded-2xl hover:border-[#0f172a] transition-all">
                {isFullscreen ? <Minimize2 size={24} /> : <Maximize2 size={24} />}
              </button>
              <button 
                onClick={() => setIsCartOpen(!isCartOpen)} 
                className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-white text-[#0f172a] border-slate-300'}`}
              >
                <ShoppingBag size={24} />
              </button>
            </div>
          </div>

          {/* Sub-Categories Horizontal (Only when main selected) */}
          {selectedMainCat && (
            <div className="flex items-center gap-2 overflow-x-auto mt-4 pb-2 no-scrollbar border-t border-slate-100 pt-4">
              {subCategories.map(sub => (
                <button 
                  key={sub.id}
                  onClick={() => setSelectedSubCat(sub.id)}
                  className={`px-5 py-2.5 rounded-xl font-black text-[10px] whitespace-nowrap border-2 transition-all ${selectedSubCat === sub.id ? 'bg-[#0f172a] text-white border-[#0f172a]' : 'bg-transparent text-slate-500 border-slate-200 hover:border-slate-400'}`}
                >
                  {sub.name}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Product Grid - Scrollable with Custom Scrollbar */}
        <div className="p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">
          {filteredProducts.map(v => (
            <button 
              key={v.id} 
              onClick={() => { const p = products.find(prod => prod.id === v.product_id); addToCart(v, p); }}
              className="group bg-white p-5 rounded-[1.8rem] border-2 border-slate-200 hover:border-emerald-600 hover:shadow-2xl transition-all duration-300 text-right flex flex-col gap-3 relative h-fit active:scale-95 shadow-sm"
            >
              <div className="flex justify-between items-center">
                <span className={`text-[9px] font-black px-2 py-1 rounded-lg ${v.stock_quantity > 0 ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-rose-50 text-rose-600 border border-rose-100'}`}>
                  {v.stock_quantity} قطعة
                </span>
                <Plus size={18} className="text-slate-300 group-hover:text-emerald-600" />
              </div>
              <div className="flex-1">
                <h3 className="font-black text-[#0f172a] text-sm leading-tight line-clamp-2">{v.productName}</h3>
                <p className="text-[9px] text-slate-400 font-bold mt-1 uppercase tracking-tighter opacity-70">{v.name}</p>
              </div>
              <div className="pt-3 border-t border-slate-100 flex items-center justify-between">
                 <span className="text-lg font-black text-[#0f172a]">{v.sale_price} <span className="text-[10px]">₪</span></span>
              </div>
            </button>
          ))}
          {filteredProducts.length === 0 && (
             <div className="col-span-full py-20 text-center opacity-20 flex flex-col items-center">
                <Search size={64} />
                <p className="font-black mt-4">لا توجد منتجات مطابقة</p>
             </div>
          )}
        </div>
      </div>

      {/* 3. CART SIDEBAR (Scrollable Items + FIXED Footer) */}
      <div className={`fixed lg:relative inset-y-0 left-0 bg-white border-r border-slate-300 shadow-2xl transition-all duration-500 z-[80] overflow-hidden flex flex-col h-full ${isCartOpen ? 'w-[320px]' : 'w-0'}`}>
        {/* Cart Header */}
        <div className="p-6 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <ShoppingBag size={20} className="text-emerald-500" />
            <span className="font-black text-lg">الفاتورة</span>
          </div>
          <button onClick={() => setIsCartOpen(false)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
        </div>

        {/* Scrollable Items Container - Fixed height flex-1 */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-10 py-10">
              <ShoppingBag size={50} />
              <p className="font-black mt-4 text-sm">السلة فارغة</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-4 rounded-2xl border-2 border-slate-200 flex flex-col gap-2 shadow-sm animate-slide-in-right">
                <div className="flex justify-between items-start gap-2">
                  <h4 className="font-black text-[#0f172a] text-[11px] leading-tight line-clamp-2 flex-1">{item.product_name}</h4>
                  <p className="font-black text-emerald-600 text-[12px]">{item.sale_price * item.quantity} ₪</p>
                </div>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-[#0f172a] shadow-sm transition-transform active:scale-90"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-[#0f172a] shadow-sm transition-transform active:scale-90"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="text-slate-300 hover:text-rose-500 p-1"><Trash2 size={16} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* FIXED FOOTER - Always at bottom */}
        <div className="p-6 bg-white border-t-2 border-slate-200 space-y-4 shrink-0 shadow-[0_-15px_50px_rgba(0,0,0,0.06)] mt-auto z-10">
          <div className="space-y-2">
            <div className="flex justify-between text-[10px] font-black text-slate-500 px-1 uppercase tracking-tight">
              <span>تطبيق خصم</span>
              <span>الإجمالي: {subtotal} ₪</span>
            </div>
            <input 
              type="number" 
              className="w-full py-3 bg-slate-50 border-2 border-slate-200 focus:border-[#0f172a] rounded-xl outline-none text-center font-black text-xl transition-all" 
              value={discount || ''} 
              placeholder="0.00"
              onChange={(e) => handleDiscountChange(Number(e.target.value))} 
            />
          </div>

          <div className="pt-2 flex justify-between items-center border-t border-slate-100">
            <span className="text-[#0f172a] font-black text-xs uppercase opacity-60 tracking-widest">الصافي للدفع</span>
            <span className="text-2xl font-black text-emerald-600 tracking-tighter leading-none">{netAmount} ₪</span>
          </div>

          <button 
            onClick={handleFinishOrder}
            disabled={cart.length === 0 || isProcessing}
            className="w-full py-4.5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl shadow-emerald-500/20 hover:bg-emerald-500 active:scale-[0.98] transition-all disabled:bg-slate-200 disabled:shadow-none flex items-center justify-center gap-2"
          >
             {isProcessing ? <Loader2 className="animate-spin" /> : <>إتمام الفاتورة <CheckCircle2 size={20} /></>}
          </button>
        </div>
      </div>

      {/* Floating Toggle Button (mobile fallback) */}
      {!isCartOpen && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-10 left-10 w-16 h-16 bg-[#0f172a] text-white rounded-full shadow-2xl flex items-center justify-center z-[60] animate-bounce"
        >
          <div className="relative">
            <ShoppingBag />
            <span className="absolute -top-3 -right-3 bg-emerald-500 text-white text-[10px] w-6 h-6 rounded-full flex items-center justify-center font-black border-2 border-[#0f172a] shadow-lg">{cart.length}</span>
          </div>
        </button>
      )}

      {/* MODALS & NOTIFICATIONS */}
      {showSuccess && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 bg-[#0f172a] text-white px-10 py-5 rounded-[1.5rem] shadow-2xl z-[200] flex items-center gap-5 border-2 border-emerald-500 animate-slide-in-right">
          <div className="w-10 h-10 bg-emerald-500/10 rounded-full flex items-center justify-center">
             <CheckCircle2 className="text-emerald-500" size={28} />
          </div>
          <p className="font-black text-xl">تم حفظ العملية بنجاح!</p>
        </div>
      )}

      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-slide-in-right h-fit border border-slate-200">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-2.5 bg-emerald-600 rounded-xl shadow-lg shadow-emerald-900/40"><PlusCircle size={24} /></div>
                <h3 className="text-xl font-black">إضافة خدمة يدوية</h3>
              </div>
              <button onClick={() => setShowExtraModal(false)} className="p-2 bg-white/10 rounded-lg hover:bg-white/20 transition-all"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-700 mr-1 uppercase tracking-tight opacity-60">وصف الخدمة</label>
                <input type="text" autoFocus className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all" placeholder="مثال: رسوم شحن، تغليف..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-5">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-1 opacity-60">التكلفة (₪)</label>
                  <input type="number" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})} />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-1 opacity-60">البيع (₪)</label>
                  <input type="number" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all text-emerald-600" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})} />
                </div>
              </div>
              <button onClick={handleAddExtraService} disabled={!extraService.name || extraService.sale_price <= 0} className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-500 transition-all disabled:bg-slate-200 disabled:shadow-none">إدراج في السلة</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingBag,
  X,
  CheckCircle2,
  Loader2,
  Maximize2,
  Minimize2,
  PlusCircle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(true);
  const [showExtraModal, setShowExtraModal] = useState(false);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const addToCart = (variant: Variant, product: any) => {
    // فتح الفاتورة تلقائياً عند إضافة صنف
    setIsCartOpen(true);

    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;

    // فتح الفاتورة تلقائياً عند إضافة خدمة
    setIsCartOpen(true);

    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const netAmount = Math.max(0, subtotal - discount);
    return { subtotal, netAmount };
  };

  const handleDiscountChange = (val: number) => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    if (val > subtotal) {
      setDiscount(subtotal);
    } else {
      setDiscount(val);
    }
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    try {
      const { subtotal, netAmount } = calculateTotals();
      const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);

      const { data: invoice, error: invError } = await supabase
        .from('invoices')
        .insert({
          total_amount: subtotal,
          discount: discount,
          net_amount: netAmount,
          total_cost: totalCost,
          profit: netAmount - totalCost
        })
        .select().single();

      if (invError) throw invError;

      const items = cart.filter(c => c.type === 'product');
      const services = cart.filter(c => c.type === 'service');

      if (items.length > 0) {
        await supabase.from('invoice_items').insert(items.map(item => ({
          invoice_id: invoice.id,
          variant_id: item.variant_id,
          product_name: item.product_name,
          variant_name: item.variant_name,
          quantity: item.quantity,
          cost_price: item.cost_price,
          sale_price: item.sale_price
        })));
        for (const item of items) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }

      if (services.length > 0) {
        await supabase.from('extra_services').insert(services.map(ser => ({
          invoice_id: invoice.id,
          name: ser.product_name,
          cost_price: ser.cost_price,
          sale_price: ser.sale_price,
          quantity: ser.quantity
        })));
      }

      // إغلاق الفاتورة تلقائياً عند إتمام العملية
      setIsCartOpen(false);

      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
      fetchData();
    } catch (error) {
      console.error(error);
      alert("خطأ في إتمام الطلب");
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = useMemo(() => {
    return products.flatMap(p => (p.variants || []).map((v: any) => ({ 
      ...v, 
      productName: p.name, 
      categoryId: p.category_id, 
      subCategoryId: p.sub_category_id 
    }))).filter(v => {
      const matchSearch = v.productName.toLowerCase().includes(searchTerm.toLowerCase()) || (v.barcode && v.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? v.categoryId === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? v.subCategoryId === selectedSubCat : true;
      return matchSearch && matchMainCat && matchSubCat;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);
  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row h-full font-['Tajawal'] bg-[#f8fafc] overflow-hidden" dir="rtl">

      {/* 1. SECTIONS SIDEBAR */}
      <aside className="hidden lg:flex flex-col w-44 shrink-0 overflow-y-auto custom-scrollbar p-5 gap-2 z-10">
        <div className="mb-2 px-1 shrink-0">
          <p className="text-[#0f172a] font-black text-[9px] uppercase tracking-widest opacity-30">الأقسام</p>
        </div>
        <button 
          onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }}
          className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${!selectedMainCat ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'bg-transparent border-slate-200 text-slate-500 hover:border-slate-400'}`}
        >
          كافة الأصناف
        </button>
        {mainCategories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
            className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${selectedMainCat === cat.id ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'bg-transparent border-slate-200 text-slate-500 hover:border-slate-400'}`}
          >
            {cat.name}
          </button>
        ))}
      </aside>

      {/* 2. MAIN WORKSPACE */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] border-r border-slate-200 overflow-hidden relative">

        {/* Search & Tool Header */}
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm shrink-0">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input 
                type="text" 
                placeholder="البحث بالاسم أو الباركود..." 
                className="w-full pr-14 pl-6 py-4 bg-slate-50 border-2 border-slate-300 focus:border-[#0f172a] rounded-[1.5rem] transition-all outline-none font-black text-lg text-[#0f172a]"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-[#0f172a]" size={24} />
            </div>

            <div className="flex gap-2 w-full sm:w-auto">
              <button 
                onClick={() => setShowExtraModal(true)}
                className="px-6 py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-all flex-1 sm:flex-none active:scale-95 shadow-lg"
              >
                <PlusCircle size={20} />
                <span>خدمة إضافية</span>
              </button>
              <button onClick={toggleFullscreen} className="p-4 bg-white border-2 border-slate-300 text-[#0f172a] rounded-2xl hover:border-[#0f172a] transition-all">
                {isFullscreen ? <Minimize2 size={24} /> : <Maximize2 size={24} />}
              </button>
              <button 
                onClick={() => setIsCartOpen(!isCartOpen)} 
                className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-white text-[#0f172a] border-slate-300'}`}
              >
                <ShoppingBag size={24} />
              </button>
            </div>
          </div>

          {/* Sub-Categories Horizontal */}
          {selectedMainCat && (
            <div className="flex items-center gap-2 overflow-x-auto mt-4 pb-2 no-scrollbar border-t border-slate-100 pt-4">
              {subCategories.map(sub => (
                <button 
                  key={sub.id}
                  onClick={() => setSelectedSubCat(sub.id)}
                  className={`px-5 py-2.5 rounded-xl font-black text-[10px] whitespace-nowrap border-2 transition-all ${selectedSubCat === sub.id ? 'bg-[#0f172a] text-white border-[#0f172a]' : 'bg-transparent text-slate-500 border-slate-200 hover:border-slate-400'}`}
                >
                  {sub.name}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Product Grid */}
        <div className="p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">
          {filteredProducts.map(v => (
            <button 
              key={v.id} 
              onClick={() => { const p = products.find(prod => prod.id === v.product_id); addToCart(v, p); }}
              className="group bg-white p-5 rounded-[1.8rem] border-2 border-slate-200 hover:border-emerald-600 hover:shadow-2xl transition-all duration-300 text-right flex flex-col gap-3 relative h-fit active:scale-95 shadow-sm"
            >
              <div className="flex justify-between items-center">
