const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  const loggedUser = localStorage.getItem('flyyti_user');
  if (!loggedUser) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) setSettings(data);
    } catch (err) { console.error(err); }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) setConfigMissing(true);
    else fetchSettings();
  }, [fetchSettings]);

  if (configMissing) return <SupabaseSetup />;
  if (loading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-[#0f172a] gap-6">
      <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
      <p className="text-white font-black text-lg animate-pulse">جاري التحميل...</p>
    </div>
  );

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
        <Route path="/*" element={
          <ProtectedRoute settings={settings}>
            <Layout settings={settings}>
              <Routes>
                <Route path="/" element={<POS />} />
                <Route path="/daily-reports" element={<DailyReports />} />
                <Route path="/inventory" element={<Inventory />} />
                <Route path="/categories" element={<Categories />} />
                <Route path="/expenses" element={<Expenses />} />
                <Route path="/invoices" element={<Invoices settings={settings} onUpdateSettings={fetchSettings} />} />
                <Route path="/reports" element={<GeneralReports />} />
                <Route path="/security" element={<Security settings={settings} onUpdate={fetchSettings} />} />
              </Routes>
            </Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());
  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    soldItems: [] as any[],
    services: [] as any[]
  });
  const [loading, setLoading] = useState(true);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end);

    if (invoices) {
      const stats = invoices.reduce((acc, inv) => {
        acc.totalSales += Number(inv.net_amount);
        acc.totalCost += Number(inv.total_cost);
        acc.totalProfit += Number(inv.profit);
        acc.discounts += Number(inv.discount);
        inv.invoice_items.forEach((item: any) => { acc.itemsCount += item.quantity; acc.soldItems.push(item); });
        inv.extra_services.forEach((ser: any) => { acc.itemsCount += ser.quantity; acc.services.push(ser); });
        return acc;
      }, { totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, soldItems: [], services: [] });
      setData(stats);
    }
    setLoading(false);
  };

  useEffect(() => { fetchDailyData(selectedDay); }, [selectedDay]);

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-6 overflow-hidden" dir="rtl">

      {/* 1. Header with Compact Day Picker Button */}
      <div className="flex items-center justify-between shrink-0">
        <h2 className="text-xl font-black text-[#0f172a] flex items-center gap-3">
           <History className="text-emerald-600" size={24} />
           التقارير اليومية
        </h2>

        <div className="relative">
          <button 
            onClick={() => setShowDayPicker(!showDayPicker)}
            className="flex items-center gap-3 bg-[#0f172a] text-white px-5 py-3 rounded-2xl shadow-lg shadow-slate-900/20 font-black text-sm active:scale-95 transition-all"
          >
            <Calendar size={18} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={16} className={`transition-transform duration-300 ${showDayPicker ? 'rotate-180' : ''}`} />
          </button>

          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-14 left-0 w-64 bg-white rounded-[1.5rem] shadow-2xl border border-slate-200 p-4 z-[111] animate-slide-in-right">
                <div className="flex justify-between items-center mb-3 px-2">
                  <span className="font-black text-xs text-slate-400">اختر اليوم</span>
                  <button onClick={() => setShowDayPicker(false)}><X size={14} /></button>
                </div>
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button
                      key={day}
                      onClick={() => { setSelectedDay(day); setShowDayPicker(false); }}
                      className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs transition-all ${selectedDay === day ? 'bg-emerald-600 text-white shadow-md' : 'hover:bg-slate-100 text-slate-600'}`}
                    >
                      {day}
                    </button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Compact Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-4 shrink-0">
        {[
