          ) : (
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-4 rounded-2xl border-2 border-slate-200 flex flex-col gap-2 shadow-sm animate-slide-in-right">
                <div className="flex justify-between items-start gap-2">
                  <h4 className="font-black text-[#0f172a] text-[11px] leading-tight line-clamp-2 flex-1">{item.product_name}</h4>
                  <p className="font-black text-emerald-600 text-[12px]">{item.sale_price * item.quantity} ₪</p>
                </div>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-[#0f172a] shadow-sm transition-transform active:scale-90"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center text-[#0f172a] shadow-sm transition-transform active:scale-90"><Plus size={12} /></button>
                  </div>
