                <p className="text-[11px] font-bold text-amber-800 leading-relaxed">تعديل الكميات هنا يقوم بتحديث إجمالي الفاتورة والأرباح. تأكد من صحة البيانات قبل الحفظ.</p>
              </div>

              {/* Items in Invoice */}
              <div className="space-y-2">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">الأصناف والخدمات</p>
                {editingInvoice.invoice_items.map((item: any, idx: number) => (
                  <div key={item.id} className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center justify-between">
                    <div>
                      <p className="font-black text-xs text-slate-700">{item.product_name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-slate-200">
                        <button 
                          onClick={() => {
                            const newItems = [...editingInvoice.invoice_items];
                            newItems[idx].quantity = Math.max(1, newItems[idx].quantity - 1);
                            setEditingInvoice({...editingInvoice, invoice_items: newItems});
                          }}
                          className="w-7 h-7 bg-slate-100 rounded flex items-center justify-center"
                        ><Minus size={12} /></button>
                        <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                        <button 
                          onClick={() => {
                            const newItems = [...editingInvoice.invoice_items];
                            newItems[idx].quantity += 1;
                            setEditingInvoice({...editingInvoice, invoice_items: newItems});
                          }}
                          className="w-7 h-7 bg-slate-100 rounded flex items-center justify-center"
                        ><Plus size={12} /></button>
                      </div>
                    </div>
                  </div>
                ))}
                {editingInvoice.extra_services.map((ser: any, idx: number) => (
                  <div key={ser.id} className="bg-emerald-50/50 p-4 rounded-2xl border border-emerald-100 flex items-center justify-between">
                    <div>
                      <p className="font-black text-xs text-emerald-800">{ser.name}</p>
                      <p className="text-[9px] text-emerald-600 font-bold uppercase">خدمة إضافية</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-emerald-100">
                        <button 
                          onClick={() => {
                            const newSers = [...editingInvoice.extra_services];
                            newSers[idx].quantity = Math.max(1, newSers[idx].quantity - 1);
                            setEditingInvoice({...editingInvoice, extra_services: newSers});
                          }}
                          className="w-7 h-7 bg-emerald-50 rounded flex items-center justify-center"
                        ><Minus size={12} /></button>
                        <span className="font-black text-xs w-6 text-center">{ser.quantity}</span>
                        <button 
                          onClick={() => {
                            const newSers = [...editingInvoice.extra_services];
                            newSers[idx].quantity += 1;
                            setEditingInvoice({...editingInvoice, extra_services: newSers});
                          }}
                          className="w-7 h-7 bg-emerald-50 rounded flex items-center justify-center"
                        ><Plus size={12} /></button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Discount Edit */}
              <div className="pt-4 border-t border-slate-100 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">قيمة الخصم</label>
                <input 
                  type="number" 
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-lg outline-none focus:border-blue-600" 
                  value={editingInvoice.discount}
                  onChange={(e) => setEditingInvoice({...editingInvoice, discount: Number(e.target.value)})}
                />
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 shrink-0">
               <button 
                onClick={handleUpdateInvoice}
                className="w-full py-5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-500 flex items-center justify-center gap-3 transition-all"
               >
                 <Save size={20} />
                 حفظ التعديلات
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DailyReports;

import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History,
  FileText,
  Edit2,
  Trash2,
  Plus,
  Minus,
  Save,
  AlertCircle,
  Search,
  PlusCircle
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [expandedSection, setExpandedSection] = useState<'transactions' | 'invoices' | null>('transactions');

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());

  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    invoices: [] as any[]
  });

  const [loading, setLoading] = useState(true);
  const [editingInvoice, setEditingInvoice] = useState<any>(null);

  // States for adding items during edit
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearch, setItemSearch] = useState('');
  const [showItemSearch, setShowItemSearch] = useState(false);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (invoices) {
      const stats = invoices.reduce((acc, inv) => {
        acc.totalSales += Number(inv.net_amount);
        acc.totalCost += Number(inv.total_cost);
        acc.totalProfit += Number(inv.profit);
        acc.discounts += Number(inv.discount);
        inv.invoice_items.forEach((item: any) => { acc.itemsCount += item.quantity; });
        inv.extra_services.forEach((ser: any) => { acc.itemsCount += ser.quantity; });
        return acc;
      }, { totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, invoices: invoices });
      setData(stats);
    }
    setLoading(false);
  };

  const fetchAllProducts = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    if (prods) {
      const flattened = prods.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
      })));
      setAllProducts(flattened);
    }
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchAllProducts();
  }, [selectedDay]);

  const handleDeleteInvoice = async (invoice: any) => {
    if (!confirm("هل أنت متأكد من حذف هذه الفاتورة نهائياً؟ سيتم إعادة الكميات للمخزون.")) return;

    try {
      for (const item of invoice.invoice_items) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
      }
      await supabase.from('invoices').delete().eq('id', invoice.id);
      fetchDailyData(selectedDay);
    } catch (e) {
      alert("خطأ في الحذف");
    }
  };

  const addItemToEditingInvoice = (v: any) => {
    // Check if variant already exists in the invoice
    const exists = editingInvoice.invoice_items.find((it: any) => it.variant_id === v.id);
    if (exists) {
      const newItems = editingInvoice.invoice_items.map((it: any) => 
        it.variant_id === v.id ? { ...it, quantity: it.quantity + 1 } : it
      );
      setEditingInvoice({ ...editingInvoice, invoice_items: newItems });
    } else {
      const newItem = {
        invoice_id: editingInvoice.id,
        variant_id: v.id,
        product_name: v.productName,
        variant_name: v.name,
        quantity: 1,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        isNew: true // Flag to identify new items
      };
      setEditingInvoice({ 
        ...editingInvoice, 
        invoice_items: [...editingInvoice.invoice_items, newItem] 
      });
    }
    setShowItemSearch(false);
    setItemSearch('');
  };

  const handleUpdateInvoice = async () => {
    if (!editingInvoice) return;

    try {
      // 1. Calculate new totals
      const newSubtotal = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                         editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
      const newCost = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                     editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.cost_price * s.quantity), 0);
      const newNet = Math.max(0, newSubtotal - editingInvoice.discount);

      // 2. Update Invoice Header
      await supabase.from('invoices').update({
        total_amount: newSubtotal,
        discount: editingInvoice.discount,
        net_amount: newNet,
        total_cost: newCost,
        profit: newNet - newCost
      }).eq('id', editingInvoice.id);

      // 3. Update Existing and Add New Items
      const originalInvoice = data.invoices.find(inv => inv.id === editingInvoice.id);

      for (const item of editingInvoice.invoice_items) {
        if (item.isNew) {
          // Insert new item
          const { isNew, ...itemToInsert } = item;
          await supabase.from('invoice_items').insert(itemToInsert);
          // Decrement stock
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        } else {
          // Update existing item
          const originalItem = originalInvoice.invoice_items.find((it: any) => it.id === item.id);
          const diff = item.quantity - originalItem.quantity;

          await supabase.from('invoice_items').update({ quantity: item.quantity }).eq('id', item.id);

          // Sync stock if quantity changed
          if (diff !== 0) {
            const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
            if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - diff }).eq('id', item.variant_id);
          }
        }
      }

      // Update services
      for (const ser of editingInvoice.extra_services) {
        await supabase.from('extra_services').update({ quantity: ser.quantity }).eq('id', ser.id);
      }

      setEditingInvoice(null);
      fetchDailyData(selectedDay);
    } catch (e) {
      console.error(e);
      alert("خطأ في التحديث");
    }
  };

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  const allSoldItems = data.invoices.flatMap(inv => 
    inv.invoice_items.map((it: any) => ({ ...it, type: 'product' }))
    .concat(inv.extra_services.map((ser: any) => ({ ...ser, type: 'service', product_name: ser.name, variant_name: 'خدمة إضافية' })))
  );

  const filteredItems = allProducts.filter(p => 
    p.productName.toLowerCase().includes(itemSearch.toLowerCase()) || 
    (p.barcode && p.barcode.includes(itemSearch))
  ).slice(0, 5);

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-4 overflow-hidden" dir="rtl">

      {/* 1. Header */}
      <div className="flex items-center justify-between shrink-0 mb-2">
        <h2 className="text-xl font-black text-[#0f172a] flex items-center gap-3">
           <History className="text-emerald-600" size={24} />
           التقارير اليومية
        </h2>

        <div className="relative">
          <button 
            onClick={() => setShowDayPicker(!showDayPicker)}
            className="flex items-center gap-3 bg-[#0f172a] text-white px-5 py-3 rounded-2xl shadow-lg shadow-slate-900/20 font-black text-sm"
          >
            <Calendar size={18} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={16} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-14 left-0 w-64 bg-white rounded-[1.5rem] shadow-2xl border border-slate-200 p-4 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Compact Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-4 shrink-0">
        {[
          { label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50' },
          { label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'text-rose-600', bg: 'bg-rose-50' }
        ].map((stat, i) => (
          <div key={i} className="p-4 bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col gap-2">
            <div className={`p-2 w-fit rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={18} /></div>
            <div>
              <p className="text-[9px] font-black uppercase opacity-60 mb-1">{stat.label}</p>
              <p className="text-lg font-black">{stat.value} ₪</p>
            </div>
          </div>
        ))}
      </div>

      {/* 3. Collapsible Sections */}
      <div className="flex-1 flex flex-col gap-4 overflow-hidden">

        {/* Section A: Transactions */}
        <div className={`flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'transactions' ? 'flex-1' : 'h-16'}`}>
          <button 
            onClick={() => setExpandedSection(expandedSection === 'transactions' ? null : 'transactions')}
            className="p-5 flex items-center justify-between hover:bg-slate-50 transition-colors shrink-0"
          >
            <div className="flex items-center gap-3">
              <History size={20} className="text-emerald-600" />
              <h3 className="font-black text-[#0f172a] text-sm">سجل حركة اليوم (الأصناف)</h3>
            </div>
            <ChevronDown size={20} className={`text-slate-400 transition-transform ${expandedSection === 'transactions' ? 'rotate-180' : ''}`} />
          </button>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <table className="w-full text-right">
              <thead className="sticky top-0 bg-slate-50 z-10">
                <tr className="border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <th className="p-4">الصنف</th>
                  <th className="p-4 text-center">الكمية</th>
                  <th className="p-4 text-center">التكلفة (₪)</th>
                  <th className="p-4 text-center">البيع (₪)</th>
                  <th className="p-4 text-left">الربح (₪)</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {allSoldItems.map((item, i) => (
                  <tr key={i} className="hover:bg-slate-50/50">
                    <td className="p-4">
                      <span className="font-black text-slate-900 text-xs block">{item.product_name}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</span>
                    </td>
                    <td className="p-4 text-center font-black text-slate-700 text-xs">{item.quantity}</td>
                    <td className="p-4 text-center font-bold text-slate-400 text-xs">{item.cost_price}</td>
                    <td className="p-4 text-center font-black text-[#0f172a] text-xs">{item.sale_price}</td>
                    <td className="p-4 text-left font-black text-emerald-600 text-xs">{(item.sale_price - item.cost_price) * item.quantity}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Section B: Invoices */}
        <div className={`flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'invoices' ? 'flex-1' : 'h-16'}`}>
          <button 
            onClick={() => setExpandedSection(expandedSection === 'invoices' ? null : 'invoices')}
            className="p-5 flex items-center justify-between hover:bg-slate-50 transition-colors shrink-0"
          >
            <div className="flex items-center gap-3">
              <FileText size={20} className="text-blue-600" />
              <h3 className="font-black text-[#0f172a] text-sm">فواتير اليوم (سجل العمليات)</h3>
            </div>
            <ChevronDown size={20} className={`text-slate-400 transition-transform ${expandedSection === 'invoices' ? 'rotate-180' : ''}`} />
          </button>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
              {data.invoices.map((inv) => (
                <div key={inv.id} className="bg-slate-50 border border-slate-200 rounded-2xl p-4 flex flex-col gap-3">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="font-mono text-[10px] text-slate-400">#{inv.id.slice(0, 8)}</p>
                      <p className="font-black text-xs text-slate-700">{new Date(inv.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => setEditingInvoice(inv)} className="p-2 bg-blue-100 text-blue-600 rounded-lg hover:bg-blue-200 transition-all"><Edit2 size={14} /></button>
                      <button onClick={() => handleDeleteInvoice(inv)} className="p-2 bg-rose-100 text-rose-600 rounded-lg hover:bg-rose-200 transition-all"><Trash2 size={14} /></button>
                    </div>
                  </div>
                  <div className="flex justify-between border-t border-slate-200 pt-2 mt-auto">
                    <span className="text-[10px] font-black text-slate-500 uppercase">الصافي للدفع</span>
                    <span className="font-black text-emerald-600 text-sm">{inv.net_amount} ₪</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* 4. Edit Invoice Modal */}
      {editingInvoice && (
        <div className="fixed inset-0 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 bg-blue-600 text-white flex justify-between items-center shrink-0">
               <div className="flex items-center gap-3">
                 <Edit2 size={20} />
                 <h3 className="font-black text-lg">تعديل فاتورة #{editingInvoice.id.slice(0,8)}</h3>
               </div>
               <button onClick={() => setEditingInvoice(null)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">

              {/* Add New Item Search Area */}
              <div className="relative">
                <div className="flex items-center gap-2 mb-2">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">إضافة صنف للفاتورة</p>
                </div>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="ابحث في المستودع بالاسم أو الباركود..."
                    className="w-full p-4 pr-12 bg-blue-50 border-2 border-blue-100 rounded-2xl outline-none focus:border-blue-600 font-bold transition-all text-sm"
                    value={itemSearch}
                    onChange={(e) => { setItemSearch(e.target.value); setShowItemSearch(true); }}
                    onFocus={() => setShowItemSearch(true)}
                  />
                  <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-400" size={20} />
                </div>

                {showItemSearch && itemSearch.length > 0 && (
                  <div className="absolute top-16 left-0 right-0 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 overflow-hidden divide-y divide-slate-100">
                    {filteredItems.map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => addItemToEditingInvoice(v)}
                        className="w-full p-4 flex items-center justify-between hover:bg-blue-50 transition-colors text-right"
                      >
                        <div>
                          <p className="font-black text-xs text-slate-800">{v.productName}</p>
                          <p className="text-[10px] text-slate-400 font-bold">{v.name}</p>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className="font-black text-blue-600 text-xs">{v.sale_price} ₪</span>
                          <PlusCircle className="text-blue-500" size={18} />
                        </div>
                      </button>
                    ))}
                    {filteredItems.length === 0 && <div className="p-4 text-center text-xs text-slate-400 font-bold">لا توجد نتائج مطابقة</div>}
                  </div>
                )}
              </div>

              {/* Items in Invoice */}
              <div className="space-y-2 pt-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">الأصناف الحالية</p>
                {editingInvoice.invoice_items.map((item: any, idx: number) => (
                  <div key={item.id || `new-${idx}`} className={`p-4 rounded-2xl border flex items-center justify-between ${item.isNew ? 'bg-amber-50 border-amber-200 animate-pulse' : 'bg-slate-50 border-slate-200'}`}>
                    <div>
                      <p className="font-black text-xs text-slate-700">{item.product_name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">
                        {item.variant_name} {item.isNew && <span className="text-amber-600">(صنف جديد)</span>}
                      </p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-slate-200">
                        <button 
                          onClick={() => {
                            const newItems = [...editingInvoice.invoice_items];
                            newItems[idx].quantity = Math.max(1, newItems[idx].quantity - 1);
                            setEditingInvoice({...editingInvoice, invoice_items: newItems});
                          }}
                          className="w-7 h-7 bg-slate-100 rounded flex items-center justify-center"
                        ><Minus size={12} /></button>
                        <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                        <button 
                          onClick={() => {
                            const newItems = [...editingInvoice.invoice_items];
                            newItems[idx].quantity += 1;
                            setEditingInvoice({...editingInvoice, invoice_items: newItems});
                          }}
                          className="w-7 h-7 bg-slate-100 rounded flex items-center justify-center"
                        ><Plus size={12} /></button>
                      </div>
                      <button 
                        onClick={() => {
                          const newItems = editingInvoice.invoice_items.filter((_, i) => i !== idx);
                          setEditingInvoice({...editingInvoice, invoice_items: newItems});
                        }}
                        className="text-slate-300 hover:text-rose-500"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                ))}

                {editingInvoice.extra_services.map((ser: any, idx: number) => (
                  <div key={ser.id} className="bg-emerald-50/50 p-4 rounded-2xl border border-emerald-100 flex items-center justify-between">
                    <div>
                      <p className="font-black text-xs text-emerald-800">{ser.name}</p>
                      <p className="text-[9px] text-emerald-600 font-bold uppercase">خدمة إضافية</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-emerald-100">
                        <button 
                          onClick={() => {
                            const newSers = [...editingInvoice.extra_services];
                            newSers[idx].quantity = Math.max(1, newSers[idx].quantity - 1);
                            setEditingInvoice({...editingInvoice, extra_services: newSers});
                          }}
                          className="w-7 h-7 bg-emerald-50 rounded flex items-center justify-center"
                        ><Minus size={12} /></button>
                        <span className="font-black text-xs w-6 text-center">{ser.quantity}</span>
                        <button 
                          onClick={() => {
                            const newSers = [...editingInvoice.extra_services];
                            newSers[idx].quantity += 1;
                            setEditingInvoice({...editingInvoice, extra_services: newSers});
                          }}
                          className="w-7 h-7 bg-emerald-50 rounded flex items-center justify-center"
                        ><Plus size={12} /></button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Discount Edit */}
              <div className="pt-4 border-t border-slate-100 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">قيمة الخصم للفاتورة</label>
                <input 
                  type="number" 
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-lg outline-none focus:border-blue-600 text-center" 
                  value={editingInvoice.discount}
                  onChange={(e) => setEditingInvoice({...editingInvoice, discount: Number(e.target.value)})}
                />
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 shrink-0">
               <button 
                onClick={handleUpdateInvoice}
                className="w-full py-5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-500 flex items-center justify-center gap-3 transition-all"
               >
                 <Save size={20} />
                 حفظ الفاتورة النهائية
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DailyReports;

import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History,
  FileText,
  Edit2,
  Trash2,
  Plus,
  Minus,
  Save,
  AlertCircle,
  Search,
  PlusCircle
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [expandedSection, setExpandedSection] = useState<'transactions' | 'invoices' | null>('transactions');

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());

  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    invoices: [] as any[]
  });

  const [loading, setLoading] = useState(true);
  const [editingInvoice, setEditingInvoice] = useState<any>(null);

  // States for adding items during edit
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearch, setItemSearch] = useState('');
  const [showItemSearch, setShowItemSearch] = useState(false);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (invoices) {
      const stats = invoices.reduce((acc, inv) => {
        acc.totalSales += Number(inv.net_amount);
        acc.totalCost += Number(inv.total_cost);
        acc.totalProfit += Number(inv.profit);
        acc.discounts += Number(inv.discount);
        inv.invoice_items.forEach((item: any) => { acc.itemsCount += item.quantity; });
        inv.extra_services.forEach((ser: any) => { acc.itemsCount += ser.quantity; });
        return acc;
      }, { totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, invoices: invoices });
      setData(stats);
    }
    setLoading(false);
  };

  const fetchAllProducts = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    if (prods) {
      const flattened = prods.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
      })));
      setAllProducts(flattened);
    }
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchAllProducts();
  }, [selectedDay]);

  const handleDeleteInvoice = async (invoice: any) => {
    if (!confirm("هل أنت متأكد من حذف هذه الفاتورة نهائياً؟ سيتم إعادة الكميات للمخزون.")) return;

    try {
      for (const item of invoice.invoice_items) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
      }
      await supabase.from('invoices').delete().eq('id', invoice.id);
      fetchDailyData(selectedDay);
    } catch (e) {
      alert("خطأ في الحذف");
    }
  };

  const addItemToEditingInvoice = (v: any) => {
    // Check if variant already exists in the invoice
    const exists = editingInvoice.invoice_items.find((it: any) => it.variant_id === v.id);
    if (exists) {
      const newItems = editingInvoice.invoice_items.map((it: any) => 
        it.variant_id === v.id ? { ...it, quantity: it.quantity + 1 } : it
      );
      setEditingInvoice({ ...editingInvoice, invoice_items: newItems });
    } else {
      const newItem = {
        invoice_id: editingInvoice.id,
        variant_id: v.id,
        product_name: v.productName,
        variant_name: v.name,
        quantity: 1,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        isNew: true // Flag to identify new items
      };
      setEditingInvoice({ 
        ...editingInvoice, 
        invoice_items: [...editingInvoice.invoice_items, newItem] 
      });
    }
    setShowItemSearch(false);
    setItemSearch('');
  };

  const handleUpdateInvoice = async () => {
    if (!editingInvoice) return;

    try {
      // 1. Calculate new totals
      const newSubtotal = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                         editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
      const newCost = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                     editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.cost_price * s.quantity), 0);
      const newNet = Math.max(0, newSubtotal - editingInvoice.discount);

      // 2. Update Invoice Header
      await supabase.from('invoices').update({
        total_amount: newSubtotal,
        discount: editingInvoice.discount,
        net_amount: newNet,
        total_cost: newCost,
        profit: newNet - newCost
      }).eq('id', editingInvoice.id);

      // 3. Update Existing and Add New Items
      const originalInvoice = data.invoices.find(inv => inv.id === editingInvoice.id);

      for (const item of editingInvoice.invoice_items) {
        if (item.isNew) {
          // Insert new item
          const { isNew, ...itemToInsert } = item;
          await supabase.from('invoice_items').insert(itemToInsert);
          // Decrement stock
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        } else {
          // Update existing item
          const originalItem = originalInvoice.invoice_items.find((it: any) => it.id === item.id);
          const diff = item.quantity - originalItem.quantity;

          await supabase.from('invoice_items').update({ quantity: item.quantity }).eq('id', item.id);

          // Sync stock if quantity changed
          if (diff !== 0) {
            const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
            if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - diff }).eq('id', item.variant_id);
          }
        }
      }

      // Update services
      for (const ser of editingInvoice.extra_services) {
        await supabase.from('extra_services').update({ quantity: ser.quantity }).eq('id', ser.id);
      }

      setEditingInvoice(null);
      fetchDailyData(selectedDay);
    } catch (e) {
      console.error(e);
      alert("خطأ في التحديث");
    }
  };

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  const allSoldItems = data.invoices.flatMap(inv => 
    inv.invoice_items.map((it: any) => ({ ...it, type: 'product' }))
    .concat(inv.extra_services.map((ser: any) => ({ ...ser, type: 'service', product_name: ser.name, variant_name: 'خدمة إضافية' })))
  );

  const filteredItems = allProducts.filter(p => 
    p.productName.toLowerCase().includes(itemSearch.toLowerCase()) || 
    (p.barcode && p.barcode.includes(itemSearch))
  ).slice(0, 5);

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-4 overflow-hidden" dir="rtl">

      {/* 1. Header */}
      <div className="flex items-center justify-between shrink-0 mb-2">
        <h2 className="text-xl font-black text-[#0f172a] flex items-center gap-3">
           <History className="text-emerald-600" size={24} />
           التقارير اليومية
        </h2>

        <div className="relative">
          <button 
            onClick={() => setShowDayPicker(!showDayPicker)}
            className="flex items-center gap-3 bg-[#0f172a] text-white px-5 py-3 rounded-2xl shadow-lg shadow-slate-900/20 font-black text-sm"
          >
            <Calendar size={18} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={16} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-14 left-0 w-64 bg-white rounded-[1.5rem] shadow-2xl border border-slate-200 p-4 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Compact Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-4 shrink-0">
        {[
          { label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50' },
          { label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'text-rose-600', bg: 'bg-rose-50' }
        ].map((stat, i) => (
          <div key={i} className="p-4 bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col gap-2">
            <div className={`p-2 w-fit rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={18} /></div>
            <div>
              <p className="text-[9px] font-black uppercase opacity-60 mb-1">{stat.label}</p>
              <p className="text-lg font-black">{stat.value} ₪</p>
            </div>
          </div>
        ))}
      </div>

      {/* 3. Collapsible Sections */}
      <div className="flex-1 flex flex-col gap-4 overflow-hidden">

        {/* Section A: Transactions */}
        <div className={`flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'transactions' ? 'flex-1' : 'h-16'}`}>
          <button 
            onClick={() => setExpandedSection(expandedSection === 'transactions' ? null : 'transactions')}
            className="p-5 flex items-center justify-between hover:bg-slate-50 transition-colors shrink-0"
          >
            <div className="flex items-center gap-3">
              <History size={20} className="text-emerald-600" />
              <h3 className="font-black text-[#0f172a] text-sm">سجل حركة اليوم (الأصناف)</h3>
            </div>
            <ChevronDown size={20} className={`text-slate-400 transition-transform ${expandedSection === 'transactions' ? 'rotate-180' : ''}`} />
          </button>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <table className="w-full text-right">
              <thead className="sticky top-0 bg-slate-50 z-10">
                <tr className="border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <th className="p-4">الصنف</th>
                  <th className="p-4 text-center">الكمية</th>
                  <th className="p-4 text-center">التكلفة (₪)</th>
                  <th className="p-4 text-center">البيع (₪)</th>
                  <th className="p-4 text-left">الربح (₪)</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {allSoldItems.map((item, i) => (
                  <tr key={i} className="hover:bg-slate-50/50">
                    <td className="p-4">
                      <span className="font-black text-slate-900 text-xs block">{item.product_name}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</span>
                    </td>
                    <td className="p-4 text-center font-black text-slate-700 text-xs">{item.quantity}</td>
                    <td className="p-4 text-center font-bold text-slate-400 text-xs">{item.cost_price}</td>
                    <td className="p-4 text-center font-black text-[#0f172a] text-xs">{item.sale_price}</td>
                    <td className="p-4 text-left font-black text-emerald-600 text-xs">{(item.sale_price - item.cost_price) * item.quantity}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Section B: Invoices */}
        <div className={`flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'invoices' ? 'flex-1' : 'h-16'}`}>
          <button 
            onClick={() => setExpandedSection(expandedSection === 'invoices' ? null : 'invoices')}
            className="p-5 flex items-center justify-between hover:bg-slate-50 transition-colors shrink-0"
          >
            <div className="flex items-center gap-3">
              <FileText size={20} className="text-blue-600" />
              <h3 className="font-black text-[#0f172a] text-sm">فواتير اليوم (سجل العمليات)</h3>
            </div>
            <ChevronDown size={20} className={`text-slate-400 transition-transform ${expandedSection === 'invoices' ? 'rotate-180' : ''}`} />
          </button>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
              {data.invoices.map((inv) => (
                <div key={inv.id} className="bg-slate-50 border border-slate-200 rounded-2xl p-4 flex flex-col gap-3 shadow-sm">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="font-mono text-[10px] text-slate-400">#{inv.id.slice(0, 8)}</p>
                      <p className="font-black text-xs text-slate-700">{new Date(inv.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => setEditingInvoice(inv)} className="p-2 bg-blue-100 text-blue-600 rounded-lg hover:bg-blue-200 transition-all"><Edit2 size={14} /></button>
                      <button onClick={() => handleDeleteInvoice(inv)} className="p-2 bg-rose-100 text-rose-600 rounded-lg hover:bg-rose-200 transition-all"><Trash2 size={14} /></button>
                    </div>
                  </div>

                  {/* Footer with totals */}
                  <div className="flex flex-col gap-1 border-t border-slate-200 pt-2 mt-auto">
                    <div className="flex justify-between items-center opacity-60">
                      <span className="text-[9px] font-black text-slate-500 uppercase">إجمالي الفاتورة</span>
                      <span className="font-bold text-slate-400 text-xs">{inv.total_amount} ₪</span>
                    </div>
                    {Number(inv.discount) > 0 && (
                      <div className="flex justify-between items-center opacity-60">
                        <span className="text-[9px] font-black text-rose-500 uppercase">خصم مطبق</span>
                        <span className="font-bold text-rose-400 text-xs">-{inv.discount} ₪</span>
                      </div>
                    )}
                    <div className="flex justify-between items-center">
                      <span className="text-[10px] font-black text-slate-500 uppercase">الصافي للدفع</span>
                      <span className="font-black text-emerald-600 text-sm">{inv.net_amount} ₪</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* 4. Edit Invoice Modal */}
      {editingInvoice && (
        <div className="fixed inset-0 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 bg-blue-600 text-white flex justify-between items-center shrink-0">
               <div className="flex items-center gap-3">
                 <Edit2 size={20} />
                 <h3 className="font-black text-lg">تعديل فاتورة #{editingInvoice.id.slice(0,8)}</h3>
               </div>
               <button onClick={() => setEditingInvoice(null)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">

              {/* Add New Item Search Area */}
              <div className="relative">
                <div className="flex items-center gap-2 mb-2">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">إضافة صنف للفاتورة</p>
                </div>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="ابحث في المستودع بالاسم أو الباركود..."
                    className="w-full p-4 pr-12 bg-blue-50 border-2 border-blue-100 rounded-2xl outline-none focus:border-blue-600 font-bold transition-all text-sm"
                    value={itemSearch}
                    onChange={(e) => { setItemSearch(e.target.value); setShowItemSearch(true); }}
                    onFocus={() => setShowItemSearch(true)}
                  />
                  <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-400" size={20} />
                </div>

                {showItemSearch && itemSearch.length > 0 && (
                  <div className="absolute top-16 left-0 right-0 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 overflow-hidden divide-y divide-slate-100">
                    {filteredItems.map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => addItemToEditingInvoice(v)}
                        className="w-full p-4 flex items-center justify-between hover:bg-blue-50 transition-colors text-right"
                      >
                        <div>
                          <p className="font-black text-xs text-slate-800">{v.productName}</p>
                          <p className="text-[10px] text-slate-400 font-bold">{v.name}</p>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className="font-black text-blue-600 text-xs">{v.sale_price} ₪</span>
                          <PlusCircle className="text-blue-500" size={18} />
                        </div>
                      </button>
                    ))}
                    {filteredItems.length === 0 && <div className="p-4 text-center text-xs text-slate-400 font-bold">لا توجد نتائج مطابقة</div>}
                  </div>
                )}
              </div>

              {/* Items in Invoice */}
              <div className="space-y-2 pt-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">الأصناف الحالية</p>
                {editingInvoice.invoice_items.map((item: any, idx: number) => (
                  <div key={item.id || `new-${idx}`} className={`p-4 rounded-2xl border flex items-center justify-between ${item.isNew ? 'bg-amber-50 border-amber-200 animate-pulse' : 'bg-slate-50 border-slate-200'}`}>
                    <div>
                      <p className="font-black text-xs text-slate-700">{item.product_name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">
                        {item.variant_name} {item.isNew && <span className="text-amber-600">(صنف جديد)</span>}
                      </p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-slate-200">
                        <button 
                          onClick={() => {
                            const newItems = [...editingInvoice.invoice_items];
                            newItems[idx].quantity = Math.max(1, newItems[idx].quantity - 1);
                            setEditingInvoice({...editingInvoice, invoice_items: newItems});
                          }}
                          className="w-7 h-7 bg-slate-100 rounded flex items-center justify-center"
                        ><Minus size={12} /></button>
                        <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                        <button 
                          onClick={() => {
                            const newItems = [...editingInvoice.invoice_items];
                            newItems[idx].quantity += 1;
                            setEditingInvoice({...editingInvoice, invoice_items: newItems});
                          }}
                          className="w-7 h-7 bg-slate-100 rounded flex items-center justify-center"
                        ><Plus size={12} /></button>
                      </div>
                      <button 
                        onClick={() => {
                          const newItems = editingInvoice.invoice_items.filter((_, i) => i !== idx);
                          setEditingInvoice({...editingInvoice, invoice_items: newItems});
                        }}
                        className="text-slate-300 hover:text-rose-500"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                ))}

                {editingInvoice.extra_services.map((ser: any, idx: number) => (
                  <div key={ser.id} className="bg-emerald-50/50 p-4 rounded-2xl border border-emerald-100 flex items-center justify-between">
                    <div>
                      <p className="font-black text-xs text-emerald-800">{ser.name}</p>
                      <p className="text-[9px] text-emerald-600 font-bold uppercase">خدمة إضافية</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-emerald-100">
                        <button 
                          onClick={() => {
                            const newSers = [...editingInvoice.extra_services];
                            newSers[idx].quantity = Math.max(1, newSers[idx].quantity - 1);
                            setEditingInvoice({...editingInvoice, extra_services: newSers});
                          }}
                          className="w-7 h-7 bg-emerald-50 rounded flex items-center justify-center"
                        ><Minus size={12} /></button>
                        <span className="font-black text-xs w-6 text-center">{ser.quantity}</span>
                        <button 
                          onClick={() => {
                            const newSers = [...editingInvoice.extra_services];
                            newSers[idx].quantity += 1;
                            setEditingInvoice({...editingInvoice, extra_services: newSers});
                          }}
                          className="w-7 h-7 bg-emerald-50 rounded flex items-center justify-center"
                        ><Plus size={12} /></button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Discount Edit */}
              <div className="pt-4 border-t border-slate-100 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">قيمة الخصم للفاتورة</label>
                <input 
                  type="number" 
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-lg outline-none focus:border-blue-600 text-center" 
                  value={editingInvoice.discount}
                  onChange={(e) => setEditingInvoice({...editingInvoice, discount: Number(e.target.value)})}
                />
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 shrink-0">
               <button 
                onClick={handleUpdateInvoice}
                className="w-full py-5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-500 flex items-center justify-center gap-3 transition-all"
               >
                 <Save size={20} />
                 حفظ الفاتورة النهائية
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DailyReports;

import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History,
  FileText,
  Edit2,
  Trash2,
  Plus,
  Minus,
  Save,
  AlertCircle,
  Search,
  PlusCircle
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [expandedSection, setExpandedSection] = useState<'transactions' | 'invoices' | null>('transactions');

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());

  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    invoices: [] as any[]
  });

  const [loading, setLoading] = useState(true);
  const [editingInvoice, setEditingInvoice] = useState<any>(null);

  // States for adding items during edit
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearch, setItemSearch] = useState('');
  const [showItemSearch, setShowItemSearch] = useState(false);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (invoices) {
      const stats = invoices.reduce((acc, inv) => {
        acc.totalSales += Number(inv.net_amount);
        acc.totalCost += Number(inv.total_cost);
        acc.totalProfit += Number(inv.profit);
        acc.discounts += Number(inv.discount);
        inv.invoice_items.forEach((item: any) => { acc.itemsCount += item.quantity; });
        inv.extra_services.forEach((ser: any) => { acc.itemsCount += ser.quantity; });
        return acc;
      }, { totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, invoices: invoices });
      setData(stats);
    }
    setLoading(false);
  };

  const fetchAllProducts = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    if (prods) {
      const flattened = prods.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
      })));
      setAllProducts(flattened);
    }
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchAllProducts();
  }, [selectedDay]);

  const handleDeleteInvoice = async (invoice: any) => {
    if (!confirm("هل أنت متأكد من حذف هذه الفاتورة نهائياً؟ سيتم إعادة الكميات للمخزون.")) return;

    try {
      for (const item of invoice.invoice_items) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
      }
      await supabase.from('invoices').delete().eq('id', invoice.id);
      fetchDailyData(selectedDay);
    } catch (e) {
      alert("خطأ في الحذف");
    }
  };

  const addItemToEditingInvoice = (v: any) => {
    // Check if variant already exists in the invoice
    const exists = editingInvoice.invoice_items.find((it: any) => it.variant_id === v.id);
    if (exists) {
      const newItems = editingInvoice.invoice_items.map((it: any) => 
        it.variant_id === v.id ? { ...it, quantity: it.quantity + 1 } : it
      );
      setEditingInvoice({ ...editingInvoice, invoice_items: newItems });
    } else {
      const newItem = {
        invoice_id: editingInvoice.id,
        variant_id: v.id,
        product_name: v.productName,
        variant_name: v.name,
        quantity: 1,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        isNew: true // Flag to identify new items
      };
      setEditingInvoice({ 
        ...editingInvoice, 
        invoice_items: [...editingInvoice.invoice_items, newItem] 
      });
    }
    setShowItemSearch(false);
    setItemSearch('');
  };

  const handleUpdateInvoice = async () => {
    if (!editingInvoice) return;

    try {
      // 1. Calculate new totals
      const newSubtotal = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                         editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
      const newCost = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                     editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.cost_price * s.quantity), 0);
      const newNet = Math.max(0, newSubtotal - editingInvoice.discount);

      // 2. Update Invoice Header
      await supabase.from('invoices').update({
        total_amount: newSubtotal,
        discount: editingInvoice.discount,
        net_amount: newNet,
        total_cost: newCost,
        profit: newNet - newCost
      }).eq('id', editingInvoice.id);

      // 3. Update Existing and Add New Items
      const originalInvoice = data.invoices.find(inv => inv.id === editingInvoice.id);

      for (const item of editingInvoice.invoice_items) {
        if (item.isNew) {
          // Insert new item
          const { isNew, ...itemToInsert } = item;
          await supabase.from('invoice_items').insert(itemToInsert);
          // Decrement stock
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        } else {
          // Update existing item
          const originalItem = originalInvoice.invoice_items.find((it: any) => it.id === item.id);
          const diff = item.quantity - originalItem.quantity;

          await supabase.from('invoice_items').update({ quantity: item.quantity }).eq('id', item.id);

          // Sync stock if quantity changed
          if (diff !== 0) {
            const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
            if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - diff }).eq('id', item.variant_id);
          }
        }
      }

      // Update services
      for (const ser of editingInvoice.extra_services) {
        await supabase.from('extra_services').update({ quantity: ser.quantity }).eq('id', ser.id);
      }

      setEditingInvoice(null);
      fetchDailyData(selectedDay);
    } catch (e) {
      console.error(e);
      alert("خطأ في التحديث");
    }
  };

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  const allSoldItems = data.invoices.flatMap(inv => 
    inv.invoice_items.map((it: any) => ({ ...it, type: 'product' }))
    .concat(inv.extra_services.map((ser: any) => ({ ...ser, type: 'service', product_name: ser.name, variant_name: 'خدمة إضافية' })))
  );

  const filteredItems = allProducts.filter(p => 
    p.productName.toLowerCase().includes(itemSearch.toLowerCase()) || 
    (p.barcode && p.barcode.includes(itemSearch))
  ).slice(0, 5);

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-4 overflow-hidden" dir="rtl">

      {/* 1. Header */}
      <div className="flex items-center justify-between shrink-0 mb-2">
        <h2 className="text-xl font-black text-[#0f172a] flex items-center gap-3">
           <History className="text-emerald-600" size={24} />
           التقارير اليومية
        </h2>

        <div className="relative">
          <button 
            onClick={() => setShowDayPicker(!showDayPicker)}
            className="flex items-center gap-3 bg-[#0f172a] text-white px-5 py-3 rounded-2xl shadow-lg shadow-slate-900/20 font-black text-sm"
          >
            <Calendar size={18} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={16} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-14 left-0 w-64 bg-white rounded-[1.5rem] shadow-2xl border border-slate-200 p-4 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Compact Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-4 shrink-0">
        {[
          { label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50' },
          { label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'text-rose-600', bg: 'bg-rose-50' }
        ].map((stat, i) => (
          <div key={i} className="p-4 bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col gap-2">
            <div className={`p-2 w-fit rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={18} /></div>
            <div>
              <p className="text-[9px] font-black uppercase opacity-60 mb-1">{stat.label}</p>
              <p className="text-lg font-black">{stat.value} ₪</p>
            </div>
          </div>
        ))}
      </div>

      {/* 3. Collapsible Sections */}
      <div className="flex-1 flex flex-col gap-4 overflow-hidden">

        {/* Section A: Transactions */}
        <div className={`flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'transactions' ? 'flex-1' : 'h-16'}`}>
          <button 
            onClick={() => setExpandedSection(expandedSection === 'transactions' ? null : 'transactions')}
            className="p-5 flex items-center justify-between hover:bg-slate-50 transition-colors shrink-0"
          >
            <div className="flex items-center gap-3">
              <History size={20} className="text-emerald-600" />
              <h3 className="font-black text-[#0f172a] text-sm">سجل حركة اليوم (الأصناف)</h3>
            </div>
            <ChevronDown size={20} className={`text-slate-400 transition-transform ${expandedSection === 'transactions' ? 'rotate-180' : ''}`} />
          </button>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <table className="w-full text-right">
              <thead className="sticky top-0 bg-slate-50 z-10">
                <tr className="border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <th className="p-4">الصنف</th>
                  <th className="p-4 text-center">الكمية</th>
                  <th className="p-4 text-center">التكلفة (₪)</th>
                  <th className="p-4 text-center">البيع (₪)</th>
                  <th className="p-4 text-left">الربح (₪)</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {allSoldItems.map((item, i) => (
                  <tr key={i} className="hover:bg-slate-50/50">
                    <td className="p-4">
                      <span className="font-black text-slate-900 text-xs block">{item.product_name}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</span>
                    </td>
                    <td className="p-4 text-center font-black text-slate-700 text-xs">{item.quantity}</td>
                    <td className="p-4 text-center font-bold text-slate-400 text-xs">{item.cost_price}</td>
                    <td className="p-4 text-center font-black text-[#0f172a] text-xs">{item.sale_price}</td>
                    <td className="p-4 text-left font-black text-emerald-600 text-xs">{(item.sale_price - item.cost_price) * item.quantity}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Section B: Invoices */}
        <div className={`flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'invoices' ? 'flex-1' : 'h-16'}`}>
          <button 
            onClick={() => setExpandedSection(expandedSection === 'invoices' ? null : 'invoices')}
            className="p-5 flex items-center justify-between hover:bg-slate-50 transition-colors shrink-0"
          >
            <div className="flex items-center gap-3">
              <FileText size={20} className="text-blue-600" />
              <h3 className="font-black text-[#0f172a] text-sm">فواتير اليوم (سجل العمليات)</h3>
            </div>
            <ChevronDown size={20} className={`text-slate-400 transition-transform ${expandedSection === 'invoices' ? 'rotate-180' : ''}`} />
          </button>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
              {data.invoices.map((inv) => (
                <div key={inv.id} className="bg-slate-50 border border-slate-200 rounded-2xl p-4 flex flex-col gap-3 shadow-sm">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="font-mono text-[10px] text-slate-400">#{inv.id.slice(0, 8)}</p>
                      <p className="font-black text-xs text-slate-700">{new Date(inv.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => setEditingInvoice(inv)} className="p-2 bg-blue-100 text-blue-600 rounded-lg hover:bg-blue-200 transition-all"><Edit2 size={14} /></button>
                      <button onClick={() => handleDeleteInvoice(inv)} className="p-2 bg-rose-100 text-rose-600 rounded-lg hover:bg-rose-200 transition-all"><Trash2 size={14} /></button>
                    </div>
                  </div>

                  {/* Footer with totals */}
                  <div className="flex flex-col gap-1 border-t border-slate-200 pt-2 mt-auto">
                    <div className="flex justify-between items-center opacity-60">
                      <span className="text-[9px] font-black text-slate-500 uppercase">إجمالي الفاتورة</span>
                      <span className="font-bold text-slate-400 text-xs">{inv.total_amount} ₪</span>
                    </div>
                    {Number(inv.discount) > 0 && (
                      <div className="flex justify-between items-center opacity-60">
                        <span className="text-[9px] font-black text-rose-500 uppercase">خصم مطبق</span>
                        <span className="font-bold text-rose-400 text-xs">-{inv.discount} ₪</span>
                      </div>
                    )}
                    <div className="flex justify-between items-center">
                      <span className="text-[10px] font-black text-slate-500 uppercase">الصافي للدفع</span>
                      <span className="font-black text-emerald-600 text-sm">{inv.net_amount} ₪</span>
                    </div>
                  </div>
                </div>
              ))}
              {data.invoices.length === 0 && (
                <div className="col-span-full py-12 text-center opacity-20 flex flex-col items-center">
                  <FileText size={48} />
                  <p className="font-black mt-2">لا توجد فواتير اليوم</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* 4. Edit Invoice Modal */}
      {editingInvoice && (
        <div className="fixed inset-0 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 bg-blue-600 text-white flex justify-between items-center shrink-0">
               <div className="flex items-center gap-3">
                 <Edit2 size={20} />
                 <h3 className="font-black text-lg">تعديل فاتورة #{editingInvoice.id.slice(0,8)}</h3>
               </div>
               <button onClick={() => setEditingInvoice(null)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">

              {/* Add New Item Search Area */}
              <div className="relative">
                <div className="flex items-center gap-2 mb-2">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">إضافة صنف للفاتورة</p>
                </div>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="ابحث في المستودع بالاسم أو الباركود..."
                    className="w-full p-4 pr-12 bg-blue-50 border-2 border-blue-100 rounded-2xl outline-none focus:border-blue-600 font-bold transition-all text-sm"
                    value={itemSearch}
                    onChange={(e) => { setItemSearch(e.target.value); setShowItemSearch(true); }}
                    onFocus={() => setShowItemSearch(true)}
                  />
                  <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-400" size={20} />
                </div>

                {showItemSearch && itemSearch.length > 0 && (
                  <div className="absolute top-16 left-0 right-0 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 overflow-hidden divide-y divide-slate-100">
                    {filteredItems.map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => addItemToEditingInvoice(v)}
                        className="w-full p-4 flex items-center justify-between hover:bg-blue-50 transition-colors text-right"
                      >
                        <div>
                          <p className="font-black text-xs text-slate-800">{v.productName}</p>
                          <p className="text-[10px] text-slate-400 font-bold">{v.name}</p>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className="font-black text-blue-600 text-xs">{v.sale_price} ₪</span>
                          <PlusCircle className="text-blue-500" size={18} />
                        </div>
                      </button>
                    ))}
                    {filteredItems.length === 0 && <div className="p-4 text-center text-xs text-slate-400 font-bold">لا توجد نتائج مطابقة</div>}
                  </div>
                )}
              </div>

              {/* Items in Invoice */}
              <div className="space-y-2 pt-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">الأصناف الحالية</p>
                {editingInvoice.invoice_items.map((item: any, idx: number) => (
                  <div key={item.id || `new-${idx}`} className={`p-4 rounded-2xl border flex items-center justify-between ${item.isNew ? 'bg-amber-50 border-amber-200 animate-pulse' : 'bg-slate-50 border-slate-200'}`}>
                    <div>
                      <p className="font-black text-xs text-slate-700">{item.product_name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">
                        {item.variant_name} {item.isNew && <span className="text-amber-600">(صنف جديد)</span>}
                      </p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-slate-200">
                        <button 
                          onClick={() => {
                            const newItems = [...editingInvoice.invoice_items];
                            newItems[idx].quantity = Math.max(1, newItems[idx].quantity - 1);
                            setEditingInvoice({...editingInvoice, invoice_items: newItems});
                          }}
                          className="w-7 h-7 bg-slate-100 rounded flex items-center justify-center"
                        ><Minus size={12} /></button>
                        <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                        <button 
                          onClick={() => {
                            const newItems = [...editingInvoice.invoice_items];
                            newItems[idx].quantity += 1;
                            setEditingInvoice({...editingInvoice, invoice_items: newItems});
                          }}
                          className="w-7 h-7 bg-slate-100 rounded flex items-center justify-center"
                        ><Plus size={12} /></button>
                      </div>
                      <button 
                        onClick={() => {
                          const newItems = editingInvoice.invoice_items.filter((_, i) => i !== idx);
                          setEditingInvoice({...editingInvoice, invoice_items: newItems});
                        }}
                        className="text-slate-300 hover:text-rose-500"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                ))}

                {editingInvoice.extra_services.map((ser: any, idx: number) => (
                  <div key={ser.id} className="bg-emerald-50/50 p-4 rounded-2xl border border-emerald-100 flex items-center justify-between">
                    <div>
                      <p className="font-black text-xs text-emerald-800">{ser.name}</p>
                      <p className="text-[9px] text-emerald-600 font-bold uppercase">خدمة إضافية</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-emerald-100">
                        <button 
                          onClick={() => {
                            const newSers = [...editingInvoice.extra_services];
                            newSers[idx].quantity = Math.max(1, newSers[idx].quantity - 1);
                            setEditingInvoice({...editingInvoice, extra_services: newSers});
                          }}
                          className="w-7 h-7 bg-emerald-50 rounded flex items-center justify-center"
                        ><Minus size={12} /></button>
                        <span className="font-black text-xs w-6 text-center">{ser.quantity}</span>
                        <button 
                          onClick={() => {
                            const newSers = [...editingInvoice.extra_services];
                            newSers[idx].quantity += 1;
                            setEditingInvoice({...editingInvoice, extra_services: newSers});
                          }}
                          className="w-7 h-7 bg-emerald-50 rounded flex items-center justify-center"
                        ><Plus size={12} /></button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Discount Edit */}
              <div className="pt-4 border-t border-slate-100 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">قيمة الخصم للفاتورة</label>
                <input 
                  type="number" 
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-lg outline-none focus:border-blue-600 text-center" 
                  value={editingInvoice.discount}
                  onChange={(e) => setEditingInvoice({...editingInvoice, discount: Number(e.target.value)})}
                />
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 shrink-0">
               <button 
                onClick={handleUpdateInvoice}
                className="w-full py-5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-500 flex items-center justify-center gap-3 transition-all"
               >
                 <Save size={20} />
                 حفظ الفاتورة النهائية
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DailyReports;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ShieldCheck, User, Lock, ArrowLeft } from 'lucide-react';
import { supabase } from '../supabase';

const Login: React.FC<{ onLoginSuccess: () => void }> = ({ onLoginSuccess }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data, error: fetchError } = await supabase
        .from('settings')
        .select('username, password')
        .eq('id', 1)
        .single();

      if (fetchError) {
        setError('حدث خطأ في الاتصال بقاعدة البيانات');
        setLoading(false);
        return;
      }

      if (data.username === username && data.password === password) {
        localStorage.setItem('flyyti_user', username);
        onLoginSuccess();
        navigate('/');
      } else {
        setError('اسم المستخدم أو كلمة المرور غير صحيحة');
      }
    } catch (err) {
      setError('خطأ غير متوقع');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] flex items-center justify-center p-6" dir="rtl">
      {/* Decorative background elements */}
      <div className="fixed top-0 left-0 w-full h-full overflow-hidden pointer-events-none opacity-20">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-emerald-600 rounded-full blur-[120px]" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-600 rounded-full blur-[120px]" />
      </div>

      <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden relative z-10 border border-white/10">
        {/* Card Header */}
        <div className="p-10 text-center bg-slate-50 border-b border-slate-100">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-[#0f172a] rounded-[1.5rem] shadow-2xl shadow-slate-900/20 text-white mb-6">
            <ShieldCheck size={40} className="text-emerald-400" />
          </div>
          <h1 className="text-3xl font-black text-[#0f172a] tracking-tight">Flyyti POS</h1>
          <p className="text-slate-500 mt-2 font-bold">نظام الإدارة المتطور</p>
        </div>

        {/* Form Content */}
        <div className="p-10">
          <form onSubmit={handleLogin} className="space-y-6">
            {error && (
              <div className="p-4 bg-rose-50 border-r-4 border-rose-500 text-rose-700 text-xs font-black animate-pulse rounded-lg">
                {error}
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 mr-1 uppercase tracking-widest">اسم المستخدم</label>
              <div className="relative group">
                <input
                  type="text"
                  required
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full pl-4 pr-12 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-[#0f172a] focus:bg-white transition-all outline-none font-bold text-slate-900 placeholder:text-slate-300"
                  placeholder="أدخل اسم المستخدم"
                />
                <User className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-[#0f172a] transition-colors" size={20} />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 mr-1 uppercase tracking-widest">كلمة المرور</label>
              <div className="relative group">
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-4 pr-12 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-[#0f172a] focus:bg-white transition-all outline-none font-bold text-slate-900 placeholder:text-slate-300"
                  placeholder="••••••••"
                />
                <Lock className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-[#0f172a] transition-colors" size={20} />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl shadow-emerald-900/20 hover:bg-emerald-500 active:scale-[0.98] transition-all flex items-center justify-center gap-3"
            >
              {loading ? (
                <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <>
                  <span>تسجيل الدخول للنظام</span>
                  <ArrowLeft size={20} />
                </>
              )}
            </button>
          </form>

          <div className="mt-10 text-center">
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] opacity-50">
              محمي بواسطة Flyyti Security &copy; {new Date().getFullYear()}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History,
  FileText,
  Edit2,
  Trash2,
  Plus,
  Minus,
  Save,
  AlertCircle,
  Search,
  PlusCircle,
  Receipt
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [expandedSection, setExpandedSection] = useState<'transactions' | 'invoices' | null>('transactions');

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());

  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    invoices: [] as any[]
  });

  const [loading, setLoading] = useState(true);
  const [editingInvoice, setEditingInvoice] = useState<any>(null);

  // States for adding items during edit
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearch, setItemSearch] = useState('');
  const [showItemSearch, setShowItemSearch] = useState(false);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (invoices) {
      const stats = invoices.reduce((acc, inv) => {
        acc.totalSales += Number(inv.net_amount);
        acc.totalCost += Number(inv.total_cost);
        acc.totalProfit += Number(inv.profit);
        acc.discounts += Number(inv.discount);
        inv.invoice_items.forEach((item: any) => { acc.itemsCount += item.quantity; });
        inv.extra_services.forEach((ser: any) => { acc.itemsCount += ser.quantity; });
        return acc;
      }, { totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, invoices: invoices });
      setData(stats);
    }
    setLoading(false);
  };

  const fetchAllProducts = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    if (prods) {
      const flattened = prods.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
      })));
      setAllProducts(flattened);
    }
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchAllProducts();
  }, [selectedDay]);

  const handleDeleteInvoice = async (invoice: any) => {
    if (!confirm("هل أنت متأكد من حذف هذه الفاتورة نهائياً؟ سيتم إعادة الكميات للمخزون.")) return;

    try {
      for (const item of invoice.invoice_items) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
      }
      await supabase.from('invoices').delete().eq('id', invoice.id);
      fetchDailyData(selectedDay);
    } catch (e) {
      alert("خطأ في الحذف");
    }
  };

  const addItemToEditingInvoice = (v: any) => {
    const exists = editingInvoice.invoice_items.find((it: any) => it.variant_id === v.id);
    if (exists) {
      const newItems = editingInvoice.invoice_items.map((it: any) => 
        it.variant_id === v.id ? { ...it, quantity: it.quantity + 1 } : it
      );
      setEditingInvoice({ ...editingInvoice, invoice_items: newItems });
    } else {
      const newItem = {
        invoice_id: editingInvoice.id,
        variant_id: v.id,
        product_name: v.productName,
        variant_name: v.name,
        quantity: 1,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        isNew: true 
      };
      setEditingInvoice({ 
        ...editingInvoice, 
        invoice_items: [...editingInvoice.invoice_items, newItem] 
      });
    }
    setShowItemSearch(false);
    setItemSearch('');
  };

  const calculateEditTotals = () => {
    if (!editingInvoice) return { subtotal: 0, net: 0 };
    const subtotal = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                    editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
    const net = Math.max(0, subtotal - editingInvoice.discount);
    return { subtotal, net };
  };

  const handleUpdateInvoice = async () => {
    if (!editingInvoice) return;

    try {
      const { subtotal, net } = calculateEditTotals();
      const newCost = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                     editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.cost_price * s.quantity), 0);

      await supabase.from('invoices').update({
        total_amount: subtotal,
        discount: editingInvoice.discount,
        net_amount: net,
        total_cost: newCost,
        profit: net - newCost
      }).eq('id', editingInvoice.id);

      const originalInvoice = data.invoices.find(inv => inv.id === editingInvoice.id);

      for (const item of editingInvoice.invoice_items) {
        if (item.isNew) {
          const { isNew, ...itemToInsert } = item;
          await supabase.from('invoice_items').insert(itemToInsert);
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        } else {
          const originalItem = originalInvoice.invoice_items.find((it: any) => it.id === item.id);
          const diff = item.quantity - (originalItem ? originalItem.quantity : 0);

          await supabase.from('invoice_items').update({ quantity: item.quantity }).eq('id', item.id);

          if (diff !== 0) {
            const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
            if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - diff }).eq('id', item.variant_id);
          }
        }
      }

      for (const ser of editingInvoice.extra_services) {
        await supabase.from('extra_services').update({ quantity: ser.quantity }).eq('id', ser.id);
      }

      setEditingInvoice(null);
      fetchDailyData(selectedDay);
    } catch (e) {
      console.error(e);
      alert("خطأ في التحديث");
    }
  };

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  const allSoldItems = data.invoices.flatMap(inv => 
    inv.invoice_items.map((it: any) => ({ ...it, type: 'product' }))
    .concat(inv.extra_services.map((ser: any) => ({ ...ser, type: 'service', product_name: ser.name, variant_name: 'خدمة إضافية' })))
  );

  const filteredItems = allProducts.filter(p => 
    p.productName.toLowerCase().includes(itemSearch.toLowerCase()) || 
    (p.barcode && p.barcode.includes(itemSearch))
  ).slice(0, 5);

  const { subtotal: modalSubtotal, net: modalNet } = calculateEditTotals();

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-4 overflow-hidden" dir="rtl">

      {/* 1. Header */}
      <div className="flex items-center justify-between shrink-0 mb-2">
        <h2 className="text-xl font-black text-[#0f172a] flex items-center gap-3">
           <History className="text-emerald-600" size={24} />
           التقارير اليومية
        </h2>

        <div className="relative">
          <button 
            onClick={() => setShowDayPicker(!showDayPicker)}
            className="flex items-center gap-3 bg-[#0f172a] text-white px-5 py-3 rounded-2xl shadow-lg shadow-slate-900/20 font-black text-sm"
          >
            <Calendar size={18} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={16} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-14 left-0 w-64 bg-white rounded-[1.5rem] shadow-2xl border border-slate-200 p-4 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Compact Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-4 shrink-0">
        {[
          { label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50' },
          { label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'text-rose-600', bg: 'bg-rose-50' }
        ].map((stat, i) => (
          <div key={i} className="p-4 bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col gap-2">
            <div className={`p-2 w-fit rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={18} /></div>
            <div>
              <p className="text-[9px] font-black uppercase opacity-60 mb-1">{stat.label}</p>
              <p className="text-lg font-black">{stat.value} ₪</p>
            </div>
          </div>
        ))}
      </div>

      {/* 3. Collapsible Sections */}
      <div className="flex-1 flex flex-col gap-4 overflow-hidden">

        {/* Section A: Transactions */}
        <div className={`flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'transactions' ? 'flex-1' : 'h-16'}`}>
          <button 
            onClick={() => setExpandedSection(expandedSection === 'transactions' ? null : 'transactions')}
            className="p-5 flex items-center justify-between hover:bg-slate-50 transition-colors shrink-0"
          >
            <div className="flex items-center gap-3">
              <History size={20} className="text-emerald-600" />
              <h3 className="font-black text-[#0f172a] text-sm">سجل حركة اليوم (الأصناف)</h3>
            </div>
            <ChevronDown size={20} className={`text-slate-400 transition-transform ${expandedSection === 'transactions' ? 'rotate-180' : ''}`} />
          </button>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <table className="w-full text-right">
              <thead className="sticky top-0 bg-slate-50 z-10">
                <tr className="border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <th className="p-4">الصنف</th>
                  <th className="p-4 text-center">الكمية</th>
                  <th className="p-4 text-center">التكلفة (₪)</th>
                  <th className="p-4 text-center">البيع (₪)</th>
                  <th className="p-4 text-left">الربح (₪)</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {allSoldItems.map((item, i) => (
                  <tr key={i} className="hover:bg-slate-50/50">
                    <td className="p-4">
                      <span className="font-black text-slate-900 text-xs block">{item.product_name}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</span>
                    </td>
                    <td className="p-4 text-center font-black text-slate-700 text-xs">{item.quantity}</td>
                    <td className="p-4 text-center font-bold text-slate-400 text-xs">{item.cost_price}</td>
                    <td className="p-4 text-center font-black text-[#0f172a] text-xs">{item.sale_price}</td>
                    <td className="p-4 text-left font-black text-emerald-600 text-xs">{(item.sale_price - item.cost_price) * item.quantity}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Section B: Invoices */}
        <div className={`flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'invoices' ? 'flex-1' : 'h-16'}`}>
          <button 
            onClick={() => setExpandedSection(expandedSection === 'invoices' ? null : 'invoices')}
            className="p-5 flex items-center justify-between hover:bg-slate-50 transition-colors shrink-0"
          >
            <div className="flex items-center gap-3">
              <FileText size={20} className="text-blue-600" />
              <h3 className="font-black text-[#0f172a] text-sm">فواتير اليوم (سجل العمليات)</h3>
            </div>
            <ChevronDown size={20} className={`text-slate-400 transition-transform ${expandedSection === 'invoices' ? 'rotate-180' : ''}`} />
          </button>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
              {data.invoices.map((inv) => (
                <div key={inv.id} className="bg-slate-50 border border-slate-200 rounded-2xl p-4 flex flex-col gap-3 shadow-sm border-r-4 border-r-blue-500">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="font-mono text-[10px] text-slate-400">#{inv.id.slice(0, 8)}</p>
                      <p className="font-black text-xs text-slate-700">{new Date(inv.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => setEditingInvoice(inv)} className="p-2 bg-blue-100 text-blue-600 rounded-lg hover:bg-blue-200 transition-all"><Edit2 size={14} /></button>
                      <button onClick={() => handleDeleteInvoice(inv)} className="p-2 bg-rose-100 text-rose-600 rounded-lg hover:bg-rose-200 transition-all"><Trash2 size={14} /></button>
                    </div>
                  </div>

                  <div className="flex flex-col gap-1 border-t border-slate-200 pt-2 mt-auto">
                    <div className="flex justify-between items-center opacity-60">
                      <span className="text-[9px] font-black text-slate-500 uppercase">قيمة الفاتورة</span>
                      <span className="font-black text-slate-600 text-xs">{inv.total_amount} ₪</span>
                    </div>
                    {Number(inv.discount) > 0 && (
                      <div className="flex justify-between items-center opacity-60">
                        <span className="text-[9px] font-black text-rose-500 uppercase">الخصم</span>
                        <span className="font-bold text-rose-400 text-xs">-{inv.discount} ₪</span>
                      </div>
                    )}
                    <div className="flex justify-between items-center mt-1">
                      <span className="text-[11px] font-black text-[#0f172a] uppercase">الصافي للدفع</span>
                      <span className="font-black text-emerald-600 text-base">{inv.net_amount} ₪</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* 4. Edit Invoice Modal with LIVE TOTALS */}
      {editingInvoice && (
        <div className="fixed inset-0 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 bg-[#0f172a] text-white flex justify-between items-center shrink-0 border-b border-white/10">
               <div className="flex items-center gap-3">
                 <div className="p-2 bg-emerald-600 rounded-xl shadow-lg shadow-emerald-900/40"><Edit2 size={20} /></div>
                 <h3 className="font-black text-lg">تعديل فاتورة #{editingInvoice.id.slice(0,8)}</h3>
               </div>
               <button onClick={() => setEditingInvoice(null)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar bg-slate-50/50">

              {/* Add New Item Search Area */}
              <div className="relative">
                <div className="flex items-center gap-2 mb-2">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">إضافة صنف جديد</p>
                </div>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="ابحث بالاسم أو الباركود..."
                    className="w-full p-4 pr-12 bg-white border-2 border-slate-200 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all text-sm shadow-sm"
                    value={itemSearch}
                    onChange={(e) => { setItemSearch(e.target.value); setShowItemSearch(true); }}
                    onFocus={() => setShowItemSearch(true)}
                  />
                  <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                </div>

                {showItemSearch && itemSearch.length > 0 && (
                  <div className="absolute top-16 left-0 right-0 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 overflow-hidden divide-y divide-slate-100">
                    {filteredItems.map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => addItemToEditingInvoice(v)}
                        className="w-full p-4 flex items-center justify-between hover:bg-emerald-50 transition-colors text-right"
                      >
                        <div>
                          <p className="font-black text-xs text-slate-800">{v.productName}</p>
                          <p className="text-[10px] text-slate-400 font-bold">{v.name}</p>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className="font-black text-emerald-600 text-xs">{v.sale_price} ₪</span>
                          <PlusCircle className="text-emerald-500" size={18} />
                        </div>
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {/* Items List */}
              <div className="space-y-2 pt-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">الأصناف المضافة</p>
                {editingInvoice.invoice_items.map((item: any, idx: number) => (
                  <div key={item.id || `new-${idx}`} className={`p-4 rounded-2xl border flex items-center justify-between shadow-sm transition-all ${item.isNew ? 'bg-emerald-50 border-emerald-200' : 'bg-white border-slate-200'}`}>
                    <div>
                      <p className="font-black text-xs text-slate-700">{item.product_name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-slate-50 p-1 rounded-xl border border-slate-100">
                        <button onClick={() => {
                          const newItems = [...editingInvoice.invoice_items];
                          newItems[idx].quantity = Math.max(1, newItems[idx].quantity - 1);
                          setEditingInvoice({...editingInvoice, invoice_items: newItems});
                        }} className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-slate-400 shadow-sm"><Minus size={14} /></button>
                        <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                        <button onClick={() => {
                          const newItems = [...editingInvoice.invoice_items];
                          newItems[idx].quantity += 1;
                          setEditingInvoice({...editingInvoice, invoice_items: newItems});
                        }} className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-[#0f172a] shadow-sm"><Plus size={14} /></button>
                      </div>
                      <button onClick={() => {
                        const newItems = editingInvoice.invoice_items.filter((_, i) => i !== idx);
                        setEditingInvoice({...editingInvoice, invoice_items: newItems});
                      }} className="text-rose-400 hover:text-rose-600 p-2"><Trash2 size={18} /></button>
                    </div>
                  </div>
                ))}

                {editingInvoice.extra_services.map((ser: any, idx: number) => (
                  <div key={ser.id} className="bg-blue-50 p-4 rounded-2xl border border-blue-100 flex items-center justify-between shadow-sm">
                    <div>
                      <p className="font-black text-xs text-blue-800">{ser.name}</p>
                      <p className="text-[9px] text-blue-600 font-bold uppercase">خدمة إضافية</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-xl border border-blue-200">
                        <button onClick={() => {
                          const newSers = [...editingInvoice.extra_services];
                          newSers[idx].quantity = Math.max(1, newSers[idx].quantity - 1);
                          setEditingInvoice({...editingInvoice, extra_services: newSers});
                        }} className="w-8 h-8 bg-blue-50 rounded-lg flex items-center justify-center text-blue-600"><Minus size={14} /></button>
                        <span className="font-black text-xs w-6 text-center">{ser.quantity}</span>
                        <button onClick={() => {
                          const newSers = [...editingInvoice.extra_services];
                          newSers[idx].quantity += 1;
                          setEditingInvoice({...editingInvoice, extra_services: newSers});
                        }} className="w-8 h-8 bg-blue-50 rounded-lg flex items-center justify-center text-blue-600"><Plus size={14} /></button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Discount Edit */}
              <div className="pt-4 border-t border-slate-200 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">تعديل الخصم</label>
                <div className="relative group">
                   <input 
                    type="number" 
                    className="w-full p-4 bg-white border-2 border-slate-200 rounded-2xl font-black text-xl outline-none focus:border-rose-500 text-center shadow-sm" 
                    value={editingInvoice.discount || ''}
                    placeholder="0.00"
                    onChange={(e) => setEditingInvoice({...editingInvoice, discount: Number(e.target.value)})}
                  />
                  <Scissors className="absolute left-4 top-1/2 -translate-y-1/2 text-rose-300" size={20} />
                </div>
              </div>
            </div>

            {/* LIVE FINANCIAL SUMMARY FOOTER */}
            <div className="p-6 bg-white border-t border-slate-200 shrink-0 space-y-4 shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                     <p className="text-[9px] font-black text-slate-400 uppercase">الإجمالي قبل الخصم</p>
                     <p className="font-black text-slate-700 text-lg">{modalSubtotal} ₪</p>
                  </div>
                  <div className="p-3 bg-emerald-50 rounded-xl border border-emerald-100">
                     <p className="text-[9px] font-black text-emerald-600 uppercase">الصافي الجديد</p>
                     <p className="font-black text-emerald-700 text-lg">{modalNet} ₪</p>
                  </div>
               </div>
               <button 
                onClick={handleUpdateInvoice}
                className="w-full py-5 bg-[#0f172a] text-white font-black text-lg rounded-[1.5rem] shadow-2xl hover:bg-slate-800 flex items-center justify-center gap-3 transition-all active:scale-95"
               >
                 <Save size={20} className="text-emerald-400" />
                 اعتماد وحفظ التغييرات
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DailyReports;

import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History,
  FileText,
  Edit2,
  Trash2,
  Plus,
  Minus,
  Save,
  AlertCircle,
  Search,
  PlusCircle,
  Receipt,
  Eye,
  EyeOff
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  // Change default to null so no section is expanded automatically
  const [expandedSection, setExpandedSection] = useState<'transactions' | 'invoices' | null>(null);
  const [showFinancials, setShowFinancials] = useState(false);

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());

  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    invoices: [] as any[]
  });

  const [loading, setLoading] = useState(true);
  const [editingInvoice, setEditingInvoice] = useState<any>(null);

  // States for adding items during edit
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearch, setItemSearch] = useState('');
  const [showItemSearch, setShowItemSearch] = useState(false);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (invoices) {
      const stats = invoices.reduce((acc, inv) => {
        acc.totalSales += Number(inv.net_amount);
        acc.totalCost += Number(inv.total_cost);
        acc.totalProfit += Number(inv.profit);
        acc.discounts += Number(inv.discount);
        inv.invoice_items.forEach((item: any) => { acc.itemsCount += item.quantity; });
        inv.extra_services.forEach((ser: any) => { acc.itemsCount += ser.quantity; });
        return acc;
      }, { totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, invoices: invoices });
      setData(stats);
    }
    setLoading(false);
  };

  const fetchAllProducts = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    if (prods) {
      const flattened = prods.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
      })));
      setAllProducts(flattened);
    }
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchAllProducts();
  }, [selectedDay]);

  const handleDeleteInvoice = async (invoice: any) => {
    if (!confirm("هل أنت متأكد من حذف هذه الفاتورة نهائياً؟ سيتم إعادة الكميات للمخزون.")) return;

    try {
      for (const item of invoice.invoice_items) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
      }
      await supabase.from('invoices').delete().eq('id', invoice.id);
      fetchDailyData(selectedDay);
    } catch (e) {
      alert("خطأ في الحذف");
    }
  };

  const addItemToEditingInvoice = (v: any) => {
    const exists = editingInvoice.invoice_items.find((it: any) => it.variant_id === v.id);
    if (exists) {
      const newItems = editingInvoice.invoice_items.map((it: any) => 
        it.variant_id === v.id ? { ...it, quantity: it.quantity + 1 } : it
      );
      setEditingInvoice({ ...editingInvoice, invoice_items: newItems });
    } else {
      const newItem = {
        invoice_id: editingInvoice.id,
        variant_id: v.id,
        product_name: v.productName,
        variant_name: v.name,
        quantity: 1,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        isNew: true 
      };
      setEditingInvoice({ 
        ...editingInvoice, 
        invoice_items: [...editingInvoice.invoice_items, newItem] 
      });
    }
    setShowItemSearch(false);
    setItemSearch('');
  };

  const calculateEditTotals = () => {
    if (!editingInvoice) return { subtotal: 0, net: 0 };
    const subtotal = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                    editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
    const net = Math.max(0, subtotal - editingInvoice.discount);
    return { subtotal, net };
  };

  const handleUpdateInvoice = async () => {
    if (!editingInvoice) return;

    try {
      const { subtotal, net } = calculateEditTotals();
      const newCost = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                     editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.cost_price * s.quantity), 0);

      await supabase.from('invoices').update({
        total_amount: subtotal,
        discount: editingInvoice.discount,
        net_amount: net,
        total_cost: newCost,
        profit: net - newCost
      }).eq('id', editingInvoice.id);

      const originalInvoice = data.invoices.find(inv => inv.id === editingInvoice.id);

      for (const item of editingInvoice.invoice_items) {
        if (item.isNew) {
          const { isNew, ...itemToInsert } = item;
          await supabase.from('invoice_items').insert(itemToInsert);
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        } else {
          const originalItem = originalInvoice.invoice_items.find((it: any) => it.id === item.id);
          const diff = item.quantity - (originalItem ? originalItem.quantity : 0);

          await supabase.from('invoice_items').update({ quantity: item.quantity }).eq('id', item.id);

          if (diff !== 0) {
            const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
            if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - diff }).eq('id', item.variant_id);
          }
        }
      }

      for (const ser of editingInvoice.extra_services) {
        await supabase.from('extra_services').update({ quantity: ser.quantity }).eq('id', ser.id);
      }

      setEditingInvoice(null);
      fetchDailyData(selectedDay);
    } catch (e) {
      console.error(e);
      alert("خطأ في التحديث");
    }
  };

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  const allSoldItems = data.invoices.flatMap(inv => 
    inv.invoice_items.map((it: any) => ({ ...it, type: 'product' }))
    .concat(inv.extra_services.map((ser: any) => ({ ...ser, type: 'service', product_name: ser.name, variant_name: 'خدمة إضافية' })))
  );

  const filteredItems = allProducts.filter(p => 
    p.productName.toLowerCase().includes(itemSearch.toLowerCase()) || 
    (p.barcode && p.barcode.includes(itemSearch))
  ).slice(0, 5);

  const { subtotal: modalSubtotal, net: modalNet } = calculateEditTotals();

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-4 overflow-hidden" dir="rtl">

      {/* 1. Header */}
      <div className="flex items-center justify-between shrink-0 mb-2">
        <h2 className="text-xl font-black text-[#0f172a] flex items-center gap-3">
           <History className="text-emerald-600" size={24} />
           التقارير اليومية
        </h2>

        <div className="relative">
          <button 
            onClick={() => setShowDayPicker(!showDayPicker)}
            className="flex items-center gap-3 bg-[#0f172a] text-white px-5 py-3 rounded-2xl shadow-lg shadow-slate-900/20 font-black text-sm"
          >
            <Calendar size={18} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={16} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-14 left-0 w-64 bg-white rounded-[1.5rem] shadow-2xl border border-slate-200 p-4 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Stats Cards with Privacy Shield */}
      <div className="relative shrink-0 overflow-hidden rounded-[2rem]">
        <div className={`grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-4 transition-all duration-500 ${!showFinancials ? 'blur-md grayscale opacity-40 select-none pointer-events-none' : ''}`}>
          {[
            { label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50' },
            { label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50' },
            { label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50' },
            { label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50' },
            { label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'text-rose-600', bg: 'bg-rose-50' }
          ].map((stat, i) => (
            <div key={i} className="p-4 bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col gap-2">
              <div className={`p-2 w-fit rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={18} /></div>
              <div>
                <p className="text-[9px] font-black uppercase opacity-60 mb-1">{stat.label}</p>
                <p className="text-lg font-black">{stat.value} ₪</p>
              </div>
            </div>
          ))}
        </div>

        {/* Privacy Overlay Layer */}
        {!showFinancials && (
          <div className="absolute inset-0 z-20 flex items-center justify-center">
            <div className="absolute inset-0 bg-white/40 backdrop-blur-[2px]" />
            <button 
              onClick={() => setShowFinancials(true)}
              className="relative z-30 group flex flex-col items-center gap-2 bg-[#0f172a] text-white px-8 py-4 rounded-[2rem] shadow-2xl hover:bg-slate-800 transition-all active:scale-95"
