            {pageTitle}
          </span>

          <button 
            onClick={toggleFullscreen}
            className="w-10 h-10 sm:w-12 sm:h-12 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
            title="ملء الشاشة"
          >
            {isFullscreen ? <Minimize2 size={22} /> : <Maximize2 size={22} />}
