          <div className="w-10 h-10 sm:w-12 sm:h-12 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center text-slate-400">
            <ShieldCheck size={22} />
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {children}
