  const [key, setKey] = useState('');

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (url && key) saveSupabaseConfig(url, key);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] flex items-center justify-center p-6 text-white" dir="rtl">
      <div className="bg-white/5 backdrop-blur-xl p-10 rounded-[2.5rem] border border-white/10 w-full max-w-md shadow-2xl space-y-8">
        <div className="text-center">
          <div className="w-20 h-20 bg-emerald-600 rounded-3xl flex items-center justify-center mx-auto shadow-2xl mb-6">
            <Database size={36} />
          </div>
          <h1 className="text-3xl font-black">Flyyti Engine</h1>
          <p className="text-slate-400 font-medium mt-2">اتصال قاعدة البيانات</p>
        </div>
        <form onSubmit={handleSave} className="space-y-5">
          <input type="text" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-emerald-500 text-white" placeholder="URL" value={url} onChange={(e) => setUrl(e.target.value)} />
          <input type="password" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-emerald-500 text-white" placeholder="Key" value={key} onChange={(e) => setKey(e.target.value)} />
          <button type="submit" className="w-full py-5 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-3">دخول <ArrowRight size={20} className="rotate-180" /></button>
        </form>
      </div>
    </div>
  );
};

const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  const loggedUser = localStorage.getItem('flyyti_user');
  if (!loggedUser) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) setSettings(data);
    } catch (err) { console.error(err); }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) setConfigMissing(true);
    else fetchSettings();
  }, [fetchSettings]);

  if (configMissing) return <SupabaseSetup />;
  if (loading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-[#0f172a] gap-6">
      <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
      <p className="text-white font-black text-lg animate-pulse">جاري التحميل...</p>
    </div>
  );

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
        <Route path="/*" element={
          <ProtectedRoute settings={settings}>
            <Layout settings={settings}>
              <Routes>
                <Route path="/" element={<POS />} />
                <Route path="/daily-reports" element={<DailyReports />} />
                <Route path="/inventory" element={<Inventory />} />
                <Route path="/categories" element={<Categories />} />
                <Route path="/expenses" element={<Expenses />} />
                <Route path="/invoices" element={<Invoices settings={settings} onUpdateSettings={fetchSettings} />} />
                <Route path="/reports" element={<GeneralReports />} />
                <Route path="/security" element={<Security settings={settings} onUpdate={fetchSettings} />} />
              </Routes>
            </Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Plus, 
  Search, 
  Edit3, 
  Trash2, 
  Copy, 
  MoreVertical, 
  Tag, 
  ChevronDown,
  ChevronUp,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Barcode
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Product, Variant, Category } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loading, setLoading] = useState(true);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  const [newProduct, setNewProduct] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*');
    setProducts(prods || []);
    setCategories(cats || []);
    setLoading(false);
  };

  const handleAddVariant = () => {
    setNewProduct({
      ...newProduct,
      variants: [...newProduct.variants, { name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
  };

  const handleSaveProduct = async () => {
    const { data: prod, error: pError } = await supabase
      .from('products')
      .insert({
        name: newProduct.name,
        barcode: newProduct.barcode || null,
        supplier: newProduct.supplier,
        category_id: newProduct.category_id || null,
        sub_category_id: newProduct.sub_category_id || null
      })
      .select()
      .single();

    if (pError) return alert("خطأ في إضافة المنتج (تحقق من عدم تكرار الباركود)");

    const variantsToInsert = newProduct.variants.map(v => ({
      ...v,
      product_id: prod.id
    }));

    await supabase.from('variants').insert(variantsToInsert);
    setShowAddModal(false);
    setNewProduct({
      name: '',
      barcode: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    fetchData();
  };

  const handleDelete = async (id: string) => {
    if (confirm("هل أنت متأكد من الحذف؟")) {
      await supabase.from('products').delete().eq('id', id);
      fetchData();
    }
  };

  const handleBulkDelete = async () => {
    if (confirm(`هل أنت متأكد من حذف ${selectedIds.length} منتجات؟`)) {
      await supabase.from('products').delete().in('id', selectedIds);
      setSelectedIds([]);
      fetchData();
    }
  };

  const handleDuplicate = async (product: any) => {
    const { data: prod } = await supabase
      .from('products')
      .insert({
        name: `${product.name} (نسخة)`,
        barcode: product.barcode ? `${product.barcode}-copy` : null,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      })
      .select()
      .single();

    if (prod) {
      const variants = product.variants.map((v: any) => ({
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prod.id
      }));
      await supabase.from('variants').insert(variants);
      fetchData();
    }
  };

  const calculateStockValue = (prods: any[]) => {
    return prods.reduce((sum, p) => {
      const vSum = p.variants.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0);
      return sum + vSum;
    }, 0);
  };

  const filtered = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (p.barcode && p.barcode.includes(searchTerm))
  );

  return (
    <div className="space-y-6" dir="rtl">
      {/* Top Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-900">المخزون</h2>
        <div className="flex gap-3 w-full md:w-auto">
          <button 
            onClick={() => setShowAddModal(true)}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-bold rounded-xl flex items-center justify-center gap-2 shadow-lg shadow-emerald-100 hover:bg-emerald-700 transition-all"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
          {selectedIds.length > 0 && (
            <button 
              onClick={handleBulkDelete}
              className="px-6 py-3 bg-rose-100 text-rose-600 font-bold rounded-xl flex items-center justify-center gap-2 hover:bg-rose-200 transition-all"
            >
              <Trash2 size={20} />
              <span>حذف ({selectedIds.length})</span>
            </button>
          )}
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
            <Package size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">إجمالي الأصناف</p>
            <p className="text-xl font-black text-gray-900">{products.length}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl">
            <DollarSign size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">قيمة المخزون (بالتكلفة)</p>
            <p className="text-xl font-black text-emerald-600">{calculateStockValue(products)} ₪</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-4 bg-purple-50 text-purple-600 rounded-2xl">
            <Layers size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-gray-400">إجمالي القطع</p>
            <p className="text-xl font-black text-gray-900">
              {products.reduce((s, p) => s + p.variants.reduce((vs: number, v: any) => vs + v.stock_quantity, 0), 0)}
            </p>
          </div>
        </div>
      </div>

      {/* Search & Table */}
      <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:border-emerald-500 outline-none font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button className="p-3 bg-gray-50 text-gray-500 rounded-xl hover:bg-gray-100">
            <Filter size={20} />
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="p-4 w-10">
                  <input 
                    type="checkbox" 
                    onChange={(e) => {
                      if (e.target.checked) setSelectedIds(products.map(p => p.id));
                      else setSelectedIds([]);
                    }}
                    checked={selectedIds.length === products.length && products.length > 0}
                  />
                </th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">الصنف والباركود</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">المورد</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest">القسم</th>
                <th className="p-4 text-xs font-black text-gray-400 uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filtered.map(p => (
                <React.Fragment key={p.id}>
                  <tr 
                    onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                    className="hover:bg-slate-50 transition-colors cursor-pointer group"
                  >
                    <td className="p-4" onClick={(e) => e.stopPropagation()}>
                      <input 
                        type="checkbox" 
                        checked={selectedIds.includes(p.id)}
                        onChange={(e) => {
                          if (e.target.checked) setSelectedIds([...selectedIds, p.id]);
                          else setSelectedIds(selectedIds.filter(id => id !== p.id));
                        }}
                      />
                    </td>
                    <td className="p-4">
                       <div className="flex items-center gap-3">
                         <div className={`transition-transform duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600' : 'text-slate-300'}`}>
                           <ChevronDown size={20} />
                         </div>
                         <div>
                           <p className="font-black text-slate-900 text-sm">{p.name}</p>
                           {p.barcode && <p className="text-[10px] font-mono text-slate-400 tracking-tighter flex items-center gap-1"><Barcode size={10}/> {p.barcode}</p>}
                         </div>
                       </div>
                    </td>
                    <td className="p-4 text-slate-500 font-bold text-xs">{p.supplier || '-'}</td>
                    <td className="p-4">
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-2 py-1 rounded">
                        {categories.find(c => c.id === p.category_id)?.name || 'غير مصنف'}
                      </span>
                    </td>
                    <td className="p-4 text-left" onClick={(e) => e.stopPropagation()}>
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={() => handleDuplicate(p)} className="p-2 text-slate-300 hover:text-blue-600"><Copy size={16} /></button>
                        <button onClick={() => handleDelete(p.id)} className="p-2 text-slate-300 hover:text-rose-600"><Trash2 size={16} /></button>
                      </div>
                    </td>
                  </tr>

                  {/* Variants Row - Collapsible */}
                  {expandedProduct === p.id && (
                    <tr className="bg-slate-50/50">
                      <td colSpan={5} className="p-0">
                        <div className="px-14 py-4 space-y-2 animate-slide-in-right">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">الأنواع والخيارات المتاحة:</p>
                          {p.variants.map((v: any) => (
                            <div key={v.id} className="grid grid-cols-4 gap-4 py-3 px-5 bg-white rounded-2xl border border-slate-200 text-xs font-black text-slate-700 shadow-sm">
                              <div className="flex items-center gap-2">
                                <div className="w-2 h-2 rounded-full bg-emerald-500" />
                                <span>{v.name}</span>
                              </div>
                              <div className="flex flex-col">
                                <span className="text-[9px] text-slate-400 uppercase">سعر التكلفة</span>
                                <span className="text-slate-500">{v.cost_price} ₪</span>
                              </div>
                              <div className="flex flex-col">
                                <span className="text-[9px] text-emerald-500 uppercase">سعر البيع</span>
                                <span className="text-emerald-600 font-black">{v.sale_price} ₪</span>
                              </div>
                              <div className="text-left flex flex-col items-end">
                                <span className="text-[9px] text-slate-400 uppercase">الكمية</span>
                                <span className={`px-2 py-0.5 rounded-lg ${v.stock_quantity < 5 ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                  {v.stock_quantity} قطعة
                                </span>
                              </div>
                            </div>
                          ))}
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={5} className="p-12 text-center text-slate-400 font-bold">لا توجد نتائج بحث</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col border border-white/10">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-900/20">
                  <Package size={24} />
                </div>
                <h3 className="text-xl font-black text-[#0f172a]">إضافة صنف جديد للمخزون</h3>
              </div>
              <button onClick={() => setShowAddModal(false)} className="p-2 bg-slate-200 text-slate-500 rounded-xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">
              {/* Product Info Section */}
              <div className="space-y-6">
                 <div className="flex items-center gap-2 mb-4">
                    <p className="text-xs font-black text-slate-400 uppercase tracking-widest border-r-4 border-emerald-500 pr-3">المعلومات الأساسية والباركود</p>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 uppercase tracking-wider mr-1">اسم الصنف</label>
                      <input 
                        type="text" 
                        required
                        placeholder="مثال: آيفون 15 برو"
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all text-sm" 
                        value={newProduct.name}
                        onChange={(e) => setNewProduct({...newProduct, name: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 uppercase tracking-wider mr-1">الباركود (عام للمنتج)</label>
                      <div className="relative group">
                        <input 
                          type="text" 
                          placeholder="امسح الباركود..."
                          className="w-full p-4 pr-12 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all text-sm" 
                          value={newProduct.barcode}
                          onChange={(e) => setNewProduct({...newProduct, barcode: e.target.value})}
                        />
                        <Barcode className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-600 transition-colors" size={20} />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 uppercase tracking-wider mr-1">المورد</label>
                      <input 
                        type="text" 
                        placeholder="اسم التاجر أو الشركة"
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all text-sm" 
                        value={newProduct.supplier}
                        onChange={(e) => setNewProduct({...newProduct, supplier: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 uppercase tracking-wider mr-1">القسم الرئيسي</label>
                      <select 
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all text-sm"
                        value={newProduct.category_id}
                        onChange={(e) => setNewProduct({...newProduct, category_id: e.target.value})}
                      >
                        <option value="">اختر القسم...</option>
                        {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 uppercase tracking-wider mr-1">القسم الفرعي</label>
                      <select 
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all text-sm"
                        value={newProduct.sub_category_id}
                        onChange={(e) => setNewProduct({...newProduct, sub_category_id: e.target.value})}
                      >
                        <option value="">اختر القسم الفرعي...</option>
                        {categories.filter(c => c.parent_id === newProduct.category_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                      </select>
                    </div>
                 </div>
              </div>

              {/* Variants Section */}
              <div className="space-y-4 pt-4 border-t border-slate-100">
                <div className="flex justify-between items-center mb-2">
                  <div className="flex items-center gap-2">
                    <p className="text-xs font-black text-slate-400 uppercase tracking-widest border-r-4 border-blue-500 pr-3">تخصيص الأنواع والكميات (Variants)</p>
                  </div>
                  <button 
                    onClick={handleAddVariant}
                    className="px-5 py-2.5 bg-blue-50 text-blue-600 font-black rounded-xl text-xs flex items-center gap-2 hover:bg-blue-100 transition-all border border-blue-100"
                  >
                    <Plus size={16} /> إضافة نوع جديد
                  </button>
                </div>

                <div className="grid grid-cols-1 gap-4">
                  {newProduct.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 bg-slate-50 rounded-[1.5rem] border border-slate-200 relative group transition-all hover:bg-white hover:shadow-lg">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 mr-1 uppercase">اسم النوع</label>
                        <input 
                          placeholder="مثال: أبيض، 256 جيجا" 
                          className="w-full p-3.5 bg-white rounded-xl border border-slate-200 outline-none focus:border-blue-500 font-bold transition-all text-xs" 
                          value={v.name}
                          onChange={(e) => {
                            const vs = [...newProduct.variants];
                            vs[idx].name = e.target.value;
                            setNewProduct({...newProduct, variants: vs});
                          }}
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 mr-1 uppercase">سعر التكلفة (₪)</label>
                        <input 
                          type="number" placeholder="0.00" 
                          className="w-full p-3.5 bg-white rounded-xl border border-slate-200 outline-none focus:border-blue-500 font-bold transition-all text-xs" 
                          value={v.cost_price || ''}
                          onChange={(e) => {
                            const vs = [...newProduct.variants];
                            vs[idx].cost_price = Number(e.target.value);
                            setNewProduct({...newProduct, variants: vs});
                          }}
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-emerald-500 mr-1 uppercase">سعر البيع (₪)</label>
                        <input 
                          type="number" placeholder="0.00" 
                          className="w-full p-3.5 bg-white rounded-xl border border-emerald-100 text-emerald-600 outline-none focus:border-emerald-500 font-black transition-all text-xs" 
                          value={v.sale_price || ''}
                          onChange={(e) => {
                            const vs = [...newProduct.variants];
                            vs[idx].sale_price = Number(e.target.value);
                            setNewProduct({...newProduct, variants: vs});
                          }}
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 mr-1 uppercase">الكمية المتوفرة</label>
                        <div className="flex gap-2">
                          <input 
                            type="number" placeholder="0" 
                            className="flex-1 p-3.5 bg-white rounded-xl border border-slate-200 outline-none focus:border-blue-500 font-bold transition-all text-xs" 
                            value={v.stock_quantity || ''}
                            onChange={(e) => {
                              const vs = [...newProduct.variants];
                              vs[idx].stock_quantity = Number(e.target.value);
                              setNewProduct({...newProduct, variants: vs});
                            }}
                          />
                          {idx > 0 && (
                            <button 
                              onClick={() => setNewProduct({...newProduct, variants: newProduct.variants.filter((_, i) => i !== idx)})}
                              className="p-3.5 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors"
                            >
                              <Trash2 size={20} />
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <p className="text-xs text-slate-400 font-bold">تأكد من دقة الأسعار والباركود قبل الحفظ.</p>
              <button 
                onClick={handleSaveProduct}
                disabled={!newProduct.name}
                className="px-10 py-5 bg-[#0f172a] text-white font-black text-lg rounded-[1.5rem] shadow-2xl hover:bg-slate-800 transition-all disabled:bg-slate-300 disabled:shadow-none active:scale-95 flex items-center gap-3"
              >
                <Save size={20} className="text-emerald-400" />
                حفظ المنتج في المخزن
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingBag,
  X,
  CheckCircle2,
  Loader2,
  PlusCircle,
  Barcode
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(true);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [selectedProductForVariants, setSelectedProductForVariants] = useState<any>(null);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const addToCart = (variant: Variant, product: any) => {
    setIsCartOpen(true);
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
    setSelectedProductForVariants(null);
  };

  const handleProductClick = (product: any) => {
    if (product.variants.length === 1) {
      addToCart(product.variants[0], product);
    } else {
      setSelectedProductForVariants(product);
    }
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setIsCartOpen(true);
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const netAmount = Math.max(0, subtotal - discount);
    return { subtotal, netAmount };
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    try {
      const { subtotal, netAmount } = calculateTotals();
      const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);
      const { data: invoice, error: invError } = await supabase.from('invoices').insert({
        total_amount: subtotal, discount, net_amount: netAmount, total_cost: totalCost, profit: netAmount - totalCost
      }).select().single();

      if (invError) throw invError;
      const items = cart.filter(c => c.type === 'product');
      const services = cart.filter(c => c.type === 'service');

      if (items.length > 0) {
        await supabase.from('invoice_items').insert(items.map(item => ({
          invoice_id: invoice.id, variant_id: item.variant_id, product_name: item.product_name, variant_name: item.variant_name, quantity: item.quantity, cost_price: item.cost_price, sale_price: item.sale_price
        })));
        for (const item of items) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }
      if (services.length > 0) {
        await supabase.from('extra_services').insert(services.map(ser => ({
          invoice_id: invoice.id, name: ser.product_name, cost_price: ser.cost_price, sale_price: ser.sale_price, quantity: ser.quantity
        })));
      }

      setIsCartOpen(false);
      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
      fetchData();
    } catch (e) { alert("خطأ في إتمام الطلب"); } finally { setIsProcessing(false); }
  };

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? p.category_id === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? p.sub_category_id === selectedSubCat : true;
      return matchSearch && matchMainCat && matchSubCat;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);
  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row h-full font-['Tajawal'] bg-[#f8fafc] overflow-hidden" dir="rtl">

      <aside className="hidden lg:flex flex-col w-44 shrink-0 overflow-y-auto custom-scrollbar p-5 gap-2 z-10">
        <div className="mb-2 px-1 shrink-0">
          <p className="text-[#0f172a] font-black text-[9px] uppercase tracking-widest opacity-30">الأقسام</p>
        </div>
        <button onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }} className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${!selectedMainCat ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-transparent border-slate-200 text-slate-500'}`}>كافة الأصناف</button>
        {mainCategories.map(cat => (
          <button key={cat.id} onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }} className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${selectedMainCat === cat.id ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-transparent border-slate-200 text-slate-500'}`}>{cat.name}</button>
        ))}
      </aside>

      <div className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] border-r border-slate-200 overflow-hidden relative">
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm shrink-0">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input type="text" placeholder="البحث بالاسم أو الباركود..." className="w-full pr-14 pl-6 py-4 bg-slate-50 border-2 border-slate-300 focus:border-[#0f172a] rounded-[1.5rem] outline-none font-black text-lg" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-[#0f172a]" size={24} />
            </div>
            <div className="flex gap-2 w-full sm:w-auto">
              <button onClick={() => setShowExtraModal(true)} className="px-6 py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-all flex-1 shadow-lg"><PlusCircle size={20} /><span>خدمة</span></button>
              <button onClick={() => setIsCartOpen(!isCartOpen)} className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-[#0f172a] border-slate-300'}`}><ShoppingBag size={24} /></button>
            </div>
          </div>
          {selectedMainCat && (
            <div className="flex items-center gap-2 overflow-x-auto mt-4 pb-2 no-scrollbar border-t border-slate-100 pt-4">
              {subCategories.map(sub => (
                <button key={sub.id} onClick={() => setSelectedSubCat(sub.id)} className={`px-5 py-2.5 rounded-xl font-black text-[10px] whitespace-nowrap border-2 transition-all ${selectedSubCat === sub.id ? 'bg-[#0f172a] text-white' : 'bg-transparent text-slate-500 border-slate-200'}`}>{sub.name}</button>
              ))}
            </div>
          )}
        </div>

        <div className="p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">
          {filteredProducts.map(p => (
            <button key={p.id} onClick={() => handleProductClick(p)} className="group bg-white p-5 rounded-[1.8rem] border-2 border-slate-200 hover:border-emerald-600 hover:shadow-2xl transition-all duration-300 text-right flex flex-col gap-3 relative h-fit active:scale-95 shadow-sm">
              <div className="flex justify-between items-center">
                <span className={`text-[9px] font-black px-2 py-1 rounded-lg bg-slate-50 text-slate-500 border border-slate-100`}>
                  {p.variants.reduce((s: number, v: any) => s + v.stock_quantity, 0)} قطعة
                </span>
                <Plus size={18} className="text-slate-300 group-hover:text-emerald-600" />
              </div>
              <div className="flex-1">
                <h3 className="font-black text-[#0f172a] text-sm leading-tight line-clamp-2">{p.name}</h3>
                {p.variants.length > 1 && <p className="text-[9px] text-blue-500 font-bold mt-1 uppercase opacity-70">متعدد الخيارات ({p.variants.length})</p>}
              </div>
              <div className="pt-3 border-t border-slate-100 flex items-center justify-between">
                 <span className="text-lg font-black text-[#0f172a]">{p.variants[0].sale_price} {p.variants.length > 1 && '...'} <span className="text-[10px]">₪</span></span>
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className={`fixed lg:relative inset-y-0 left-0 bg-white border-r border-slate-300 shadow-2xl transition-all duration-500 z-[80] overflow-hidden flex flex-col h-full ${isCartOpen ? 'w-[320px]' : 'w-0'}`}>
        <div className="p-6 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3"><ShoppingBag size={20} className="text-emerald-500" /><span className="font-black text-lg">الفاتورة</span></div>
          <button onClick={() => setIsCartOpen(false)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
          {cart.length === 0 ? <div className="h-full flex flex-col items-center justify-center opacity-10 py-10"><ShoppingBag size={50} /><p className="font-black mt-4 text-sm">السلة فارغة</p></div> : 
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-4 rounded-2xl border-2 border-slate-200 flex flex-col gap-2 shadow-sm animate-slide-in-right">
                <div className="flex justify-between items-start gap-2"><h4 className="font-black text-[#0f172a] text-[11px] line-clamp-2 flex-1">{item.product_name}</h4><p className="font-black text-emerald-600 text-[12px]">{item.sale_price * item.quantity} ₪</p></div>
                <p className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center shadow-sm active:scale-90"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center shadow-sm active:scale-90"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="text-slate-300 hover:text-rose-500 p-1"><Trash2 size={16} /></button>
                </div>
              </div>
            ))
          }
        </div>
        <div className="p-6 bg-white border-t-2 border-slate-200 space-y-4 shrink-0 shadow-lg mt-auto z-10">
          <div className="space-y-2"><div className="flex justify-between text-[10px] font-black text-slate-500 px-1 uppercase tracking-tight"><span>تطبيق خصم</span><span>الإجمالي: {subtotal} ₪</span></div><input type="number" className="w-full py-3 bg-slate-50 border-2 border-slate-200 focus:border-[#0f172a] rounded-xl text-center font-black text-xl outline-none" value={discount || ''} placeholder="0.00" onChange={(e) => setDiscount(Math.min(subtotal, Number(e.target.value)))} /></div>
          <div className="pt-2 flex justify-between items-center border-t border-slate-100"><span className="text-[#0f172a] font-black text-xs opacity-60">الصافي للدفع</span><span className="text-2xl font-black text-emerald-600">{netAmount} ₪</span></div>
          <button onClick={handleFinishOrder} disabled={cart.length === 0 || isProcessing} className="w-full py-4.5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-500 disabled:bg-slate-200 flex items-center justify-center gap-2">
             {isProcessing ? <Loader2 className="animate-spin" /> : <>إتمام الفاتورة <CheckCircle2 size={20} /></>}
          </button>
        </div>
      </div>

      {/* Variant Selector Modal */}
      {selectedProductForVariants && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[250] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-slide-in-right">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between">
              <div className="flex items-center gap-4"><div className="p-2.5 bg-blue-600 rounded-xl"><Layers size={24} /></div><h3 className="text-xl font-black">{selectedProductForVariants.name}</h3></div>
              <button onClick={() => setSelectedProductForVariants(null)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-3 overflow-y-auto max-h-[60vh] custom-scrollbar">
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">يرجى اختيار النوع المطلوب:</p>
              {selectedProductForVariants.variants.map((v: any) => (
                <button key={v.id} onClick={() => addToCart(v, selectedProductForVariants)} className="w-full p-5 bg-slate-50 border-2 border-slate-100 rounded-2xl flex items-center justify-between hover:border-emerald-500 hover:bg-white transition-all group shadow-sm active:scale-95">
                  <div className="text-right">
                    <p className="font-black text-slate-800 text-sm">{v.name}</p>
                    <p className="text-[10px] text-slate-400 font-bold">الكمية: {v.stock_quantity} قطعة</p>
                  </div>
                  <span className="font-black text-emerald-600 text-lg">{v.sale_price} ₪</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden border border-slate-200">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between"><div className="flex items-center gap-4"><div className="p-2.5 bg-emerald-600 rounded-xl"><PlusCircle size={24} /></div><h3 className="text-xl font-black">إضافة خدمة يدوية</h3></div><button onClick={() => setShowExtraModal(false)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button></div>
            <div className="p-8 space-y-6">
              <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">وصف الخدمة</label><input type="text" autoFocus className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" placeholder="مثال: رسوم شحن..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-5">
                <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">التكلفة (₪)</label><input type="number" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})} /></div>
                <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">البيع (₪)</label><input type="number" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold text-emerald-600" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})} /></div>
              </div>
              <button onClick={handleAddExtraService} disabled={!extraService.name || extraService.sale_price <= 0} className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-500">إدراج في السلة</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

