                      />
                    </td>
                    <td className="p-4">
                       <div className="flex items-center gap-3">
                         <div className={`transition-transform duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600' : 'text-slate-300'}`}>
                           <ChevronDown size={20} />
                         </div>
                         <div>
                           <p className="font-black text-slate-900 text-sm">{p.name}</p>
                           {p.barcode && <p className="text-[10px] font-mono text-slate-400 tracking-tighter flex items-center gap-1"><Barcode size={10}/> {p.barcode}</p>}
                         </div>
                       </div>
                    </td>
                    <td className="p-4 text-slate-500 font-bold text-xs">{p.supplier || '-'}</td>
                    <td className="p-4">
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-2 py-1 rounded">
