                    <td className="p-4 text-left" onClick={(e) => e.stopPropagation()}>
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={() => handleDuplicate(p)} className="p-2 text-slate-300 hover:text-blue-600"><Copy size={16} /></button>
                        <button onClick={() => handleDelete(p.id)} className="p-2 text-slate-300 hover:text-rose-600"><Trash2 size={16} /></button>
                      </div>
                    </td>
