                    <td className="p-4">
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-2.5 py-1 rounded-lg border border-blue-100">
                        {categories.find(c => c.id === p.category_id)?.name || 'غير مصنف'}
