                    </td>
                  </tr>

                  {/* Variants Row - Collapsible */}
                  {expandedProduct === p.id && (
                    <tr className="bg-slate-50/30">
                      <td colSpan={5} className="p-0 border-b border-slate-100">
                        <div className="px-14 py-6 space-y-3 animate-slide-in-right">
                          <div className="flex items-center justify-between mb-2">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                              <Layers size={14} />
                              الأنواع والخيارات المتاحة ({p.variants?.length || 0}):
                            </p>
                          </div>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                            {p.variants?.map((v: any) => (
                              <div key={v.id} className="flex items-center justify-between py-4 px-5 bg-white rounded-2xl border border-slate-200 text-xs font-black text-slate-700 shadow-sm hover:border-emerald-200 transition-all">
                                <div className="flex items-center gap-3">
                                  <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]" />
                                  <span className="text-sm">{v.name}</span>
                                </div>
                                <div className="flex items-center gap-6">
                                  <div className="flex flex-col text-left">
                                    <span className="text-[9px] text-slate-400 uppercase mb-0.5">سعر البيع</span>
                                    <span className="text-emerald-600 font-black text-sm">{v.sale_price} ₪</span>
