                                  <div className="flex flex-col text-left border-r pr-4 border-slate-100">
                                    <span className="text-[9px] text-slate-400 uppercase mb-0.5">الكمية</span>
                                    <span className={`px-2 py-0.5 rounded-lg text-center ${v.stock_quantity < 5 ? 'bg-rose-50 text-rose-600 border border-rose-100' : 'bg-emerald-50 text-emerald-600 border border-emerald-100'}`}>
