                          className="w-full p-4 bg-white rounded-2xl border border-slate-200 outline-none focus:border-blue-500 font-black transition-all text-xs" 
                          value={v.cost_price || ''}
                          onChange={(e) => {
                            const vs = [...newProduct.variants];
                            vs[idx].cost_price = Number(e.target.value);
                            setNewProduct({...newProduct, variants: vs});
                          }}
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mr-1">البيع (₪)</label>
                        <input 
                          type="number" placeholder="0.00" 
                          className="w-full p-4 bg-white rounded-2xl border-2 border-emerald-100 text-emerald-600 outline-none focus:border-emerald-500 font-black transition-all text-xs" 
                          value={v.sale_price || ''}
                          onChange={(e) => {
                            const vs = [...newProduct.variants];
                            vs[idx].sale_price = Number(e.target.value);
                            setNewProduct({...newProduct, variants: vs});
                          }}
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-1">الكمية</label>
                        <div className="flex gap-3">
                          <input 
                            type="number" placeholder="0" 
                            className="flex-1 p-4 bg-white rounded-2xl border border-slate-200 outline-none focus:border-blue-500 font-black transition-all text-xs" 
                            value={v.stock_quantity || ''}
                            onChange={(e) => {
                              const vs = [...newProduct.variants];
                              vs[idx].stock_quantity = Number(e.target.value);
                              setNewProduct({...newProduct, variants: vs});
                            }}
                          />
                          {idx > 0 && (
                            <button 
                              onClick={() => setNewProduct({...newProduct, variants: newProduct.variants.filter((_, i) => i !== idx)})}
                              className="p-4 text-rose-500 hover:bg-rose-50 rounded-2xl transition-colors border border-transparent hover:border-rose-100"
                            >
                              <Trash2 size={22} />
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-3 text-amber-600 bg-amber-50 px-5 py-3 rounded-2xl border border-amber-100">
                <AlertCircle size={20} />
                <p className="text-xs font-black">يرجى مراجعة كافة الأسعار والباركود قبل الحفظ النهائي.</p>
              </div>
              <button 
                onClick={handleSaveProduct}
                disabled={!newProduct.name || saving}
                className="px-14 py-5 bg-slate-900 text-white font-black text-lg rounded-[1.8rem] shadow-2xl hover:bg-slate-800 transition-all disabled:bg-slate-200 disabled:shadow-none active:scale-95 flex items-center gap-4"
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} className="text-emerald-400" />}
                <span>{saving ? 'جاري الحفظ...' : 'تأكيد وحفظ الصنف'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Barcode,
  Save,
  AlertCircle,
  Building2,
  Loader2
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  // Filtering States
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [filterSupplier, setFilterSupplier] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);

  const [newProduct, setNewProduct] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddVariant = () => {
    setNewProduct({
      ...newProduct,
      variants: [...newProduct.variants, { name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
  };

  const handleSaveProduct = async () => {
    if (!newProduct.name || saving) return;

    setSaving(true);
    try {
      // 1. Prepare UUID fields (convert empty strings to null)
      const categoryId = newProduct.category_id && newProduct.category_id !== "" ? newProduct.category_id : null;
      const subCategoryId = newProduct.sub_category_id && newProduct.sub_category_id !== "" ? newProduct.sub_category_id : null;

      // 2. Insert Product
      const { data: prodData, error: pError } = await supabase
        .from('products')
        .insert({
          name: newProduct.name,
          barcode: newProduct.barcode || null,
          supplier: newProduct.supplier || null,
          category_id: categoryId,
          sub_category_id: subCategoryId
        })
        .select();

      if (pError) throw pError;
      if (!prodData || prodData.length === 0) throw new Error("لم يتم إرجاع بيانات المنتج بعد الحفظ");

      const prod = prodData[0];

      // 3. Insert Variants
      const variantsToInsert = newProduct.variants.map(v => ({
        name: v.name || 'افتراضي',
        cost_price: Number(v.cost_price) || 0,
        sale_price: Number(v.sale_price) || 0,
        stock_quantity: Number(v.stock_quantity) || 0,
        product_id: prod.id
      }));

      const { error: vError } = await supabase.from('variants').insert(variantsToInsert);
      if (vError) throw vError;

      // Success Reset
      setShowAddModal(false);
      setNewProduct({
        name: '',
        barcode: '',
        supplier: '',
        category_id: '',
        sub_category_id: '',
        variants: [{ name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
      });
      await fetchData();
      alert("تم حفظ الصنف بنجاح ✅");
    } catch (err: any) {
      console.error("Save Error:", err);
      alert(`فشل الحفظ: ${err.message || "تأكد من عدم تكرار الباركود وصحة البيانات"}`);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // منع فتح تفاصيل الصنف عند النقر على الحذف
    if (!confirm("هل أنت متأكد من حذف هذا الصنف بالكامل؟")) return;

    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;

      setProducts(prev => prev.filter(p => p.id !== id));
      setSelectedIds(prev => prev.filter(sid => sid !== id));
      if (expandedProduct === id) setExpandedProduct(null);
      alert("تم الحذف بنجاح");
    } catch (err: any) {
      alert("فشل الحذف: " + err.message);
    }
  };

  const handleBulkDelete = async () => {
    if (!confirm(`هل أنت متأكد من حذف ${selectedIds.length} منتجات؟`)) return;
    try {
      const { error } = await supabase.from('products').delete().in('id', selectedIds);
      if (error) throw error;

      setSelectedIds([]);
      await fetchData();
      alert("تم حذف المجموعة بنجاح");
    } catch (err: any) {
      alert("فشل حذف المجموعة: " + err.message);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      // إفراغ الباركود لأنه يجب أن يكون فريداً
      const { data: prodData, error: pError } = await supabase
        .from('products')
        .insert({
          name: `${product.name} (نسخة)`,
          barcode: null, 
          supplier: product.supplier,
          category_id: product.category_id,
          sub_category_id: product.sub_category_id
        })
        .select();

      if (pError) throw pError;
      const prod = prodData && prodData[0];

      if (prod && product.variants && product.variants.length > 0) {
        const variants = product.variants.map((v: any) => ({
          name: v.name,
          cost_price: v.cost_price,
          sale_price: v.sale_price,
          stock_quantity: v.stock_quantity,
          product_id: prod.id
        }));
        const { error: vError } = await supabase.from('variants').insert(variants);
        if (vError) throw vError;
      }
      await fetchData();
      alert("تم تكرار الصنف بنجاح (بدون باركود لمنع التكرار)");
    } catch (err: any) {
      alert("فشل تكرار الصنف: " + err.message);
    }
  };

  const calculateStockValue = (prods: any[]) => {
    return prods.reduce((sum, p) => {
      const vSum = p.variants?.reduce((vs: number, v: any) => vs + (Number(v.cost_price) * Number(v.stock_quantity)), 0) || 0;
      return sum + vSum;
    }, 0);
  };

  const uniqueSuppliers = useMemo(() => {
    const sups = products.map(p => p.supplier).filter(Boolean);
    return Array.from(new Set(sups));
  }, [products]);

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        (p.barcode && p.barcode.includes(searchTerm));
      const matchCategory = filterCategory === 'all' || p.category_id === filterCategory;
      const matchSupplier = filterSupplier === 'all' || p.supplier === filterSupplier;
      return matchSearch && matchCategory && matchSupplier;
    });
  }, [products, searchTerm, filterCategory, filterSupplier]);

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden" dir="rtl">
      {/* Top Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          <button 
            onClick={() => setShowAddModal(true)}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-emerald-900/20 hover:bg-emerald-700 transition-all active:scale-95"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
          {selectedIds.length > 0 && (
            <button 
              onClick={(e) => { e.preventDefault(); handleBulkDelete(); }}
              className="px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-rose-900/20 hover:bg-rose-600 transition-all active:scale-95 animate-slide-in-right"
            >
              <Trash2 size={20} />
              <span>حذف ({selectedIds.length})</span>
            </button>
          )}
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 shrink-0 px-2">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl"><Package size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إجمالي الأصناف</p><p className="text-xl font-black text-slate-900">{products.length}</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><DollarSign size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">قيمة المخزون</p><p className="text-xl font-black text-emerald-600">{calculateStockValue(products).toFixed(2)} ₪</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl"><Layers size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إجمالي القطع</p><p className="text-xl font-black text-slate-900">{products.reduce((s, p) => s + (p.variants?.reduce((vs: number, v: any) => vs + Number(v.stock_quantity), 0) || 0), 0)}</p></div>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm shrink-0 mx-2 relative z-50">
        <div className="p-4 flex flex-col sm:flex-row items-center gap-4">
          <div className="relative flex-1 w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-emerald-500 outline-none font-black text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="relative w-full sm:w-auto">
            <button 
              onClick={() => setShowFilters(!showFilters)}
              className={`w-full sm:w-auto p-3.5 rounded-2xl transition-all flex items-center justify-center gap-3 font-black text-sm border-2 ${showFilters ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-100 text-slate-500 hover:bg-slate-50'}`}
            >
              <Filter size={18} />
              <span>تصفية</span>
            </button>

            {showFilters && (
              <>
                <div className="fixed inset-0 z-[60]" onClick={() => setShowFilters(false)} />
                <div className="absolute top-16 right-0 left-0 sm:left-auto w-full sm:w-72 bg-white border border-slate-200 shadow-2xl rounded-[2rem] p-6 z-[70] space-y-5 animate-slide-in-right">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-r-4 border-emerald-500 pr-2">فلترة حسب القسم</label>
                    <select 
                      className="w-full p-3.5 bg-slate-50 border-2 border-slate-100 rounded-xl outline-none text-xs font-black"
                      value={filterCategory}
                      onChange={(e) => setFilterCategory(e.target.value)}
                    >
                      <option value="all">جميع الأقسام</option>
                      {categories.filter(c => !c.parent_id).map(c => (
                        <option key={c.id} value={c.id}>{c.name}</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-r-4 border-blue-500 pr-2">فلترة حسب المورد</label>
                    <select 
                      className="w-full p-3.5 bg-slate-50 border-2 border-slate-100 rounded-xl outline-none text-xs font-black"
                      value={filterSupplier}
                      onChange={(e) => setFilterSupplier(e.target.value)}
                    >
                      <option value="all">جميع الموردين</option>
                      {uniqueSuppliers.map(s => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                  </div>
                  <button 
                    onClick={() => { setFilterCategory('all'); setFilterSupplier('all'); setShowFilters(false); }}
                    className="w-full py-3 bg-rose-50 text-rose-600 font-black text-xs hover:bg-rose-100 rounded-xl transition-colors border border-rose-100"
                  >
                    إعادة تعيين الفلاتر
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Table Section */}
      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm flex-1 mx-2 mb-4 overflow-hidden flex flex-col">
        <div className="overflow-x-auto flex-1 custom-scrollbar">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-50/90 backdrop-blur-sm z-10 border-b border-slate-200">
              <tr>
                <th className="p-5 w-14 text-center">
                  <input 
                    type="checkbox" 
                    className="w-5 h-5 rounded-lg accent-emerald-600 cursor-pointer"
                    onChange={(e) => {
                      if (e.target.checked) setSelectedIds(filtered.map(p => p.id));
                      else setSelectedIds([]);
                    }}
                    checked={selectedIds.length === filtered.length && filtered.length > 0}
                  />
                </th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">اسم الصنف والباركود</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">المورد</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">القسم</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filtered.map(p => (
                <React.Fragment key={p.id}>
                  <tr 
                    onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                    className={`transition-all cursor-pointer group ${expandedProduct === p.id ? 'bg-emerald-50/30' : 'hover:bg-slate-50/80'}`}
                  >
                    <td className="p-5 text-center" onClick={(e) => e.stopPropagation()}>
                      <input 
                        type="checkbox" 
                        className="w-5 h-5 rounded-lg accent-emerald-600 cursor-pointer"
                        checked={selectedIds.includes(p.id)}
                        onChange={(e) => {
                          if (e.target.checked) setSelectedIds([...selectedIds, p.id]);
                          else setSelectedIds(selectedIds.filter(id => id !== p.id));
                        }}
                      />
                    </td>
                    <td className="p-5">
                       <div className="flex items-center gap-4">
                         <div className={`transition-all duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600 scale-125' : 'text-slate-300 group-hover:text-slate-500'}`}>
                           <ChevronDown size={20} />
                         </div>
                         <div>
                           <p className="font-black text-slate-900 text-sm">{p.name}</p>
                           {p.barcode && (
                             <div className="flex items-center gap-2 mt-1 px-2 py-0.5 bg-slate-100 rounded-md w-fit">
                               <Barcode size={10} className="text-slate-500"/>
                               <p className="text-[10px] font-mono text-slate-500 tracking-tighter">{p.barcode}</p>
                             </div>
                           )}
                         </div>
                       </div>
                    </td>
                    <td className="p-5 text-xs font-black text-slate-500">{p.supplier || '-'}</td>
                    <td className="p-5">
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1.5 rounded-xl border border-blue-100">
                        {categories.find(c => c.id === p.category_id)?.name || 'غير مصنف'}
                      </span>
                    </td>
                    <td className="p-5 text-left" onClick={(e) => e.stopPropagation()}>
                      <div className="flex items-center justify-end gap-3">
                        <button 
                          onClick={(e) => handleDuplicate(e, p)} 
                          className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
                          title="تكرار الصنف"
                        >
                          <Copy size={18} />
                        </button>
                        <button 
                          onClick={(e) => handleDelete(e, p.id)} 
                          className="p-2.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"
                          title="حذف الصنف"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>

                  {expandedProduct === p.id && (
                    <tr className="bg-slate-50/40">
                      <td colSpan={5} className="p-0 border-b border-slate-100">
                        <div className="px-16 py-8 space-y-4 animate-slide-in-right">
                          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                            {p.variants?.map((v: any) => (
                              <div key={v.id} className="bg-white p-5 rounded-3xl border border-slate-200 flex flex-col shadow-sm">
                                <div className="flex justify-between items-center mb-3">
                                  <span className="font-black text-slate-800 text-sm">{v.name}</span>
                                  <span className={`px-2.5 py-1 rounded-lg text-[10px] font-black border ${v.stock_quantity < 5 ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>
                                    {v.stock_quantity} قطعة
                                  </span>
                                </div>
                                <div className="flex justify-between items-center text-xs font-bold pt-2 border-t border-slate-50">
                                   <span className="text-slate-400">سعر البيع:</span>
                                   <span className="text-emerald-600 font-black">{v.sale_price} ₪</span>
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-slide-in-right">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50 shrink-0">
              <div className="flex items-center gap-4">
                <div className="p-4 bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-900/30">
                  <Package size={28} />
                </div>
                <h3 className="text-xl font-black text-slate-900">إضافة صنف جديد للمخزون</h3>
              </div>
              <button onClick={() => setShowAddModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-10 custom-scrollbar max-h-[70vh]">
              <div className="space-y-6">
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 mr-1 uppercase">اسم الصنف *</label>
                      <input 
                        type="text" 
                        required
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all text-sm" 
                        value={newProduct.name}
                        onChange={(e) => setNewProduct({...newProduct, name: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 mr-1 uppercase">الباركود</label>
                      <input 
                        type="text" 
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all text-sm" 
                        value={newProduct.barcode}
                        onChange={(e) => setNewProduct({...newProduct, barcode: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 mr-1 uppercase">المورد</label>
                      <input 
                        type="text" 
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all text-sm" 
                        value={newProduct.supplier}
                        onChange={(e) => setNewProduct({...newProduct, supplier: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 mr-1 uppercase">القسم الرئيسي</label>
                      <select 
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all text-sm"
                        value={newProduct.category_id}
                        onChange={(e) => setNewProduct({...newProduct, category_id: e.target.value})}
                      >
                        <option value="">اختر القسم...</option>
                        {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-500 mr-1 uppercase">القسم الفرعي</label>
                      <select 
                        className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all text-sm"
                        value={newProduct.sub_category_id}
                        onChange={(e) => setNewProduct({...newProduct, sub_category_id: e.target.value})}
                      >
                        <option value="">اختر القسم الفرعي...</option>
                        {categories.filter(c => c.parent_id === newProduct.category_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                      </select>
                    </div>
                 </div>
              </div>

              {/* Variants Section */}
              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-[11px] font-black text-slate-900 uppercase tracking-[0.2em]">الأنواع والكميات</p>
                  <button 
                    onClick={handleAddVariant}
                    className="px-6 py-3 bg-blue-50 text-blue-600 font-black rounded-2xl text-xs flex items-center gap-3 hover:bg-blue-100 transition-all border border-blue-100"
                  >
                    <Plus size={18} /> إضافة نوع جديد
                  </button>
                </div>

                <div className="grid grid-cols-1 gap-4">
                  {newProduct.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 bg-slate-50 rounded-[2rem] border-2 border-slate-100">
                      <input 
                        placeholder="اسم النوع" 
                        className="p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" 
                        value={v.name}
                        onChange={(e) => {
                          const vs = [...newProduct.variants];
                          vs[idx].name = e.target.value;
                          setNewProduct({...newProduct, variants: vs});
                        }}
                      />
                      <input 
                        type="number" placeholder="التكلفة" 
                        className="p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" 
                        value={v.cost_price || ''}
                        onChange={(e) => {
                          const vs = [...newProduct.variants];
                          vs[idx].cost_price = Number(e.target.value);
                          setNewProduct({...newProduct, variants: vs});
                        }}
                      />
                      <input 
                        type="number" placeholder="البيع" 
                        className="p-4 bg-white rounded-2xl border-2 border-emerald-100 text-emerald-600 outline-none font-black text-xs" 
                        value={v.sale_price || ''}
                        onChange={(e) => {
                          const vs = [...newProduct.variants];
                          vs[idx].sale_price = Number(e.target.value);
                          setNewProduct({...newProduct, variants: vs});
                        }}
                      />
                      <div className="flex gap-3">
                        <input 
                          type="number" placeholder="الكمية" 
                          className="flex-1 p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" 
                          value={v.stock_quantity || ''}
                          onChange={(e) => {
                            const vs = [...newProduct.variants];
                            vs[idx].stock_quantity = Number(e.target.value);
                            setNewProduct({...newProduct, variants: vs});
                          }}
                        />
                        {idx > 0 && (
                          <button 
                            onClick={() => setNewProduct({...newProduct, variants: newProduct.variants.filter((_, i) => i !== idx)})}
                            className="p-4 text-rose-500 hover:bg-rose-50 rounded-2xl"
                          >
                            <Trash2 size={22} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between shrink-0">
              <p className="text-xs font-black text-amber-600 bg-amber-50 px-5 py-3 rounded-2xl border border-amber-100">يرجى التأكد من الباركود والأسعار.</p>
              <button 
                onClick={(e) => { e.preventDefault(); handleSaveProduct(); }}
                disabled={!newProduct.name || saving}
                className="px-14 py-5 bg-slate-900 text-white font-black text-lg rounded-[1.8rem] shadow-2xl hover:bg-slate-800 transition-all disabled:bg-slate-200 active:scale-95 flex items-center gap-4"
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} className="text-emerald-400" />}
                <span>{saving ? 'جاري الحفظ...' : 'تأكيد وحفظ الصنف'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Barcode,
  Save,
  AlertCircle,
  Building2,
  Loader2
} from 'lucide-center';
import { supabase } from '../supabase';
import type { Category } from '../types';

// تعويض الأيقونة الناقصة من المكتبة إذا لزم الأمر
import { LucideIcon } from 'lucide-react';
const LoaderIcon = Loader2;

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [filterSupplier, setFilterSupplier] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);

  const [newProduct, setNewProduct] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddVariant = () => {
    setNewProduct({
      ...newProduct,
      variants: [...newProduct.variants, { name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
  };

  const handleSaveProduct = async () => {
    if (!newProduct.name || saving) {
      if (!newProduct.name) alert("يرجى إدخال اسم الصنف");
      return;
    }

    setSaving(true);
    try {
      // 1. فحص وتحويل الـ UUIDs (إذا كانت فارغة نرسل null)
      const categoryId = newProduct.category_id && newProduct.category_id.length > 10 ? newProduct.category_id : null;
      const subCategoryId = newProduct.sub_category_id && newProduct.sub_category_id.length > 10 ? newProduct.sub_category_id : null;

      console.log("جاري حفظ المنتج...", newProduct);

      // 2. إدخال المنتج الرئيسي
      const { data: prodData, error: pError } = await supabase
        .from('products')
        .insert({
          name: newProduct.name,
          barcode: newProduct.barcode || null,
          supplier: newProduct.supplier || null,
          category_id: categoryId,
          sub_category_id: subCategoryId
        })
        .select();

      if (pError) {
        console.error("خطأ في جدول المنتجات:", pError);
        throw new Error(`خطأ في البيانات: ${pError.message}`);
      }

      if (!prodData || prodData.length === 0) {
        throw new Error("فشلت عملية الحفظ، لم يتم إرجاع بيانات من السيرفر. قد يكون هناك مشكلة في صلاحيات RLS.");
      }

      const prodId = prodData[0].id;

      // 3. إدخال الأنواع (Variants)
      const variantsToInsert = newProduct.variants.map(v => ({
        name: v.name || 'افتراضي',
        cost_price: Number(v.cost_price) || 0,
        sale_price: Number(v.sale_price) || 0,
        stock_quantity: Number(v.stock_quantity) || 0,
        product_id: prodId
      }));

      const { error: vError } = await supabase.from('variants').insert(variantsToInsert);

      if (vError) {
        console.error("خطأ في جدول الأنواع:", vError);
        // ملاحظة: المنتج تم حفظه ولكن الأنواع فشلت
        throw new Error(`تم حفظ المنتج ولكن فشل حفظ الكميات: ${vError.message}`);
      }

      // إغلاق المودال وتحديث الواجهة
      setShowAddModal(false);
      setNewProduct({
        name: '',
        barcode: '',
        supplier: '',
        category_id: '',
        sub_category_id: '',
        variants: [{ name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
      });

      await fetchData();
      alert("✅ تم حفظ الصنف بنجاح في المخزون");
    } catch (err: any) {
      console.error("Full Save Error Object:", err);
      alert(`❌ فشل الحفظ: ${err.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذا الصنف بالكامل من المخزون؟")) return;

    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;

      setProducts(prev => prev.filter(p => p.id !== id));
      setSelectedIds(prev => prev.filter(sid => sid !== id));
      alert("تم الحذف بنجاح");
    } catch (err: any) {
      alert("فشل الحذف: " + err.message);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      const { data: prodData, error: pError } = await supabase
        .from('products')
        .insert({
          name: `${product.name} (نسخة)`,
          barcode: null, // الباركود يجب أن يكون فريداً
          supplier: product.supplier,
          category_id: product.category_id,
          sub_category_id: product.sub_category_id
        })
        .select();

      if (pError) throw pError;
      const newProd = prodData[0];

      if (product.variants && product.variants.length > 0) {
        const vars = product.variants.map((v: any) => ({
          name: v.name,
          cost_price: v.cost_price,
          sale_price: v.sale_price,
          stock_quantity: v.stock_quantity,
          product_id: newProd.id
        }));
        await supabase.from('variants').insert(vars);
      }
      await fetchData();
      alert("تم تكرار الصنف بنجاح");
    } catch (err: any) {
      alert("فشل التكرار: " + err.message);
    }
  };

  const calculateStockValue = (prods: any[]) => {
    return prods.reduce((sum, p) => {
      const vSum = p.variants?.reduce((vs: number, v: any) => vs + (Number(v.cost_price) * Number(v.stock_quantity)), 0) || 0;
      return sum + vSum;
    }, 0);
  };

  const uniqueSuppliers = useMemo(() => {
    const sups = products.map(p => p.supplier).filter(Boolean);
    return Array.from(new Set(sups));
  }, [products]);

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        (p.barcode && p.barcode.includes(searchTerm));
      const matchCategory = filterCategory === 'all' || p.category_id === filterCategory;
      const matchSupplier = filterSupplier === 'all' || p.supplier === filterSupplier;
      return matchSearch && matchCategory && matchSupplier;
    });
  }, [products, searchTerm, filterCategory, filterSupplier]);

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden" dir="rtl">
      {/* الرأس العلوي */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          <button 
            onClick={() => setShowAddModal(true)}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-emerald-900/20 hover:bg-emerald-700 transition-all active:scale-95"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
        </div>
      </div>

      {/* بطاقات الإحصائيات */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 shrink-0 px-2">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl"><Package size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إجمالي الأصناف</p><p className="text-xl font-black text-slate-900">{products.length}</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><DollarSign size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">قيمة المخزون</p><p className="text-xl font-black text-emerald-600">{calculateStockValue(products).toFixed(2)} ₪</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl"><Layers size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إجمالي القطع</p><p className="text-xl font-black text-slate-900">{products.reduce((s, p) => s + (p.variants?.reduce((vs: number, v: any) => vs + Number(v.stock_quantity), 0) || 0), 0)}</p></div>
        </div>
      </div>

      {/* شريط البحث والتصفية */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm shrink-0 mx-2 relative z-50">
        <div className="p-4 flex flex-col sm:flex-row items-center gap-4">
          <div className="relative flex-1 w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-emerald-500 outline-none font-black text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`w-full sm:w-auto p-3.5 rounded-2xl transition-all flex items-center justify-center gap-3 font-black text-sm border-2 ${showFilters ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-100 text-slate-500 hover:bg-slate-50'}`}
          >
            <Filter size={18} />
            <span>تصفية</span>
          </button>

          {showFilters && (
            <div className="absolute top-16 right-0 left-0 sm:left-auto sm:right-4 w-full sm:w-72 bg-white border border-slate-200 shadow-2xl rounded-[2rem] p-6 z-[70] space-y-5 animate-slide-in-right">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pr-2">فلترة حسب القسم</label>
                <select className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl" value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)}>
                  <option value="all">جميع الأقسام</option>
                  {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <button onClick={() => { setFilterCategory('all'); setFilterSupplier('all'); setShowFilters(false); }} className="w-full py-2 bg-rose-50 text-rose-600 rounded-xl text-xs font-black">إعادة تعيين</button>
            </div>
          )}
        </div>
      </div>

      {/* جدول البيانات */}
      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm flex-1 mx-2 mb-4 overflow-hidden flex flex-col">
        <div className="overflow-x-auto flex-1 custom-scrollbar">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-50/90 backdrop-blur-sm z-10 border-b border-slate-200">
              <tr>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">اسم الصنف والباركود</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">المورد</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">القسم</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filtered.map(p => (
                <React.Fragment key={p.id}>
                  <tr 
                    onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                    className={`transition-all cursor-pointer group ${expandedProduct === p.id ? 'bg-emerald-50/30' : 'hover:bg-slate-50/80'}`}
                  >
                    <td className="p-5">
                       <div className="flex items-center gap-4">
                         <div className={`transition-all duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600 scale-125' : 'text-slate-300 group-hover:text-slate-500'}`}>
                           <ChevronDown size={20} />
                         </div>
                         <div>
                           <p className="font-black text-slate-900 text-sm">{p.name}</p>
                           {p.barcode && <p className="text-[10px] font-mono text-slate-400">{p.barcode}</p>}
                         </div>
                       </div>
                    </td>
                    <td className="p-5 text-xs font-black text-slate-500">{p.supplier || '-'}</td>
                    <td className="p-5">
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1.5 rounded-xl border border-blue-100">
                        {categories.find(c => c.id === p.category_id)?.name || 'غير مصنف'}
                      </span>
                    </td>
                    <td className="p-5 text-left" onClick={(e) => e.stopPropagation()}>
                      <div className="flex items-center justify-end gap-3">
                        <button onClick={(e) => handleDuplicate(e, p)} className="p-2 text-slate-400 hover:text-blue-600"><Copy size={18} /></button>
                        <button onClick={(e) => handleDelete(e, p.id)} className="p-2 text-slate-400 hover:text-rose-600"><Trash2 size={18} /></button>
                      </div>
                    </td>
                  </tr>
                  {expandedProduct === p.id && (
                    <tr className="bg-slate-50/40">
                      <td colSpan={4} className="p-8">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 animate-slide-in-right">
                          {p.variants?.map((v: any) => (
                            <div key={v.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
                              <div>
                                <p className="font-black text-slate-800 text-xs">{v.name}</p>
                                <p className="text-[10px] text-slate-400">الكمية: {v.stock_quantity}</p>
                              </div>
                              <p className="font-black text-emerald-600">{v.sale_price} ₪</p>
                            </div>
                          ))}
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* نافذة الإضافة (Modal) */}
      {showAddModal && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-slide-in-right">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className="p-4 bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-900/30">
                  <Package size={28} />
                </div>
                <h3 className="text-xl font-black text-slate-900">إضافة صنف جديد للمخزون</h3>
              </div>
              <button onClick={() => setShowAddModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-10 custom-scrollbar max-h-[70vh]">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">اسم الصنف *</label>
                  <input type="text" required className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black" value={newProduct.name} onChange={(e) => setNewProduct({...newProduct, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">الباركود</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black" value={newProduct.barcode} onChange={(e) => setNewProduct({...newProduct, barcode: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">المورد</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black" value={newProduct.supplier} onChange={(e) => setNewProduct({...newProduct, supplier: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">القسم الرئيسي</label>
                  <select className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black" value={newProduct.category_id} onChange={(e) => setNewProduct({...newProduct, category_id: e.target.value})}>
                    <option value="">اختر القسم...</option>
                    {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              {/* قسم الأنواع */}
              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-[11px] font-black text-slate-900 uppercase tracking-[0.2em]">تخصيص الأنواع والكميات</p>
                  <button onClick={handleAddVariant} className="px-6 py-3 bg-blue-50 text-blue-600 font-black rounded-2xl text-xs flex items-center gap-3 border border-blue-100"><Plus size={18} /> إضافة نوع جديد</button>
                </div>
                {newProduct.variants.map((v, idx) => (
                  <div key={idx} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 bg-slate-50 rounded-[2rem] border-2 border-slate-100">
                    <input placeholder="اسم النوع" className="p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" value={v.name} onChange={(e) => { const vs = [...newProduct.variants]; vs[idx].name = e.target.value; setNewProduct({...newProduct, variants: vs}); }} />
                    <input type="number" placeholder="التكلفة" className="p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" value={v.cost_price || ''} onChange={(e) => { const vs = [...newProduct.variants]; vs[idx].cost_price = Number(e.target.value); setNewProduct({...newProduct, variants: vs}); }} />
                    <input type="number" placeholder="البيع" className="p-4 bg-white rounded-2xl border-2 border-emerald-100 text-emerald-600 outline-none font-black text-xs" value={v.sale_price || ''} onChange={(e) => { const vs = [...newProduct.variants]; vs[idx].sale_price = Number(e.target.value); setNewProduct({...newProduct, variants: vs}); }} />
                    <div className="flex gap-3">
                      <input type="number" placeholder="الكمية" className="flex-1 p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" value={v.stock_quantity || ''} onChange={(e) => { const vs = [...newProduct.variants]; vs[idx].stock_quantity = Number(e.target.value); setNewProduct({...newProduct, variants: vs}); }} />
                      {idx > 0 && <button onClick={() => setNewProduct({...newProduct, variants: newProduct.variants.filter((_, i) => i !== idx)})} className="p-4 text-rose-500 hover:bg-rose-50 rounded-2xl"><Trash2 size={22} /></button>}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <p className="text-xs font-black text-amber-600 bg-amber-50 px-5 py-3 rounded-2xl border border-amber-100">تنبيه: سيتم حفظ البيانات في قاعدة البيانات مباشرة.</p>
              <button 
                onClick={handleSaveProduct}
                disabled={!newProduct.name || saving}
                className="px-14 py-5 bg-slate-900 text-white font-black text-lg rounded-[1.8rem] shadow-2xl hover:bg-slate-800 disabled:bg-slate-300 flex items-center gap-4 transition-all"
              >
                {saving ? <LoaderIcon className="animate-spin" size={24} /> : <Save size={24} className="text-emerald-400" />}
                <span>{saving ? 'جاري الحفظ والتحقق...' : 'تأكيد وحفظ الصنف'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Barcode,
  Save,
  AlertCircle,
  Building2,
  Loader2
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [filterSupplier, setFilterSupplier] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);

  const [newProduct, setNewProduct] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddVariant = () => {
    setNewProduct({
      ...newProduct,
      variants: [...newProduct.variants, { name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
  };

  const handleSaveProduct = async () => {
    if (!newProduct.name || saving) {
      if (!newProduct.name) alert("يرجى إدخال اسم الصنف");
      return;
    }

    setSaving(true);
    try {
      // 1. تحويل القيم الفارغة إلى null لضمان قبولها في حقول UUID
      const categoryId = newProduct.category_id && newProduct.category_id.trim() !== "" ? newProduct.category_id : null;
      const subCategoryId = newProduct.sub_category_id && newProduct.sub_category_id.trim() !== "" ? newProduct.sub_category_id : null;
      const barcodeValue = newProduct.barcode && newProduct.barcode.trim() !== "" ? newProduct.barcode : null;
      const supplierValue = newProduct.supplier && newProduct.supplier.trim() !== "" ? newProduct.supplier : null;

      // 2. إدخال المنتج الرئيسي
      const { data: prodData, error: pError } = await supabase
        .from('products')
        .insert({
          name: newProduct.name,
          barcode: barcodeValue,
          supplier: supplierValue,
          category_id: categoryId,
          sub_category_id: subCategoryId
        })
        .select();

      if (pError) throw new Error(`خطأ في بيانات المنتج: ${pError.message}`);
      if (!prodData || prodData.length === 0) throw new Error("لم يتم حفظ المنتج، قد تكون هناك مشكلة في الاتصال.");

      const prodId = prodData[0].id;

      // 3. إدخال الأنواع (Variants)
      const variantsToInsert = newProduct.variants.map(v => ({
        name: v.name || 'افتراضي',
        cost_price: Number(v.cost_price) || 0,
        sale_price: Number(v.sale_price) || 0,
        stock_quantity: Number(v.stock_quantity) || 0,
        product_id: prodId
      }));

      const { error: vError } = await supabase.from('variants').insert(variantsToInsert);
      if (vError) throw new Error(`تم حفظ المنتج ولكن فشل حفظ الكميات: ${vError.message}`);

      // نجاح العملية
      setShowAddModal(false);
      setNewProduct({
        name: '',
        barcode: '',
        supplier: '',
        category_id: '',
        sub_category_id: '',
        variants: [{ name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
      });

      await fetchData();
      alert("✅ تم حفظ الصنف بنجاح");
    } catch (err: any) {
      alert(`❌ فشل الحفظ: ${err.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذا الصنف بالكامل؟")) return;

    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;

      setProducts(prev => prev.filter(p => p.id !== id));
      setSelectedIds(prev => prev.filter(sid => sid !== id));
      alert("تم الحذف بنجاح");
    } catch (err: any) {
      alert("فشل الحذف: " + err.message);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      const { data: prodData, error: pError } = await supabase
        .from('products')
        .insert({
          name: `${product.name} (نسخة)`,
          barcode: null, 
          supplier: product.supplier,
          category_id: product.category_id,
          sub_category_id: product.sub_category_id
        })
        .select();

      if (pError) throw pError;
      const newProd = prodData[0];

      if (product.variants && product.variants.length > 0) {
        const vars = product.variants.map((v: any) => ({
          name: v.name,
          cost_price: v.cost_price,
          sale_price: v.sale_price,
          stock_quantity: v.stock_quantity,
          product_id: newProd.id
        }));
        await supabase.from('variants').insert(vars);
      }
      await fetchData();
      alert("تم تكرار الصنف بنجاح (بدون باركود)");
    } catch (err: any) {
      alert("فشل التكرار: " + err.message);
    }
  };

  const calculateStockValue = (prods: any[]) => {
    return prods.reduce((sum, p) => {
      const vSum = p.variants?.reduce((vs: number, v: any) => vs + (Number(v.cost_price) * Number(v.stock_quantity)), 0) || 0;
      return sum + vSum;
    }, 0);
  };

  const uniqueSuppliers = useMemo(() => {
    const sups = products.map(p => p.supplier).filter(Boolean);
    return Array.from(new Set(sups));
  }, [products]);

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        (p.barcode && p.barcode.includes(searchTerm));
      const matchCategory = filterCategory === 'all' || p.category_id === filterCategory;
      const matchSupplier = filterSupplier === 'all' || p.supplier === filterSupplier;
      return matchSearch && matchCategory && matchSupplier;
    });
  }, [products, searchTerm, filterCategory, filterSupplier]);

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          <button 
            onClick={() => setShowAddModal(true)}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg hover:bg-emerald-700 transition-all active:scale-95"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 shrink-0 px-2">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl"><Package size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إجمالي الأصناف</p><p className="text-xl font-black text-slate-900">{products.length}</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><DollarSign size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">قيمة المخزون</p><p className="text-xl font-black text-emerald-600">{calculateStockValue(products).toFixed(2)} ₪</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl"><Layers size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إجمالي القطع</p><p className="text-xl font-black text-slate-900">{products.reduce((s, p) => s + (p.variants?.reduce((vs: number, v: any) => vs + Number(v.stock_quantity), 0) || 0), 0)}</p></div>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm shrink-0 mx-2 relative z-50">
        <div className="p-4 flex flex-col sm:flex-row items-center gap-4">
          <div className="relative flex-1 w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-emerald-500 outline-none font-black text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`w-full sm:w-auto p-3.5 rounded-2xl transition-all flex items-center justify-center gap-3 font-black text-sm border-2 ${showFilters ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-100 text-slate-500'}`}
          >
            <Filter size={18} />
            <span>تصفية</span>
          </button>

          {showFilters && (
            <div className="absolute top-16 right-0 left-0 sm:left-auto sm:right-4 w-full sm:w-72 bg-white border border-slate-200 shadow-2xl rounded-[2rem] p-6 z-[70] space-y-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">فلترة حسب القسم</label>
                <select className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl" value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)}>
                  <option value="all">جميع الأقسام</option>
                  {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <button onClick={() => { setFilterCategory('all'); setFilterSupplier('all'); setShowFilters(false); }} className="w-full py-2 bg-rose-50 text-rose-600 rounded-xl text-xs font-black">إعادة تعيين</button>
            </div>
          )}
        </div>
      </div>

      {/* Table Section */}
      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm flex-1 mx-2 mb-4 overflow-hidden flex flex-col">
        <div className="overflow-x-auto flex-1 custom-scrollbar">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-50/90 backdrop-blur-sm z-10 border-b border-slate-200">
              <tr>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">اسم الصنف والباركود</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">المورد</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest">القسم</th>
                <th className="p-5 text-xs font-black text-slate-400 uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filtered.map(p => (
                <React.Fragment key={p.id}>
                  <tr 
                    onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                    className={`transition-all cursor-pointer group ${expandedProduct === p.id ? 'bg-emerald-50/30' : 'hover:bg-slate-50/80'}`}
                  >
                    <td className="p-5">
                       <div className="flex items-center gap-4">
                         <div className={`transition-all duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600 scale-125' : 'text-slate-300'}`}>
                           <ChevronDown size={20} />
                         </div>
                         <div>
                           <p className="font-black text-slate-900 text-sm">{p.name}</p>
                           {p.barcode && <p className="text-[10px] font-mono text-slate-400">{p.barcode}</p>}
                         </div>
                       </div>
                    </td>
                    <td className="p-5 text-xs font-black text-slate-500">{p.supplier || '-'}</td>
                    <td className="p-5">
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1.5 rounded-xl border border-blue-100">
                        {categories.find(c => c.id === p.category_id)?.name || 'غير مصنف'}
                      </span>
                    </td>
                    <td className="p-5 text-left" onClick={(e) => e.stopPropagation()}>
                      <div className="flex items-center justify-end gap-3">
                        <button onClick={(e) => handleDuplicate(e, p)} className="p-2 text-slate-400 hover:text-blue-600"><Copy size={18} /></button>
                        <button onClick={(e) => handleDelete(e, p.id)} className="p-2 text-slate-400 hover:text-rose-600"><Trash2 size={18} /></button>
                      </div>
                    </td>
                  </tr>
                  {expandedProduct === p.id && (
                    <tr className="bg-slate-50/40">
                      <td colSpan={4} className="p-8">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                          {p.variants?.map((v: any) => (
                            <div key={v.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
                              <div>
                                <p className="font-black text-slate-800 text-xs">{v.name}</p>
                                <p className="text-[10px] text-slate-400">الكمية: {v.stock_quantity}</p>
                              </div>
                              <p className="font-black text-emerald-600">{v.sale_price} ₪</p>
                            </div>
                          ))}
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className="p-4 bg-emerald-600 text-white rounded-2xl shadow-xl">
                  <Package size={28} />
                </div>
                <h3 className="text-xl font-black text-slate-900">إضافة صنف جديد</h3>
              </div>
              <button onClick={() => setShowAddModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-10 custom-scrollbar max-h-[70vh]">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">اسم الصنف *</label>
                  <input type="text" required className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black" value={newProduct.name} onChange={(e) => setNewProduct({...newProduct, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">الباركود</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black" value={newProduct.barcode} onChange={(e) => setNewProduct({...newProduct, barcode: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">المورد</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black" value={newProduct.supplier} onChange={(e) => setNewProduct({...newProduct, supplier: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">القسم الرئيسي</label>
                  <select className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black" value={newProduct.category_id} onChange={(e) => setNewProduct({...newProduct, category_id: e.target.value})}>
                    <option value="">اختر القسم...</option>
                    {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-[11px] font-black text-slate-900 uppercase tracking-[0.2em]">تخصيص الأنواع والكميات</p>
                  <button onClick={handleAddVariant} className="px-6 py-3 bg-blue-50 text-blue-600 font-black rounded-2xl text-xs flex items-center gap-3 border border-blue-100"><Plus size={18} /> إضافة نوع جديد</button>
                </div>
                {newProduct.variants.map((v, idx) => (
                  <div key={idx} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 bg-slate-50 rounded-[2rem] border-2 border-slate-100">
                    <input placeholder="اسم النوع" className="p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" value={v.name} onChange={(e) => { const vs = [...newProduct.variants]; vs[idx].name = e.target.value; setNewProduct({...newProduct, variants: vs}); }} />
                    <input type="number" placeholder="التكلفة" className="p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" value={v.cost_price || ''} onChange={(e) => { const vs = [...newProduct.variants]; vs[idx].cost_price = Number(e.target.value); setNewProduct({...newProduct, variants: vs}); }} />
                    <input type="number" placeholder="البيع" className="p-4 bg-white rounded-2xl border-2 border-emerald-100 text-emerald-600 outline-none font-black text-xs" value={v.sale_price || ''} onChange={(e) => { const vs = [...newProduct.variants]; vs[idx].sale_price = Number(e.target.value); setNewProduct({...newProduct, variants: vs}); }} />
                    <div className="flex gap-3">
                      <input type="number" placeholder="الكمية" className="flex-1 p-4 bg-white rounded-2xl border border-slate-200 outline-none font-black text-xs" value={v.stock_quantity || ''} onChange={(e) => { const vs = [...newProduct.variants]; vs[idx].stock_quantity = Number(e.target.value); setNewProduct({...newProduct, variants: vs}); }} />
                      {idx > 0 && <button onClick={() => setNewProduct({...newProduct, variants: newProduct.variants.filter((_, i) => i !== idx)})} className="p-4 text-rose-500 hover:bg-rose-50 rounded-2xl"><Trash2 size={22} /></button>}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3 text-amber-600">
                <AlertCircle size={20} />
                <p className="text-xs font-black">سيتم حفظ البيانات مباشرة في المخزون.</p>
              </div>
              <button 
                onClick={handleSaveProduct}
                disabled={!newProduct.name || saving}
                className="px-14 py-5 bg-slate-900 text-white font-black text-lg rounded-[1.8rem] shadow-2xl hover:bg-slate-800 disabled:bg-slate-300 flex items-center gap-4 transition-all"
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} className="text-emerald-400" />}
                <span>{saving ? 'جاري الحفظ...' : 'تأكيد وحفظ الصنف'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

