import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Save,
  AlertCircle,
  Loader2,
  Edit3,
  CheckSquare,
  Square
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category, Product, Variant } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);

  const [form, setForm] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ id: undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const sanitizeUUID = (id: string | null | undefined) => {
    if (!id || id.trim() === "" || id === "all") return null;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id) ? id : null;
  };

  const handleOpenAdd = () => {
    setModalMode('add');
    setEditingId(null);
    setForm({
      name: '',
      barcode: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ id: undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    setShowModal(true);
  };

  const handleOpenEdit = (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    setModalMode('edit');
    setEditingId(product.id);
    setForm({
      name: product.name,
      barcode: product.barcode || '',
      supplier: product.supplier || '',
      category_id: product.category_id || '',
      sub_category_id: product.sub_category_id || '',
      variants: product.variants.map((v: any) => ({
        id: v.id,
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity
      }))
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.name || saving) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        barcode: form.barcode?.trim() || null,
        supplier: form.supplier?.trim() || null,
        category_id: sanitizeUUID(form.category_id),
        sub_category_id: sanitizeUUID(form.sub_category_id)
      };

      let prodId = editingId;

      if (modalMode === 'add') {
        const { data: prodData, error: pError } = await supabase.from('products').insert(payload).select().single();
        if (pError) throw pError;
        prodId = prodData.id;
      } else {
        const { error: pError } = await supabase.from('products').update(payload).eq('id', prodId);
        if (pError) throw pError;
      }

      // معالجة الـ Variants (تحديث/إضافة/حذف)
      if (modalMode === 'edit') {
        // حذف الأنواع التي لم تعد موجودة في النموذج
        const currentVariantIds = form.variants.filter(v => v.id).map(v => v.id);
        const { data: existingVariants } = await supabase.from('variants').select('id').eq('product_id', prodId);
        const idsToDelete = existingVariants?.filter(ev => !currentVariantIds.includes(ev.id)).map(ev => ev.id) || [];
        if (idsToDelete.length > 0) {
          await supabase.from('variants').delete().in('id', idsToDelete);
        }
      }

      const variantsToUpsert = form.variants.map(v => ({
        id: v.id,
        product_id: prodId,
        name: v.name || 'افتراضي',
        cost_price: Number(v.cost_price) || 0,
        sale_price: Number(v.sale_price) || 0,
        stock_quantity: Number(v.stock_quantity) || 0
      }));

      const { error: vError } = await supabase.from('variants').upsert(variantsToUpsert);
      if (vError) throw vError;

      setShowModal(false);
      await fetchData();
      alert(modalMode === 'add' ? "✅ تم إضافة الصنف" : "✅ تم تحديث الصنف");
    } catch (err: any) {
      alert(`❌ خطأ: ${err.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteOne = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذا الصنف؟")) return;
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
      setSelectedIds(prev => prev.filter(sid => sid !== id));
    } catch (err: any) { alert(err.message); }
  };

  const handleBulkDelete = async () => {
    if (!confirm(`هل أنت متأكد من حذف ${selectedIds.length} أصناف نهائياً؟`)) return;
    setLoading(true);
    try {
      const { error } = await supabase.from('products').delete().in('id', selectedIds);
      if (error) throw error;
      await fetchData();
      setSelectedIds([]);
      alert("تم حذف الأصناف المحددة بنجاح");
    } catch (err: any) {
      alert(`فشل الحذف الجماعي: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      const { data: prodData, error: pError } = await supabase.from('products').insert({
        name: `${product.name} (نسخة)`,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      }).select().single();

      if (pError) throw pError;
      const vars = product.variants.map((v: any) => ({
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prodData.id
      }));
      await supabase.from('variants').insert(vars);
      await fetchData();
    } catch (err: any) { alert(err.message); }
  };

  const toggleSelectAll = () => {
    if (selectedIds.length === filtered.length) setSelectedIds([]);
    else setSelectedIds(filtered.map(p => p.id));
  };

  const toggleSelectItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchCategory = filterCategory === 'all' || p.category_id === filterCategory;
      return matchSearch && matchCategory;
    });
  }, [products, searchTerm, filterCategory]);

  const stockValue = filtered.reduce((sum, p) => sum + (p.variants?.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0) || 0), 0);

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden relative" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button 
              onClick={handleBulkDelete}
              className="px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-rose-200 animate-in fade-in zoom-in"
            >
              <Trash2 size={20} />
              <span>حذف المحددة ({selectedIds.length})</span>
            </button>
          )}
          <button 
            onClick={handleOpenAdd}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg hover:bg-emerald-700 transition-all active:scale-95"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 shrink-0 px-2">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-blue-50 text-blue-600 rounded-2xl"><Package size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي الأصناف</p><p className="text-xl font-black">{filtered.length}</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><DollarSign size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">قيمة المخزون</p><p className="text-xl font-black text-emerald-600">{stockValue.toFixed(2)} ₪</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4 hidden sm:flex">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl"><Layers size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي القطع</p><p className="text-xl font-black">{filtered.reduce((s, p) => s + (p.variants?.reduce((vs: number, v: any) => vs + v.stock_quantity, 0) || 0), 0)}</p></div>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm shrink-0 mx-2 z-50">
        <div className="p-4 flex items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-emerald-500 outline-none font-black text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-3.5 rounded-2xl transition-all border-2 ${showFilters ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-100 text-slate-500'}`}
          >
            <Filter size={18} />
          </button>
        </div>
        {showFilters && (
          <div className="p-4 border-t border-slate-100 flex gap-4 animate-in slide-in-from-top-2">
            <select className="flex-1 p-3 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs" value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)}>
              <option value="all">جميع الأقسام</option>
              {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            <button onClick={() => { setFilterCategory('all'); setShowFilters(false); }} className="px-4 py-3 bg-rose-50 text-rose-600 rounded-xl text-xs font-black">إلغاء الفلتر</button>
          </div>
        )}
      </div>

      {/* Table Section */}
      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm flex-1 mx-2 mb-4 overflow-hidden flex flex-col">
        {loading ? (
          <div className="flex-1 flex flex-col items-center justify-center gap-4"><Loader2 className="animate-spin text-emerald-600" size={40} /><p className="font-black text-slate-400">جاري التحميل...</p></div>
        ) : (
          <div className="overflow-x-auto flex-1 custom-scrollbar">
            <table className="w-full text-right border-collapse">
              <thead className="sticky top-0 bg-slate-50 z-10 border-b border-slate-200">
                <tr>
                  <th className="p-5 w-14">
                    <button onClick={toggleSelectAll} className="text-slate-400 hover:text-emerald-600 transition-colors">
                      {selectedIds.length === filtered.length && filtered.length > 0 ? <CheckSquare size={22} className="text-emerald-600" /> : <Square size={22} />}
                    </button>
                  </th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase">اسم الصنف والباركود</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase hidden sm:table-cell">المورد</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase hidden sm:table-cell">القسم</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase text-left">الإجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filtered.map(p => (
                  <React.Fragment key={p.id}>
                    <tr 
                      onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                      className={`transition-all cursor-pointer group ${expandedProduct === p.id ? 'bg-emerald-50/30' : 'hover:bg-slate-50/80'} ${selectedIds.includes(p.id) ? 'bg-emerald-50' : ''}`}
                    >
                      <td className="p-5" onClick={(e) => toggleSelectItem(e, p.id)}>
                        <div className={`transition-all ${selectedIds.includes(p.id) ? 'text-emerald-600' : 'text-slate-300'}`}>
                          {selectedIds.includes(p.id) ? <CheckSquare size={22} /> : <Square size={22} />}
                        </div>
                      </td>
                      <td className="p-5">
                         <div className="flex items-center gap-4">
                           <div className={`transition-all duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600' : 'text-slate-300'}`}><ChevronDown size={20} /></div>
                           <div><p className="font-black text-slate-900 text-sm">{p.name}</p>{p.barcode && <p className="text-[10px] font-mono text-slate-400">{p.barcode}</p>}</div>
                         </div>
                      </td>
                      <td className="p-5 text-xs font-black text-slate-500 hidden sm:table-cell">{p.supplier || '-'}</td>
                      <td className="p-5 hidden sm:table-cell">
                        <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1 rounded-lg border border-blue-100">
                          {categories.find(c => c.id === p.category_id)?.name || 'غير مصنف'}
                        </span>
                      </td>
                      <td className="p-5 text-left" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={(e) => handleOpenEdit(e, p)} className="p-2 text-slate-400 hover:text-emerald-600" title="تعديل"><Edit3 size={18} /></button>
                          <button onClick={(e) => handleDuplicate(e, p)} className="p-2 text-slate-400 hover:text-blue-600" title="تكرار"><Copy size={18} /></button>
                          <button onClick={(e) => handleDeleteOne(e, p.id)} className="p-2 text-slate-400 hover:text-rose-600" title="حذف"><Trash2 size={18} /></button>
                        </div>
                      </td>
                    </tr>
                    {expandedProduct === p.id && (
                      <tr className="bg-slate-50/40">
                        <td colSpan={5} className="p-6">
                          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                            {p.variants?.map((v: any) => (
                              <div key={v.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
                                <div><p className="font-black text-slate-800 text-xs">{v.name}</p><p className="text-[10px] text-slate-400">الكمية: {v.stock_quantity}</p></div>
                                <div className="text-left"><p className="font-black text-emerald-600">{v.sale_price} ₪</p><p className="text-[9px] text-slate-400">التكلفة: {v.cost_price} ₪</p></div>
                              </div>
                            ))}
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Unified Modal (Add/Edit) */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl shadow-xl text-white ${modalMode === 'add' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-blue-600 shadow-blue-200'}`}>
                  {modalMode === 'add' ? <Plus size={28} /> : <Edit3 size={28} />}
                </div>
                <h3 className="text-xl font-black text-slate-900">{modalMode === 'add' ? 'إضافة صنف جديد' : 'تعديل بيانات الصنف'}</h3>
              </div>
              <button onClick={() => setShowModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar max-h-[70vh]">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم الصنف *</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.name} onChange={(e) => setForm({...form, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">الباركود</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.barcode} onChange={(e) => setForm({...form, barcode: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">المورد</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.supplier} onChange={(e) => setForm({...form, supplier: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم</label>
                  <select className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all" value={form.category_id} onChange={(e) => setForm({...form, category_id: e.target.value})}>
                    <option value="">اختر القسم...</option>
                    {categories.filter(c => !c.parent_id).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-xs font-black text-slate-900 uppercase tracking-widest">تخصيص الأنواع والكميات</p>
                  <button onClick={() => setForm({...form, variants: [...form.variants, { id: undefined, name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]})} className="px-5 py-2.5 bg-blue-50 text-blue-600 font-black rounded-xl text-xs flex items-center gap-2 border border-blue-100">
                    <Plus size={16} /> إضافة نوع
                  </button>
                </div>
                <div className="space-y-4">
                  {form.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-3 p-5 bg-slate-50 rounded-3xl border-2 border-slate-100 relative group">
                      <input placeholder="اسم النوع" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.name} onChange={(e) => { const vs = [...form.variants]; vs[idx].name = e.target.value; setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="التكلفة" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.cost_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].cost_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="البيع" className="p-3.5 bg-white rounded-xl border-2 border-emerald-100 text-emerald-600 font-black text-xs" value={v.sale_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].sale_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="الكمية" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.stock_quantity || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].stock_quantity = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <div className="flex items-center justify-end">
                        {form.variants.length > 1 && (
                          <button onClick={() => setForm({...form, variants: form.variants.filter((_, i) => i !== idx)})} className="p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors">
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3 text-amber-600">
                <AlertCircle size={20} />
                <p className="text-xs font-black">سيتم حفظ التغييرات فوراً في المخزون.</p>
              </div>
              <button 
                onClick={handleSave}
                disabled={!form.name || saving}
                className={`px-12 py-4.5 text-white font-black text-lg rounded-[1.8rem] shadow-2xl flex items-center gap-3 transition-all active:scale-95 ${modalMode === 'add' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} />}
                <span>{saving ? 'جاري الحفظ...' : modalMode === 'add' ? 'إضافة الصنف' : 'تحديث البيانات'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Save,
  AlertCircle,
  Loader2,
  Edit3,
  CheckSquare,
  Square
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category, Product, Variant } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);

  const [form, setForm] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ id: undefined as string | undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*')
        .order('name');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const sanitizeUUID = (id: string | null | undefined) => {
    if (!id || id.trim() === "" || id === "all") return null;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id) ? id : null;
  };

  const handleOpenAdd = () => {
    setModalMode('add');
    setEditingId(null);
    setForm({
      name: '',
      barcode: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ id: undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    setShowModal(true);
  };

  const handleOpenEdit = (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    setModalMode('edit');
    setEditingId(product.id);
    setForm({
      name: product.name,
      barcode: product.barcode || '',
      supplier: product.supplier || '',
      category_id: product.category_id || '',
      sub_category_id: product.sub_category_id || '',
      variants: product.variants.map((v: any) => ({
        id: v.id,
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity
      }))
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.name || saving) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        barcode: form.barcode?.trim() || null,
        supplier: form.supplier?.trim() || null,
        category_id: sanitizeUUID(form.category_id),
        sub_category_id: sanitizeUUID(form.sub_category_id)
      };

      let prodId = editingId;

      if (modalMode === 'add') {
        const { data: prodData, error: pError } = await supabase.from('products').insert(payload).select().single();
        if (pError) throw pError;
        prodId = prodData.id;
      } else {
        const { error: pError } = await supabase.from('products').update(payload).eq('id', prodId);
        if (pError) throw pError;
      }

      // معالجة الـ Variants (تحديث/إضافة/حذف)
      if (modalMode === 'edit') {
        const currentVariantIds = form.variants.filter(v => v.id).map(v => v.id);
        const { data: existingVariants } = await supabase.from('variants').select('id').eq('product_id', prodId);
        const idsToDelete = existingVariants?.filter(ev => !currentVariantIds.includes(ev.id)).map(ev => ev.id) || [];
        if (idsToDelete.length > 0) {
          await supabase.from('variants').delete().in('id', idsToDelete);
        }
      }

      const variantsToUpsert = form.variants.map(v => ({
        id: v.id,
        product_id: prodId,
        name: v.name || 'افتراضي',
        cost_price: Number(v.cost_price) || 0,
        sale_price: Number(v.sale_price) || 0,
        stock_quantity: Number(v.stock_quantity) || 0
      }));

      const { error: vError } = await supabase.from('variants').upsert(variantsToUpsert);
      if (vError) throw vError;

      setShowModal(false);
      await fetchData();
      alert(modalMode === 'add' ? "✅ تم إضافة الصنف" : "✅ تم تحديث الصنف");
    } catch (err: any) {
      alert(`❌ خطأ: ${err.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteOne = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذا الصنف؟")) return;
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
      setSelectedIds(prev => prev.filter(sid => sid !== id));
    } catch (err: any) { alert(err.message); }
  };

  const handleBulkDelete = async () => {
    if (!confirm(`هل أنت متأكد من حذف ${selectedIds.length} أصناف نهائياً؟`)) return;
    setLoading(true);
    try {
      const { error } = await supabase.from('products').delete().in('id', selectedIds);
      if (error) throw error;
      await fetchData();
      setSelectedIds([]);
      alert("تم حذف الأصناف المحددة بنجاح");
    } catch (err: any) {
      alert(`فشل الحذف الجماعي: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      const { data: prodData, error: pError } = await supabase.from('products').insert({
        name: `${product.name} (نسخة)`,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      }).select().single();

      if (pError) throw pError;
      const vars = product.variants.map((v: any) => ({
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prodData.id
      }));
      await supabase.from('variants').insert(vars);
      await fetchData();
    } catch (err: any) { alert(err.message); }
  };

  const toggleSelectAll = () => {
    if (selectedIds.length === filtered.length) setSelectedIds([]);
    else setSelectedIds(filtered.map(p => p.id));
  };

  const toggleSelectItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchCategory = filterCategory === 'all' || p.category_id === filterCategory || p.sub_category_id === filterCategory;
      return matchSearch && matchCategory;
    });
  }, [products, searchTerm, filterCategory]);

  const stockValue = filtered.reduce((sum, p) => sum + (p.variants?.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0) || 0), 0);

  const mainCategories = useMemo(() => categories.filter(c => !c.parent_id), [categories]);
  const subCategoriesForSelected = useMemo(() => categories.filter(c => c.parent_id === form.category_id), [categories, form.category_id]);

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden relative" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button 
              onClick={handleBulkDelete}
              className="px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-rose-200 animate-in fade-in zoom-in"
            >
              <Trash2 size={20} />
              <span>حذف المحددة ({selectedIds.length})</span>
            </button>
          )}
          <button 
            onClick={handleOpenAdd}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg hover:bg-emerald-700 transition-all active:scale-95"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 shrink-0 px-2">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-blue-50 text-blue-600 rounded-2xl"><Package size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي الأصناف</p><p className="text-xl font-black">{filtered.length}</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><DollarSign size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">قيمة المخزون</p><p className="text-xl font-black text-emerald-600">{stockValue.toFixed(2)} ₪</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4 hidden sm:flex">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl"><Layers size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي القطع</p><p className="text-xl font-black">{filtered.reduce((s, p) => s + (p.variants?.reduce((vs: number, v: any) => vs + v.stock_quantity, 0) || 0), 0)}</p></div>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm shrink-0 mx-2 z-50">
        <div className="p-4 flex items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-emerald-500 outline-none font-black text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-3.5 rounded-2xl transition-all border-2 ${showFilters ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-100 text-slate-500'}`}
          >
            <Filter size={18} />
          </button>
        </div>
        {showFilters && (
          <div className="p-4 border-t border-slate-100 flex gap-4 animate-in slide-in-from-top-2">
            <select className="flex-1 p-3 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs" value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)}>
              <option value="all">جميع الأقسام</option>
              {categories.map(c => <option key={c.id} value={c.id}>{c.parent_id ? '└ ' : ''}{c.name}</option>)}
            </select>
            <button onClick={() => { setFilterCategory('all'); setShowFilters(false); }} className="px-4 py-3 bg-rose-50 text-rose-600 rounded-xl text-xs font-black">إلغاء الفلتر</button>
          </div>
        )}
      </div>

      {/* Table Section */}
      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm flex-1 mx-2 mb-4 overflow-hidden flex flex-col">
        {loading ? (
          <div className="flex-1 flex flex-col items-center justify-center gap-4"><Loader2 className="animate-spin text-emerald-600" size={40} /><p className="font-black text-slate-400">جاري التحميل...</p></div>
        ) : (
          <div className="overflow-x-auto flex-1 custom-scrollbar">
            <table className="w-full text-right border-collapse">
              <thead className="sticky top-0 bg-slate-50 z-10 border-b border-slate-200">
                <tr>
                  <th className="p-5 w-14">
                    <button onClick={toggleSelectAll} className="text-slate-400 hover:text-emerald-600 transition-colors">
                      {selectedIds.length === filtered.length && filtered.length > 0 ? <CheckSquare size={22} className="text-emerald-600" /> : <Square size={22} />}
                    </button>
                  </th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase">اسم الصنف والباركود</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase hidden sm:table-cell">المورد</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase hidden sm:table-cell">القسم</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase text-left">الإجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filtered.map(p => (
                  <React.Fragment key={p.id}>
                    <tr 
                      onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                      className={`transition-all cursor-pointer group ${expandedProduct === p.id ? 'bg-emerald-50/30' : 'hover:bg-slate-50/80'} ${selectedIds.includes(p.id) ? 'bg-emerald-50' : ''}`}
                    >
                      <td className="p-5" onClick={(e) => toggleSelectItem(e, p.id)}>
                        <div className={`transition-all ${selectedIds.includes(p.id) ? 'text-emerald-600' : 'text-slate-300'}`}>
                          {selectedIds.includes(p.id) ? <CheckSquare size={22} /> : <Square size={22} />}
                        </div>
                      </td>
                      <td className="p-5">
                         <div className="flex items-center gap-4">
                           <div className={`transition-all duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600' : 'text-slate-300'}`}><ChevronDown size={20} /></div>
                           <div><p className="font-black text-slate-900 text-sm">{p.name}</p>{p.barcode && <p className="text-[10px] font-mono text-slate-400">{p.barcode}</p>}</div>
                         </div>
                      </td>
                      <td className="p-5 text-xs font-black text-slate-500 hidden sm:table-cell">{p.supplier || '-'}</td>
                      <td className="p-5 hidden sm:table-cell">
                        <div className="flex flex-col gap-1">
                          <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1 rounded-lg border border-blue-100 w-fit">
                            {categories.find(c => c.id === p.category_id)?.name || 'بدون قسم'}
                          </span>
                          {p.sub_category_id && (
                            <span className="bg-indigo-50 text-indigo-600 text-[9px] font-bold px-3 py-1 rounded-lg border border-indigo-100 w-fit">
                              {categories.find(c => c.id === p.sub_category_id)?.name}
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="p-5 text-left" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={(e) => handleOpenEdit(e, p)} className="p-2 text-slate-400 hover:text-emerald-600" title="تعديل"><Edit3 size={18} /></button>
                          <button onClick={(e) => handleDuplicate(e, p)} className="p-2 text-slate-400 hover:text-blue-600" title="تكرار"><Copy size={18} /></button>
                          <button onClick={(e) => handleDeleteOne(e, p.id)} className="p-2 text-slate-400 hover:text-rose-600" title="حذف"><Trash2 size={18} /></button>
                        </div>
                      </td>
                    </tr>
                    {expandedProduct === p.id && (
                      <tr className="bg-slate-50/40">
                        <td colSpan={5} className="p-6">
                          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                            {p.variants?.map((v: any) => (
                              <div key={v.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
                                <div><p className="font-black text-slate-800 text-xs">{v.name}</p><p className="text-[10px] text-slate-400">الكمية: {v.stock_quantity}</p></div>
                                <div className="text-left"><p className="font-black text-emerald-600">{v.sale_price} ₪</p><p className="text-[9px] text-slate-400">التكلفة: {v.cost_price} ₪</p></div>
                              </div>
                            ))}
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Unified Modal (Add/Edit) */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl shadow-xl text-white ${modalMode === 'add' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-blue-600 shadow-blue-200'}`}>
                  {modalMode === 'add' ? <Plus size={28} /> : <Edit3 size={28} />}
                </div>
                <h3 className="text-xl font-black text-slate-900">{modalMode === 'add' ? 'إضافة صنف جديد' : 'تعديل بيانات الصنف'}</h3>
              </div>
              <button onClick={() => setShowModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar max-h-[70vh]">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم الصنف *</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.name} onChange={(e) => setForm({...form, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">الباركود</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.barcode} onChange={(e) => setForm({...form, barcode: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">المورد</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.supplier} onChange={(e) => setForm({...form, supplier: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الرئيسي</label>
                  <select 
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all" 
                    value={form.category_id} 
                    onChange={(e) => setForm({...form, category_id: e.target.value, sub_category_id: ''})}
                  >
                    <option value="">اختر القسم الرئيسي...</option>
                    {mainCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الفرعي</label>
                  <select 
                    disabled={!form.category_id}
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all disabled:opacity-50" 
                    value={form.sub_category_id} 
                    onChange={(e) => setForm({...form, sub_category_id: e.target.value})}
                  >
                    <option value="">اختر القسم الفرعي...</option>
                    {subCategoriesForSelected.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-xs font-black text-slate-900 uppercase tracking-widest">تخصيص الأنواع والكميات</p>
                  <button onClick={() => setForm({...form, variants: [...form.variants, { id: undefined, name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]})} className="px-5 py-2.5 bg-blue-50 text-blue-600 font-black rounded-xl text-xs flex items-center gap-2 border border-blue-100">
                    <Plus size={16} /> إضافة نوع
                  </button>
                </div>
                <div className="space-y-4">
                  {form.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-3 p-5 bg-slate-50 rounded-3xl border-2 border-slate-100 relative group">
                      <input placeholder="اسم النوع" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.name} onChange={(e) => { const vs = [...form.variants]; vs[idx].name = e.target.value; setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="التكلفة" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.cost_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].cost_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="البيع" className="p-3.5 bg-white rounded-xl border-2 border-emerald-100 text-emerald-600 font-black text-xs" value={v.sale_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].sale_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="الكمية" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.stock_quantity || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].stock_quantity = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <div className="flex items-center justify-end">
                        {form.variants.length > 1 && (
                          <button onClick={() => setForm({...form, variants: form.variants.filter((_, i) => i !== idx)})} className="p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors">
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3 text-amber-600">
                <AlertCircle size={20} />
                <p className="text-xs font-black">سيتم حفظ التغييرات فوراً في المخزون.</p>
              </div>
              <button 
                onClick={handleSave}
                disabled={!form.name || saving}
                className={`px-12 py-4.5 text-white font-black text-lg rounded-[1.8rem] shadow-2xl flex items-center gap-3 transition-all active:scale-95 ${modalMode === 'add' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} />}
                <span>{saving ? 'جاري الحفظ...' : modalMode === 'add' ? 'إضافة الصنف' : 'تحديث البيانات'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Save,
  AlertCircle,
  Loader2,
  Edit3,
  CheckSquare,
  Square,
  RotateCcw
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category, Product, Variant } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  // States for Filtering
  const [filterMainCategory, setFilterMainCategory] = useState<string>('all');
  const [filterSubCategory, setFilterSubCategory] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);

  const [form, setForm] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ id: undefined as string | undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*')
        .order('name');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const sanitizeUUID = (id: string | null | undefined) => {
    if (!id || id.trim() === "" || id === "all") return null;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id) ? id : null;
  };

  const handleOpenAdd = () => {
    setModalMode('add');
    setEditingId(null);
    setForm({
      name: '',
      barcode: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ id: undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    setShowModal(true);
  };

  const handleOpenEdit = (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    setModalMode('edit');
    setEditingId(product.id);
    setForm({
      name: product.name,
      barcode: product.barcode || '',
      supplier: product.supplier || '',
      category_id: product.category_id || '',
      sub_category_id: product.sub_category_id || '',
      variants: product.variants.map((v: any) => ({
        id: v.id,
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity
      }))
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.name || saving) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        barcode: form.barcode?.trim() || null,
        supplier: form.supplier?.trim() || null,
        category_id: sanitizeUUID(form.category_id),
        sub_category_id: sanitizeUUID(form.sub_category_id)
      };

      let prodId = editingId;

      if (modalMode === 'add') {
        const { data: prodData, error: pError } = await supabase.from('products').insert(payload).select().single();
        if (pError) throw pError;
        prodId = prodData.id;
      } else {
        const { error: pError } = await supabase.from('products').update(payload).eq('id', prodId);
        if (pError) throw pError;
      }

      if (modalMode === 'edit') {
        const currentVariantIds = form.variants.filter(v => v.id).map(v => v.id);
        const { data: existingVariants } = await supabase.from('variants').select('id').eq('product_id', prodId);
        const idsToDelete = existingVariants?.filter(ev => !currentVariantIds.includes(ev.id)).map(ev => ev.id) || [];
        if (idsToDelete.length > 0) {
          await supabase.from('variants').delete().in('id', idsToDelete);
        }
      }

      const variantsToUpsert = form.variants.map(v => ({
        id: v.id,
        product_id: prodId,
        name: v.name || 'افتراضي',
        cost_price: Number(v.cost_price) || 0,
        sale_price: Number(v.sale_price) || 0,
        stock_quantity: Number(v.stock_quantity) || 0
      }));

      const { error: vError } = await supabase.from('variants').upsert(variantsToUpsert);
      if (vError) throw vError;

      setShowModal(false);
      await fetchData();
      alert(modalMode === 'add' ? "✅ تم إضافة الصنف" : "✅ تم تحديث الصنف");
    } catch (err: any) {
      alert(`❌ خطأ: ${err.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteOne = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذا الصنف؟")) return;
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
      setSelectedIds(prev => prev.filter(sid => sid !== id));
    } catch (err: any) { alert(err.message); }
  };

  const handleBulkDelete = async () => {
    if (!confirm(`هل أنت متأكد من حذف ${selectedIds.length} أصناف نهائياً؟`)) return;
    setLoading(true);
    try {
      const { error } = await supabase.from('products').delete().in('id', selectedIds);
      if (error) throw error;
      await fetchData();
      setSelectedIds([]);
      alert("تم حذف الأصناف المحددة بنجاح");
    } catch (err: any) {
      alert(`فشل الحذف الجماعي: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      const { data: prodData, error: pError } = await supabase.from('products').insert({
        name: `${product.name} (نسخة)`,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      }).select().single();

      if (pError) throw pError;
      const vars = product.variants.map((v: any) => ({
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prodData.id
      }));
      await supabase.from('variants').insert(vars);
      await fetchData();
    } catch (err: any) { alert(err.message); }
  };

  const toggleSelectAll = () => {
    if (selectedIds.length === filtered.length) setSelectedIds([]);
    else setSelectedIds(filtered.map(p => p.id));
  };

  const toggleSelectItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  // Improved filtering logic
  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        (p.barcode && p.barcode.includes(searchTerm));

      const matchMain = filterMainCategory === 'all' || p.category_id === filterMainCategory;
      const matchSub = filterSubCategory === 'all' || p.sub_category_id === filterSubCategory;

      return matchSearch && matchMain && matchSub;
    });
  }, [products, searchTerm, filterMainCategory, filterSubCategory]);

  const stockValue = filtered.reduce((sum, p) => sum + (p.variants?.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0) || 0), 0);

  const mainCategories = useMemo(() => categories.filter(c => !c.parent_id), [categories]);
  const subCategoriesForFilter = useMemo(() => categories.filter(c => c.parent_id === filterMainCategory), [categories, filterMainCategory]);
  const subCategoriesForForm = useMemo(() => categories.filter(c => c.parent_id === form.category_id), [categories, form.category_id]);

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden relative" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button 
              onClick={handleBulkDelete}
              className="px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-rose-200 animate-in fade-in zoom-in"
            >
              <Trash2 size={20} />
              <span>حذف المحددة ({selectedIds.length})</span>
            </button>
          )}
          <button 
            onClick={handleOpenAdd}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg hover:bg-emerald-700 transition-all active:scale-95"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 shrink-0 px-2">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-blue-50 text-blue-600 rounded-2xl"><Package size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي الأصناف</p><p className="text-xl font-black">{filtered.length}</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><DollarSign size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">قيمة المخزون</p><p className="text-xl font-black text-emerald-600">{stockValue.toFixed(2)} ₪</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4 hidden sm:flex">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl"><Layers size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي القطع</p><p className="text-xl font-black">{filtered.reduce((s, p) => s + (p.variants?.reduce((vs: number, v: any) => vs + v.stock_quantity, 0) || 0), 0)}</p></div>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm shrink-0 mx-2 z-50">
        <div className="p-4 flex items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-emerald-500 outline-none font-black text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-3.5 rounded-2xl transition-all border-2 flex items-center gap-2 font-black text-sm ${showFilters ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-100 text-slate-500'}`}
          >
            <Filter size={18} />
            <span className="hidden sm:inline">تصفية</span>
          </button>
        </div>

        {/* Dynamic Multi-level Filter */}
        {showFilters && (
          <div className="p-4 border-t border-slate-100 grid grid-cols-1 md:grid-cols-3 gap-4 animate-in slide-in-from-top-2">
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1">القسم الرئيسي</label>
              <select 
                className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs outline-none focus:border-emerald-500" 
                value={filterMainCategory} 
                onChange={(e) => {
                  setFilterMainCategory(e.target.value);
                  setFilterSubCategory('all');
                }}
              >
                <option value="all">كل الأقسام الرئيسية</option>
                {mainCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1">القسم الفرعي</label>
              <select 
                disabled={filterMainCategory === 'all'}
                className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs outline-none focus:border-emerald-500 disabled:opacity-50" 
                value={filterSubCategory} 
                onChange={(e) => setFilterSubCategory(e.target.value)}
              >
                <option value="all">كل الأقسام الفرعية</option>
                {subCategoriesForFilter.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="flex items-end">
              <button 
                onClick={() => { 
                  setFilterMainCategory('all'); 
                  setFilterSubCategory('all'); 
                  setSearchTerm('');
                  setShowFilters(false); 
                }} 
                className="w-full py-3 bg-rose-50 text-rose-600 rounded-xl text-xs font-black flex items-center justify-center gap-2 hover:bg-rose-100 transition-colors"
              >
                <RotateCcw size={14} />
                إعادة ضبط الفلاتر
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Table Section */}
      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm flex-1 mx-2 mb-4 overflow-hidden flex flex-col">
        {loading ? (
          <div className="flex-1 flex flex-col items-center justify-center gap-4"><Loader2 className="animate-spin text-emerald-600" size={40} /><p className="font-black text-slate-400">جاري التحميل...</p></div>
        ) : (
          <div className="overflow-x-auto flex-1 custom-scrollbar">
            <table className="w-full text-right border-collapse">
              <thead className="sticky top-0 bg-slate-50 z-10 border-b border-slate-200">
                <tr>
                  <th className="p-5 w-14 text-right">
                    <button onClick={toggleSelectAll} className="text-slate-400 hover:text-emerald-600 transition-colors">
                      {selectedIds.length === filtered.length && filtered.length > 0 ? <CheckSquare size={22} className="text-emerald-600" /> : <Square size={22} />}
                    </button>
                  </th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase">اسم الصنف والباركود</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase hidden sm:table-cell">المورد</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase hidden sm:table-cell">التصنيف</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase text-left">الإجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filtered.map(p => (
                  <React.Fragment key={p.id}>
                    <tr 
                      onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                      className={`transition-all cursor-pointer group ${expandedProduct === p.id ? 'bg-emerald-50/30' : 'hover:bg-slate-50/80'} ${selectedIds.includes(p.id) ? 'bg-emerald-50' : ''}`}
                    >
                      <td className="p-5" onClick={(e) => toggleSelectItem(e, p.id)}>
                        <div className={`transition-all ${selectedIds.includes(p.id) ? 'text-emerald-600' : 'text-slate-300'}`}>
                          {selectedIds.includes(p.id) ? <CheckSquare size={22} /> : <Square size={22} />}
                        </div>
                      </td>
                      <td className="p-5">
                         <div className="flex items-center gap-4">
                           <div className={`transition-all duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600' : 'text-slate-300'}`}><ChevronDown size={20} /></div>
                           <div><p className="font-black text-slate-900 text-sm">{p.name}</p>{p.barcode && <p className="text-[10px] font-mono text-slate-400">{p.barcode}</p>}</div>
                         </div>
                      </td>
                      <td className="p-5 text-xs font-black text-slate-500 hidden sm:table-cell">{p.supplier || '-'}</td>
                      <td className="p-5 hidden sm:table-cell">
                        <div className="flex flex-col gap-1">
                          <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1 rounded-lg border border-blue-100 w-fit">
                            {categories.find(c => c.id === p.category_id)?.name || 'بدون قسم'}
                          </span>
                          {p.sub_category_id && (
                            <span className="bg-indigo-50 text-indigo-600 text-[9px] font-bold px-3 py-1 rounded-lg border border-indigo-100 w-fit">
                              {categories.find(c => c.id === p.sub_category_id)?.name}
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="p-5 text-left" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={(e) => handleOpenEdit(e, p)} className="p-2 text-slate-400 hover:text-emerald-600" title="تعديل"><Edit3 size={18} /></button>
                          <button onClick={(e) => handleDuplicate(e, p)} className="p-2 text-slate-400 hover:text-blue-600" title="تكرار"><Copy size={18} /></button>
                          <button onClick={(e) => handleDeleteOne(e, p.id)} className="p-2 text-slate-400 hover:text-rose-600" title="حذف"><Trash2 size={18} /></button>
                        </div>
                      </td>
                    </tr>
                    {expandedProduct === p.id && (
                      <tr className="bg-slate-50/40">
                        <td colSpan={5} className="p-6">
                          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                            {p.variants?.map((v: any) => (
                              <div key={v.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
                                <div><p className="font-black text-slate-800 text-xs">{v.name}</p><p className="text-[10px] text-slate-400">الكمية: {v.stock_quantity}</p></div>
                                <div className="text-left"><p className="font-black text-emerald-600">{v.sale_price} ₪</p><p className="text-[9px] text-slate-400">التكلفة: {v.cost_price} ₪</p></div>
                              </div>
                            ))}
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Unified Modal (Add/Edit) */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl shadow-xl text-white ${modalMode === 'add' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-blue-600 shadow-blue-200'}`}>
                  {modalMode === 'add' ? <Plus size={28} /> : <Edit3 size={28} />}
                </div>
                <h3 className="text-xl font-black text-slate-900">{modalMode === 'add' ? 'إضافة صنف جديد' : 'تعديل بيانات الصنف'}</h3>
              </div>
              <button onClick={() => setShowModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar max-h-[70vh]">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم الصنف *</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.name} onChange={(e) => setForm({...form, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">الباركود</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.barcode} onChange={(e) => setForm({...form, barcode: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">المورد</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.supplier} onChange={(e) => setForm({...form, supplier: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الرئيسي</label>
                  <select 
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all" 
                    value={form.category_id} 
                    onChange={(e) => setForm({...form, category_id: e.target.value, sub_category_id: ''})}
                  >
                    <option value="">اختر القسم الرئيسي...</option>
                    {mainCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الفرعي</label>
                  <select 
                    disabled={!form.category_id}
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all disabled:opacity-50" 
                    value={form.sub_category_id} 
                    onChange={(e) => setForm({...form, sub_category_id: e.target.value})}
                  >
                    <option value="">اختر القسم الفرعي...</option>
                    {subCategoriesForForm.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-xs font-black text-slate-900 uppercase tracking-widest">تخصيص الأنواع والكميات</p>
                  <button onClick={() => setForm({...form, variants: [...form.variants, { id: undefined, name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]})} className="px-5 py-2.5 bg-blue-50 text-blue-600 font-black rounded-xl text-xs flex items-center gap-2 border border-blue-100">
                    <Plus size={16} /> إضافة نوع
                  </button>
                </div>
                <div className="space-y-4">
                  {form.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-3 p-5 bg-slate-50 rounded-3xl border-2 border-slate-100 relative group">
                      <input placeholder="اسم النوع" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.name} onChange={(e) => { const vs = [...form.variants]; vs[idx].name = e.target.value; setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="التكلفة" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.cost_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].cost_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="البيع" className="p-3.5 bg-white rounded-xl border-2 border-emerald-100 text-emerald-600 font-black text-xs" value={v.sale_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].sale_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="الكمية" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.stock_quantity || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].stock_quantity = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <div className="flex items-center justify-end">
                        {form.variants.length > 1 && (
                          <button onClick={() => setForm({...form, variants: form.variants.filter((_, i) => i !== idx)})} className="p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors">
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3 text-amber-600">
                <AlertCircle size={20} />
                <p className="text-xs font-black">سيتم حفظ التغييرات فوراً في المخزون.</p>
              </div>
              <button 
                onClick={handleSave}
                disabled={!form.name || saving}
                className={`px-12 py-4.5 text-white font-black text-lg rounded-[1.8rem] shadow-2xl flex items-center gap-3 transition-all active:scale-95 ${modalMode === 'add' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} />}
                <span>{saving ? 'جاري الحفظ...' : modalMode === 'add' ? 'إضافة الصنف' : 'تحديث البيانات'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Save,
  AlertCircle,
  Loader2,
  Edit3,
  CheckSquare,
  Square,
  RotateCcw,
  AlertTriangle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category, Product, Variant } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  // Custom Confirmation States
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{id: string | null, type: 'single' | 'bulk'}>({id: null, type: 'single'});

  // States for Filtering
  const [filterMainCategory, setFilterMainCategory] = useState<string>('all');
  const [filterSubCategory, setFilterSubCategory] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);

  const [form, setForm] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ id: undefined as string | undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*')
        .order('name');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const sanitizeUUID = (id: string | null | undefined) => {
    if (!id || id.trim() === "" || id === "all") return null;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id) ? id : null;
  };

  const handleOpenAdd = () => {
    setModalMode('add');
    setEditingId(null);
    setForm({
      name: '',
      barcode: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ id: undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    setShowModal(true);
  };

  const handleOpenEdit = (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    setModalMode('edit');
    setEditingId(product.id);
    setForm({
      name: product.name,
      barcode: product.barcode || '',
      supplier: product.supplier || '',
      category_id: product.category_id || '',
      sub_category_id: product.sub_category_id || '',
      variants: product.variants.map((v: any) => ({
        id: v.id,
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity
      }))
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.name || saving) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        barcode: form.barcode?.trim() || null,
        supplier: form.supplier?.trim() || null,
        category_id: sanitizeUUID(form.category_id),
        sub_category_id: sanitizeUUID(form.sub_category_id)
      };

      let prodId = editingId;

      if (modalMode === 'add') {
        const { data: prodData, error: pError } = await supabase.from('products').insert(payload).select().single();
        if (pError) throw pError;
        prodId = prodData.id;
      } else {
        const { error: pError } = await supabase.from('products').update(payload).eq('id', prodId);
        if (pError) throw pError;
      }

      if (modalMode === 'edit') {
        const currentVariantIds = form.variants.filter(v => v.id).map(v => v.id);
        const { data: existingVariants } = await supabase.from('variants').select('id').eq('product_id', prodId);
        const idsToDelete = existingVariants?.filter(ev => !currentVariantIds.includes(ev.id)).map(ev => ev.id) || [];
        if (idsToDelete.length > 0) {
          await supabase.from('variants').delete().in('id', idsToDelete);
        }
      }

      const variantsToUpsert = form.variants.map(v => ({
        id: v.id,
        product_id: prodId,
        name: v.name || 'افتراضي',
        cost_price: Number(v.cost_price) || 0,
        sale_price: Number(v.sale_price) || 0,
        stock_quantity: Number(v.stock_quantity) || 0
      }));

      const { error: vError } = await supabase.from('variants').upsert(variantsToUpsert);
      if (vError) throw vError;

      setShowModal(false);
      await fetchData();
    } catch (err: any) {
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  const requestDeleteOne = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setDeleteTarget({id, type: 'single'});
    setShowDeleteConfirm(true);
  };

  const requestBulkDelete = () => {
    setDeleteTarget({id: null, type: 'bulk'});
    setShowDeleteConfirm(true);
  };

  const confirmDeleteAction = async () => {
    setLoading(true);
    setShowDeleteConfirm(false);
    try {
      if (deleteTarget.type === 'single' && deleteTarget.id) {
        await supabase.from('products').delete().eq('id', deleteTarget.id);
        setProducts(prev => prev.filter(p => p.id !== deleteTarget.id));
        setSelectedIds(prev => prev.filter(sid => sid !== deleteTarget.id));
      } else if (deleteTarget.type === 'bulk') {
        const { error } = await supabase.from('products').delete().in('id', selectedIds);
        if (error) throw error;
        await fetchData();
        setSelectedIds([]);
      }
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      const { data: prodData, error: pError } = await supabase.from('products').insert({
        name: `${product.name} (نسخة)`,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      }).select().single();

      if (pError) throw pError;
      const vars = product.variants.map((v: any) => ({
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prodData.id
      }));
      await supabase.from('variants').insert(vars);
      await fetchData();
    } catch (err: any) { console.error(err); }
  };

  const toggleSelectAll = () => {
    if (selectedIds.length === filtered.length) setSelectedIds([]);
    else setSelectedIds(filtered.map(p => p.id));
  };

  const toggleSelectItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        (p.barcode && p.barcode.includes(searchTerm));

      const matchMain = filterMainCategory === 'all' || p.category_id === filterMainCategory;
      const matchSub = filterSubCategory === 'all' || p.sub_category_id === filterSubCategory;

      return matchSearch && matchMain && matchSub;
    });
  }, [products, searchTerm, filterMainCategory, filterSubCategory]);

  const stockValue = filtered.reduce((sum, p) => sum + (p.variants?.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0) || 0), 0);

  const mainCategories = useMemo(() => categories.filter(c => !c.parent_id), [categories]);
  const subCategoriesForFilter = useMemo(() => categories.filter(c => c.parent_id === filterMainCategory), [categories, filterMainCategory]);
  const subCategoriesForForm = useMemo(() => categories.filter(c => c.parent_id === form.category_id), [categories, form.category_id]);

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden relative" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button 
              onClick={requestBulkDelete}
              className="px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-rose-200 animate-in fade-in zoom-in"
            >
              <Trash2 size={20} />
              <span>حذف المحددة ({selectedIds.length})</span>
            </button>
          )}
          <button 
            onClick={handleOpenAdd}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg hover:bg-emerald-700 transition-all active:scale-95"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 shrink-0 px-2">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-blue-50 text-blue-600 rounded-2xl"><Package size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي الأصناف</p><p className="text-xl font-black">{filtered.length}</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><DollarSign size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">قيمة المخزون</p><p className="text-xl font-black text-emerald-600">{stockValue.toFixed(2)} ₪</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4 hidden sm:flex">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl"><Layers size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي القطع</p><p className="text-xl font-black">{filtered.reduce((s, p) => s + (p.variants?.reduce((vs: number, v: any) => vs + v.stock_quantity, 0) || 0), 0)}</p></div>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm shrink-0 mx-2 z-50">
        <div className="p-4 flex items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-emerald-500 outline-none font-black text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-3.5 rounded-2xl transition-all border-2 flex items-center gap-2 font-black text-sm ${showFilters ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-100 text-slate-500'}`}
          >
            <Filter size={18} />
            <span className="hidden sm:inline">تصفية</span>
          </button>
        </div>

        {showFilters && (
          <div className="p-4 border-t border-slate-100 grid grid-cols-1 md:grid-cols-3 gap-4 animate-in slide-in-from-top-2">
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1">القسم الرئيسي</label>
              <select 
                className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs outline-none focus:border-emerald-500" 
                value={filterMainCategory} 
                onChange={(e) => {
                  setFilterMainCategory(e.target.value);
                  setFilterSubCategory('all');
                }}
              >
                <option value="all">كل الأقسام الرئيسية</option>
                {mainCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1">القسم الفرعي</label>
              <select 
                disabled={filterMainCategory === 'all'}
                className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs outline-none focus:border-emerald-500 disabled:opacity-50" 
                value={filterSubCategory} 
                onChange={(e) => setFilterSubCategory(e.target.value)}
              >
                <option value="all">كل الأقسام الفرعية</option>
                {subCategoriesForFilter.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="flex items-end">
              <button 
                onClick={() => { 
                  setFilterMainCategory('all'); 
                  setFilterSubCategory('all'); 
                  setSearchTerm('');
                  setShowFilters(false); 
                }} 
                className="w-full py-3 bg-rose-50 text-rose-600 rounded-xl text-xs font-black flex items-center justify-center gap-2 hover:bg-rose-100 transition-colors"
              >
                <RotateCcw size={14} />
                إعادة ضبط الفلاتر
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Table Section */}
      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm flex-1 mx-2 mb-4 overflow-hidden flex flex-col">
        {loading ? (
          <div className="flex-1 flex flex-col items-center justify-center gap-4"><Loader2 className="animate-spin text-emerald-600" size={40} /><p className="font-black text-slate-400">جاري التحميل...</p></div>
        ) : (
          <div className="overflow-x-auto flex-1 custom-scrollbar">
            <table className="w-full text-right border-collapse">
              <thead className="sticky top-0 bg-slate-50 z-10 border-b border-slate-200">
                <tr>
                  <th className="p-5 w-14 text-right">
                    <button onClick={toggleSelectAll} className="text-slate-400 hover:text-emerald-600 transition-colors">
                      {selectedIds.length === filtered.length && filtered.length > 0 ? <CheckSquare size={22} className="text-emerald-600" /> : <Square size={22} />}
                    </button>
                  </th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase">اسم الصنف والباركود</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase hidden sm:table-cell">المورد</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase hidden sm:table-cell">التصنيف</th>
                  <th className="p-5 text-xs font-black text-slate-400 uppercase text-left">الإجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filtered.map(p => (
                  <React.Fragment key={p.id}>
                    <tr 
                      onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                      className={`transition-all cursor-pointer group ${expandedProduct === p.id ? 'bg-emerald-50/30' : 'hover:bg-slate-50/80'} ${selectedIds.includes(p.id) ? 'bg-emerald-50' : ''}`}
                    >
                      <td className="p-5" onClick={(e) => toggleSelectItem(e, p.id)}>
                        <div className={`transition-all ${selectedIds.includes(p.id) ? 'text-emerald-600' : 'text-slate-300'}`}>
                          {selectedIds.includes(p.id) ? <CheckSquare size={22} /> : <Square size={22} />}
                        </div>
                      </td>
                      <td className="p-5">
                         <div className="flex items-center gap-4">
                           <div className={`transition-all duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600' : 'text-slate-300'}`}><ChevronDown size={20} /></div>
                           <div><p className="font-black text-slate-900 text-sm">{p.name}</p>{p.barcode && <p className="text-[10px] font-mono text-slate-400">{p.barcode}</p>}</div>
                         </div>
                      </td>
                      <td className="p-5 text-xs font-black text-slate-500 hidden sm:table-cell">{p.supplier || '-'}</td>
                      <td className="p-5 hidden sm:table-cell">
                        <div className="flex flex-col gap-1">
                          <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1 rounded-lg border border-blue-100 w-fit">
                            {categories.find(c => c.id === p.category_id)?.name || 'بدون قسم'}
                          </span>
                          {p.sub_category_id && (
                            <span className="bg-indigo-50 text-indigo-600 text-[9px] font-bold px-3 py-1 rounded-lg border border-indigo-100 w-fit">
                              {categories.find(c => c.id === p.sub_category_id)?.name}
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="p-5 text-left" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={(e) => handleOpenEdit(e, p)} className="p-2 text-slate-400 hover:text-emerald-600" title="تعديل"><Edit3 size={18} /></button>
                          <button onClick={(e) => handleDuplicate(e, p)} className="p-2 text-slate-400 hover:text-blue-600" title="تكرار"><Copy size={18} /></button>
                          <button onClick={(e) => requestDeleteOne(e, p.id)} className="p-2 text-slate-400 hover:text-rose-600" title="حذف"><Trash2 size={18} /></button>
                        </div>
                      </td>
                    </tr>
                    {expandedProduct === p.id && (
                      <tr className="bg-slate-50/40">
                        <td colSpan={5} className="p-6">
                          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                            {p.variants?.map((v: any) => (
                              <div key={v.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
                                <div><p className="font-black text-slate-800 text-xs">{v.name}</p><p className="text-[10px] text-slate-400">الكمية: {v.stock_quantity}</p></div>
                                <div className="text-left"><p className="font-black text-emerald-600">{v.sale_price} ₪</p><p className="text-[9px] text-slate-400">التكلفة: {v.cost_price} ₪</p></div>
                              </div>
                            ))}
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center z-[200] p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-sm overflow-hidden p-8 space-y-6 border border-slate-200 animate-in zoom-in-95 duration-200">
             <div className="flex flex-col items-center gap-4 text-center">
                <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center shadow-inner">
                   <AlertTriangle size={40} />
                </div>
                <div>
                   <h3 className="text-xl font-black text-slate-900">تأكيد عملية الحذف</h3>
                   <p className="text-slate-500 text-sm mt-2 font-bold leading-relaxed">
                     {deleteTarget.type === 'single' ? 'هل أنت متأكد من حذف هذا الصنف نهائياً؟' : `هل أنت متأكد من حذف ${selectedIds.length} أصناف نهائياً؟`}
                     <br /> لا يمكن التراجع عن هذا الإجراء.
                   </p>
                </div>
             </div>
             <div className="flex gap-3">
                <button 
                  onClick={confirmDeleteAction}
                  className="flex-1 py-4 bg-rose-500 text-white font-black rounded-2xl shadow-lg shadow-rose-200 active:scale-95 transition-all"
                >
                  نعم، حذف
                </button>
                <button 
                  onClick={() => setShowDeleteConfirm(false)}
                  className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl active:scale-95 transition-all"
                >
                  إلغاء
                </button>
             </div>
          </div>
        </div>
      )}

      {/* Unified Modal (Add/Edit) */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl shadow-xl text-white ${modalMode === 'add' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-blue-600 shadow-blue-200'}`}>
                  {modalMode === 'add' ? <Plus size={28} /> : <Edit3 size={28} />}
                </div>
                <h3 className="text-xl font-black text-slate-900">{modalMode === 'add' ? 'إضافة صنف جديد' : 'تعديل بيانات الصنف'}</h3>
              </div>
              <button onClick={() => setShowModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar max-h-[70vh]">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم الصنف *</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.name} onChange={(e) => setForm({...form, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">الباركود</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.barcode} onChange={(e) => setForm({...form, barcode: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">المورد</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.supplier} onChange={(e) => setForm({...form, supplier: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الرئيسي</label>
                  <select 
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all" 
                    value={form.category_id} 
                    onChange={(e) => setForm({...form, category_id: e.target.value, sub_category_id: ''})}
                  >
                    <option value="">اختر القسم الرئيسي...</option>
                    {mainCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الفرعي</label>
                  <select 
                    disabled={!form.category_id}
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all disabled:opacity-50" 
                    value={form.sub_category_id} 
                    onChange={(e) => setForm({...form, sub_category_id: e.target.value})}
                  >
                    <option value="">اختر القسم الفرعي...</option>
                    {subCategoriesForForm.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-xs font-black text-slate-900 uppercase tracking-widest">تخصيص الأنواع والكميات</p>
                  <button onClick={() => setForm({...form, variants: [...form.variants, { id: undefined, name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]})} className="px-5 py-2.5 bg-blue-50 text-blue-600 font-black rounded-xl text-xs flex items-center gap-2 border border-blue-100">
                    <Plus size={16} /> إضافة نوع
                  </button>
                </div>
                <div className="space-y-4">
                  {form.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-3 p-5 bg-slate-50 rounded-3xl border-2 border-slate-100 relative group">
                      <input placeholder="اسم النوع" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.name} onChange={(e) => { const vs = [...form.variants]; vs[idx].name = e.target.value; setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="التكلفة" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.cost_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].cost_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="البيع" className="p-3.5 bg-white rounded-xl border-2 border-emerald-100 text-emerald-600 font-black text-xs" value={v.sale_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].sale_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <input type="number" placeholder="الكمية" className="p-3.5 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.stock_quantity || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].stock_quantity = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      <div className="flex items-center justify-end">
                        {form.variants.length > 1 && (
                          <button onClick={() => setForm({...form, variants: form.variants.filter((_, i) => i !== idx)})} className="p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors">
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3 text-amber-600">
                <AlertCircle size={20} />
                <p className="text-xs font-black">سيتم حفظ التغييرات فوراً في المخزون.</p>
              </div>
              <button 
                onClick={handleSave}
                disabled={!form.name || saving}
                className={`px-12 py-4.5 text-white font-black text-lg rounded-[1.8rem] shadow-2xl flex items-center gap-3 transition-all active:scale-95 ${modalMode === 'add' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} />}
                <span>{saving ? 'جاري الحفظ...' : modalMode === 'add' ? 'إضافة الصنف' : 'تحديث البيانات'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Save,
  AlertCircle,
  Loader2,
  Edit3,
  CheckSquare,
  Square,
  RotateCcw,
  AlertTriangle,
  CheckCircle2
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category, Product, Variant } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  // Custom Notifications (Toast)
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Custom Confirmation States
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{id: string | null, type: 'single' | 'bulk'}>({id: null, type: 'single'});

  // States for Filtering
  const [filterMainCategory, setFilterMainCategory] = useState<string>('all');
  const [filterSubCategory, setFilterSubCategory] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);

  const [form, setForm] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ id: undefined as string | undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*')
        .order('name');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const sanitizeUUID = (id: string | null | undefined) => {
    if (!id || id.trim() === "" || id === "all") return null;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id) ? id : null;
  };

  const handleOpenAdd = () => {
    setModalMode('add');
    setEditingId(null);
    setForm({
      name: '',
      barcode: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ id: undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    setShowModal(true);
  };

  const handleOpenEdit = (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    setModalMode('edit');
    setEditingId(product.id);
    setForm({
      name: product.name,
      barcode: product.barcode || '',
      supplier: product.supplier || '',
      category_id: product.category_id || '',
      sub_category_id: product.sub_category_id || '',
      variants: product.variants.map((v: any) => ({
        id: v.id,
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity
      }))
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.name || saving) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        barcode: form.barcode?.trim() || null,
        supplier: form.supplier?.trim() || null,
        category_id: sanitizeUUID(form.category_id),
        sub_category_id: sanitizeUUID(form.sub_category_id)
      };

      let prodId = editingId;

      if (modalMode === 'add') {
        const { data: prodData, error: pError } = await supabase.from('products').insert(payload).select().single();
        if (pError) {
            if (pError.code === '23505') {
                showToast("عذراً، هذا الباركود مستخدم بالفعل لصنف آخر", "error");
                setSaving(false);
                return;
            }
            throw pError;
        }
        prodId = prodData.id;
      } else {
        const { error: pError } = await supabase.from('products').update(payload).eq('id', prodId);
        if (pError) {
             if (pError.code === '23505') {
                showToast("عذراً، هذا الباركود مستخدم بالفعل لصنف آخر", "error");
                setSaving(false);
                return;
            }
            throw pError;
        }
      }

      if (modalMode === 'edit') {
        const currentVariantIds = form.variants.filter(v => v.id).map(v => v.id);
        const { data: existingVariants } = await supabase.from('variants').select('id').eq('product_id', prodId);
        const idsToDelete = existingVariants?.filter(ev => !currentVariantIds.includes(ev.id)).map(ev => ev.id) || [];
        if (idsToDelete.length > 0) {
          await supabase.from('variants').delete().in('id', idsToDelete);
        }
      }

      const variantsToUpsert = form.variants.map(v => ({
        id: v.id,
        product_id: prodId,
        name: v.name || 'افتراضي',
        cost_price: Number(v.cost_price) || 0,
        sale_price: Number(v.sale_price) || 0,
        stock_quantity: Number(v.stock_quantity) || 0
      }));

      const { error: vError } = await supabase.from('variants').upsert(variantsToUpsert);
      if (vError) throw vError;

      setShowModal(false);
      showToast(modalMode === 'add' ? "تم إضافة الصنف بنجاح" : "تم تحديث البيانات بنجاح", "success");
      await fetchData();
    } catch (err: any) {
      console.error("Save Error:", err);
      showToast("حدث خطأ أثناء الحفظ، يرجى المحاولة لاحقاً", "error");
    } finally {
      setSaving(false);
    }
  };

  const requestDeleteOne = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setDeleteTarget({id, type: 'single'});
    setShowDeleteConfirm(true);
  };

  const requestBulkDelete = () => {
    setDeleteTarget({id: null, type: 'bulk'});
    setShowDeleteConfirm(true);
  };

  const confirmDeleteAction = async () => {
    setLoading(true);
    setShowDeleteConfirm(false);
    try {
      if (deleteTarget.type === 'single' && deleteTarget.id) {
        await supabase.from('products').delete().eq('id', deleteTarget.id);
        setProducts(prev => prev.filter(p => p.id !== deleteTarget.id));
        setSelectedIds(prev => prev.filter(sid => sid !== deleteTarget.id));
        showToast("تم حذف الصنف");
      } else if (deleteTarget.type === 'bulk') {
        const { error } = await supabase.from('products').delete().in('id', selectedIds);
        if (error) throw error;
        await fetchData();
        setSelectedIds([]);
        showToast(`تم حذف ${selectedIds.length} أصناف`);
      }
    } catch (err: any) {
      console.error(err);
      showToast("فشل الحذف", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      const { data: prodData, error: pError } = await supabase.from('products').insert({
        name: `${product.name} (نسخة)`,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      }).select().single();

      if (pError) throw pError;
      const vars = product.variants.map((v: any) => ({
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prodData.id
      }));
      await supabase.from('variants').insert(vars);
      showToast("تم تكرار الصنف بنجاح");
      await fetchData();
    } catch (err: any) { 
        console.error(err); 
        showToast("خطأ في تكرار الصنف", "error");
    }
  };

  const toggleSelectAll = () => {
    if (selectedIds.length === filtered.length) setSelectedIds([]);
    else setSelectedIds(filtered.map(p => p.id));
  };

  const toggleSelectItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        (p.barcode && p.barcode.includes(searchTerm));

      const matchMain = filterMainCategory === 'all' || p.category_id === filterMainCategory;
      const matchSub = filterSubCategory === 'all' || p.sub_category_id === filterSubCategory;

      return matchSearch && matchMain && matchSub;
    });
  }, [products, searchTerm, filterMainCategory, filterSubCategory]);

  const stockValue = filtered.reduce((sum, p) => sum + (p.variants?.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0) || 0), 0);

  const mainCategories = useMemo(() => categories.filter(c => !c.parent_id), [categories]);
  const subCategoriesForFilter = useMemo(() => categories.filter(c => c.parent_id === filterMainCategory), [categories, filterMainCategory]);
  const subCategoriesForForm = useMemo(() => categories.filter(c => c.parent_id === form.category_id), [categories, form.category_id]);

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden relative" dir="rtl">
      {/* Toast Notification */}
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[300] flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl animate-in slide-in-from-top-10 duration-300 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-rose-600 border-rose-500 text-white'}`}>
          {toast.type === 'success' ? <CheckCircle2 size={24} /> : <AlertTriangle size={24} />}
          <span className="font-black text-sm">{toast.message}</span>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button 
              onClick={requestBulkDelete}
              className="px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-rose-200 animate-in fade-in zoom-in"
            >
              <Trash2 size={20} />
              <span>حذف المحددة ({selectedIds.length})</span>
            </button>
          )}
          <button 
            onClick={handleOpenAdd}
