                          <button onClick={(e) => handleDelete(e, sub.id)} className="p-2 text-slate-400 hover:text-rose-600 bg-white rounded-xl border border-slate-100 shadow-sm"><Trash2 size={16} /></button>
                        </div>
                      </div>
                      <p className="font-black text-slate-900 text-lg">{sub.name}</p>
                    </div>
                  ))}
                </div>
