            <div className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم القسم</label>
                <input 
                  autoFocus
                  type="text" 
                  placeholder="مثال: مشروبات، ملابس، خدمات..."
