import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Edit3, 
  Trash2, 
  Tag, 
  ChevronLeft, 
  X, 
  FolderTree, 
  Layers, 
  LayoutGrid,
  Loader2,
  AlertCircle,
  PlusCircle,
  CheckCircle2,
  Copy,
  CheckSquare,
  Square,
  AlertTriangle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category } from '../types';

const Categories: React.FC = () => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainId, setSelectedMainId] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const [form, setForm] = useState({ 
    name: '', 
    parent_id: null as string | null 
  });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('categories').select('*').order('name');
      if (error) throw error;
      setCategories(data || []);

      if (data && data.length > 0 && !selectedMainId) {
        const firstMain = data.find(c => !c.parent_id);
        if (firstMain) setSelectedMainId(firstMain.id);
      }
    } catch (err) {
      console.error(err);
      showToast("خطأ في تحميل الأقسام", "error");
    } finally {
      setLoading(false);
    }
  };

  const mainCategories = useMemo(() => categories.filter(c => !c.parent_id), [categories]);
  const subCategories = useMemo(() => categories.filter(c => c.parent_id === selectedMainId), [categories, selectedMainId]);

  const handleOpenAdd = (parentId: string | null = null) => {
    setModalMode('add');
    setEditingId(null);
    setForm({ name: '', parent_id: parentId });
    setShowAddModal(true);
  };

  const handleOpenEdit = (e: React.MouseEvent, cat: Category) => {
    e.stopPropagation();
    setModalMode('edit');
    setEditingId(cat.id);
    setForm({ name: cat.name, parent_id: cat.parent_id });
    setShowAddModal(true);
  };

  const handleSave = async () => {
    if (!form.name || saving) return;
    setSaving(true);
    try {
      if (modalMode === 'add') {
        const { error } = await supabase.from('categories').insert(form);
        if (error) throw error;
        showToast("تم إضافة القسم بنجاح");
      } else {
        const { error } = await supabase.from('categories').update({ name: form.name, parent_id: form.parent_id }).eq('id', editingId);
        if (error) throw error;
        showToast("تم تحديث البيانات");
      }
      setShowAddModal(false);
      fetchCategories();
    } catch (err) {
      console.error(err);
      showToast("فشل الحفظ", "error");
    } finally {
      setSaving(false);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, cat: Category) => {
    e.stopPropagation();
    try {
      const { error } = await supabase.from('categories').insert({
        name: `${cat.name} (نسخة)`,
        parent_id: cat.parent_id
      });
      if (error) throw error;
      showToast("تم تكرار القسم بنجاح");
      fetchCategories();
    } catch (err) {
      console.error(err);
      showToast("خطأ في التكرار", "error");
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("هل أنت متأكد؟ سيتم حذف كافة الأقسام الفرعية والأصناف المرتبطة بهذا القسم.")) {
      try {
        const { error } = await supabase.from('categories').delete().eq('id', id);
        if (error) throw error;
        showToast("تم الحذف بنجاح");
        if (selectedMainId === id) setSelectedMainId(null);
        setSelectedIds(prev => prev.filter(sid => sid !== id));
        fetchCategories();
      } catch (err) {
        console.error(err);
        showToast("فشل الحذف", "error");
      }
    }
  };

  const handleBulkDelete = async () => {
    if (confirm(`هل أنت متأكد من حذف ${selectedIds.length} أقسام مختارة؟ سيتم حذف كافة البيانات المرتبطة بها.`)) {
      setLoading(true);
      try {
        const { error } = await supabase.from('categories').delete().in('id', selectedIds);
        if (error) throw error;
        showToast(`تم حذف ${selectedIds.length} أقسام بنجاح`);
        setSelectedIds([]);
        fetchCategories();
      } catch (err) {
        console.error(err);
        showToast("خطأ في الحذف الجماعي", "error");
      } finally {
        setLoading(false);
      }
    }
  };

  const toggleSelect = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  return (
    <div className="h-full flex flex-col space-y-6 overflow-hidden relative" dir="rtl">
      {/* Toast Notification */}
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[300] flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl animate-in slide-in-from-top-10 duration-300 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-rose-600 border-rose-500 text-white'}`}>
          {toast.type === 'success' ? <CheckCircle2 size={24} /> : <AlertTriangle size={24} />}
          <span className="font-black text-sm">{toast.message}</span>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <FolderTree className="text-blue-600" />
          إدارة الأقسام
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button 
              onClick={handleBulkDelete}
              className="flex-1 md:flex-none px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg animate-in zoom-in"
            >
              <Trash2 size={20} />
              <span>حذف المحددة ({selectedIds.length})</span>
            </button>
          )}
          <button 
            onClick={() => handleOpenAdd(null)}
            className="flex-1 md:flex-none px-6 py-3 bg-blue-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg hover:bg-blue-700 transition-all active:scale-95"
          >
            <PlusCircle size={20} />
            <span>قسم رئيسي جديد</span>
          </button>
        </div>
      </div>

      {loading ? (
        <div className="flex-1 flex flex-col items-center justify-center gap-4">
          <Loader2 className="animate-spin text-blue-600" size={40} />
          <p className="font-black text-slate-400">جاري تحميل الهيكلية...</p>
        </div>
      ) : (
        <div className="flex-1 flex flex-col lg:flex-row gap-6 overflow-hidden pb-4">

          {/* Column 1: Main Categories */}
          <div className="flex flex-col w-full lg:w-1/3 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex-shrink-0">
            <div className="p-5 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-3">
                <LayoutGrid size={20} className="text-slate-400" />
                <h3 className="font-black text-slate-900 text-sm uppercase tracking-tight">الأقسام الرئيسية</h3>
              </div>
              <button 
                onClick={() => {
                  const allMainIds = mainCategories.map(c => c.id);
                  const isAllSelected = allMainIds.every(id => selectedIds.includes(id));
                  if (isAllSelected) setSelectedIds(prev => prev.filter(id => !allMainIds.includes(id)));
                  else setSelectedIds(prev => Array.from(new Set([...prev, ...allMainIds])));
                }}
                className="text-[10px] font-black text-blue-600 uppercase"
              >
                تحديد الكل
              </button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2">
              {mainCategories.map(main => (
                <div
                  key={main.id}
                  onClick={() => setSelectedMainId(main.id)}
                  className={`group relative p-4 rounded-2xl flex items-center justify-between transition-all duration-300 border-2 cursor-pointer ${selectedMainId === main.id ? 'bg-blue-600 border-blue-600 text-white shadow-xl shadow-blue-100 translate-x-1' : 'bg-transparent border-transparent hover:bg-slate-50 text-slate-600'}`}
                >
                  <div className="flex items-center gap-3">
                    <button 
                      onClick={(e) => toggleSelect(e, main.id)}
                      className={`transition-all ${selectedIds.includes(main.id) ? 'text-white' : (selectedMainId === main.id ? 'text-blue-200' : 'text-slate-300')}`}
                    >
                      {selectedIds.includes(main.id) ? <CheckSquare size={18} /> : <Square size={18} />}
                    </button>
                    <span className="font-black text-sm">{main.name}</span>
                  </div>
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={(e) => handleDuplicate(e, main)} className={`p-2 rounded-lg ${selectedMainId === main.id ? 'hover:bg-blue-500' : 'hover:bg-slate-200'}`} title="تكرار"><Copy size={14} /></button>
                    <button onClick={(e) => handleOpenEdit(e, main)} className={`p-2 rounded-lg ${selectedMainId === main.id ? 'hover:bg-blue-500' : 'hover:bg-slate-200'}`} title="تعديل"><Edit3 size={14} /></button>
                    <button onClick={(e) => handleDelete(e, main.id)} className={`p-2 rounded-lg ${selectedMainId === main.id ? 'hover:bg-rose-500' : 'hover:bg-rose-50 text-rose-500'}`} title="حذف"><Trash2 size={14} /></button>
                  </div>
                </div>
              ))}
              {mainCategories.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center p-10 text-center opacity-30">
                  <FolderTree size={40} />
                  <p className="font-black text-xs mt-4">لا توجد أقسام رئيسية</p>
                </div>
              )}
            </div>
          </div>

          {/* Column 2: Sub Categories */}
          <div className="flex flex-col flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden min-w-0">
            <div className="p-5 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-3">
                <Layers size={20} className="text-slate-400" />
                <h3 className="font-black text-slate-900 text-sm uppercase tracking-tight">
                  {selectedMainId ? `الأقسام الفرعية لـ (${mainCategories.find(c => c.id === selectedMainId)?.name})` : 'الأقسام الفرعية'}
                </h3>
              </div>
              <div className="flex items-center gap-3">
                {subCategories.length > 0 && (
                  <button 
                    onClick={() => {
                      const allSubIds = subCategories.map(c => c.id);
                      const isAllSelected = allSubIds.every(id => selectedIds.includes(id));
                      if (isAllSelected) setSelectedIds(prev => prev.filter(id => !allSubIds.includes(id)));
                      else setSelectedIds(prev => Array.from(new Set([...prev, ...allSubIds])));
                    }}
                    className="text-[10px] font-black text-blue-600 uppercase"
                  >
                    تحديد الكل
                  </button>
                )}
                {selectedMainId && (
                  <button 
                    onClick={() => handleOpenAdd(selectedMainId)}
                    className="px-4 py-2 bg-emerald-50 text-emerald-600 rounded-xl font-black text-xs flex items-center gap-2 border border-emerald-100 hover:bg-emerald-100 transition-colors"
                  >
                    <Plus size={16} /> إضافة فرعي
                  </button>
                )}
              </div>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-6">
              {!selectedMainId ? (
                <div className="h-full flex flex-col items-center justify-center opacity-40 space-y-4">
                  <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center"><ChevronLeft size={40} /></div>
                  <p className="font-black text-slate-500">يرجى اختيار قسم رئيسي لعرض تفرعاته</p>
                </div>
              ) : subCategories.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center opacity-30 space-y-4">
                  <Layers size={60} />
                  <p className="font-black text-slate-500">لا توجد أقسام فرعية مرتبطة بهذا القسم</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 animate-in fade-in duration-300">
                  {subCategories.map(sub => (
                    <div 
                      key={sub.id} 
                      onClick={(e) => toggleSelect(e, sub.id)}
                      className={`group p-5 rounded-3xl border-2 transition-all shadow-sm flex flex-col gap-4 cursor-pointer relative ${selectedIds.includes(sub.id) ? 'bg-blue-50 border-blue-500 shadow-blue-100' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-blue-300'}`}
                    >
                      <div className="flex justify-between items-start">
                        <div className={`p-3 rounded-2xl border transition-all ${selectedIds.includes(sub.id) ? 'bg-blue-600 text-white border-blue-600' : 'bg-white border-slate-200 text-blue-600 shadow-sm'}`}>
                          {selectedIds.includes(sub.id) ? <CheckSquare size={20} /> : <Tag size={20} />}
                        </div>
                        <div className="flex gap-1">
                          <button onClick={(e) => handleDuplicate(e, sub)} className="p-2 text-slate-400 hover:text-blue-600 bg-white rounded-xl border border-slate-100 shadow-sm" title="تكرار"><Copy size={16} /></button>
                          <button onClick={(e) => handleOpenEdit(e, sub)} className="p-2 text-slate-400 hover:text-blue-600 bg-white rounded-xl border border-slate-100 shadow-sm" title="تعديل"><Edit3 size={16} /></button>
                          <button onClick={(e) => handleDelete(e, sub.id)} className="p-2 text-slate-400 hover:text-rose-600 bg-white rounded-xl border border-slate-100 shadow-sm" title="حذف"><Trash2 size={16} /></button>
                        </div>
                      </div>
                      <p className={`font-black text-lg ${selectedIds.includes(sub.id) ? 'text-blue-900' : 'text-slate-900'}`}>{sub.name}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

        </div>
      )}

      {/* Modal: Add/Edit Category */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[200] p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200 border border-slate-200">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
               <div className="flex items-center gap-4">
                  <div className={`p-4 rounded-2xl shadow-xl text-white ${modalMode === 'add' ? 'bg-blue-600' : 'bg-indigo-600'}`}>
                    {modalMode === 'add' ? <Plus size={24} /> : <Edit3 size={24} />}
                  </div>
                  <h3 className="text-xl font-black text-slate-900">
                    {modalMode === 'add' ? (form.parent_id ? 'إضافة قسم فرعي' : 'إضافة قسم رئيسي') : 'تعديل بيانات القسم'}
                  </h3>
               </div>
               <button onClick={() => setShowAddModal(false)} className="p-2 text-slate-400 hover:text-slate-600"><X size={24} /></button>
            </div>

            <div className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم القسم</label>
                <input 
                  autoFocus
                  type="text" 
                  placeholder="مثال: مشروبات، ملابس، خدمات..."
                  className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-blue-600 font-black transition-all" 
                  value={form.name}
                  onChange={(e) => setForm({...form, name: e.target.value})}
                />
