              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الأب (الرئيسي)</label>
                <select 
                  className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black outline-none focus:border-blue-600 transition-all appearance-none"
                  value={form.parent_id || ''}
                  onChange={(e) => setForm({...form, parent_id: e.target.value || null})}
                >
                  <option value="">-- بدون (سيصبح قسماً رئيسياً) --</option>
                  {mainCategories.filter(c => c.id !== editingId).map(c => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              </div>

              <div className="pt-4">
                <button 
                  onClick={handleSave}
                  disabled={!form.name || saving}
                  className="w-full py-5 bg-blue-600 text-white font-black text-xl rounded-2xl shadow-2xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                >
                  {saving ? <Loader2 className="animate-spin" size={24} /> : modalMode === 'add' ? 'حفظ القسم الجديد' : 'تحديث البيانات'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

