  return (
    <Link 
      to={to} 
      onClick={onClick} 
      className={`flex items-center gap-4 px-6 py-5 rounded-2xl transition-all duration-300 group ${isActive ? 'bg-emerald-600 text-white shadow-xl shadow-emerald-900/40' : 'text-slate-300 hover:bg-white/5 hover:text-white border border-transparent hover:border-white/10'}`}
    >
      <Icon size={24} className={`${isActive ? 'text-white' : 'text-slate-500 group-hover:text-emerald-400'}`} />
      <span className="font-black text-lg tracking-tight">{label}</span>
    </Link>
  );
};

