  const location = useLocation();

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch((e) => {
        console.error(`Error attempting to enable full-screen mode: ${e.message}`);
      });
      setIsFullscreen(true);
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
        setIsFullscreen(false);
      }
    }
  };

  useEffect(() => {
    const handleFsChange = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', handleFsChange);
    return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  const pageTitle = location.pathname === '/' ? 'نقطة البيع' : 
                   location.pathname === '/inventory' ? 'المخزون' :
                   location.pathname === '/daily-reports' ? 'التقارير اليومية' : 
                   location.pathname === '/expenses' ? 'الإدارة المالية' : 'لوحة التحكم';

  return (
    <div className="h-screen w-screen bg-[#f8fafc] flex flex-col overflow-hidden font-['Tajawal']" dir="rtl">
      {/* Header with Menu Button */}
      <header className="h-20 bg-[#0f172a] border-b border-white/10 flex items-center justify-between px-6 shrink-0 z-[100] no-print">
        <div className="flex items-center gap-6">
          <button 
            onClick={() => setSidebarOpen(true)} 
            className="p-3 bg-emerald-600 text-white rounded-2xl shadow-lg shadow-emerald-900/40 hover:bg-emerald-500 transition-all active:scale-90"
          >
            <Menu size={28} />
          </button>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-emerald-500">
              <ShoppingCart size={22} />
            </div>
            <h1 className="text-xl font-black text-white hidden sm:block">Flyyti POS</h1>
          </div>
        </div>

        <div className="flex items-center gap-3 sm:gap-4">
          <span className="bg-emerald-500/10 text-emerald-500 px-4 py-2 rounded-xl text-xs sm:text-sm font-black border border-emerald-500/20">
            {pageTitle}
          </span>

          <button 
            onClick={toggleFullscreen}
            className="w-10 h-10 sm:w-12 sm:h-12 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
            title="ملء الشاشة"
          >
            {isFullscreen ? <Minimize2 size={22} /> : <Maximize2 size={22} />}
          </button>

          <div className="w-10 h-10 sm:w-12 sm:h-12 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center text-slate-400">
            <ShieldCheck size={22} />
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {children}
      </main>

      {sidebarOpen && (
        <>
          <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[150] transition-opacity" onClick={() => setSidebarOpen(false)} />
          <div className="fixed inset-y-0 right-0 w-80 bg-[#0f172a] z-[151] shadow-[20px_0_50px_rgba(0,0,0,0.5)] flex flex-col animate-slide-in-right border-l border-white/10">
            <div className="p-8 border-b border-white/10 flex items-center justify-between bg-black/20">
              <div className="flex items-center gap-3">
                 <div className="w-12 h-12 bg-emerald-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-emerald-900/40"><Menu size={24} /></div>
                 <span className="font-black text-white text-xl uppercase tracking-tighter">القائمة</span>
              </div>
              <button onClick={() => setSidebarOpen(false)} className="p-2 text-slate-400 hover:text-white transition-all"><X size={28} /></button>
            </div>

            <nav className="flex-1 p-6 space-y-2 overflow-y-auto custom-scrollbar">
              <NavItem to="/" icon={ShoppingCart} label="نقطة البيع" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/daily-reports" icon={LayoutDashboard} label="التقارير اليومية" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/inventory" icon={Package} label="المخزون" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/categories" icon={Tags} label="الأقسام" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/expenses" icon={Wallet} label="المصاريف" onClick={() => setSidebarOpen(false)} />
