                  onChange={(e) => setForm({...form, note: e.target.value})}
                />
              </div>

              <div className="pt-4">
                <button 
                  onClick={handleSave}
                  className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl shadow-emerald-100 hover:bg-emerald-700 active:scale-95 transition-all flex items-center justify-center gap-3"
                >
                  <Save size={24} />
                  حفظ البيانات
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

