import type { AppSettings } from '../types';

const Invoices: React.FC<{ settings: AppSettings | null, onUpdateSettings: () => void }> = ({ settings, onUpdateSettings }) => {
  const [invoices, setInvoices] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingInvoice, setEditingInvoice] = useState<any>(null);
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearch, setItemSearch] = useState('');
  const [showItemSearch, setShowItemSearch] = useState(false);
  const [loading, setLoading] = useState(false);

  // Date Filtering States
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [showDatePicker, setShowDatePicker] = useState(false);

  const fetchInvoices = useCallback(async () => {
    setLoading(true);
    const start = `${selectedDate}T00:00:00.000Z`;
    const end = `${selectedDate}T23:59:59.999Z`;

    const { data, error } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (!error) setInvoices(data || []);
    setLoading(false);
  }, [selectedDate]);

  useEffect(() => {
    fetchInvoices();
    fetchAllProducts();
  }, [fetchInvoices]);

  const fetchAllProducts = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    if (prods) {
      const flattened = prods.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
      })));
      setAllProducts(flattened);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm("هل أنت متأكد من حذف الفاتورة؟ لن يتم إرجاع المخزون تلقائياً.")) {
      await supabase.from('invoices').delete().eq('id', id);
      fetchInvoices();
    }
  };

  const handlePrint = (invoice: any) => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const itemsHtml = invoice.invoice_items.map((it: any) => `
      <tr>
        <td style="padding: 5px; border-bottom: 1px solid #eee;">${it.product_name} <br/><small>${it.variant_name}</small></td>
        <td style="padding: 5px; border-bottom: 1px solid #eee; text-align: center;">${it.quantity}</td>
        <td style="padding: 5px; border-bottom: 1px solid #eee; text-align: left;">${it.sale_price * it.quantity} ₪</td>
      </tr>
    `).join('');

    const servicesHtml = invoice.extra_services.map((ser: any) => `
      <tr>
        <td style="padding: 5px; border-bottom: 1px solid #eee;">${ser.name} (خدمة)</td>
        <td style="padding: 5px; border-bottom: 1px solid #eee; text-align: center;">${ser.quantity}</td>
        <td style="padding: 5px; border-bottom: 1px solid #eee; text-align: left;">${ser.sale_price * ser.quantity} ₪</td>
      </tr>
    `).join('');

    printWindow.document.write(`
      <html dir="rtl">
        <head>
          <title>فاتورة #${invoice.id.slice(0,8)}</title>
          <style>
            body { font-family: 'Tajawal', sans-serif; padding: 20px; width: 80mm; margin: 0 auto; }
            h2 { text-align: center; margin-bottom: 10px; }
            table { width: 100%; border-collapse: collapse; margin-top: 15px; font-size: 12px; }
            .total-row { font-weight: bold; border-top: 2px solid #000; }
            .center { text-align: center; }
            .right { text-align: right; }
            .left { text-align: left; }
          </style>
        </head>
        <body>
          <h2>Flyyti Mobile POS</h2>
          <p class="center">فاتورة مبيعات</p>
          <p>الرقم: #${invoice.id.slice(0,8)}</p>
          <p>التاريخ: ${new Date(invoice.created_at).toLocaleString('ar-EG')}</p>
          <hr/>
          <table>
            <thead>
              <tr>
                <th class="right">الصنف</th>
                <th class="center">الكمية</th>
                <th class="left">السعر</th>
              </tr>
            </thead>
            <tbody>
              ${itemsHtml}
              ${servicesHtml}
            </tbody>
          </table>
          <div style="margin-top: 20px; border-top: 1px solid #000; padding-top: 10px;">
            <p>الإجمالي: ${invoice.total_amount} ₪</p>
            <p>الخصم: ${invoice.discount} ₪</p>
            <h3 style="border-top: 2px solid #000; padding-top: 5px;">الصافي: ${invoice.net_amount} ₪</h3>
          </div>
          <p class="center" style="margin-top: 30px; font-size: 10px;">شكراً لزيارتكم!</p>
          <script>window.onload = function() { window.print(); window.close(); };</script>
        </body>
      </html>
    `);
    printWindow.document.close();
  };

  const calculateEditTotals = () => {
    if (!editingInvoice) return { subtotal: 0, net: 0 };
    const subtotal = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                    editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
    const net = Math.max(0, subtotal - editingInvoice.discount);
    return { subtotal, net };
  };

  const addItemToEditingInvoice = (v: any) => {
    const exists = editingInvoice.invoice_items.find((it: any) => it.variant_id === v.id);
    if (exists) {
      const newItems = editingInvoice.invoice_items.map((it: any) => 
        it.variant_id === v.id ? { ...it, quantity: it.quantity + 1 } : it
      );
      setEditingInvoice({ ...editingInvoice, invoice_items: newItems });
    } else {
      const newItem = {
        invoice_id: editingInvoice.id,
        variant_id: v.id,
        product_name: v.productName,
        variant_name: v.name,
        quantity: 1,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        isNew: true 
      };
      setEditingInvoice({ 
        ...editingInvoice, 
        invoice_items: [...editingInvoice.invoice_items, newItem] 
      });
    }
    setShowItemSearch(false);
    setItemSearch('');
  };

  const handleUpdateInvoice = async () => {
    if (!editingInvoice) return;
    setLoading(true);

    try {
      const { subtotal, net } = calculateEditTotals();
      const newCost = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                     editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);

      await supabase.from('invoices').update({
        total_amount: subtotal,
        discount: editingInvoice.discount,
        net_amount: net,
        total_cost: newCost,
        profit: net - newCost
      }).eq('id', editingInvoice.id);

      const originalInvoice = invoices.find(inv => inv.id === editingInvoice.id);

      for (const item of editingInvoice.invoice_items) {
        if (item.isNew) {
          const { isNew, ...itemToInsert } = item;
          await supabase.from('invoice_items').insert(itemToInsert);
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        } else {
          const originalItem = originalInvoice.invoice_items.find((it: any) => it.id === item.id);
          const diff = item.quantity - (originalItem ? originalItem.quantity : 0);

          await supabase.from('invoice_items').update({ quantity: item.quantity }).eq('id', item.id);

          if (diff !== 0) {
            const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
            if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - diff }).eq('id', item.variant_id);
          }
        }
      }

      const currentItemIds = editingInvoice.invoice_items.filter((i:any) => i.id).map((i:any) => i.id);
      const itemsToRemove = originalInvoice.invoice_items.filter((i:any) => !currentItemIds.includes(i.id));
      for (const item of itemsToRemove) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
        await supabase.from('invoice_items').delete().eq('id', item.id);
      }

      setEditingInvoice(null);
      fetchInvoices();
    } catch (e) {
      console.error(e);
      alert("خطأ في التحديث");
    } finally {
      setLoading(false);
    }
  };

  const filteredItems = allProducts.filter(p => 
    p.productName.toLowerCase().includes(itemSearch.toLowerCase()) || 
    (p.barcode && p.barcode.includes(itemSearch))
  ).slice(0, 5);

  const { subtotal: modalSubtotal, net: modalNet } = calculateEditTotals();

  // Helper for human-readable date
  const getReadableDate = (dateStr: string) => {
    const d = new Date(dateStr);
    const today = new Date().toISOString().split('T')[0];
    if (dateStr === today) return 'اليوم';
    return d.toLocaleDateString('ar-EG', { day: 'numeric', month: 'long', year: 'numeric' });
  };

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-6 overflow-hidden font-['Tajawal']" dir="rtl">

      {/* Header Area with Date Picker */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 shrink-0">
         <div className="flex items-center gap-4">
            <div className="p-4 bg-slate-900 text-white rounded-2xl shadow-xl shadow-slate-200">
               <FileText size={24} />
            </div>
            <div>
               <h2 className="text-2xl font-black text-slate-900 tracking-tight">سجل الفواتير</h2>
               <div className="flex items-center gap-2 mt-1">
                  <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                  <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">عرض فواتير: {getReadableDate(selectedDate)}</p>
               </div>
            </div>
         </div>

         <div className="flex flex-col sm:flex-row items-stretch gap-3 w-full lg:w-auto">
            {/* Elegant Date Selector */}
            <div className="relative group flex-1 sm:flex-none">
               <button 
                  onClick={() => setShowDatePicker(!showDatePicker)}
                  className={`w-full flex items-center justify-between gap-4 px-6 py-4 rounded-2xl font-black text-sm border-2 transition-all shadow-sm ${showDatePicker ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-200 text-slate-600 hover:border-slate-400'}`}
               >
                  <div className="flex items-center gap-3">
                     <CalendarIcon size={18} className={showDatePicker ? 'text-emerald-400' : 'text-slate-400'} />
                     <span>{getReadableDate(selectedDate)}</span>
                  </div>
                  <ChevronDown size={16} className={`transition-transform duration-300 ${showDatePicker ? 'rotate-180' : ''}`} />
               </button>

               {showDatePicker && (
                  <>
                     <div className="fixed inset-0 z-[150]" onClick={() => setShowDatePicker(false)} />
                     <div className="absolute top-16 right-0 left-0 sm:left-auto sm:w-80 bg-white rounded-[2rem] shadow-2xl border border-slate-200 z-[151] p-6 animate-in slide-in-from-top-4 duration-300">
                        <div className="flex items-center justify-between mb-4 border-b border-slate-100 pb-3">
                           <h4 className="font-black text-slate-900 text-sm">تحديد التاريخ</h4>
                           <button onClick={() => setSelectedDate(new Date().toISOString().split('T')[0])} className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-lg">العودة لليوم</button>
                        </div>
                        <div className="space-y-4">
                           <input 
                              type="date" 
                              className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-slate-900 font-black text-center"
                              value={selectedDate}
                              onChange={(e) => { setSelectedDate(e.target.value); setShowDatePicker(false); }}
                           />
                           <div className="grid grid-cols-2 gap-2">
                              <button onClick={() => {
                                 const yesterday = new Date();
                                 yesterday.setDate(yesterday.getDate() - 1);
                                 setSelectedDate(yesterday.toISOString().split('T')[0]);
                                 setShowDatePicker(false);
                              }} className="p-3 bg-slate-50 hover:bg-slate-100 rounded-xl text-xs font-bold text-slate-600 transition-colors">فواتير الأمس</button>
                              <button onClick={() => {
                                 const lastWeek = new Date();
                                 lastWeek.setDate(lastWeek.getDate() - 7);
                                 setSelectedDate(lastWeek.toISOString().split('T')[0]);
                                 setShowDatePicker(false);
                              }} className="p-3 bg-slate-50 hover:bg-slate-100 rounded-xl text-xs font-bold text-slate-600 transition-colors">قبل أسبوع</button>
                           </div>
                        </div>
                     </div>
                  </>
               )}
            </div>

            {/* Search Input */}
            <div className="relative group flex-1 lg:w-80">
               <SearchIcon className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-slate-900 transition-colors" size={20} />
               <input
                 type="text"
                 placeholder="ابحث برقم العملية..."
                 className="w-full pr-14 pl-6 py-4 bg-white border-2 border-slate-200 rounded-2xl focus:border-slate-900 outline-none font-black shadow-sm transition-all"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
               />
            </div>
         </div>
      </div>

      {/* Invoices List Table */}
      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col flex-1 relative">
        {loading && (
          <div className="absolute inset-0 bg-white/60 backdrop-blur-[1px] z-50 flex flex-col items-center justify-center gap-4">
             <div className="w-12 h-12 border-4 border-slate-100 border-t-emerald-600 rounded-full animate-spin"></div>
             <p className="font-black text-slate-400 text-sm">جاري جلب الفواتير...</p>
          </div>
        )}

        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-900 text-white z-10">
              <tr>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-right">المعرف / التوقيت</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">إجمالي القيمة</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الخصم</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">صافي المدفوع</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الربح</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {invoices.filter(i => i.id.includes(searchTerm)).map(i => (
                <tr key={i.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="p-6">
                    <div className="flex flex-col gap-1">
                       <span className="font-mono text-[10px] text-slate-400">#{i.id.slice(0, 8)}</span>
                       <div className="flex items-center gap-2 text-slate-900 font-black text-sm">
                          <Clock size={14} className="text-slate-400" />
                          {new Date(i.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
                       </div>
                    </div>
                  </td>
                  <td className="p-6 text-center">
                     <span className="font-bold text-slate-400 text-xs">{i.total_amount} ₪</span>
                  </td>
                  <td className="p-6 text-center">
                     <span className={`px-3 py-1 rounded-lg text-[10px] font-black ${Number(i.discount) > 0 ? 'bg-rose-50 text-rose-500 border border-rose-100' : 'text-slate-300'}`}>
                        {Number(i.discount) > 0 ? `-${i.discount} ₪` : '0.00'}
                     </span>
                  </td>
                  <td className="p-6 text-center">
                     <span className="font-black text-emerald-600 text-lg">{i.net_amount} ₪</span>
                  </td>
                  <td className="p-6 text-center">
                     <div className="inline-flex items-center justify-center gap-1.5 px-3 py-1 bg-slate-900 text-white rounded-xl text-xs font-black shadow-lg shadow-slate-200">
                        {i.profit} ₪
                     </div>
                  </td>
                  <td className="p-6 text-left">
                    <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all transform translate-x-2 group-hover:translate-x-0">
                      <button onClick={() => handlePrint(i)} className="p-3 text-emerald-600 hover:bg-emerald-50 bg-slate-50 rounded-xl" title="طباعة"><Printer size={18} /></button>
                      <button onClick={() => setEditingInvoice(i)} className="p-3 text-blue-600 hover:bg-blue-50 bg-slate-50 rounded-xl" title="تعديل"><Edit2 size={18} /></button>
                      <button onClick={() => handleDelete(i.id)} className="p-3 text-rose-600 hover:bg-rose-50 bg-slate-50 rounded-xl" title="حذف"><Trash2 size={18} /></button>
                    </div>
                  </td>
                </tr>
              ))}
              {invoices.length === 0 && !loading && (
                <tr>
                   <td colSpan={7} className="p-32 text-center">
                      <div className="flex flex-col items-center gap-4 opacity-20">
                         <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center">
                           <FileText size={48} />
                         </div>
                         <p className="font-black text-xl">لا توجد فواتير في هذا التاريخ</p>
                      </div>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* List Summary Footer */}
        <div className="p-6 bg-slate-50 border-t border-slate-100 flex items-center justify-between shrink-0">
           <div className="flex items-center gap-6">
              <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">عدد الفواتير</p>
                 <p className="font-black text-slate-900">{invoices.length} عملية</p>
              </div>
              <div className="h-8 w-px bg-slate-200"></div>
              <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">إجمالي مبيعات اليوم</p>
                 <p className="font-black text-emerald-600">{invoices.reduce((s, i) => s + Number(i.net_amount), 0).toFixed(2)} ₪</p>
              </div>
           </div>
           <button onClick={fetchInvoices} className="p-3 bg-white border border-slate-200 text-slate-500 rounded-xl hover:text-slate-900 hover:border-slate-400 transition-all">
              <RefreshCw size={18} className={loading ? 'animate-spin' : ''} />
           </button>
        </div>
      </div>

      {/* Edit Invoice Modal */}
      {editingInvoice && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[250] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-200">
            <div className="p-6 bg-slate-900 text-white flex justify-between items-center shrink-0 border-b border-white/10">
               <div className="flex items-center gap-3">
                 <div className="p-2 bg-emerald-600 rounded-xl shadow-lg"><Edit2 size={20} /></div>
                 <h3 className="font-black text-lg">تعديل فاتورة #{editingInvoice.id.slice(0,8)}</h3>
               </div>
               <button onClick={() => setEditingInvoice(null)} className="p-2 bg-white/10 rounded-lg hover:text-rose-400 transition-colors"><X size={20} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar bg-slate-50/30">
              <div className="relative">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1 mb-2">إضافة صنف للفاتورة</p>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="ابحث بالاسم أو الباركود..."
                    className="w-full p-4 pr-12 bg-white border-2 border-slate-200 rounded-2xl outline-none focus:border-emerald-600 font-bold transition-all text-sm shadow-sm"
                    value={itemSearch}
                    onChange={(e) => { setItemSearch(e.target.value); setShowItemSearch(true); }}
                    onFocus={() => setShowItemSearch(true)}
                  />
                  <SearchIcon className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                </div>

                {showItemSearch && itemSearch.length > 0 && (
                  <div className="absolute top-16 left-0 right-0 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 overflow-hidden divide-y divide-slate-100 animate-in slide-in-from-top-2">
                    {filteredItems.map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => addItemToEditingInvoice(v)}
                        className="w-full p-4 flex items-center justify-between hover:bg-emerald-50 transition-colors text-right"
                      >
                        <div>
                          <p className="font-black text-xs text-slate-800">{v.productName}</p>
                          <p className="text-[10px] text-slate-400 font-bold">{v.name}</p>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className="font-black text-emerald-600 text-xs">{v.sale_price} ₪</span>
                          <Plus className="text-emerald-500" size={18} />
                        </div>
                      </button>
                    ))}
                    {filteredItems.length === 0 && <div className="p-4 text-center text-xs text-slate-400">لا توجد نتائج</div>}
                  </div>
                )}
              </div>

              <div className="space-y-2 pt-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">قائمة الأصناف الحالية</p>
                {editingInvoice.invoice_items.map((item: any, idx: number) => (
                  <div key={item.id || `new-${idx}`} className={`p-4 rounded-2xl border flex items-center justify-between shadow-sm transition-all ${item.isNew ? 'bg-emerald-50 border-emerald-200' : 'bg-white border-slate-200'}`}>
                    <div>
                      <p className="font-black text-xs text-slate-700">{item.product_name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-slate-50 p-1 rounded-xl border border-slate-100">
                        <button onClick={() => {
                          const newItems = [...editingInvoice.invoice_items];
                          newItems[idx].quantity = Math.max(1, newItems[idx].quantity - 1);
                          setEditingInvoice({...editingInvoice, invoice_items: newItems});
                        }} className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-slate-400 shadow-sm"><Minus size={14} /></button>
                        <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                        <button onClick={() => {
                          const newItems = [...editingInvoice.invoice_items];
                          newItems[idx].quantity += 1;
                          setEditingInvoice({...editingInvoice, invoice_items: newItems});
                        }} className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-slate-900 shadow-sm"><Plus size={14} /></button>
                      </div>
                      <button onClick={() => {
                        const newItems = editingInvoice.invoice_items.filter((_, i) => i !== idx);
                        setEditingInvoice({...editingInvoice, invoice_items: newItems});
                      }} className="text-rose-400 hover:text-rose-600 p-2"><Trash2 size={18} /></button>
                    </div>
                  </div>
                ))}

                {editingInvoice.extra_services.map((ser: any, idx: number) => (
                  <div key={ser.id} className="bg-emerald-50 p-4 rounded-2xl border border-emerald-100 flex items-center justify-between shadow-sm">
                    <div>
                      <p className="font-black text-xs text-emerald-800">{ser.name}</p>
                      <p className="text-[9px] text-emerald-600 font-bold uppercase">خدمة إضافية</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-white p-1 rounded-xl border border-emerald-200">
                        <button onClick={() => {
                          const newSers = [...editingInvoice.extra_services];
                          newSers[idx].quantity = Math.max(1, newSers[idx].quantity - 1);
                          setEditingInvoice({...editingInvoice, extra_services: newSers});
                        }} className="w-8 h-8 bg-emerald-50 rounded-lg flex items-center justify-center text-emerald-600"><Minus size={14} /></button>
                        <span className="font-black text-xs w-6 text-center">{ser.quantity}</span>
                        <button onClick={() => {
                          const newSers = [...editingInvoice.extra_services];
                          newSers[idx].quantity += 1;
                          setEditingInvoice({...editingInvoice, extra_services: newSers});
                        }} className="w-8 h-8 bg-emerald-50 rounded-lg flex items-center justify-center text-emerald-600"><Plus size={14} /></button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="pt-4 border-t border-slate-200 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">تعديل قيمة الخصم (₪)</label>
                <input 
                  type="number" 
                  className="w-full p-4 bg-white border-2 border-slate-200 rounded-2xl font-black text-xl outline-none focus:border-rose-500 text-center shadow-sm" 
                  value={editingInvoice.discount || ''}
                  placeholder="0.00"
                  onChange={(e) => setEditingInvoice({...editingInvoice, discount: Number(e.target.value)})}
                />
              </div>
            </div>

            <div className="p-6 bg-white border-t border-slate-200 shrink-0 space-y-4 shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                     <p className="text-[9px] font-black text-slate-400 uppercase mb-1">إجمالي الفاتورة</p>
                     <p className="font-black text-slate-900 text-xl">{modalSubtotal} ₪</p>
                  </div>
                  <div className="p-4 bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-900/10">
                     <p className="text-[9px] font-black uppercase mb-1 opacity-70">الصافي الجديد</p>
                     <p className="font-black text-2xl">{modalNet} ₪</p>
                  </div>
               </div>
               <button 
                onClick={handleUpdateInvoice}
                disabled={loading}
                className="w-full py-5 bg-slate-900 text-white font-black text-lg rounded-[1.5rem] shadow-2xl hover:bg-slate-800 flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50"
               >
                 <Save size={20} className="text-emerald-400" />
                 {loading ? 'جاري الحفظ...' : 'اعتماد وحفظ التعديلات'}
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Invoices;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  FileText, 
  Edit2, 
  Trash2, 
  Printer, 
  Search, 
  X, 
  Save, 
  Plus, 
  Minus, 
  Search as SearchIcon,
  ShoppingBag,
  CheckCircle2,
  AlertTriangle,
  Calendar as CalendarIcon,
  ChevronDown,
  Filter,
  RefreshCw,
  Clock,
  Layers,
  CalendarDays,
  CalendarRange,
  ChevronLeft
} from 'lucide-react';
import { supabase } from '../supabase';
import type { AppSettings } from '../types';

type FilterMode = 'day' | 'month' | 'year';

const Invoices: React.FC<{ settings: AppSettings | null, onUpdateSettings: () => void }> = ({ settings, onUpdateSettings }) => {
  const [invoices, setInvoices] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingInvoice, setEditingInvoice] = useState<any>(null);
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearch, setItemSearch] = useState('');
  const [showItemSearch, setShowItemSearch] = useState(false);
  const [loading, setLoading] = useState(false);

  // Date Filtering States
  const [filterMode, setFilterMode] = useState<FilterMode>('day');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth());
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [showFilterPanel, setShowFilterPanel] = useState(false);

  const fetchInvoices = useCallback(async () => {
    setLoading(true);
    let start, end;

    if (filterMode === 'day') {
      start = `${selectedDate}T00:00:00.000Z`;
      end = `${selectedDate}T23:59:59.999Z`;
    } else if (filterMode === 'month') {
      const firstDay = new Date(selectedYear, selectedMonth, 1);
      const lastDay = new Date(selectedYear, selectedMonth + 1, 0);
      start = firstDay.toISOString();
      end = lastDay.toISOString();
      // Adjust last day to end of day
      end = end.split('T')[0] + 'T23:59:59.999Z';
    } else {
      const firstDay = new Date(selectedYear, 0, 1);
      const lastDay = new Date(selectedYear, 11, 31);
      start = firstDay.toISOString();
      end = lastDay.toISOString();
      end = end.split('T')[0] + 'T23:59:59.999Z';
    }

    const { data, error } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (!error) setInvoices(data || []);
    setLoading(false);
  }, [filterMode, selectedDate, selectedMonth, selectedYear]);

  // Reset to "Today" every time the user enters the page
  useEffect(() => {
    setFilterMode('day');
    setSelectedDate(new Date().toISOString().split('T')[0]);
    fetchInvoices();
    fetchAllProducts();
  }, []);

  // Refetch when filters change
  useEffect(() => {
    fetchInvoices();
  }, [fetchInvoices]);

  const fetchAllProducts = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    if (prods) {
      const flattened = prods.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
      })));
      setAllProducts(flattened);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm("هل أنت متأكد من حذف الفاتورة؟ لن يتم إرجاع المخزون تلقائياً.")) {
      await supabase.from('invoices').delete().eq('id', id);
      fetchInvoices();
    }
  };

  const handlePrint = (invoice: any) => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const itemsHtml = invoice.invoice_items.map((it: any) => `
      <tr>
        <td style="padding: 5px; border-bottom: 1px solid #eee;">${it.product_name} <br/><small>${it.variant_name}</small></td>
        <td style="padding: 5px; border-bottom: 1px solid #eee; text-align: center;">${it.quantity}</td>
        <td style="padding: 5px; border-bottom: 1px solid #eee; text-align: left;">${it.sale_price * it.quantity} ₪</td>
      </tr>
    `).join('');

    const servicesHtml = invoice.extra_services.map((ser: any) => `
      <tr>
        <td style="padding: 5px; border-bottom: 1px solid #eee;">${ser.name} (خدمة)</td>
        <td style="padding: 5px; border-bottom: 1px solid #eee; text-align: center;">${ser.quantity}</td>
        <td style="padding: 5px; border-bottom: 1px solid #eee; text-align: left;">${ser.sale_price * ser.quantity} ₪</td>
      </tr>
    `).join('');

    printWindow.document.write(`
      <html dir="rtl">
        <head>
          <title>فاتورة #${invoice.id.slice(0,8)}</title>
          <style>
            body { font-family: 'Tajawal', sans-serif; padding: 20px; width: 80mm; margin: 0 auto; }
            h2 { text-align: center; margin-bottom: 10px; }
            table { width: 100%; border-collapse: collapse; margin-top: 15px; font-size: 12px; }
            .total-row { font-weight: bold; border-top: 2px solid #000; }
            .center { text-align: center; }
            .right { text-align: right; }
            .left { text-align: left; }
          </style>
        </head>
        <body>
          <h2>Flyyti Mobile POS</h2>
          <p class="center">فاتورة مبيعات</p>
          <p>الرقم: #${invoice.id.slice(0,8)}</p>
          <p>التاريخ: ${new Date(invoice.created_at).toLocaleString('ar-EG')}</p>
          <hr/>
          <table>
            <thead>
              <tr>
                <th class="right">الصنف</th>
                <th class="center">الكمية</th>
                <th class="left">السعر</th>
              </tr>
            </thead>
            <tbody>
              ${itemsHtml}
              ${servicesHtml}
            </tbody>
          </table>
          <div style="margin-top: 20px; border-top: 1px solid #000; padding-top: 10px;">
            <p>الإجمالي: ${invoice.total_amount} ₪</p>
            <p>الخصم: ${invoice.discount} ₪</p>
            <h3 style="border-top: 2px solid #000; padding-top: 5px;">الصافي: ${invoice.net_amount} ₪</h3>
          </div>
          <p class="center" style="margin-top: 30px; font-size: 10px;">شكراً لزيارتكم!</p>
          <script>window.onload = function() { window.print(); window.close(); };</script>
        </body>
      </html>
    `);
    printWindow.document.close();
  };

  const calculateEditTotals = () => {
    if (!editingInvoice) return { subtotal: 0, net: 0 };
    const subtotal = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                    editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
    const net = Math.max(0, subtotal - editingInvoice.discount);
    return { subtotal, net };
  };

  const addItemToEditingInvoice = (v: any) => {
    const exists = editingInvoice.invoice_items.find((it: any) => it.variant_id === v.id);
    if (exists) {
      const newItems = editingInvoice.invoice_items.map((it: any) => 
        it.variant_id === v.id ? { ...it, quantity: it.quantity + 1 } : it
      );
      setEditingInvoice({ ...editingInvoice, invoice_items: newItems });
    } else {
      const newItem = {
        invoice_id: editingInvoice.id,
        variant_id: v.id,
        product_name: v.productName,
        variant_name: v.name,
        quantity: 1,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        isNew: true 
      };
      setEditingInvoice({ 
        ...editingInvoice, 
        invoice_items: [...editingInvoice.invoice_items, newItem] 
      });
    }
    setShowItemSearch(false);
    setItemSearch('');
  };

  const handleUpdateInvoice = async () => {
    if (!editingInvoice) return;
    setLoading(true);

    try {
      const { subtotal, net } = calculateEditTotals();
      const newCost = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                     editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);

      await supabase.from('invoices').update({
        total_amount: subtotal,
        discount: editingInvoice.discount,
        net_amount: net,
        total_cost: newCost,
        profit: net - newCost
      }).eq('id', editingInvoice.id);

      const originalInvoice = invoices.find(inv => inv.id === editingInvoice.id);

      for (const item of editingInvoice.invoice_items) {
        if (item.isNew) {
          const { isNew, ...itemToInsert } = item;
          await supabase.from('invoice_items').insert(itemToInsert);
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        } else {
          const originalItem = originalInvoice.invoice_items.find((it: any) => it.id === item.id);
          const diff = item.quantity - (originalItem ? originalItem.quantity : 0);

          await supabase.from('invoice_items').update({ quantity: item.quantity }).eq('id', item.id);

          if (diff !== 0) {
            const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
            if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - diff }).eq('id', item.variant_id);
          }
        }
      }

      const currentItemIds = editingInvoice.invoice_items.filter((i:any) => i.id).map((i:any) => i.id);
      const itemsToRemove = originalInvoice.invoice_items.filter((i:any) => !currentItemIds.includes(i.id));
      for (const item of itemsToRemove) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
        await supabase.from('invoice_items').delete().eq('id', item.id);
      }

      setEditingInvoice(null);
      fetchInvoices();
    } catch (e) {
      console.error(e);
      alert("خطأ في التحديث");
    } finally {
      setLoading(false);
    }
  };

  const filteredItems = allProducts.filter(p => 
    p.productName.toLowerCase().includes(itemSearch.toLowerCase()) || 
    (p.barcode && p.barcode.includes(itemSearch))
  ).slice(0, 5);

  const { subtotal: modalSubtotal, net: modalNet } = calculateEditTotals();

  // Helper for human-readable filter description
  const getReadableFilter = () => {
    if (filterMode === 'day') {
      const today = new Date().toISOString().split('T')[0];
      if (selectedDate === today) return 'اليوم';
      return new Date(selectedDate).toLocaleDateString('ar-EG', { day: 'numeric', month: 'long', year: 'numeric' });
    } else if (filterMode === 'month') {
      const monthName = new Date(selectedYear, selectedMonth).toLocaleDateString('ar-EG', { month: 'long' });
      return `شهر ${monthName} ${selectedYear}`;
    } else {
      return `سنة ${selectedYear}`;
    }
  };

  const months = [
    'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
    'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
  ];

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-6 overflow-hidden font-['Tajawal']" dir="rtl">

      {/* Header Area with Advanced Date Filtering */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 shrink-0">
         <div className="flex items-center gap-4">
            <div className="p-4 bg-slate-900 text-white rounded-2xl shadow-xl shadow-slate-200">
               <FileText size={24} />
            </div>
            <div>
               <h2 className="text-2xl font-black text-slate-900 tracking-tight">سجل الفواتير</h2>
               <div className="flex items-center gap-2 mt-1">
                  <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                  <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">
                    النطاق الحالي: <span className="text-slate-600">{getReadableFilter()}</span>
                  </p>
               </div>
            </div>
         </div>

         <div className="flex flex-col sm:flex-row items-stretch gap-3 w-full lg:w-auto">
            {/* Luxurious Filter Panel Button */}
            <div className="relative flex-1 sm:flex-none">
               <button 
                  onClick={() => setShowFilterPanel(!showFilterPanel)}
                  className={`w-full flex items-center justify-between gap-4 px-6 py-4 rounded-2xl font-black text-sm border-2 transition-all shadow-sm ${showFilterPanel ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-200 text-slate-600 hover:border-slate-400'}`}
               >
                  <div className="flex items-center gap-3">
                     <CalendarRange size={18} className={showFilterPanel ? 'text-emerald-400' : 'text-slate-400'} />
                     <span>تحديد النطاق الزمني</span>
                  </div>
                  <ChevronDown size={16} className={`transition-transform duration-300 ${showFilterPanel ? 'rotate-180' : ''}`} />
               </button>

               {showFilterPanel && (
                  <>
                     <div className="fixed inset-0 z-[150]" onClick={() => setShowFilterPanel(false)} />
                     <div className="absolute top-16 right-0 left-0 sm:left-auto sm:w-[400px] bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 z-[151] overflow-hidden animate-in slide-in-from-top-4 duration-300">
                        {/* Filter Tabs */}
                        <div className="flex bg-slate-900 p-2 border-b border-white/10">
                           {(['day', 'month', 'year'] as FilterMode[]).map((mode) => (
                             <button
                               key={mode}
                               onClick={() => setFilterMode(mode)}
                               className={`flex-1 py-3 rounded-xl font-black text-xs transition-all ${filterMode === mode ? 'bg-emerald-600 text-white' : 'text-slate-400 hover:text-white'}`}
                             >
                               {mode === 'day' ? 'يومي' : mode === 'month' ? 'شهري' : 'سنوي'}
                             </button>
                           ))}
                        </div>

                        <div className="p-8 space-y-6">
                           {filterMode === 'day' && (
                             <div className="space-y-4">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">اختر تاريخاً محدداً</label>
                                <input 
                                   type="date" 
                                   className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-slate-900 font-black text-center"
                                   value={selectedDate}
                                   onChange={(e) => { setSelectedDate(e.target.value); setShowFilterPanel(false); }}
                                />
                             </div>
                           )}

                           {filterMode === 'month' && (
                             <div className="space-y-6">
                                <div className="space-y-2">
                                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">اختر السنة</label>
                                  <select 
                                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black outline-none appearance-none text-center"
                                    value={selectedYear}
                                    onChange={(e) => setSelectedYear(Number(e.target.value))}
                                  >
                                    {[2023, 2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
                                  </select>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                   {months.map((m, idx) => (
                                     <button
                                       key={m}
                                       onClick={() => { setSelectedMonth(idx); setShowFilterPanel(false); }}
                                       className={`p-3 rounded-xl font-black text-[11px] border-2 transition-all ${selectedMonth === idx ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-slate-50 border-transparent text-slate-500 hover:border-slate-200'}`}
                                     >
                                       {m}
                                     </button>
                                   ))}
                                </div>
                             </div>
                           )}

                           {filterMode === 'year' && (
                             <div className="grid grid-cols-2 gap-3">
                                {[2023, 2024, 2025, 2026].map(y => (
                                  <button
                                    key={y}
                                    onClick={() => { setSelectedYear(y); setShowFilterPanel(false); }}
                                    className={`p-6 rounded-2xl font-black text-xl border-2 transition-all ${selectedYear === y ? 'bg-slate-900 border-slate-900 text-white shadow-xl shadow-slate-200' : 'bg-slate-50 border-transparent text-slate-400 hover:border-slate-200'}`}
                                  >
                                    {y}
                                  </button>
                                ))}
                             </div>
                           )}

                           <div className="pt-4 border-t border-slate-100">
                              <button 
                                onClick={() => {
                                  setFilterMode('day');
                                  setSelectedDate(new Date().toISOString().split('T')[0]);
                                  setShowFilterPanel(false);
                                }}
                                className="w-full py-4 bg-emerald-50 text-emerald-600 font-black text-xs rounded-xl hover:bg-emerald-100 transition-all"
                              >
                                العودة لليوم الحالي
                              </button>
                           </div>
                        </div>
                     </div>
                  </>
               )}
            </div>

            {/* Search Input */}
            <div className="relative group flex-1 lg:w-80">
               <SearchIcon className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-slate-900 transition-colors" size={20} />
               <input
                 type="text"
                 placeholder="ابحث برقم العملية..."
                 className="w-full pr-14 pl-6 py-4 bg-white border-2 border-slate-200 rounded-2xl focus:border-slate-900 outline-none font-black shadow-sm transition-all"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
               />
            </div>
         </div>
      </div>

      {/* Invoices List Table */}
      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col flex-1 relative">
        {loading && (
          <div className="absolute inset-0 bg-white/60 backdrop-blur-[1px] z-50 flex flex-col items-center justify-center gap-4">
             <div className="w-12 h-12 border-4 border-slate-100 border-t-emerald-600 rounded-full animate-spin"></div>
             <p className="font-black text-slate-400 text-sm">جاري جلب الفواتير...</p>
          </div>
        )}

        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-900 text-white z-10">
              <tr>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-right">المعرف / التوقيت</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">إجمالي القيمة</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الخصم</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">صافي المدفوع</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الربح</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {invoices.filter(i => i.id.includes(searchTerm)).map(i => (
                <tr key={i.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="p-6">
                    <div className="flex flex-col gap-1">
                       <span className="font-mono text-[10px] text-slate-400">#{i.id.slice(0, 8)}</span>
                       <div className="flex items-center gap-2 text-slate-900 font-black text-sm">
