import React, { useState, useEffect } from 'react';
import { 
  BarChart3, 
  Calendar, 
  ChevronDown, 
  Package, 
  ShoppingCart,
  Zap,
  FileText,
  TrendingUp,
  DollarSign,
  Scissors,
  Wallet,
  CalendarDays,
  PieChart,
  ArrowRightLeft,
  Info,
  ChevronUp,
  History,
  Activity
} from 'lucide-react';
import { supabase } from '../supabase';

const GeneralReports: React.FC = () => {
  const [period, setPeriod] = useState<'day' | 'month' | 'year' | 'custom'>('day');
  const [dateRange, setDateRange] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date().toISOString().split('T')[0] 
  });
  const [loading, setLoading] = useState(true);
  const [expandedSection, setExpandedSection] = useState<'topItems' | 'services' | 'dailySummary' | null>(null);
  const [hoveredTip, setHoveredTip] = useState<string | null>(null);

  const [stats, setStats] = useState({
    grossSales: 0,
    netSales: 0,
    grossWholesale: 0,
    netWholesale: 0,
    grossProfit: 0,
    netProfit: 0,
    totalExpenses: 0,
    totalPurchases: 0,
    itemsSold: 0,
    totalDiscount: 0,
    topItems: [] as any[],
    services: [] as any[],
    dailySummary: [] as any[]
  });

  const fetchData = async () => {
    setLoading(true);
    let start = new Date(dateRange.start + 'T00:00:00Z').toISOString();
    let end = new Date(dateRange.end + 'T23:59:59Z').toISOString();

    const { data: invoices } = await supabase.from('invoices').select('*, invoice_items(*), extra_services(*)').gte('created_at', start).lte('created_at', end);
    const { data: expenses } = await supabase.from('expenses').select('*').gte('date', dateRange.start).lte('date', dateRange.end);
    const { data: purchases } = await supabase.from('purchases').select('*').gte('date', dateRange.start).lte('date', dateRange.end);

    if (invoices) {
      let s = {
        grossSales: 0,
        netSales: 0,
        grossWholesale: 0,
        netWholesale: 0,
        grossProfit: 0,
        totalDiscount: 0,
        itemsSold: 0,
        topItems: [] as any[],
        services: [] as any[],
        dailySummary: [] as any[]
      };

      const itemCounts: Record<string, any> = {};
      const dailyMap: Record<string, any> = {};

      invoices.forEach(inv => {
        const dateKey = new Date(inv.created_at).toLocaleDateString('en-CA');
        if (!dailyMap[dateKey]) {
          dailyMap[dateKey] = { date: dateKey, sales: 0, profit: 0, count: 0 };
        }

        s.grossSales += Number(inv.total_amount);
        s.netSales += Number(inv.net_amount);
        s.grossWholesale += Number(inv.total_cost);
        s.totalDiscount += Number(inv.discount);
        s.grossProfit += Number(inv.profit);

        dailyMap[dateKey].sales += Number(inv.net_amount);
        dailyMap[dateKey].profit += Number(inv.profit);
        dailyMap[dateKey].count += 1;

        inv.invoice_items.forEach((it: any) => {
          s.itemsSold += it.quantity;
          const key = `${it.product_name}-${it.variant_name}`;
          if (!itemCounts[key]) itemCounts[key] = { name: it.product_name, variant: it.variant_name, qty: 0 };
          itemCounts[key].qty += it.quantity;
        });

        inv.extra_services.forEach((ser: any) => {
          s.itemsSold += ser.quantity;
          s.services.push({ ...ser, created_at: inv.created_at });
        });
      });

      const totalExp = expenses?.reduce((sum, e) => sum + Number(e.amount), 0) || 0;
      const totalPur = purchases?.reduce((sum, p) => sum + Number(p.amount), 0) || 0;

      setStats({
        ...s,
        netWholesale: s.grossWholesale, 
        totalExpenses: totalExp,
        totalPurchases: totalPur,
        netProfit: s.grossProfit - totalExp,
        topItems: Object.values(itemCounts).sort((a, b) => b.qty - a.qty).slice(0, 15),
        dailySummary: Object.values(dailyMap).sort((a, b) => b.date.localeCompare(a.date))
      });
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, [dateRange]);

  const handlePeriodChange = (p: typeof period) => {
    setPeriod(p);
    const now = new Date();
    if (p === 'day') {
      const d = now.toISOString().split('T')[0];
      setDateRange({ start: d, end: d });
    } else if (p === 'month') {
      const start = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
      const end = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
      setDateRange({ start, end });
    } else if (p === 'year') {
      const start = new Date(now.getFullYear(), 0, 1).toISOString().split('T')[0];
      const end = new Date(now.getFullYear(), 11, 31).toISOString().split('T')[0];
      setDateRange({ start, end });
    }
  };

  const toggleSection = (section: typeof expandedSection) => {
    setExpandedSection(expandedSection === section ? null : section);
  };

  const Tooltip = ({ text }: { text: string }) => (
    <div className="absolute bottom-full mb-3 left-1/2 -translate-x-1/2 w-48 p-3 bg-black text-white text-[10px] font-bold rounded-xl shadow-2xl z-50 animate-in fade-in zoom-in duration-200">
      {text}
      <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-black"></div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-50 p-6 space-y-8 overflow-y-auto custom-scrollbar font-['Tajawal']" dir="rtl">

      {/* 1. Royal Header with Floating Date Picker */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-[#0f172a] p-10 rounded-[3rem] shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-emerald-500/5 rounded-full blur-[100px] -translate-y-1/2 translate-x-1/3"></div>

        <div className="flex items-center gap-8 relative z-10">
          <div className="p-5 bg-emerald-600 rounded-[2rem] shadow-2xl shadow-emerald-900/40 text-white flex items-center justify-center">
            <PieChart size={40} />
          </div>
          <div>
            <h2 className="text-4xl font-black text-white tracking-tight">التقارير المالية والذكاء المالي</h2>
            <div className="flex items-center gap-3 mt-1">
               <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
               <p className="text-slate-400 font-bold text-xs uppercase tracking-[0.2em]">Flyyti POS Intelligence System</p>
            </div>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row items-center gap-5 w-full lg:w-auto relative z-10">
          <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/10 w-full sm:w-auto backdrop-blur-md">
            {['day', 'month', 'year', 'custom'].map((p: any) => (
              <button 
                key={p} 
                onClick={() => handlePeriodChange(p)}
                className={`flex-1 px-8 py-3 rounded-xl text-xs font-black transition-all ${period === p ? 'bg-emerald-600 text-white shadow-xl' : 'text-slate-400 hover:text-white'}`}
              >
