import React, { useState, useEffect } from 'react';
import { 
  BarChart3, 
  Calendar, 
  ChevronDown, 
  Package, 
  ShoppingCart,
  Zap,
  FileText,
  TrendingUp,
  DollarSign,
  Scissors,
  Wallet,
  CalendarDays,
  PieChart,
  ArrowRightLeft,
  Info,
  ChevronUp,
  History,
  Activity
} from 'lucide-react';
import { supabase } from '../supabase';

const GeneralReports: React.FC = () => {
  const [period, setPeriod] = useState<'day' | 'month' | 'year' | 'custom'>('day');
  const [dateRange, setDateRange] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date().toISOString().split('T')[0] 
  });
  const [loading, setLoading] = useState(true);
  const [expandedSection, setExpandedSection] = useState<'topItems' | 'services' | 'dailySummary' | null>(null);
  const [hoveredTip, setHoveredTip] = useState<string | null>(null);

  const [stats, setStats] = useState({
    grossSales: 0,
    netSales: 0,
    grossWholesale: 0,
    netWholesale: 0,
    grossProfit: 0,
    netProfit: 0,
    totalExpenses: 0,
    totalPurchases: 0,
    itemsSold: 0,
    totalDiscount: 0,
    topItems: [] as any[],
    services: [] as any[],
    dailySummary: [] as any[]
  });

  const fetchData = async () => {
    setLoading(true);
    let start = new Date(dateRange.start + 'T00:00:00Z').toISOString();
    let end = new Date(dateRange.end + 'T23:59:59Z').toISOString();

    const { data: invoices } = await supabase.from('invoices').select('*, invoice_items(*), extra_services(*)').gte('created_at', start).lte('created_at', end);
    const { data: expenses } = await supabase.from('expenses').select('*').gte('date', dateRange.start).lte('date', dateRange.end);
    const { data: purchases } = await supabase.from('purchases').select('*').gte('date', dateRange.start).lte('date', dateRange.end);

    const totalExp = expenses?.reduce((sum, e) => sum + Number(e.amount), 0) || 0;
    const totalPur = purchases?.reduce((sum, p) => sum + Number(p.amount), 0) || 0;

    if (invoices) {
      let productSales = 0;
      let productCost = 0;
      let extraServiceProfit = 0;
      let totalDiscount = 0;
      let itemsSold = 0;
      const itemCounts: Record<string, any> = {};
      const dailyMap: Record<string, any> = {};

      invoices.forEach(inv => {
        const dateKey = new Date(inv.created_at).toLocaleDateString('en-CA');
        if (!dailyMap[dateKey]) {
          dailyMap[dateKey] = { date: dateKey, sales: 0, profit: 0, count: 0 };
        }

        totalDiscount += Number(inv.discount);

        // Calculate Products Only
        inv.invoice_items.forEach((it: any) => {
          itemsSold += it.quantity;
          productSales += (it.sale_price * it.quantity);
          productCost += (it.cost_price * it.quantity);

          const key = `${it.product_name}-${it.variant_name}`;
          if (!itemCounts[key]) itemCounts[key] = { name: it.product_name, variant: it.variant_name, qty: 0 };
          itemCounts[key].qty += it.quantity;
        });

        // Calculate Extra Services Profit Only
        inv.extra_services.forEach((ser: any) => {
          itemsSold += ser.quantity;
          const serviceProfit = (ser.sale_price - ser.cost_price) * ser.quantity;
          extraServiceProfit += serviceProfit;
        });
      });

      // Apply New Formulas
      const grossSales = (productSales - totalDiscount) + extraServiceProfit;
      const netSales = grossSales - totalExp - totalPur;
      const grossWholesale = productCost;
      const netWholesale = grossWholesale - totalPur;
      const grossProfit = (productSales - productCost - totalDiscount) + extraServiceProfit;
      const netProfit = grossProfit - totalExp;

      setStats({
        grossSales,
        netSales,
        grossWholesale,
        netWholesale,
        grossProfit,
        netProfit,
        totalExpenses: totalExp,
        totalPurchases: totalPur,
        itemsSold,
        totalDiscount,
        topItems: Object.values(itemCounts).sort((a, b) => b.qty - a.qty).slice(0, 15),
        dailySummary: Object.values(dailyMap).sort((a, b) => b.date.localeCompare(a.date)),
        services: invoices.flatMap(inv => inv.extra_services.map((s: any) => ({ ...s, created_at: inv.created_at })))
      });
    }
    setLoading(false);
  };

