  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (invoices) {
      let productSales = 0;
      let productCost = 0;
      let extraServiceProfit = 0;
      let totalDiscounts = 0;
      let itemsCount = 0;

      invoices.forEach(inv => {
        totalDiscounts += Number(inv.discount);

        inv.invoice_items.forEach((item: any) => { 
          itemsCount += item.quantity; 
          productSales += (item.sale_price * item.quantity);
          productCost += (item.cost_price * item.quantity);
        });

        inv.extra_services.forEach((ser: any) => { 
          itemsCount += ser.quantity; 
          extraServiceProfit += (ser.sale_price - ser.cost_price) * ser.quantity;
        });
      });

      // Unified Logic
      const totalSales = (productSales - totalDiscounts) + extraServiceProfit;
      const totalProfit = (productSales - productCost - totalDiscounts) + extraServiceProfit;

      setData({
        totalSales,
        totalCost: productCost,
        totalProfit,
        itemsCount,
        discounts: totalDiscounts,
        invoices: invoices
      });
    }
    setLoading(false);
  };

  const fetchAllProducts = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    if (prods) {
      const flattened = prods.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
      })));
      setAllProducts(flattened);
    }
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchAllProducts();
  }, [selectedDay]);

  const handleDeleteInvoice = async (invoice: any) => {
    if (!confirm("هل أنت متأكد من حذف هذه الفاتورة نهائياً؟ سيتم إعادة الكميات للمخزون.")) return;
    try {
      for (const item of invoice.invoice_items) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
      }
      await supabase.from('invoices').delete().eq('id', invoice.id);
      fetchDailyData(selectedDay);
    } catch (e) { alert("خطأ في الحذف"); }
  };

  const handleUpdateInvoice = async () => {
    if (!editingInvoice) return;
    try {
      const subtotal = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                       editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
      const net = Math.max(0, subtotal - editingInvoice.discount);
      const newCost = editingInvoice.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                      editingInvoice.extra_services.reduce((sum: number, s: any) => sum + (s.cost_price * s.quantity), 0);

      await supabase.from('invoices').update({
        total_amount: subtotal, discount: editingInvoice.discount, net_amount: net, total_cost: newCost, profit: net - newCost
      }).eq('id', editingInvoice.id);

      setEditingInvoice(null);
      fetchDailyData(selectedDay);
    } catch (e) { alert("خطأ في التحديث"); }
  };

  const Tooltip = ({ title, formula }: { title: string, formula: string }) => (
    <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 w-48 p-3 bg-[#0f172a] text-white rounded-xl shadow-2xl z-50 animate-in fade-in zoom-in duration-200 border border-emerald-500/30">
      <p className="text-[8px] font-black text-emerald-400 uppercase tracking-widest mb-1">{title}</p>
      <p className="text-[9px] font-bold leading-relaxed opacity-90">{formula}</p>
      <div className="absolute top-full left-1/2 -translate-x-1/2 border-[6px] border-transparent border-t-[#0f172a]"></div>
    </div>
  );

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  const allSoldItems = data.invoices.flatMap(inv => 
    inv.invoice_items.map((it: any) => ({ ...it, type: 'product' }))
    .concat(inv.extra_services.map((ser: any) => ({ ...ser, type: 'service', product_name: ser.name, variant_name: 'خدمة إضافية' })))
  );

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-4 space-y-4 overflow-hidden" dir="rtl">

      {/* 1. Header */}
      <div className="flex items-center justify-between shrink-0">
        <h2 className="text-lg font-black text-[#0f172a] flex items-center gap-2">
           <History className="text-emerald-600" size={20} />
           التقارير اليومية
        </h2>

        <div className="relative">
          <button onClick={() => setShowDayPicker(!showDayPicker)} className="flex items-center gap-2 bg-[#0f172a] text-white px-4 py-2 rounded-xl shadow-lg font-black text-xs">
            <Calendar size={14} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={14} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-12 left-0 w-56 bg-white rounded-2xl shadow-2xl border border-slate-200 p-3 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-7 h-7 rounded-lg flex items-center justify-center font-bold text-[10px] ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Stats Cards with Privacy Shield & Tooltips */}
      <div className="relative shrink-0 overflow-hidden rounded-2xl">
        <div className={`grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-3 transition-all duration-500 ${!showFinancials ? 'blur-md grayscale opacity-40 select-none pointer-events-none' : ''}`}>
          {[
            { id: 'sales', label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50', formula: 'المبيعات = (بيع المنتجات - الخصم) + (ربح الخدمات)' },
            { id: 'cost', label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50', formula: 'مجموع جملة تكلفة المنتجات فقط' },
            { id: 'profit', label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50', formula: 'صافي الربح = (ربح المنتجات - الخصم) + (ربح الخدمات)' },
            { id: 'items', label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50', formula: 'عدد القطع والخدمات المباعة' },
            { id: 'discounts', label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'text-rose-600', bg: 'bg-rose-50', formula: 'مجموع الخصومات الممنوحة' }
          ].map((stat) => (
            <div key={stat.id} className="p-3.5 bg-white rounded-xl border border-slate-200 shadow-sm flex flex-col gap-2 relative group">
              <div className="flex justify-between items-start">
                <div className={`p-1.5 rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={16} /></div>
                <div className="relative">
                  <Info size={12} className="text-slate-300 hover:text-[#0f172a] cursor-help" onMouseEnter={() => setHoveredTip(stat.id)} onMouseLeave={() => setHoveredTip(null)} />
                  {hoveredTip === stat.id && <Tooltip title={stat.label} formula={stat.formula} />}
                </div>
              </div>
              <div>
                <p className="text-[8px] font-black uppercase opacity-60 mb-0.5">{stat.label}</p>
                <p className="text-base font-black truncate">{stat.value.toFixed(2)} ₪</p>
              </div>
            </div>
          ))}
        </div>

        {!showFinancials && (
          <div className="absolute inset-0 z-20 flex items-center justify-center">
            <div className="absolute inset-0 bg-white/40 backdrop-blur-[2px]" />
            <button onClick={() => setShowFinancials(true)} className="relative z-30 flex flex-col items-center gap-1.5 bg-[#0f172a] text-white px-6 py-3 rounded-2xl shadow-2xl hover:bg-slate-800 transition-all">
              <Eye size={20} className="text-emerald-500" />
              <span className="text-[9px] font-black uppercase tracking-widest">كشف البيانات المالية</span>
            </button>
          </div>
        )}

        {showFinancials && (
          <button onClick={() => setShowFinancials(false)} className="absolute top-1 left-1 z-30 p-1.5 text-slate-400 hover:text-rose-500 transition-all">
            <EyeOff size={14} />
          </button>
        )}
      </div>

      {/* 3. Collapsible Sections */}
      <div className="flex-1 flex flex-col gap-3 overflow-hidden">
        <div className={`flex flex-col bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'transactions' ? 'flex-1' : 'h-14'}`}>
          <button onClick={() => setExpandedSection(expandedSection === 'transactions' ? null : 'transactions')} className="p-4 flex items-center justify-between hover:bg-slate-50 shrink-0">
            <div className="flex items-center gap-3"><History size={16} className="text-emerald-600" /><h3 className="font-black text-[#0f172a] text-xs">حركة الأصناف اليوم</h3></div>
            <ChevronDown size={16} className={`text-slate-400 transition-transform ${expandedSection === 'transactions' ? 'rotate-180' : ''}`} />
          </button>
          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <table className="w-full text-right"><thead className="sticky top-0 bg-slate-50"><tr className="text-[9px] font-black text-slate-400 uppercase tracking-widest"><th className="p-3">الصنف</th><th className="p-3 text-center">الكمية</th><th className="p-3 text-center">البيع</th><th className="p-3 text-left">الربح</th></tr></thead>
              <tbody className="divide-y divide-slate-100">{allSoldItems.map((item, i) => (<tr key={i} className="hover:bg-slate-50/50"><td className="p-3"><span className="font-black text-slate-900 text-[11px] block">{item.product_name}</span><span className="text-[8px] text-slate-400 font-bold">{item.variant_name}</span></td><td className="p-3 text-center font-black text-xs">{item.quantity}</td><td className="p-3 text-center font-black text-xs">{item.sale_price}</td><td className="p-3 text-left font-black text-emerald-600 text-xs">{(item.sale_price - item.cost_price) * item.quantity}</td></tr>))}</tbody>
            </table>
          </div>
        </div>

        <div className={`flex flex-col bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden transition-all duration-300 ${expandedSection === 'invoices' ? 'flex-1' : 'h-14'}`}>
          <button onClick={() => setExpandedSection(expandedSection === 'invoices' ? null : 'invoices')} className="p-4 flex items-center justify-between hover:bg-slate-50 shrink-0">
            <div className="flex items-center gap-3"><FileText size={16} className="text-blue-600" /><h3 className="font-black text-[#0f172a] text-xs">سجل الفواتير الصادرة</h3></div>
            <ChevronDown size={16} className={`text-slate-400 transition-transform ${expandedSection === 'invoices' ? 'rotate-180' : ''}`} />
          </button>
          <div className="flex-1 overflow-y-auto custom-scrollbar p-3 grid grid-cols-1 md:grid-cols-2 gap-3">
            {data.invoices.map((inv) => (
              <div key={inv.id} className="bg-slate-50 border border-slate-200 rounded-xl p-3 flex flex-col gap-2 border-r-4 border-r-blue-500">
                <div className="flex justify-between items-start">
                  <div><p className="font-mono text-[9px] text-slate-400">#{inv.id.slice(0, 8)}</p><p className="font-black text-[10px] text-slate-700">{new Date(inv.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</p></div>
                  <div className="flex gap-1.5"><button onClick={() => setEditingInvoice(inv)} className="p-1.5 bg-blue-100 text-blue-600 rounded-lg"><Edit2 size={12} /></button><button onClick={() => handleDeleteInvoice(inv)} className="p-1.5 bg-rose-100 text-rose-600 rounded-lg"><Trash2 size={12} /></button></div>
                </div>
                <div className="flex justify-between items-center mt-auto pt-1.5 border-t border-slate-200">
                  <span className="text-[10px] font-black text-slate-500">الصافي</span>
                  <span className="font-black text-emerald-600 text-sm">{inv.net_amount} ₪</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default DailyReports;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Edit3, 
  Trash2, 
  Tag, 
  ChevronLeft, 
  X, 
  FolderTree, 
  Layers, 
  LayoutGrid,
  Loader2,
  AlertCircle,
  CheckCircle2,
  Copy,
  CheckSquare,
  Square,
  AlertTriangle,
  PlusCircle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category } from '../types';

const Categories: React.FC = () => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainId, setSelectedMainId] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Delete Confirmation State
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const [form, setForm] = useState({ 
    name: '', 
    parent_id: null as string | null 
  });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('categories').select('*').order('name');
      if (error) throw error;
      setCategories(data || []);

      if (data && data.length > 0 && !selectedMainId) {
        const firstMain = data.find(c => !c.parent_id);
        if (firstMain) setSelectedMainId(firstMain.id);
      }
    } catch (err) {
      console.error(err);
      showToast("خطأ في تحميل الأقسام", "error");
    } finally {
      setLoading(false);
    }
  };

  const mainCategories = useMemo(() => categories.filter(c => !c.parent_id), [categories]);
  const subCategories = useMemo(() => categories.filter(c => c.parent_id === selectedMainId), [categories, selectedMainId]);

  const handleOpenAdd = (parentId: string | null = null) => {
    setModalMode('add');
    setEditingId(null);
    setForm({ name: '', parent_id: parentId });
    setShowAddModal(true);
  };

  const handleOpenEdit = (e: React.MouseEvent, cat: Category) => {
    e.stopPropagation();
    setModalMode('edit');
    setEditingId(cat.id);
    setForm({ name: cat.name, parent_id: cat.parent_id });
    setShowAddModal(true);
  };

  const handleSave = async () => {
    if (!form.name || saving) return;
    setSaving(true);
    try {
      if (modalMode === 'add') {
        const { error } = await supabase.from('categories').insert(form);
        if (error) throw error;
        showToast("تم إضافة القسم بنجاح");
      } else {
        const { error } = await supabase.from('categories').update({ name: form.name, parent_id: form.parent_id }).eq('id', editingId);
        if (error) throw error;
        showToast("تم تحديث البيانات");
      }
      setShowAddModal(false);
      fetchCategories();
    } catch (err) {
      console.error(err);
      showToast("فشل الحفظ", "error");
    } finally {
      setSaving(false);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, cat: Category) => {
    e.stopPropagation();
    try {
      const { error } = await supabase.from('categories').insert({
        name: `${cat.name} (نسخة)`,
        parent_id: cat.parent_id
      });
      if (error) throw error;
      showToast("تم تكرار القسم بنجاح");
      fetchCategories();
    } catch (err) {
      console.error(err);
      showToast("خطأ في التكرار", "error");
    }
  };

  const requestDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setDeleteId(id);
    setShowDeleteModal(true);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      const { error } = await supabase.from('categories').delete().eq('id', deleteId);
      if (error) throw error;
      showToast("تم الحذف بنجاح");
      if (selectedMainId === deleteId) setSelectedMainId(null);
      setSelectedIds(prev => prev.filter(sid => sid !== deleteId));
      fetchCategories();
    } catch (err) {
      console.error(err);
      showToast("فشل الحذف", "error");
    } finally {
      setShowDeleteModal(false);
      setDeleteId(null);
    }
  };

  const handleBulkDelete = async () => {
    if (selectedIds.length === 0) return;
    setLoading(true);
    try {
      const { error } = await supabase.from('categories').delete().in('id', selectedIds);
      if (error) throw error;
      showToast(`تم حذف ${selectedIds.length} أقسام بنجاح`);
      setSelectedIds([]);
      fetchCategories();
    } catch (err) {
      console.error(err);
      showToast("خطأ في الحذف الجماعي", "error");
    } finally {
      setLoading(false);
      setShowDeleteModal(false);
    }
  };

  const toggleSelect = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  return (
    <div className="h-full flex flex-col space-y-6 overflow-hidden relative font-['Tajawal']" dir="rtl">
      {/* Toast Notification */}
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[300] flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl animate-in slide-in-from-top-10 duration-300 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-rose-600 border-rose-500 text-white'}`}>
          {toast.type === 'success' ? <CheckCircle2 size={24} /> : <AlertTriangle size={24} />}
          <span className="font-black text-sm">{toast.message}</span>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-4 pt-4">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <FolderTree className="text-slate-900" />
          إدارة الأقسام
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button 
              onClick={() => { setDeleteId(null); setShowDeleteModal(true); }}
              className="flex-1 md:flex-none px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg animate-in zoom-in"
            >
              <Trash2 size={20} />
              <span>حذف المحددة ({selectedIds.length})</span>
            </button>
          )}
        </div>
      </div>

      {loading ? (
        <div className="flex-1 flex flex-col items-center justify-center gap-4">
          <Loader2 className="animate-spin text-slate-900" size={40} />
          <p className="font-black text-slate-400">جاري تحميل الهيكلية...</p>
        </div>
      ) : (
        <div className="flex-1 flex flex-col lg:flex-row gap-6 overflow-hidden pb-4 px-4">

          {/* Column 1: Main Categories */}
          <div className="flex flex-col w-full lg:w-1/3 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex-shrink-0">
            <div className="p-5 bg-slate-900 border-b border-slate-800 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-3">
                <LayoutGrid size={20} className="text-emerald-500" />
                <h3 className="font-black text-white text-sm uppercase tracking-tight">الأقسام الرئيسية</h3>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => {
                    const allMainIds = mainCategories.map(c => c.id);
                    const isAllSelected = allMainIds.every(id => selectedIds.includes(id));
                    if (isAllSelected) setSelectedIds(prev => prev.filter(id => !allMainIds.includes(id)));
                    else setSelectedIds(prev => Array.from(new Set([...prev, ...allMainIds])));
                  }}
                  className="text-[10px] font-black text-emerald-500 uppercase hover:text-emerald-400"
                >
                  تحديد الكل
                </button>
                <button 
                  onClick={() => handleOpenAdd(null)}
                  className="p-2 bg-emerald-600 text-white rounded-xl hover:bg-emerald-500 transition-all shadow-lg shadow-emerald-900/40"
                  title="إضافة قسم رئيسي"
                >
                  <Plus size={18} />
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2">
              {mainCategories.map(main => (
                <div
                  key={main.id}
                  onClick={() => setSelectedMainId(main.id)}
                  className={`group relative p-4 rounded-2xl flex items-center justify-between transition-all duration-300 border-2 cursor-pointer ${selectedMainId === main.id ? 'bg-slate-900 border-slate-900 text-white shadow-xl shadow-slate-200 translate-x-1' : 'bg-white border-slate-100 hover:bg-slate-50 text-slate-600'}`}
                >
                  <div className="flex items-center gap-3">
                    <button 
                      onClick={(e) => toggleSelect(e, main.id)}
                      className={`transition-all ${selectedIds.includes(main.id) ? 'text-emerald-500' : (selectedMainId === main.id ? 'text-slate-400' : 'text-slate-300')}`}
                    >
                      {selectedIds.includes(main.id) ? <CheckSquare size={18} /> : <Square size={18} />}
                    </button>
                    <span className="font-black text-sm">{main.name}</span>
                  </div>
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={(e) => handleDuplicate(e, main)} className={`p-2 rounded-lg ${selectedMainId === main.id ? 'hover:bg-slate-800' : 'hover:bg-slate-200'}`} title="تكرار"><Copy size={14} /></button>
                    <button onClick={(e) => handleOpenEdit(e, main)} className={`p-2 rounded-lg ${selectedMainId === main.id ? 'hover:bg-slate-800' : 'hover:bg-slate-200'}`} title="تعديل"><Edit3 size={14} /></button>
                    <button onClick={(e) => requestDelete(e, main.id)} className={`p-2 rounded-lg ${selectedMainId === main.id ? 'hover:bg-rose-500' : 'hover:bg-rose-50 text-rose-500'}`} title="حذف"><Trash2 size={14} /></button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Column 2: Sub Categories */}
          <div className="flex flex-col flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden min-w-0">
            <div className="p-5 bg-slate-900 border-b border-slate-800 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-3">
                <Layers size={20} className="text-emerald-500" />
                <h3 className="font-black text-white text-sm uppercase tracking-tight">
                  {selectedMainId ? `الأقسام الفرعية لـ (${mainCategories.find(c => c.id === selectedMainId)?.name})` : 'الأقسام الفرعية'}
                </h3>
              </div>
              <div className="flex items-center gap-3">
                {subCategories.length > 0 && (
                  <button 
                    onClick={() => {
                      const allSubIds = subCategories.map(c => c.id);
                      const isAllSelected = allSubIds.every(id => selectedIds.includes(id));
                      if (isAllSelected) setSelectedIds(prev => prev.filter(id => !allSubIds.includes(id)));
                      else setSelectedIds(prev => Array.from(new Set([...prev, ...allSubIds])));
                    }}
                    className="text-[10px] font-black text-emerald-500 uppercase hover:text-emerald-400"
                  >
                    تحديد الكل
                  </button>
                )}
                {selectedMainId && (
                  <button 
                    onClick={() => handleOpenAdd(selectedMainId)}
                    className="p-2 bg-emerald-600 text-white rounded-xl hover:bg-emerald-500 transition-all shadow-lg shadow-emerald-900/40"
                    title="إضافة قسم فرعي"
                  >
                    <Plus size={18} />
                  </button>
                )}
              </div>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50/30">
              {selectedMainId && subCategories.length > 0 && (
                <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 animate-in fade-in duration-300">
                  {subCategories.map(sub => (
                    <div 
                      key={sub.id} 
                      onClick={(e) => toggleSelect(e, sub.id)}
                      className={`group p-5 rounded-3xl border-2 transition-all shadow-sm flex flex-col gap-4 cursor-pointer relative ${selectedIds.includes(sub.id) ? 'bg-slate-900 border-slate-900 text-white shadow-xl shadow-slate-200' : 'bg-white border-slate-100 hover:border-emerald-500 hover:shadow-md'}`}
                    >
                      <div className="flex justify-between items-start">
                        <div className={`p-3 rounded-2xl border transition-all ${selectedIds.includes(sub.id) ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-slate-50 border-slate-200 text-slate-900 shadow-sm'}`}>
                          {selectedIds.includes(sub.id) ? <CheckSquare size={20} /> : <Tag size={20} />}
                        </div>
                        <div className="flex gap-1">
                          <button onClick={(e) => handleDuplicate(e, sub)} className="p-2 text-slate-400 hover:text-slate-900 bg-slate-50 rounded-xl border border-slate-100 shadow-sm" title="تكرار"><Copy size={16} /></button>
                          <button onClick={(e) => handleOpenEdit(e, sub)} className="p-2 text-slate-400 hover:text-emerald-600 bg-slate-50 rounded-xl border border-slate-100 shadow-sm" title="تعديل"><Edit3 size={16} /></button>
                          <button onClick={(e) => requestDelete(e, sub.id)} className="p-2 text-slate-400 hover:text-rose-600 bg-slate-50 rounded-xl border border-slate-100 shadow-sm" title="حذف"><Trash2 size={16} /></button>
                        </div>
                      </div>
                      <p className={`font-black text-lg ${selectedIds.includes(sub.id) ? 'text-white' : 'text-slate-900'}`}>{sub.name}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteModal && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center z-[400] p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-sm overflow-hidden p-8 space-y-6 border border-slate-200 animate-in zoom-in-95 duration-200">
             <div className="flex flex-col items-center gap-4 text-center">
                <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center shadow-inner">
                   <AlertTriangle size={40} />
                </div>
                <div>
                   <h3 className="text-xl font-black text-slate-900">تأكيد عملية الحذف</h3>
                   <p className="text-slate-500 text-sm mt-2 font-bold leading-relaxed">
                     {deleteId ? 'هل أنت متأكد من حذف هذا القسم نهائياً؟ سيتم حذف كافة التفرعات والأصناف المرتبطة به.' : `هل أنت متأكد من حذف ${selectedIds.length} أقسام مختارة؟`}
                   </p>
                </div>
             </div>
             <div className="flex gap-3">
                <button 
                  onClick={deleteId ? confirmDelete : handleBulkDelete}
                  className="flex-1 py-4 bg-rose-500 text-white font-black rounded-2xl shadow-lg active:scale-95 transition-all"
                >
                  نعم، حذف
                </button>
                <button 
                  onClick={() => setShowDeleteModal(false)}
                  className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl active:scale-95 transition-all"
                >
                  إلغاء
                </button>
             </div>
          </div>
        </div>
      )}

      {/* Modal: Add/Edit Category */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center z-[200] p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200 border border-white/20">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-900 text-white">
               <div className="flex items-center gap-4">
                  <div className={`p-4 rounded-2xl shadow-xl bg-emerald-600 text-white`}>
                    {modalMode === 'add' ? <Plus size={24} /> : <Edit3 size={24} />}
                  </div>
                  <h3 className="text-xl font-black">
                    {modalMode === 'add' ? (form.parent_id ? 'إضافة قسم فرعي' : 'إضافة قسم رئيسي') : 'تعديل بيانات القسم'}
                  </h3>
               </div>
               <button onClick={() => setShowAddModal(false)} className="p-2 text-slate-400 hover:text-white"><X size={24} /></button>
            </div>

            <div className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم القسم</label>
                <input 
                  autoFocus
                  type="text" 
                  placeholder="مثال: مشروبات، ملابس، خدمات..."
                  className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-slate-900 font-black transition-all" 
                  value={form.name}
                  onChange={(e) => setForm({...form, name: e.target.value})}
                />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الأب (الرئيسي)</label>
                <div className="relative">
                  <select 
                    className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black outline-none focus:border-slate-900 transition-all appearance-none"
                    value={form.parent_id || ''}
                    onChange={(e) => setForm({...form, parent_id: e.target.value || null})}
                  >
                    <option value="">-- بدون (سيصبح قسماً رئيسياً) --</option>
                    {mainCategories.filter(c => c.id !== editingId).map(c => (
                      <option key={c.id} value={c.id}>{c.name}</option>
                    ))}
                  </select>
                  <ChevronLeft className="absolute left-4 top-1/2 -translate-y-1/2 -rotate-90 text-slate-400 pointer-events-none" size={18} />
                </div>
              </div>

              <div className="pt-4">
                <button 
                  onClick={handleSave}
                  disabled={!form.name || saving}
                  className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-2xl shadow-emerald-900/20 hover:bg-emerald-700 active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                >
                  {saving ? <Loader2 className="animate-spin" size={24} /> : modalMode === 'add' ? 'حفظ القسم الجديد' : 'تحديث البيانات'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Categories;

import React, { useState, useEffect } from 'react';
import { 
  Plus, 
  Wallet, 
  ShoppingCart, 
  Trash2, 
  Calendar, 
  FileText, 
  X, 
  TrendingUp, 
  Edit2, 
  Save, 
  PieChart, 
  Percent,
  PlusCircle,
  Loader2,
  AlertTriangle,
  Receipt
} from 'lucide-react';
import { supabase } from '../supabase';
import type { AppSettings } from '../types';

interface Props {
  settings: AppSettings | null;
  onUpdateSettings: () => void;
}

const Expenses: React.FC<Props> = ({ settings, onUpdateSettings }) => {
  const [activeTab, setActiveTab] = useState<'expenses' | 'purchases'>('expenses');
  const [expenses, setExpenses] = useState<any[]>([]);
  const [purchases, setPurchases] = useState<any[]>([]);
  const [invoices, setInvoices] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [editMode, setEditMode] = useState<'capital' | 'shares' | null>(null);
  const [tempSettings, setTempSettings] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // Delete Confirmation State
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, table: string} | null>(null);

  const [form, setForm] = useState({
    type: '',
    amount: 0,
    supplier: '',
    note: '',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    const { data: ex } = await supabase.from('expenses').select('*').order('date', { ascending: false });
    const { data: pu } = await supabase.from('purchases').select('*').order('date', { ascending: false });
    const { data: inv } = await supabase.from('invoices').select('profit');
    setExpenses(ex || []);
    setPurchases(pu || []);
    setInvoices(inv || []);
    setLoading(false);
  };

  const handleSave = async () => {
    if (activeTab === 'expenses') {
      await supabase.from('expenses').insert({
        type: form.type,
        amount: form.amount,
        date: form.date,
        note: form.note
      });
    } else {
      await supabase.from('purchases').insert({
        amount: form.amount,
        supplier: form.supplier,
        date: form.date,
        note: form.note
      });
    }
    setShowModal(false);
    setForm({ type: '', amount: 0, supplier: '', note: '', date: new Date().toISOString().split('T')[0] });
    fetchData();
  };

  const requestDelete = (id: string, table: string) => {
    setDeleteTarget({ id, table });
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    await supabase.from(deleteTarget.table).delete().eq('id', deleteTarget.id);
    setShowDeleteConfirm(false);
    setDeleteTarget(null);
    fetchData();
  };

  const handleUpdateGlobalSettings = async () => {
    const { error } = await supabase
      .from('settings')
      .update(tempSettings)
      .eq('id', 1);

    if (!error) {
      onUpdateSettings();
      setEditMode(null);
    }
  };

  const totalInvoicesProfit = invoices.reduce((s, i) => s + Number(i.profit), 0);
  const netProfit = totalInvoicesProfit; 

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-8 overflow-y-auto custom-scrollbar font-['Tajawal']" dir="rtl">

      {/* 1. Dashboard Header */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 shrink-0">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-32 h-32 bg-slate-900/5 rounded-full -translate-y-16 translate-x-16"></div>
          <div className="flex justify-between items-start relative">
            <div className="flex items-center gap-4">
               <div className="p-4 bg-slate-900 text-white rounded-2xl shadow-xl shadow-slate-200"><TrendingUp size={24} /></div>
               <div>
                  <h3 className="text-xl font-black text-slate-900 tracking-tight">الوضع المالي العام</h3>
                  <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">Flyyti Finance Control</p>
               </div>
            </div>
            <button 
              onClick={() => { setEditMode('capital'); setTempSettings({ capital: settings?.capital, savings: settings?.savings }); }}
              className="p-3 text-slate-400 hover:text-slate-900 bg-slate-50 rounded-xl transition-all"
            >
              <Edit2 size={18} />
            </button>
          </div>

          <div className="grid grid-cols-3 gap-6 mt-10 relative">
            <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">رأس المال</p>
              <p className="text-xl font-black text-slate-900">{settings?.capital} <span className="text-xs">₪</span></p>
            </div>
            <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">الادخار</p>
              <p className="text-xl font-black text-slate-900">{settings?.savings} <span className="text-xs">₪</span></p>
            </div>
            <div className="p-5 bg-emerald-50 rounded-2xl border border-emerald-100">
              <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-2">إجمالي الربح</p>
              <p className="text-xl font-black text-emerald-600">{netProfit.toFixed(2)} <span className="text-xs">₪</span></p>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm">
          <div className="flex justify-between items-start">
            <div className="flex items-center gap-4">
               <div className="p-4 bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-100"><PieChart size={24} /></div>
               <div>
                  <h3 className="text-xl font-black text-slate-900 tracking-tight">توزيع الأرباح والنسب</h3>
                  <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">Profit Share Calculations</p>
