              <div className="space-y-2"><label className="text-xs font-black text-slate-500 mr-1 uppercase tracking-widest px-1">ملاحظات إضافية</label><textarea className="w-full p-5 bg-white border-2 border-slate-100 rounded-2xl outline-none focus:border-slate-900 font-bold min-h-[120px] resize-none" placeholder="أدخل أي تفاصيل إضافية هنا..." value={form.note} onChange={(e) => setForm({...form, note: e.target.value})} /></div>
              <div className="pt-4"><button onClick={handleSave} className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-700 active:scale-95 transition-all flex items-center justify-center gap-3"><Save size={24} />حفظ البيانات</button></div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

