    printWindow.document.write(`<html dir="rtl"><head><title>فاتورة #${invoice.id.slice(0,8)}</title><style>body { font-family: 'Tajawal', sans-serif; padding: 20px; width: 80mm; margin: 0 auto; } h2 { text-align: center; margin-bottom: 10px; } table { width: 100%; border-collapse: collapse; margin-top: 15px; font-size: 12px; } .total-row { font-weight: bold; border-top: 2px solid #000; } .center { text-align: center; } .right { text-align: right; } .left { text-align: left; } </style></head><body><h2>Flyyti Mobile POS</h2><p class="center">فاتورة مبيعات</p><p>الرقم: #${invoice.id.slice(0,8)}</p><p>التاريخ: ${new Date(invoice.created_at).toLocaleString('ar-EG')}</p><hr/><table><thead><tr><th class="right">الصنف</th><th class="center">الكمية</th><th class="left">السعر</th></tr></thead><tbody>${itemsHtml}${servicesHtml}</tbody></table><div style="margin-top: 20px; border-top: 1px solid #000; padding-top: 10px;"><p>الإجمالي: ${invoice.total_amount} ₪</p><p>الخصم: ${invoice.discount} ₪</p><h3 style="border-top: 2px solid #000; padding-top: 5px;">الصافي: ${invoice.net_amount} ₪</h3></div><p class="center" style="margin-top: 30px; font-size: 10px;">شكراً لزيارتكم!</p><script>window.onload = function() { window.print(); window.close(); };</script></body></html>`);
    printWindow.document.close();
