         <div className="flex items-center gap-4">
            <div className="p-4 bg-slate-900 text-white rounded-2xl shadow-xl shadow-slate-200"><FileText size={24} /></div>
            <div>
               <h2 className="text-2xl font-black text-slate-900 tracking-tight">سجل الفواتير</h2>
               <p className="text-slate-400 font-bold text-xs uppercase mt-1 tracking-widest">مراجعة وإدارة كافة العمليات الصادرة</p>
            </div>
         </div>
         <div className="flex gap-3 w-full lg:w-auto">
            <div className="relative group flex-1">
               <SearchIcon className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
               <input type="text" placeholder="ابحث برقم العملية..." className="w-full pr-14 pl-6 py-4 bg-white border-2 border-slate-200 rounded-2xl outline-none font-black shadow-sm" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
            </div>
         </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col flex-1 relative">
        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-900 text-white z-10">
              <tr>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-right">المعرف / التوقيت</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">إجمالي القيمة</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الخصم</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">صافي المدفوع</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الربح</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {invoices.filter(i => i.id.includes(searchTerm)).map(i => (
                <tr key={i.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="p-6"><div className="flex flex-col gap-1"><span className="font-mono text-[10px] text-slate-400">#{i.id.slice(0, 8)}</span><div className="flex items-center gap-2 text-slate-900 font-black text-sm"><Clock size={14} className="text-slate-400" />{new Date(i.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</div></div></td>
                  <td className="p-6 text-center"><span className="font-bold text-slate-400 text-xs">{i.total_amount} ₪</span></td>
                  <td className="p-6 text-center"><span className={`px-3 py-1 rounded-lg text-[10px] font-black ${Number(i.discount) > 0 ? 'bg-rose-50 text-rose-500 border border-rose-100' : 'text-slate-300'}`}>{Number(i.discount) > 0 ? `-${i.discount} ₪` : '0.00'}</span></td>
                  <td className="p-6 text-center"><span className="font-black text-emerald-600 text-lg">{i.net_amount} ₪</span></td>
                  <td className="p-6 text-center"><div className="inline-flex items-center justify-center gap-1.5 px-3 py-1 bg-slate-900 text-white rounded-xl text-xs font-black shadow-lg shadow-slate-200">{i.profit} ₪</div></td>
                  <td className="p-6 text-left"><div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all"><button onClick={() => handlePrint(i)} className="p-3 text-emerald-600 hover:bg-emerald-50 bg-slate-50 rounded-xl" title="طباعة"><Printer size={18} /></button><button onClick={() => requestDelete(i.id)} className="p-3 text-rose-600 hover:bg-rose-50 bg-slate-50 rounded-xl" title="حذف"><Trash2 size={18} /></button></div></td>
