import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History,
  FileText,
  Edit2,
  Trash2,
  Plus,
  Minus,
  Save,
  AlertCircle,
  Search,
  PlusCircle,
  Receipt,
  Eye,
  EyeOff,
