      <p className="text-[8px] font-black text-emerald-400 uppercase tracking-widest mb-1">{title}</p>
      <p className="text-[9px] font-bold leading-relaxed opacity-90">{formula}</p>
      <div className="absolute top-full left-1/2 -translate-x-1/2 border-[6px] border-transparent border-t-[#0f172a]"></div>
    </div>
