                          <td className="p-4 text-center font-black text-blue-700 text-xs">{ser.sale_price} ₪</td>
                          <td className="p-4 text-left">
                             <span className="text-[8px] font-black text-blue-400 uppercase">خدمة إضافية</span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Discount Section */}
              <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-200 grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1 flex items-center gap-2">
                    <Scissors size={14} /> تعديل قيمة الخصم (₪)
                  </label>
                  <input 
                    type="number" 
                    className="w-full p-4.5 bg-white border-2 border-slate-200 rounded-2xl outline-none focus:border-rose-500 font-black text-xl text-center" 
                    value={editingInvoice.discount || ''}
                    placeholder="0.00"
                    onChange={(e) => setEditingInvoice(recalculateInvoice({...editingInvoice, discount: Number(e.target.value)}))}
                  />
                </div>

                <div className="space-y-4">
                  <div className="flex justify-between items-center text-xs font-black">
                    <span className="text-slate-400 uppercase tracking-widest">الإجمالي قبل الخصم</span>
                    <span className="text-slate-800">{editingInvoice.total_amount.toFixed(2)} ₪</span>
                  </div>
                  <div className="flex justify-between items-center text-xs font-black">
                    <span className="text-rose-500 uppercase tracking-widest">قيمة الخصم</span>
                    <span className="text-rose-500">-{editingInvoice.discount.toFixed(2)} ₪</span>
                  </div>
                  <div className="flex justify-between items-center pt-4 border-t border-slate-200">
                    <span className="text-lg font-black text-slate-900">الصافي للدفع</span>
                    <span className="text-3xl font-black text-emerald-600">{editingInvoice.net_amount.toFixed(2)} ₪</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-900 border-t border-white/5 flex items-center justify-between">
              <div className="flex items-center gap-3 text-amber-500">
                <AlertCircle size={20} />
                <p className="text-xs font-black">تنبيه: سيتم تحديث المخزون تلقائياً عند الحفظ.</p>
              </div>
              <button 
                onClick={saveInvoiceEdits}
                disabled={loading}
                className="px-12 py-5 bg-emerald-600 text-white font-black text-xl rounded-[1.8rem] shadow-2xl flex items-center gap-3 transition-all active:scale-95 hover:bg-emerald-700"
              >
                {loading ? <Loader2 className="animate-spin" size={24} /> : <CheckCircle2 size={24} />}
                <span>حفظ كافة التغييرات</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center z-[400] p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-sm overflow-hidden p-8 space-y-6 border border-slate-200 animate-in zoom-in-95 duration-200">
             <div className="flex flex-col items-center gap-4 text-center">
                <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center shadow-inner">
                   <AlertTriangle size={40} />
                </div>
                <div>
                   <h3 className="text-xl font-black text-slate-900">حذف نهائي للفاتورة</h3>
                   <p className="text-slate-500 text-sm mt-2 font-bold leading-relaxed">
                     هل أنت متأكد من حذف هذه الفاتورة؟ سيتم إعادة الكميات للمخزون تلقائياً.
                   </p>
                </div>
             </div>
             <div className="flex gap-3">
                <button onClick={confirmDelete} className="flex-1 py-4 bg-rose-500 text-white font-black rounded-2xl shadow-lg active:scale-95 transition-all">نعم، حذف</button>
                <button onClick={() => { setShowDeleteConfirm(false); setDeleteTargetInvoice(null); }} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl active:scale-95 transition-all">إلغاء</button>
             </div>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default DailyReports;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingBag,
  X,
  CheckCircle2,
  Loader2,
  PlusCircle,
  Barcode,
  Layers
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(true);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [selectedProductForVariants, setSelectedProductForVariants] = useState<any>(null);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const addToCart = (variant: Variant, product: any) => {
    setIsCartOpen(true);
    setCart(prev => {
      const existing = prev.find(item => item.variant_id === variant.id);
      if (existing) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
    setSelectedProductForVariants(null);
  };

  const handleProductClick = (product: any) => {
    if (!product.variants || product.variants.length === 0) return;
    if (product.variants.length === 1) {
      addToCart(product.variants[0], product);
    } else {
      setSelectedProductForVariants(product);
    }
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    setIsCartOpen(true);
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const netAmount = Math.max(0, subtotal - discount);
    return { subtotal, netAmount };
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    try {
      const { subtotal, netAmount } = calculateTotals();
      const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);
      const { data: invoice, error: invError } = await supabase.from('invoices').insert({
        total_amount: subtotal, discount, net_amount: netAmount, total_cost: totalCost, profit: netAmount - totalCost
      }).select().single();

      if (invError) throw invError;
      const items = cart.filter(c => c.type === 'product');
      const services = cart.filter(c => c.type === 'service');

      if (items.length > 0) {
        await supabase.from('invoice_items').insert(items.map(item => ({
          invoice_id: invoice.id, variant_id: item.variant_id, product_name: item.product_name, variant_name: item.variant_name, quantity: item.quantity, cost_price: item.cost_price, sale_price: item.sale_price
        })));
        for (const item of items) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }
      if (services.length > 0) {
        await supabase.from('extra_services').insert(services.map(ser => ({
          invoice_id: invoice.id, name: ser.product_name, cost_price: ser.cost_price, sale_price: ser.sale_price, quantity: ser.quantity
        })));
      }

      setIsCartOpen(false);
      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
      fetchData();
    } catch (e) { alert("خطأ في إتمام الطلب"); } finally { setIsProcessing(false); }
  };

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? p.category_id === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? p.sub_category_id === selectedSubCat : true;
      return matchSearch && matchMainCat && matchSubCat;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);
  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row h-full font-['Tajawal'] bg-[#f8fafc] overflow-hidden" dir="rtl">

      <aside className="hidden lg:flex flex-col w-44 shrink-0 overflow-y-auto custom-scrollbar p-5 gap-2 z-10">
        <div className="mb-2 px-1 shrink-0">
          <p className="text-[#0f172a] font-black text-[9px] uppercase tracking-widest opacity-30">الأقسام</p>
        </div>
        <button onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }} className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${!selectedMainCat ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-transparent border-slate-200 text-slate-500'}`}>كافة الأصناف</button>
        {mainCategories.map(cat => (
          <button key={cat.id} onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }} className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${selectedMainCat === cat.id ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-transparent border-slate-200 text-slate-500'}`}>{cat.name}</button>
        ))}
      </aside>

      <div className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] border-r border-slate-200 overflow-hidden relative">
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm shrink-0">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input type="text" placeholder="البحث بالاسم أو الباركود..." className="w-full pr-14 pl-6 py-4 bg-slate-50 border-2 border-slate-300 focus:border-[#0f172a] rounded-[1.5rem] outline-none font-black text-lg" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-[#0f172a]" size={24} />
            </div>
            <div className="flex gap-2 w-full sm:w-auto">
              <button onClick={() => setShowExtraModal(true)} className="px-6 py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-all flex-1 shadow-lg"><PlusCircle size={20} /><span>خدمة</span></button>
              <button onClick={() => setIsCartOpen(!isCartOpen)} className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-[#0f172a] border-slate-300'}`}><ShoppingBag size={24} /></button>
            </div>
          </div>
          {selectedMainCat && (
            <div className="flex items-center gap-2 overflow-x-auto mt-4 pb-2 no-scrollbar border-t border-slate-100 pt-4">
              {subCategories.map(sub => (
                <button key={sub.id} onClick={() => setSelectedSubCat(sub.id)} className={`px-5 py-2.5 rounded-xl font-black text-[10px] whitespace-nowrap border-2 transition-all ${selectedSubCat === sub.id ? 'bg-[#0f172a] text-white' : 'bg-transparent text-slate-500 border-slate-200'}`}>{sub.name}</button>
              ))}
            </div>
          )}
        </div>

        <div className="p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">
          {filteredProducts.map(p => (
            <button key={p.id} onClick={() => handleProductClick(p)} className="group bg-white p-5 rounded-[1.8rem] border-2 border-slate-200 hover:border-emerald-600 hover:shadow-2xl transition-all duration-300 text-right flex flex-col gap-3 relative h-fit active:scale-95 shadow-sm">
              <div className="flex justify-between items-center">
                <span className={`text-[9px] font-black px-2 py-1 rounded-lg bg-slate-50 text-slate-500 border border-slate-100`}>
                  {p.variants?.reduce((s: number, v: any) => s + v.stock_quantity, 0) || 0} قطعة
                </span>
                <Plus size={18} className="text-slate-300 group-hover:text-emerald-600" />
              </div>
              <div className="flex-1">
                <h3 className="font-black text-[#0f172a] text-sm leading-tight line-clamp-2">{p.name}</h3>
                {p.variants?.length > 1 && <p className="text-[9px] text-blue-500 font-bold mt-1 uppercase opacity-70">متعدد الخيارات ({p.variants.length})</p>}
              </div>
              <div className="pt-3 border-t border-slate-100 flex items-center justify-between">
                 <span className="text-lg font-black text-[#0f172a]">
                   {Math.round(p.variants?.[0]?.sale_price || 0)} {p.variants?.length > 1 && '...'} <span className="text-[10px]">₪</span>
                 </span>
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className={`fixed lg:relative inset-y-0 left-0 bg-white border-r border-slate-300 shadow-2xl transition-all duration-500 z-[80] overflow-hidden flex flex-col h-full ${isCartOpen ? 'w-[320px]' : 'w-0'}`}>
        <div className="p-6 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3"><ShoppingBag size={20} className="text-emerald-500" /><span className="font-black text-lg">الفاتورة</span></div>
          <button onClick={() => setIsCartOpen(false)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
          {cart.length === 0 ? <div className="h-full flex flex-col items-center justify-center opacity-10 py-10"><ShoppingBag size={50} /><p className="font-black mt-4 text-sm">السلة فارغة</p></div> : 
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-4 rounded-2xl border-2 border-slate-200 flex flex-col gap-2 shadow-sm animate-slide-in-right">
                <div className="flex justify-between items-start gap-2"><h4 className="font-black text-[#0f172a] text-[11px] line-clamp-2 flex-1">{item.product_name}</h4><p className="font-black text-emerald-600 text-[12px]">{Math.round(item.sale_price * item.quantity)} ₪</p></div>
                <p className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center shadow-sm active:scale-90"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center shadow-sm active:scale-90"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="text-slate-300 hover:text-rose-500 p-1"><Trash2 size={16} /></button>
                </div>
              </div>
            ))
          }
        </div>
        <div className="p-6 bg-white border-t-2 border-slate-200 space-y-4 shrink-0 shadow-lg mt-auto z-10">
          <div className="space-y-2"><div className="flex justify-between text-[10px] font-black text-slate-500 px-1 uppercase tracking-tight"><span>تطبيق خصم</span><span>الإجمالي: {Math.round(subtotal)} ₪</span></div><input type="number" className="w-full py-3 bg-slate-50 border-2 border-slate-200 focus:border-[#0f172a] rounded-xl text-center font-black text-xl outline-none" value={discount || ''} placeholder="0" onChange={(e) => setDiscount(Math.min(subtotal, Number(e.target.value)))} /></div>
          <div className="pt-2 flex justify-between items-center border-t border-slate-100"><span className="text-[#0f172a] font-black text-xs opacity-60">الصافي للدفع</span><span className="text-2xl font-black text-emerald-600">{Math.round(netAmount)} ₪</span></div>
          <button onClick={handleFinishOrder} disabled={cart.length === 0 || isProcessing} className="w-full py-4.5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-500 disabled:bg-slate-200 flex items-center justify-center gap-2">
             {isProcessing ? <Loader2 className="animate-spin" /> : <>إتمام الفاتورة <CheckCircle2 size={20} /></>}
          </button>
        </div>
      </div>

      {/* Variant Selector Modal */}
      {selectedProductForVariants && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[250] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-slide-in-right">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between">
              <div className="flex items-center gap-4"><div className="p-2.5 bg-blue-600 rounded-xl"><Layers size={24} /></div><h3 className="text-xl font-black">{selectedProductForVariants.name}</h3></div>
              <button onClick={() => setSelectedProductForVariants(null)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-3 overflow-y-auto max-h-[60vh] custom-scrollbar">
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">يرجى اختيار النوع المطلوب:</p>
              {selectedProductForVariants.variants?.map((v: any) => (
                <button key={v.id} onClick={() => addToCart(v, selectedProductForVariants)} className="w-full p-5 bg-slate-50 border-2 border-slate-100 rounded-2xl flex items-center justify-between hover:border-emerald-500 hover:bg-white transition-all group shadow-sm active:scale-95">
                  <div className="text-right">
                    <p className="font-black text-slate-800 text-sm">{v.name}</p>
                    <p className="text-[10px] text-slate-400 font-bold">الكمية: {v.stock_quantity} قطعة</p>
                  </div>
                  <span className="font-black text-emerald-600 text-lg">{Math.round(v.sale_price)} ₪</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden border border-slate-200">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between"><div className="flex items-center gap-4"><div className="p-2.5 bg-emerald-600 rounded-xl"><PlusCircle size={24} /></div><h3 className="text-xl font-black">إضافة خدمة يدوية</h3></div><button onClick={() => setShowExtraModal(false)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button></div>
            <div className="p-8 space-y-6">
              <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">وصف الخدمة</label><input type="text" autoFocus className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" placeholder="مثال: رسوم شحن..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-5">
                <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">التكلفة (₪)</label><input type="number" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})} /></div>
                <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">البيع (₪)</label><input type="number" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold text-emerald-600" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})} /></div>
              </div>
              <button onClick={handleAddExtraService} disabled={!extraService.name || extraService.sale_price <= 0} className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-500">إدراج في السلة</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History,
  FileText,
  Edit2,
  Trash2,
  Plus, 
  Minus, 
  Save, 
  AlertCircle,
  Search,
  PlusCircle,
  Receipt,
  Eye,
  EyeOff,
  Info,
  AlertTriangle,
  ShoppingBag,
  CheckCircle2,
  Layers,
  Loader2
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [expandedInvoiceId, setExpandedInvoiceId] = useState<string | null>(null);
  const [showFinancials, setShowFinancials] = useState(false);
  const [hoveredTip, setHoveredTip] = useState<string | null>(null);

  // States for Editing and Deleting
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTargetInvoice, setDeleteTargetInvoice] = useState<any>(null);
  const [editingInvoice, setEditingInvoice] = useState<any>(null);
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearchTerm, setItemSearchTerm] = useState('');

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());

  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    invoices: [] as any[]
  });

  const [loading, setLoading] = useState(true);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase.from('invoices').select(`*, invoice_items (*), extra_services (*)`).gte('created_at', start).lte('created_at', end).order('created_at', { ascending: false });
    if (invoices) {
      let productSales = 0, productCost = 0, extraServiceProfit = 0, totalDiscounts = 0, itemsCount = 0;
      invoices.forEach(inv => {
        totalDiscounts += Number(inv.discount);
        inv.invoice_items.forEach((item: any) => { itemsCount += item.quantity; productSales += (item.sale_price * item.quantity); productCost += (item.cost_price * item.quantity); });
        inv.extra_services.forEach((ser: any) => { itemsCount += ser.quantity; extraServiceProfit += (ser.sale_price - ser.cost_price) * ser.quantity; });
      });
      const totalSales = (productSales - totalDiscounts) + extraServiceProfit;
      const totalProfit = (productSales - productCost - totalDiscounts) + extraServiceProfit;
      setData({ totalSales, totalCost: productCost, totalProfit, itemsCount, discounts: totalDiscounts, invoices });
    }
    setLoading(false);
  };

  const fetchProducts = async () => {
    const { data } = await supabase.from('products').select('*, variants(*)');
    setAllProducts(data || []);
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchProducts();
  }, [selectedDay]);

  // Invoice Logic: Recalculate Totals
  const recalculateInvoice = (inv: any) => {
    const total_amount = inv.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                        inv.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
    const net_amount = Math.max(0, total_amount - inv.discount);
    const total_cost = inv.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                       inv.extra_services.reduce((sum: number, s: any) => sum + (s.cost_price * s.quantity), 0);
    const profit = net_amount - total_cost;

    return { ...inv, total_amount, net_amount, total_cost, profit };
  };

  const handleUpdateItemQty = async (itemId: string, delta: number) => {
    const updatedInv = { ...editingInvoice };
    const item = updatedInv.invoice_items.find((i: any) => i.id === itemId);
    if (!item) return;

    const newQty = item.quantity + delta;
    if (newQty < 1) return;

    // Check stock for increase
    if (delta > 0 && item.variant_id) {
      const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
      if (v && v.stock_quantity < 1) {
        alert("عذراً، نفد المخزون من هذا النوع");
        return;
      }
    }

    item.quantity = newQty;
    setEditingInvoice(recalculateInvoice(updatedInv));
  };

  const handleRemoveItem = (itemId: string) => {
    const updatedInv = { ...editingInvoice };
    updatedInv.invoice_items = updatedInv.invoice_items.filter((i: any) => i.id !== itemId);
    setEditingInvoice(recalculateInvoice(updatedInv));
  };

  const handleAddProductToInvoice = (variant: any, product: any) => {
    const updatedInv = { ...editingInvoice };
    const newItem = {
      id: `temp-${Date.now()}`,
      invoice_id: editingInvoice.id,
      variant_id: variant.id,
      product_name: product.name,
      variant_name: variant.name,
      quantity: 1,
      cost_price: variant.cost_price,
      sale_price: variant.sale_price,
      is_new: true
    };
    updatedInv.invoice_items.push(newItem);
    setEditingInvoice(recalculateInvoice(updatedInv));
    setItemSearchTerm('');
  };

  const saveInvoiceEdits = async () => {
    try {
      setLoading(true);
      const originalInvoice = data.invoices.find(i => i.id === editingInvoice.id);

      await supabase.from('invoices').update({
        total_amount: editingInvoice.total_amount,
        discount: editingInvoice.discount,
        net_amount: editingInvoice.net_amount,
        total_cost: editingInvoice.total_cost,
        profit: editingInvoice.profit
      }).eq('id', editingInvoice.id);

      // 1. Revert OLD stock
      for (const item of originalInvoice.invoice_items) {
        if (item.variant_id) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
        }
      }

      // 2. Clear old items
      await supabase.from('invoice_items').delete().eq('invoice_id', editingInvoice.id);

      // 3. Insert NEW items and subtract stock
      for (const item of editingInvoice.invoice_items) {
        const { is_new, id, ...cleanItem } = item;
        await supabase.from('invoice_items').insert(cleanItem);

        if (item.variant_id) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }

      setEditingInvoice(null);
      await fetchDailyData(selectedDay);
    } catch (e) {
      alert("خطأ أثناء حفظ التعديلات");
    } finally {
      setLoading(false);
    }
  };

  const requestDelete = (invoice: any) => {
    setDeleteTargetInvoice(invoice);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async () => {
    if (!deleteTargetInvoice) return;
    try {
      for (const item of deleteTargetInvoice.invoice_items) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
        if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
      }
      await supabase.from('invoices').delete().eq('id', deleteTargetInvoice.id);
      setShowDeleteConfirm(false);
      setDeleteTargetInvoice(null);
      fetchDailyData(selectedDay);
    } catch (e) { alert("خطأ في الحذف"); }
  };

  const Tooltip = ({ title, formula }: { title: string, formula: string }) => (
    <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 w-48 p-3 bg-[#0f172a] text-white rounded-xl shadow-2xl z-50 animate-in fade-in zoom-in duration-200 border border-emerald-500/30">
      <p className="text-[8px] font-black text-emerald-400 uppercase tracking-widest mb-1">{title}</p>
      <p className="text-[9px] font-bold leading-relaxed opacity-90">{formula}</p>
      <div className="absolute top-full left-1/2 -translate-x-1/2 border-[6px] border-transparent border-t-[#0f172a]"></div>
    </div>
  );

  const filteredItemsToSearch = allProducts.flatMap(p => p.variants.map((v: any) => ({ ...v, productName: p.name, fullProduct: p }))).filter(v => v.productName.toLowerCase().includes(itemSearchTerm.toLowerCase()));

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-4 space-y-4 overflow-hidden font-['Tajawal']" dir="rtl">

      {/* 1. Header */}
      <div className="flex items-center justify-between shrink-0">
        <h2 className="text-lg font-black text-[#0f172a] flex items-center gap-2">
          <History className="text-emerald-600" size={20} />
          التقارير اليومية
        </h2>
        <div className="relative">
          <button onClick={() => setShowDayPicker(!showDayPicker)} className="flex items-center gap-2 bg-[#0f172a] text-white px-4 py-2 rounded-xl shadow-lg font-black text-xs">
            <Calendar size={14} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={14} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-12 left-0 w-56 bg-white rounded-2xl shadow-2xl border border-slate-200 p-3 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-7 h-7 rounded-lg flex items-center justify-center font-bold text-[10px] ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Stats Section with Privacy Shield */}
      <div className="relative shrink-0 overflow-hidden rounded-2xl">
        <div className={`grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-3 transition-all duration-500 ${!showFinancials ? 'blur-md grayscale opacity-40 select-none pointer-events-none' : ''}`}>
          {[
            { id: 'sales', label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50', formula: 'المبيعات = (بيع المنتجات - الخصم) + (ربح الخدمات)' },
            { id: 'cost', label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50', formula: 'مجموع جملة تكلفة المنتجات فقط' },
            { id: 'profit', label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50', formula: 'صافي الربح = (ربح المنتجات - الخصم) + (ربح الخدمات)' },
            { id: 'items', label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50', formula: 'عدد القطع والخدمات المباعة' },
            { id: 'discounts', label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'text-rose-600', bg: 'bg-rose-50', formula: 'مجموع الخصومات الممنوحة' }
          ].map((stat) => (
            <div key={stat.id} className="p-3.5 bg-white rounded-xl border border-slate-200 shadow-sm flex flex-col gap-2 relative group">
              <div className="flex justify-between items-start">
                <div className={`p-1.5 rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={16} /></div>
                <div className="relative"><Info size={12} className="text-slate-300 hover:text-[#0f172a] cursor-help" onMouseEnter={() => setHoveredTip(stat.id)} onMouseLeave={() => setHoveredTip(null)} />{hoveredTip === stat.id && <Tooltip title={stat.label} formula={stat.formula} />}</div>
              </div>
              <div><p className="text-[8px] font-black uppercase opacity-60 mb-0.5">{stat.label}</p><p className="text-base font-black truncate">{Math.round(stat.value)} ₪</p></div>
            </div>
          ))}
        </div>

        {!showFinancials && (
          <div className="absolute inset-0 z-20 flex items-center justify-center">
            <div className="absolute inset-0 bg-white/40 backdrop-blur-[2px]" />
            <button onClick={() => setShowFinancials(true)} className="relative z-30 flex flex-col items-center gap-1.5 bg-[#0f172a] text-white px-8 py-4 rounded-2xl shadow-2xl hover:bg-slate-800 transition-all">
              <Eye size={22} className="text-emerald-500" />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">كشف البيانات المالية</span>
            </button>
          </div>
        )}

        {showFinancials && (
          <button onClick={() => setShowFinancials(false)} className="absolute top-2 left-2 z-30 p-2 bg-white/80 backdrop-blur-md text-slate-400 hover:text-rose-500 rounded-xl shadow-lg border border-slate-100 transition-all active:scale-90">
            <EyeOff size={16} />
          </button>
        )}
      </div>

      {/* 3. Invoices Section (Accordion Style) */}
      <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 pb-4">
        <div className="flex items-center gap-3 px-1">
           <Receipt className="text-blue-600" size={18} />
           <h3 className="font-black text-[#0f172a] text-xs">سجل الفواتير الصادرة</h3>
        </div>

        {data.invoices.map((inv) => (
          <div key={inv.id} className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden flex flex-col transition-all">
            <button 
              onClick={() => setExpandedInvoiceId(expandedInvoiceId === inv.id ? null : inv.id)}
              className="p-4 flex items-center justify-between hover:bg-slate-50 transition-colors"
            >
              <div className="flex items-center gap-4">
                <div className={`p-2 rounded-xl ${expandedInvoiceId === inv.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'bg-slate-100 text-slate-400'}`}>
                  <FileText size={18} />
                </div>
                <div className="text-right">
                  <p className="font-mono text-[9px] text-slate-400">#{inv.id.slice(0, 8)}</p>
                  <p className="font-black text-[11px] text-slate-900">{new Date(inv.created_at).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}</p>
                </div>
              </div>
              <div className="flex items-center gap-6">
                <div className="hidden sm:block text-left">
                  <p className="text-[8px] font-black text-slate-400 uppercase">الصافي</p>
                  <p className="font-black text-emerald-600 text-sm">{Math.round(inv.net_amount)} ₪</p>
                </div>
                <ChevronDown size={18} className={`text-slate-300 transition-transform duration-300 ${expandedInvoiceId === inv.id ? 'rotate-180 text-blue-600' : ''}`} />
              </div>
            </button>

            {expandedInvoiceId === inv.id && (
              <div className="border-t border-slate-100 animate-in slide-in-from-top-2 duration-300">
                <div className="p-4 bg-slate-50/50 flex flex-col gap-4">
                  {/* Detailed Table */}
                  <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
                    <table className="w-full text-right">
                      <thead className="bg-[#0f172a] text-white">
                        <tr>
                          <th className="p-3 text-[9px] font-black uppercase">الصنف</th>
                          <th className="p-3 text-[9px] font-black uppercase text-center">السعر</th>
                          <th className="p-3 text-[9px] font-black uppercase text-center">الكمية</th>
                          <th className="p-3 text-[9px] font-black uppercase text-left">المجموع</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {inv.invoice_items.map((it: any) => (
                          <tr key={it.id} className="text-[10px] font-bold text-slate-600">
                            <td className="p-3">
                              <span className="block font-black text-slate-900">{it.product_name}</span>
                              <span className="text-[8px] opacity-60">{it.variant_name}</span>
                            </td>
                            <td className="p-3 text-center">{Math.round(it.sale_price)} ₪</td>
                            <td className="p-3 text-center">x{it.quantity}</td>
                            <td className="p-3 text-left font-black text-slate-900">{Math.round(it.sale_price * it.quantity)} ₪</td>
                          </tr>
                        ))}
                        {inv.extra_services.map((ser: any) => (
                          <tr key={ser.id} className="text-[10px] font-bold text-blue-600 bg-blue-50/30">
                            <td className="p-3">
                              <span className="block font-black">{ser.name}</span>
                              <span className="text-[8px] opacity-60">خدمة إضافية</span>
                            </td>
                            <td className="p-3 text-center">{Math.round(ser.sale_price)} ₪</td>
                            <td className="p-3 text-center">x{ser.quantity}</td>
                            <td className="p-3 text-left font-black">{Math.round(ser.sale_price * ser.quantity)} ₪</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>

                  {/* Financial Footer for specific invoice */}
                  <div className="flex flex-wrap items-center justify-between gap-4 p-4 bg-white rounded-xl border border-slate-200 border-r-4 border-r-blue-600">
                    <div className="flex gap-6">
                      <div className="space-y-1">
                        <p className="text-[8px] font-black text-slate-400 uppercase">قبل الخصم</p>
                        <p className="font-black text-slate-600 text-sm">{Math.round(inv.total_amount)} ₪</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[8px] font-black text-rose-500 uppercase">الخصم</p>
                        <p className="font-black text-rose-500 text-sm">{Math.round(inv.discount)} ₪</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[8px] font-black text-emerald-600 uppercase tracking-widest">صافي الدفع</p>
                        <p className="font-black text-emerald-600 text-lg">{Math.round(inv.net_amount)} ₪</p>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                       <button 
                        onClick={() => setEditingInvoice({...inv})}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-[10px] font-black shadow-lg shadow-blue-100 active:scale-95 transition-all"
                       >
                         <Edit2 size={14} /> تعديل الفاتورة
                       </button>
                       <button 
                        onClick={() => requestDelete(inv)}
                        className="p-2 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all active:scale-95"
                       >
                         <Trash2 size={18} />
                       </button>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        ))}
        {data.invoices.length === 0 && <div className="py-20 text-center text-slate-300 font-bold flex flex-col items-center gap-4"><ShoppingBag size={48} opacity={0.2} /><p>لا توجد فواتير مسجلة لهذا اليوم</p></div>}
      </div>

      {/* 4. Invoice EDIT Modal */}
      {editingInvoice && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-xl flex items-center justify-center z-[200] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-in zoom-in-95 duration-200 max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className="p-4 rounded-2xl bg-blue-600 text-white shadow-xl shadow-blue-100">
                  <Edit2 size={24} />
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-900">تعديل فاتورة رقم #{editingInvoice.id.slice(0, 8)}</h3>
                  <p className="text-[10px] font-bold text-slate-400">تعديل الأصناف والكميات والخصم</p>
                </div>
              </div>
              <button onClick={() => setEditingInvoice(null)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">

              {/* Add New Item Search */}
              <div className="space-y-4">
                <p className="text-xs font-black text-[#0f172a] uppercase tracking-widest px-1">إضافة صنف جديد للفاتورة</p>
                <div className="relative group">
                  <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600" size={20} />
                  <input 
                    type="text" 
                    placeholder="ابحث باسم المنتج لإضافته..."
                    className="w-full pr-14 pl-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-blue-600 font-black transition-all"
                    value={itemSearchTerm}
                    onChange={(e) => setItemSearchTerm(e.target.value)}
                  />
                  {itemSearchTerm && (
                    <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-2xl shadow-2xl z-[210] max-h-60 overflow-y-auto custom-scrollbar p-2 space-y-1">
                      {filteredItemsToSearch.map((v, idx) => (
                        <button 
                          key={idx} 
                          onClick={() => handleAddProductToInvoice(v, v.fullProduct)}
                          className="w-full p-3 flex items-center justify-between hover:bg-blue-50 rounded-xl transition-all"
                        >
                          <div className="text-right">
                            <span className="block font-black text-slate-800 text-xs">{v.productName}</span>
                            <span className="text-[9px] text-slate-400">{v.name} - المخزون: {v.stock_quantity}</span>
                          </div>
                          <span className="font-black text-blue-600 text-xs">{Math.round(v.sale_price)} ₪</span>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Editable Items Table */}
              <div className="space-y-4">
                <p className="text-xs font-black text-[#0f172a] uppercase tracking-widest px-1">محتويات الفاتورة الحالية</p>
                <div className="overflow-hidden border border-slate-200 rounded-2xl shadow-sm">
                  <table className="w-full text-right border-collapse">
                    <thead className="bg-slate-50 border-b border-slate-100">
                      <tr>
                        <th className="p-4 text-[9px] font-black uppercase text-slate-400">الصنف</th>
                        <th className="p-4 text-[9px] font-black uppercase text-slate-400 text-center">الكمية</th>
                        <th className="p-4 text-[9px] font-black uppercase text-slate-400 text-center">السعر</th>
                        <th className="p-4 text-[9px] font-black uppercase text-slate-400 text-left">الإجراء</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {editingInvoice.invoice_items.map((it: any) => (
                        <tr key={it.id} className="bg-white hover:bg-slate-50/50">
                          <td className="p-4">
                            <span className="block font-black text-slate-800 text-xs">{it.product_name}</span>
                            <span className="text-[9px] text-slate-400 font-bold uppercase">{it.variant_name}</span>
                          </td>
                          <td className="p-4 text-center">
