                              <span className="font-black text-xs min-w-[20px]">{it.quantity}</span>
                              <button onClick={() => handleUpdateItemQty(it.id, 1)} className="p-1 bg-white text-slate-400 hover:text-emerald-500 rounded-lg shadow-sm active:scale-90"><Plus size={14} /></button>
                            </div>
                          </td>
