import React, { useState, useEffect, useCallback } from 'react';
import { 
  FileText, 
  Edit2, 
  Trash2, 
  Printer, 
  Search, 
  X, 
  Save, 
  Plus, 
  Minus, 
  Search as SearchIcon,
  ShoppingBag,
  CheckCircle2,
  AlertTriangle,
  Calendar as CalendarIcon,
  ChevronDown,
  Filter,
  RefreshCw,
  Clock,
  Layers,
  CalendarDays,
  CalendarRange,
  ChevronLeft
} from 'lucide-react';
import { supabase } from '../supabase';
import type { AppSettings } from '../types';

type FilterMode = 'day' | 'month' | 'year';

const Invoices: React.FC<{ settings: AppSettings | null, onUpdateSettings: () => void }> = ({ settings, onUpdateSettings }) => {
  const [invoices, setInvoices] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  // Delete Confirmation State
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTargetId, setDeleteTargetId] = useState<string | null>(null);

  const [filterMode, setFilterMode] = useState<FilterMode>('day');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth());
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());

  const fetchInvoices = useCallback(async () => {
    setLoading(true);
    let start, end;
    if (filterMode === 'day') { start = `${selectedDate}T00:00:00.000Z`; end = `${selectedDate}T23:59:59.999Z`; } 
    else if (filterMode === 'month') { const firstDay = new Date(selectedYear, selectedMonth, 1); const lastDay = new Date(selectedYear, selectedMonth + 1, 0); start = firstDay.toISOString(); end = lastDay.toISOString().split('T')[0] + 'T23:59:59.999Z'; } 
    else { const firstDay = new Date(selectedYear, 0, 1); const lastDay = new Date(selectedYear, 11, 31); start = firstDay.toISOString(); end = lastDay.toISOString().split('T')[0] + 'T23:59:59.999Z'; }

    const { data, error } = await supabase.from('invoices').select(`*, invoice_items (*), extra_services (*)`).gte('created_at', start).lte('created_at', end).order('created_at', { ascending: false });
    if (!error) setInvoices(data || []);
    setLoading(false);
  }, [filterMode, selectedDate, selectedMonth, selectedYear]);

  useEffect(() => { fetchInvoices(); }, [fetchInvoices]);

  const requestDelete = (id: string) => {
    setDeleteTargetId(id);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async () => {
    if (!deleteTargetId) return;
    await supabase.from('invoices').delete().eq('id', deleteTargetId);
    setShowDeleteConfirm(false);
    setDeleteTargetId(null);
    fetchInvoices();
  };

  const handlePrint = (invoice: any) => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;
    const itemsHtml = invoice.invoice_items.map((it: any) => `<tr><td style="padding: 5px; border-bottom: 1px solid #eee;">${it.product_name} <br/><small>${it.variant_name}</small></td><td style="padding: 5px; border-bottom: 1px solid #eee; text-align: center;">${it.quantity}</td><td style="padding: 5px; border-bottom: 1px solid #eee; text-align: left;">${Math.round(it.sale_price * it.quantity)} ₪</td></tr>`).join('');
    const servicesHtml = invoice.extra_services.map((ser: any) => `<tr><td style="padding: 5px; border-bottom: 1px solid #eee;">${ser.name} (خدمة)</td><td style="padding: 5px; border-bottom: 1px solid #eee; text-align: center;">${ser.quantity}</td><td style="padding: 5px; border-bottom: 1px solid #eee; text-align: left;">${Math.round(ser.sale_price * ser.quantity)} ₪</td></tr>`).join('');
    printWindow.document.write(`<html dir="rtl"><head><title>فاتورة #${invoice.id.slice(0,8)}</title><style>body { font-family: 'Tajawal', sans-serif; padding: 20px; width: 80mm; margin: 0 auto; } h2 { text-align: center; margin-bottom: 10px; } table { width: 100%; border-collapse: collapse; margin-top: 15px; font-size: 12px; } .total-row { font-weight: bold; border-top: 2px solid #000; } .center { text-align: center; } .right { text-align: right; } .left { text-align: left; } </style></head><body><h2>Flyyti Mobile POS</h2><p class="center">فاتورة مبيعات</p><p>الرقم: #${invoice.id.slice(0,8)}</p><p>التاريخ: ${new Date(invoice.created_at).toLocaleString('en-GB')}</p><hr/><table><thead><tr><th class="right">الصنف</th><th class="center">الكمية</th><th class="left">السعر</th></tr></thead><tbody>${itemsHtml}${servicesHtml}</tbody></table><div style="margin-top: 20px; border-top: 1px solid #000; padding-top: 10px;"><p>الإجمالي: ${Math.round(invoice.total_amount)} ₪</p><p>الخصم: ${Math.round(invoice.discount)} ₪</p><h3 style="border-top: 2px solid #000; padding-top: 5px;">الصافي: ${Math.round(invoice.net_amount)} ₪</h3></div><p class="center" style="margin-top: 30px; font-size: 10px;">شكراً لزيارتكم!</p><script>window.onload = function() { window.print(); window.close(); };</script></body></html>`);
    printWindow.document.close();
  };

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-6 overflow-hidden font-['Tajawal']" dir="rtl">
      {/* (بقية الهيدر تبقى كما هي) */}
      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col flex-1 relative">
        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-900 text-white z-10">
              <tr>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-right">المعرف / التوقيت</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">إجمالي القيمة</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الخصم</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">صافي المدفوع</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الربح</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {invoices.filter(i => i.id.includes(searchTerm)).map(i => (
                <tr key={i.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="p-6"><div className="flex flex-col gap-1"><span className="font-mono text-[10px] text-slate-400">#{i.id.slice(0, 8)}</span><div className="flex items-center gap-2 text-slate-900 font-black text-sm"><Clock size={14} className="text-slate-400" />{new Date(i.created_at).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}</div></div></td>
                  <td className="p-6 text-center"><span className="font-bold text-slate-400 text-xs">{Math.round(i.total_amount)} ₪</span></td>
                  <td className="p-6 text-center"><span className={`px-3 py-1 rounded-lg text-[10px] font-black ${Number(i.discount) > 0 ? 'bg-rose-50 text-rose-500 border border-rose-100' : 'text-slate-300'}`}>{Number(i.discount) > 0 ? `-${Math.round(i.discount)} ₪` : '0'}</span></td>
                  <td className="p-6 text-center"><span className="font-black text-emerald-600 text-lg">{Math.round(i.net_amount)} ₪</span></td>
                  <td className="p-6 text-center"><div className="inline-flex items-center justify-center gap-1.5 px-3 py-1 bg-slate-900 text-white rounded-xl text-xs font-black shadow-lg shadow-slate-200">{Math.round(i.profit)} ₪</div></td>
                  <td className="p-6 text-left"><div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all"><button onClick={() => handlePrint(i)} className="p-3 text-emerald-600 hover:bg-emerald-50 bg-slate-50 rounded-xl" title="طباعة"><Printer size={18} /></button><button onClick={() => requestDelete(i.id)} className="p-3 text-rose-600 hover:bg-rose-50 bg-slate-50 rounded-xl" title="حذف"><Trash2 size={18} /></button></div></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

