/**
 * دالة ذكية لجلب إعدادات الاتصال من مصادر متعددة (Variables, LocalStorage, Hardcoded)
 */
const getEnvValue = (key: string): string => {
  const viteKey = `VITE_${key}`;

  // 1. البحث في متغيرات البيئة (Environment Variables)
  const env = (import.meta as any).env;
  if (env && env[viteKey]) return env[viteKey];
  if (env && env[key]) return env[key];

  // 2. البحث في التخزين المحلي (LocalStorage) - للمستخدمين الذين يغيرون الإعدادات يدوياً
  if (typeof localStorage !== 'undefined') {
    const stored = localStorage.getItem(viteKey) || localStorage.getItem(key);
    if (stored) return stored;
  }

  // 3. القيم الافتراضية (Fallback) - استبدل هذه القيم بقيم مشروعك إذا لم تستخدم متغيرات بيئة
  const fallbacks: Record<string, string> = {
    'SUPABASE_URL': 'https://gpclqttogygmqzoemooz.supabase.co/',
    'SUPABASE_ANON_KEY': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdwY2xxdHRvZ3lnbXF6b2Vtb296Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3Njk1NDcyODYsImV4cCI6MjA4NTEyMzI4Nn0.iPltb4EZBhFUFriofeR3MJFM_rVXfF39zL9P82RRhIw'
  };

  return fallbacks[key] || '';
};

export const getSupabaseConfig = () => {
  const url = getEnvValue('SUPABASE_URL');
  const key = getEnvValue('SUPABASE_ANON_KEY');
  return {
    url,
    key,
    isValid: url.startsWith('https://') && key.length > 20
  };
};

const config = getSupabaseConfig();

// إنشاء العميل
export const supabase: SupabaseClient = createClient(config.url, config.key);

/**
 * دالة لحفظ الإعدادات يدوياً وإعادة تشغيل التطبيق
 */
export const saveSupabaseConfig = (url: string, key: string) => {
  localStorage.setItem('VITE_SUPABASE_URL', url.trim());
  localStorage.setItem('VITE_SUPABASE_ANON_KEY', key.trim());
  window.location.reload();
};

