---

### ثانياً: كود SQL (انسخه في Supabase SQL Editor)
هذا السكربت يقوم بإنشاء كافة الجداول اللازمة، مع إضافة الأعمدة التي طلبتها (مثل `login_protection_enabled`) والبيانات الافتراضية:

```sql
-- 1. تفعيل الملحقات الضرورية
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. جدول الأقسام (Categories)
CREATE TABLE IF NOT EXISTS categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  parent_id UUID REFERENCES categories(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. جدول المنتجات (Products)
CREATE TABLE IF NOT EXISTS products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  barcode TEXT UNIQUE,
  category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
  sub_category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
  supplier TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. جدول الأنواع والأسعار (Variants)
CREATE TABLE IF NOT EXISTS variants (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id UUID REFERENCES products(id) ON DELETE CASCADE,
  name TEXT NOT NULL DEFAULT 'افتراضي',
  cost_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  sale_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  stock_quantity INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. جدول الفواتير (Invoices)
CREATE TABLE IF NOT EXISTS invoices (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  total_amount DECIMAL(10,2) NOT NULL DEFAULT 0,
  discount DECIMAL(10,2) DEFAULT 0,
  net_amount DECIMAL(10,2) NOT NULL DEFAULT 0,
  total_cost DECIMAL(10,2) NOT NULL DEFAULT 0,
  profit DECIMAL(10,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 6. تفاصيل الفاتورة (Invoice Items)
CREATE TABLE IF NOT EXISTS invoice_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID REFERENCES invoices(id) ON DELETE CASCADE,
  variant_id UUID REFERENCES variants(id) ON DELETE SET NULL,
  product_name TEXT NOT NULL,
  variant_name TEXT,
  quantity INTEGER NOT NULL DEFAULT 1,
  cost_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  sale_price DECIMAL(10,2) NOT NULL DEFAULT 0
);

-- 7. الخدمات الإضافية (Extra Services)
CREATE TABLE IF NOT EXISTS extra_services (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID REFERENCES invoices(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  cost_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  sale_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  quantity INTEGER NOT NULL DEFAULT 1
);

-- 8. المصاريف (Expenses)
CREATE TABLE IF NOT EXISTS expenses (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  type TEXT NOT NULL,
  amount DECIMAL(10,2) NOT NULL DEFAULT 0,
  date DATE NOT NULL DEFAULT CURRENT_DATE,
  note TEXT
);

-- 9. المشتريات (Purchases)
CREATE TABLE IF NOT EXISTS purchases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  amount DECIMAL(10,2) NOT NULL DEFAULT 0,
  supplier TEXT,
  date DATE NOT NULL DEFAULT CURRENT_DATE,
  note TEXT
);

-- 10. الإعدادات والأمان (Settings)
CREATE TABLE IF NOT EXISTS settings (
  id INTEGER PRIMARY KEY DEFAULT 1,
  username TEXT DEFAULT 'admin',
  password TEXT DEFAULT 'admin',
  page_password TEXT DEFAULT '1234',
  capital DECIMAL(15,2) DEFAULT 0,
  savings DECIMAL(15,2) DEFAULT 0,
  protection_enabled BOOLEAN DEFAULT TRUE,
  login_protection_enabled BOOLEAN DEFAULT TRUE,
  page_locks JSONB DEFAULT '{"inventory": true, "categories": true, "expenses": true, "invoices": true, "reports": true, "security": true}',
  profit_shares JSONB DEFAULT '{"mujahed": 25, "abboud": 25, "shop": 40, "special": 10}'
);

-- إدراج الإعدادات الافتراضية إذا لم تكن موجودة
INSERT INTO settings (id, username, password, page_password, login_protection_enabled) 
VALUES (1, 'admin', 'admin', '1234', TRUE) 
ON CONFLICT (id) DO NOTHING;

-- تفعيل سياسات الوصول (RLS) - اختيارياً يمكن تعطيلها لتسهيل التطوير الابتدائي
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to categories" ON categories FOR ALL USING (true);

ALTER TABLE products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to products" ON products FOR ALL USING (true);

ALTER TABLE variants ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to variants" ON variants FOR ALL USING (true);

ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to invoices" ON invoices FOR ALL USING (true);

ALTER TABLE invoice_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to invoice_items" ON invoice_items FOR ALL USING (true);

ALTER TABLE extra_services ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to extra_services" ON extra_services FOR ALL USING (true);

ALTER TABLE expenses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to expenses" ON expenses FOR ALL USING (true);

ALTER TABLE purchases ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to purchases" ON purchases FOR ALL USING (true);

ALTER TABLE settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all to settings" ON settings FOR ALL USING (true);
```

### كيف تستخدم هذا الكود؟
1.  افتح مشروعك في [Supabase](https://supabase.com).
2.  اضغط على **SQL Editor** من القائمة الجانبية (أيقونة `>_`).
3.  اضغط على **New Query**.
4.  انسخ كود SQL أعلاه والصقه بالكامل.
5.  اضغط على زر **Run** في أسفل الصفحة.

سيؤدي هذا إلى بناء قاعدة بيانات نظيفة وجاهزة تماماً لتطبيق **Flyyti Mobile POS**.

