import React, { useState, useEffect, useMemo } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Scissors,
  ChevronDown,
  Target,
  X,
  History,
  FileText,
  Edit2,
  Trash2,
  Plus, 
  Minus, 
  Save, 
  AlertCircle,
  Search,
  PlusCircle,
  Receipt,
  Eye,
  EyeOff,
  Info,
  AlertTriangle,
  ShoppingBag,
  CheckCircle2,
  Layers,
  Loader2,
  Zap,
  LayoutList,
  ArrowUpRight,
  ChevronUp
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [expandedInvoiceId, setExpandedInvoiceId] = useState<string | null>(null);
  const [showFinancials, setShowFinancials] = useState(false);
  const [hoveredTip, setHoveredTip] = useState<string | null>(null);

  // Accordion Sections State
  const [openSections, setOpenSections] = useState({
    sales: true,
    services: false,
    invoices: false
  });

  // States for Editing and Deleting
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTargetInvoice, setDeleteTargetInvoice] = useState<any>(null);
  const [editingInvoice, setEditingInvoice] = useState<any>(null);
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearchTerm, setItemSearchTerm] = useState('');

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());

  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    invoices: [] as any[]
  });

  const [loading, setLoading] = useState(true);

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase.from('invoices').select(`*, invoice_items (*), extra_services (*)`).gte('created_at', start).lte('created_at', end).order('created_at', { ascending: false });
    if (invoices) {
      let productSales = 0, productCost = 0, extraServiceProfit = 0, totalDiscounts = 0, itemsCount = 0;
      invoices.forEach(inv => {
        totalDiscounts += Number(inv.discount);
        inv.invoice_items.forEach((item: any) => { itemsCount += item.quantity; productSales += (item.sale_price * item.quantity); productCost += (item.cost_price * item.quantity); });
        inv.extra_services.forEach((ser: any) => { itemsCount += ser.quantity; extraServiceProfit += (ser.sale_price - ser.cost_price) * ser.quantity; });
      });
      const totalSales = (productSales - totalDiscounts) + extraServiceProfit;
      const totalProfit = (productSales - productCost - totalDiscounts) + extraServiceProfit;
      setData({ totalSales, totalCost: productCost, totalProfit, itemsCount, discounts: totalDiscounts, invoices });
    }
    setLoading(false);
  };

  const fetchProducts = async () => {
    const { data } = await supabase.from('products').select('*, variants(*)');
    setAllProducts(data || []);
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchProducts();
  }, [selectedDay]);

  // Aggregate Items and Services for the new sections
  const aggregatedStats = useMemo(() => {
    const itemsMap: Record<string, any> = {};
    const servicesMap: Record<string, any> = {};

    data.invoices.forEach(inv => {
      inv.invoice_items.forEach((it: any) => {
        const key = `${it.product_name}-${it.variant_name}`;
        if (!itemsMap[key]) {
          itemsMap[key] = { name: it.product_name, variant: it.variant_name, qty: 0, cost: 0, sale: 0 };
        }
        itemsMap[key].qty += it.quantity;
        itemsMap[key].cost += it.cost_price * it.quantity;
        itemsMap[key].sale += it.sale_price * it.quantity;
      });

      inv.extra_services.forEach((ser: any) => {
        const key = ser.name;
        if (!servicesMap[key]) {
          servicesMap[key] = { name: ser.name, qty: 0, cost: 0, sale: 0 };
        }
        servicesMap[key].qty += ser.quantity;
        servicesMap[key].cost += ser.cost_price * ser.quantity;
        servicesMap[key].sale += ser.sale_price * ser.quantity;
      });
    });

    return {
      products: Object.values(itemsMap).sort((a, b) => b.qty - a.qty),
      services: Object.values(servicesMap).sort((a, b) => b.qty - a.qty)
    };
  }, [data.invoices]);

  // Invoice Logic: Recalculate Totals
  const recalculateInvoice = (inv: any) => {
    const total_amount = inv.invoice_items.reduce((sum: number, i: any) => sum + (i.sale_price * i.quantity), 0) +
                        inv.extra_services.reduce((sum: number, s: any) => sum + (s.sale_price * s.quantity), 0);
    const discVal = parseFloat(inv.discount) || 0; 
    const net_amount = Math.max(0, total_amount - discVal);
    const total_cost = inv.invoice_items.reduce((sum: number, i: any) => sum + (i.cost_price * i.quantity), 0) +
                       inv.extra_services.reduce((sum: number, s: any) => sum + (s.cost_price * s.quantity), 0);
    const profit = net_amount - total_cost;

    return { ...inv, total_amount, net_amount, total_cost, profit };
  };

  const handleUpdateItemQty = async (itemId: string, delta: number) => {
    const updatedInv = { ...editingInvoice };
    const item = updatedInv.invoice_items.find((i: any) => i.id === itemId);
    if (!item) return;
    const newQty = item.quantity + delta;
    if (newQty < 1) return;
    item.quantity = newQty;
    setEditingInvoice(recalculateInvoice(updatedInv));
  };

  const handleRemoveItem = (itemId: string) => {
    const updatedInv = { ...editingInvoice };
    updatedInv.invoice_items = updatedInv.invoice_items.filter((i: any) => i.id !== itemId);
    setEditingInvoice(recalculateInvoice(updatedInv));
  };

  const handleAddProductToInvoice = (variant: any, product: any) => {
    const updatedInv = { ...editingInvoice };
    const newItem = {
      id: `temp-${Date.now()}`,
      invoice_id: editingInvoice.id,
      variant_id: variant.id,
      product_name: product.name,
      variant_name: variant.name,
      quantity: 1,
      cost_price: variant.cost_price,
      sale_price: variant.sale_price,
      is_new: true
    };
    updatedInv.invoice_items.push(newItem);
    setEditingInvoice(recalculateInvoice(updatedInv));
    setItemSearchTerm('');
  };

  const saveInvoiceEdits = async () => {
    try {
      setLoading(true);
      const originalInvoice = data.invoices.find(i => i.id === editingInvoice.id);

      await supabase.from('invoices').update({
        total_amount: editingInvoice.total_amount,
        discount: parseFloat(editingInvoice.discount) || 0,
        net_amount: editingInvoice.net_amount,
        total_cost: editingInvoice.total_cost,
        profit: editingInvoice.profit
      }).eq('id', editingInvoice.id);

      for (const item of originalInvoice.invoice_items) {
        if (item.variant_id) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity + item.quantity }).eq('id', item.variant_id);
        }
      }

      await supabase.from('invoice_items').delete().eq('invoice_id', editingInvoice.id);

      for (const item of editingInvoice.invoice_items) {
        const { is_new, id, ...cleanItem } = item;
        await supabase.from('invoice_items').insert(cleanItem);

        if (item.variant_id) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }

      setEditingInvoice(null);
      await fetchDailyData(selectedDay);
    } catch (e) {
      alert("خطأ أثناء حفظ التعديلات");
    } finally {
      setLoading(false);
    }
  };

  const requestDelete = (invoice: any) => {
    setDeleteTargetInvoice(invoice);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async () => {
    if (!deleteTargetInvoice) return;
    try {
      for (const item of deleteTargetInvoice.invoice_items) {
        const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
