                <div className="space-y-4">
                  <div className="flex justify-between items-center text-xs font-black"><span className="text-slate-400 uppercase tracking-widest">الإجمالي قبل الخصم</span><span className="text-slate-800">{Math.round(editingInvoice.total_amount)} ₪</span></div>
                  <div className="flex justify-between items-center text-xs font-black"><span className="text-rose-500 uppercase tracking-widest">قيمة الخصم</span><span className="text-rose-500">-{Math.round(parseFloat(editingInvoice.discount) || 0)} ₪</span></div>
                  <div className="flex justify-between items-center pt-4 border-t border-slate-200"><span className="text-lg font-black text-slate-900">الصافي للدفع</span><span className="text-3xl font-black text-emerald-600">{Math.round(editingInvoice.net_amount)} ₪</span></div>
