        <h2 className="text-lg font-black text-[#0f172a] flex items-center gap-2">
          <BarChart3 className="text-emerald-600" size={20} />
          التقارير اليومية التفصيلية
        </h2>
        <div className="relative">
          <button onClick={() => setShowDayPicker(!showDayPicker)} className="flex items-center gap-2 bg-[#0f172a] text-white px-4 py-2 rounded-xl shadow-lg font-black text-xs">
            <Calendar size={14} className="text-emerald-400" />
            <span>{selectedDay} {monthName}</span>
            <ChevronDown size={14} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-12 left-0 w-56 bg-white rounded-2xl shadow-2xl border border-slate-200 p-3 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-7 h-7 rounded-lg flex items-center justify-center font-bold text-[10px] ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Stats Section */}
      <div className="relative shrink-0 overflow-hidden rounded-2xl">
        <div className={`grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-3 transition-all duration-500 ${!showFinancials ? 'blur-md grayscale opacity-40 select-none pointer-events-none' : ''}`}>
          {[
            { id: 'sales', label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50', formula: 'المبيعات = (بيع المنتجات - الخصم) + (ربح الخدمات)' },
            { id: 'cost', label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50', formula: 'مجموع جملة تكلفة المنتجات فقط' },
            { id: 'profit', label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50', formula: 'صافي الربح = (ربح المنتجات - الخصم) + (ربح الخدمات)' },
            { id: 'items', label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50', formula: 'عدد القطع والخدمات المباعة' },
            { id: 'discounts', label: 'الخصومات', value: data.discounts, icon: Scissors, color: 'text-rose-600', bg: 'bg-rose-50', formula: 'مجموع الخصومات الممنوحة' }
          ].map((stat) => (
            <div key={stat.id} className="p-3 bg-white rounded-xl border border-slate-200 shadow-sm flex flex-col gap-1 relative group">
              <div className="flex justify-between items-start">
                <div className={`p-1.5 rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={16} /></div>
                <div className="relative"><Info size={12} className="text-slate-300 hover:text-[#0f172a] cursor-help" onMouseEnter={() => setHoveredTip(stat.id)} onMouseLeave={() => setHoveredTip(null)} />{hoveredTip === stat.id && <Tooltip title={stat.label} formula={stat.formula} />}</div>
              </div>
              <div><p className="text-[8px] font-black uppercase opacity-60">{stat.label}</p><p className="text-sm font-black truncate">{Math.round(stat.value)} ₪</p></div>
