              <Eye size={20} className="text-emerald-500" />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">كشف الأرقام المالية</span>
            </button>
          </div>
        )}

        {showFinancials && (
          <button onClick={() => setShowFinancials(false)} className="absolute top-2 left-2 z-30 p-2 bg-white/80 backdrop-blur-md text-slate-400 hover:text-rose-500 rounded-xl shadow-lg border border-slate-100 transition-all">
            <EyeOff size={16} />
          </button>
        )}
      </div>

      {/* 3. Dynamic Sections Container (Accordions) */}
      <div className="flex-1 overflow-y-auto custom-scrollbar space-y-4 pb-10">

        {/* Section A: All Sales Summary (Collapsible) */}
        <div className="bg-white border border-slate-200 rounded-[1.8rem] shadow-sm overflow-hidden">
