              <div className="p-3 bg-emerald-100 text-emerald-600 rounded-xl"><LayoutList size={20} /></div>
              <div className="text-right">
                <h3 className="font-black text-slate-900 text-sm">ملخص كافة المبيعات اليومية</h3>
