  const envUrl = (import.meta as any).env?.VITE_SUPABASE_URL;
  const envKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY;

  const url = storedUrl || envUrl || 'https://gpclqttogygmqzoemooz.supabase.co/';
  const key = storedKey || envKey || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdwY2xxdHRvZ3lnbXF6b2Vtb296Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3Njk1NDcyODYsImV4cCI6MjA4NTEyMzI4Nn0.iPltb4EZBhFUFriofeR3MJFM_rVXfF39zL9P82RRhIw';

  return {
    url: url.trim(),
    key: key.trim(),
    isValid: url && url.startsWith('https://') && key && key.length > 20
  };
};

