                        <div className={`p-2 rounded-xl ${expandedInvoiceId === inv.id ? 'bg-blue-600 text-white' : 'bg-white text-slate-400'}`}>
                          <FileText size={18} />
                        </div>
                        <div className="text-right">
                          <p className="font-mono text-[9px] text-slate-400">#{inv.id.slice(0, 8)}</p>
                          <p className="font-black text-[11px] text-slate-900">{new Date(inv.created_at).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-6">
                        <p className="font-black text-emerald-600 text-sm">{Math.round(inv.net_amount)} ₪</p>
                        <ChevronDown size={18} className={`text-slate-300 transition-transform ${expandedInvoiceId === inv.id ? 'rotate-180' : ''}`} />
                      </div>
                    </button>
                    {expandedInvoiceId === inv.id && (
                      <div className="p-4 bg-white border-t border-slate-100">
                        <div className="flex justify-between items-center text-xs mb-4">
                           <span className="text-slate-500 font-bold">صافي الربح لهذه الفاتورة:</span>
                           <span className="text-emerald-600 font-black">{Math.round(inv.profit)} ₪</span>
                        </div>
                        <table className="w-full text-right text-[10px]">
                           <thead><tr className="text-slate-400 font-black"><th>الصنف</th><th className="text-center">الكمية</th><th className="text-left">المجموع</th></tr></thead>
                           <tbody>
                              {inv.invoice_items.map((it: any) => (<tr key={it.id} className="border-b border-slate-50"><td className="py-2">{it.product_name} ({it.variant_name})</td><td className="text-center">x{it.quantity}</td><td className="text-left font-black">{Math.round(it.sale_price * it.quantity)} ₪</td></tr>))}
                           </tbody>
                        </table>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

