// PIN Entry Overlay Component
const PinOverlay: React.FC<{ expectedPin: string, onUnlock: () => void, pageLabel: string }> = ({ expectedPin, onUnlock, pageLabel }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);

  const handleKeyPress = (num: string) => {
    if (pin.length < 4) {
      const newPin = pin + num;
      setPin(newPin);
      if (newPin.length === 4) {
        if (newPin === expectedPin) {
          onUnlock();
        } else {
          setError(true);
          setTimeout(() => { setPin(''); setError(false); }, 600);
        }
      }
    }
  };

  const removeLast = () => setPin(prev => prev.slice(0, -1));

  return (
    <div className="absolute inset-0 z-[200] bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white overflow-hidden">
      <div className="max-w-xs w-full space-y-8 animate-in zoom-in duration-300">
        <div className="text-center space-y-4">
          <div className="inline-flex p-5 bg-white/5 rounded-full border border-white/10 text-emerald-500 mb-2">
            <Lock size={40} />
          </div>
          <h2 className="text-2xl font-black">قسم محمي</h2>
          <p className="text-slate-400 font-bold text-sm">يرجى إدخال رمز PIN للوصول إلى<br/><span className="text-white">"{pageLabel}"</span></p>
        </div>

        <div className="flex justify-center gap-4">
          {[0, 1, 2, 3].map(i => (
            <div key={i} className={`w-4 h-4 rounded-full border-2 transition-all duration-300 ${error ? 'border-rose-500 bg-rose-500 scale-125' : (pin.length > i ? 'bg-emerald-500 border-emerald-500 scale-110 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'border-white/20')}`} />
          ))}
        </div>

        <div className="grid grid-cols-3 gap-4 pt-4">
          {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(num => (
            <button key={num} onClick={() => handleKeyPress(num)} className="w-16 h-16 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center text-xl font-black hover:bg-white/10 active:scale-90 transition-all">{num}</button>
          ))}
          <div />
          <button onClick={() => handleKeyPress('0')} className="w-16 h-16 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center text-xl font-black hover:bg-white/10 active:scale-90 transition-all">0</button>
          <button onClick={removeLast} className="w-16 h-16 rounded-2xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center text-rose-500 hover:bg-rose-500 hover:text-white active:scale-90 transition-all"><Delete size={24} /></button>
        </div>
      </div>
    </div>
  );
};

// PageGuard for checking locks
const PageGuard: React.FC<{ children: React.ReactNode, pageId: string, pageLabel: string, settings: AppSettings | null }> = ({ children, pageId, pageLabel, settings }) => {
  const [unlocked, setUnlocked] = useState(false);
  const isLocked = settings?.protection_enabled && settings?.page_locks?.[pageId];

  // If page is not locked or security globally disabled, show content
  if (!isLocked || unlocked) return <>{children}</>;

  return (
    <PinOverlay 
      expectedPin={settings?.page_password || '1234'} 
      pageLabel={pageLabel} 
      onUnlock={() => setUnlocked(true)} 
    />
  );
};

