// New Auth Overlay Component (Mirroring Login.tsx style)
const PageAuthOverlay: React.FC<{ expectedPin: string, onUnlock: () => void, pageLabel: string }> = ({ expectedPin, onUnlock, pageLabel }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (password === expectedPin) {
      setTimeout(() => {
        onUnlock();
        setLoading(false);
      }, 500);
    } else {
      setTimeout(() => {
        setError('كلمة المرور غير صحيحة');
        setLoading(false);
      }, 500);
    }
  };

  return (
    <div className="absolute inset-0 z-[200] bg-[#0f172a] flex items-center justify-center p-6 overflow-hidden">
      {/* Decorative background elements */}
      <div className="fixed top-0 left-0 w-full h-full overflow-hidden pointer-events-none opacity-20">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-emerald-600 rounded-full blur-[120px]" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-600 rounded-full blur-[120px]" />
      </div>

      <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden relative z-10 border border-white/10 animate-in zoom-in duration-300">
        {/* Card Header */}
        <div className="p-10 text-center bg-slate-50 border-b border-slate-100">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-[#0f172a] rounded-[1.5rem] shadow-2xl shadow-slate-900/20 mb-6">
            <Lock className="text-emerald-500" size={36} />
          </div>
          <h2 className="text-2xl font-black text-[#0f172a] tracking-tight">قسم محمي</h2>
          <p className="text-slate-500 mt-2 font-bold italic">"{pageLabel}"</p>
        </div>

        {/* Form Content */}
        <div className="p-10">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="p-4 bg-rose-50 border-r-4 border-rose-500 text-rose-700 text-xs font-black animate-shake rounded-lg">
                {error}
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 mr-1 uppercase tracking-widest">كلمة مرور القسم</label>
              <div className="relative group">
                <input
                  type="password"
                  required
                  autoFocus
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-4 pr-12 py-5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-[#0f172a] focus:bg-white transition-all outline-none font-bold text-slate-900 placeholder:text-slate-300 text-center text-2xl tracking-[0.5em]"
                  placeholder="••••"
                />
                <ShieldAlert className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-[#0f172a] transition-colors" size={24} />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-5 bg-[#0f172a] text-white font-black text-lg rounded-2xl shadow-xl hover:bg-black active:scale-[0.98] transition-all flex items-center justify-center gap-3"
            >
              {loading ? (
                <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <>
                  <span>فتح القسم</span>
                  <ArrowLeft size={20} />
                </>
              )}
            </button>
          </form>

          <div className="mt-8 text-center">
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] opacity-50">
              Flyyti Page Protection
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

// PageGuard for checking locks
// Note: useState(false) inside PageGuard ensures that every time the component is mounted (route change), 
// it starts locked, requiring password for EACH visit.
const PageGuard: React.FC<{ children: React.ReactNode, pageId: string, pageLabel: string, settings: AppSettings | null }> = ({ children, pageId, pageLabel, settings }) => {
  const [unlocked, setUnlocked] = useState(false);
  const isLocked = settings?.protection_enabled && settings?.page_locks?.[pageId];

  // If page is not locked or security globally disabled, show content
  if (!isLocked || unlocked) return <>{children}</>;

  return (
    <PageAuthOverlay 
      expectedPin={settings?.page_password || '1234'} 
      pageLabel={pageLabel} 
      onUnlock={() => setUnlocked(true)} 
    />
  );
};

