const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  if (settings && !settings.login_protection_enabled) return <>{children}</>;
  const loggedUser = localStorage.getItem('flyyti_user');
  if (!loggedUser) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) setSettings(data);
    } catch (err) { console.error(err); }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) setConfigMissing(true);
    else fetchSettings();
  }, [fetchSettings]);

  if (configMissing) return (
    <div className="min-h-screen bg-[#0f172a] flex items-center justify-center p-6 text-white" dir="rtl">
      <div className="bg-white/5 backdrop-blur-xl p-10 rounded-[2.5rem] border border-white/10 w-full max-w-md space-y-8">
        <div className="text-center">
          <div className="w-20 h-20 bg-emerald-600 rounded-3xl flex items-center justify-center mx-auto mb-6"><Database size={36} /></div>
          <h1 className="text-3xl font-black">Flyyti Engine</h1>
          <p className="text-slate-400 mt-2">اتصال قاعدة البيانات</p>
        </div>
        <form onSubmit={(e: any) => { e.preventDefault(); const url = e.target.url.value; const key = e.target.key.value; if (url && key) saveSupabaseConfig(url, key); }} className="space-y-5">
          <input name="url" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none" placeholder="URL" />
          <input name="key" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none" placeholder="Key" />
          <button className="w-full py-5 bg-emerald-600 text-white font-black rounded-2xl">دخول</button>
        </form>
      </div>
    </div>
  );

  if (loading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-[#0f172a] gap-6">
      <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
      <p className="text-white font-black text-lg">جاري التحميل...</p>
    </div>
  );

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
        <Route path="/*" element={
          <ProtectedRoute settings={settings}>
            <Layout settings={settings}>
              <Routes>
                <Route path="/" element={<PageGuard pageId="pos" pageLabel="نقطة البيع" settings={settings}><POS /></PageGuard>} />
                <Route path="/daily-reports" element={<PageGuard pageId="daily_reports" pageLabel="التقارير اليومية" settings={settings}><DailyReports /></PageGuard>} />
                <Route path="/inventory" element={<PageGuard pageId="inventory" pageLabel="المخزون" settings={settings}><Inventory /></PageGuard>} />
                <Route path="/categories" element={<PageGuard pageId="categories" pageLabel="التصنيفات" settings={settings}><Categories /></PageGuard>} />
                <Route path="/expenses" element={<PageGuard pageId="expenses" pageLabel="المصاريف" settings={settings}><Expenses settings={settings} onUpdateSettings={fetchSettings} /></PageGuard>} />
                <Route path="/invoices" element={<PageGuard pageId="invoices" pageLabel="سجل الفواتير" settings={settings}><Invoices settings={settings} onUpdateSettings={fetchSettings} /></PageGuard>} />
                <Route path="/reports" element={<PageGuard pageId="reports" pageLabel="التقارير المالية" settings={settings}><GeneralReports /></PageGuard>} />
                <Route path="/security" element={<PageGuard pageId="security" pageLabel="إعدادات النظام" settings={settings}><Security settings={settings} onUpdate={fetchSettings} /></PageGuard>} />
              </Routes>
            </Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

export default App;

