// Persistent Page Guard using sessionStorage
const PageGuard: React.FC<{ children: React.ReactNode, pageId: string, pageLabel: string, settings: AppSettings | null }> = ({ children, pageId, pageLabel, settings }) => {
  // Use session state to persist "unlocked" status during current session
  const storageKey = `flyyti_unlocked_${pageId}`;
  const [isUnlocked, setIsUnlocked] = useState(() => {
    return sessionStorage.getItem(storageKey) === 'true';
  });

  const isProtectionActive = settings?.protection_enabled && settings?.page_locks?.[pageId];

  // If globally unlocked for this session or not locked in settings
  if (!isProtectionActive || isUnlocked) return <>{children}</>;

  const handleUnlock = () => {
    sessionStorage.setItem(storageKey, 'true');
    setIsUnlocked(true);
  };

  return (
    <PageAuthOverlay 
      expectedPin={settings?.page_password || '1234'} 
      pageLabel={pageLabel} 
      onUnlock={handleUnlock} 
    />
  );
};

