// Independent Page Guard Component
const PageGuard: React.FC<{ children: React.ReactNode, pageId: string, pageLabel: string, settings: AppSettings | null }> = ({ children, pageId, pageLabel, settings }) => {
  // مفتاح فريد لكل صفحة لضمان الاستقلالية التامة
  const sessionKey = `flyyti_access_granted_${pageId}`;

  // حالة محلية لمعرفة ما إذا كانت الصفحة قد فتحت في هذه الجلسة
  const [isUnlocked, setIsUnlocked] = useState(() => {
    return sessionStorage.getItem(sessionKey) === 'true';
  });

  // تحديد ما إذا كانت الصفحة تتطلب حماية أصلاً من الإعدادات
  const needsProtection = useMemo(() => {
    return settings?.protection_enabled && settings?.page_locks?.[pageId];
  }, [settings, pageId]);

  // إذا كانت الصفحة لا تحتاج حماية أو تم فتحها مسبقاً في هذه الجلسة، نعرض المحتوى
  if (!needsProtection || isUnlocked) {
    return <>{children}</>;
  }

  // دالة تُستدعى عند نجاح إدخال كلمة المرور
  const handleSuccess = () => {
    sessionStorage.setItem(sessionKey, 'true');
    setIsUnlocked(true);
  };

  return (
    <PageAuthOverlay 
      expectedPin={settings?.page_password || '1234'} 
      pageLabel={pageLabel} 
      onUnlock={handleSuccess} 
    />
  );
};

