// Full-Screen Authentication Overlay (Login Style)
const PageAuthOverlay: React.FC<{ expectedPin: string, onUnlock: () => void, pageLabel: string }> = ({ expectedPin, onUnlock, pageLabel }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (password === expectedPin) {
      setTimeout(() => {
        onUnlock();
        setLoading(false);
      }, 400);
    } else {
      setTimeout(() => {
        setError('رمز الدخول غير صحيح');
        setLoading(false);
        setPassword('');
      }, 300);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-[#0f172a] flex items-center justify-center p-6 overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none opacity-20">
        <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-emerald-600 rounded-full blur-[140px]" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-blue-600 rounded-full blur-[140px]" />
      </div>

      <div className="bg-white w-full max-w-md rounded-[3rem] shadow-2xl overflow-hidden relative z-10 border border-white/10 animate-in zoom-in duration-300">
        <div className="p-10 text-center bg-slate-50 border-b border-slate-100">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-[#0f172a] rounded-[1.8rem] shadow-2xl shadow-slate-900/20 mb-6">
            <Lock className="text-emerald-500" size={36} />
          </div>
          <h2 className="text-2xl font-black text-[#0f172a] tracking-tight">منطقة محمية</h2>
          <div className="mt-2 px-4 py-1.5 bg-emerald-50 text-emerald-600 rounded-xl inline-block text-[11px] font-black uppercase tracking-widest border border-emerald-100">
            {pageLabel}
          </div>
        </div>

        <div className="p-10">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="p-4 bg-rose-50 border-r-4 border-rose-500 text-rose-700 text-xs font-black animate-shake rounded-xl flex items-center gap-2">
                <ShieldAlert size={16} />
                {error}
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 mr-2 uppercase tracking-[0.2em]">رمز مرور الصفحة</label>
              <div className="relative group">
                <input
                  type="password"
                  required
                  autoFocus
                  inputMode="numeric"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-4 pr-12 py-5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-[#0f172a] focus:bg-white transition-all outline-none font-black text-slate-900 text-center text-3xl tracking-[0.5em] placeholder:text-slate-200"
                  placeholder="••••"
                />
                <ShieldCheck className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-[#0f172a] transition-colors" size={24} />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-5 bg-[#0f172a] text-white font-black text-lg rounded-2xl shadow-xl hover:bg-black active:scale-[0.98] transition-all flex items-center justify-center gap-3 group"
            >
              {loading ? (
                <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <>
                  <span>تأكيد الدخول</span>
                  <ArrowLeft size={20} className="group-hover:-translate-x-1 transition-transform" />
                </>
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

// Strict Page Guard (No Session Storage)
const PageGuard: React.FC<{ children: React.ReactNode, pageId: string, pageLabel: string, settings: AppSettings | null }> = ({ children, pageId, pageLabel, settings }) => {
  // حالة "فتح القفل" محلية فقط. بمجرد الخروج من الصفحة (unmount) يتم تدمير الحالة.
  const [isUnlocked, setIsUnlocked] = useState(false);

  const needsProtection = useMemo(() => {
    return settings?.protection_enabled && settings?.page_locks?.[pageId];
  }, [settings, pageId]);

  // إذا كانت الصفحة لا تحتاج حماية، نعرض المحتوى فوراً
  if (!needsProtection || isUnlocked) {
    return <>{children}</>;
  }

  return (
    <PageAuthOverlay 
      expectedPin={settings?.page_password || '1234'} 
      pageLabel={pageLabel} 
      onUnlock={() => setIsUnlocked(true)} 
    />
  );
};

const NavItem: React.FC<{ to: string, icon: any, label: string, onClick?: () => void }> = ({ to, icon: Icon, label, onClick }) => {
  const location = useLocation();
  const isActive = location.pathname === to;

  return (
    <Link 
      to={to} 
      onClick={onClick} 
      className={`flex items-center gap-4 px-6 py-5 rounded-2xl transition-all duration-300 group ${isActive ? 'bg-emerald-600 text-white shadow-xl shadow-emerald-900/40' : 'text-slate-300 hover:bg-white/5 hover:text-white border border-transparent hover:border-white/10'}`}
    >
      <Icon size={24} className={`${isActive ? 'text-white' : 'text-slate-500 group-hover:text-emerald-400'}`} />
      <span className="font-black text-lg tracking-tight">{label}</span>
    </Link>
  );
};

const Layout: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(e => console.error(e));
      setIsFullscreen(true);
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
        setIsFullscreen(false);
      }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('flyyti_user');
    sessionStorage.clear(); // مسح كافة البيانات المؤقتة
    window.location.href = '#/login'; // إجبار العودة لصفحة الدخول الرئيسية
    window.location.reload(); // تحديث الصفحة لضمان تصفير كافة الحالات
  };

  const pageTitle = location.pathname === '/' ? 'نقطة البيع' : 
                   location.pathname === '/inventory' ? 'المخزون' :
                   location.pathname === '/daily-reports' ? 'التقارير اليومية' : 
                   location.pathname === '/expenses' ? 'الإدارة المالية' : 'لوحة التحكم';

  return (
    <div className="h-screen w-screen bg-[#f8fafc] flex flex-col overflow-hidden font-['Tajawal']" dir="rtl">
      <header className="h-20 bg-[#0f172a] border-b border-white/10 flex items-center justify-between px-6 shrink-0 z-[100] no-print">
        <div className="flex items-center gap-6">
          <button onClick={() => setSidebarOpen(true)} className="p-3 bg-emerald-600 text-white rounded-2xl shadow-lg hover:bg-emerald-500 transition-all active:scale-90"><Menu size={28} /></button>
          <div className="flex items-center gap-3">
            <FlyytiLogo className="w-10 h-10" />
            <h1 className="text-xl font-black text-white hidden sm:block">Flyyti Mobile POS</h1>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className="bg-emerald-500/10 text-emerald-500 px-4 py-2 rounded-xl text-xs sm:text-sm font-black border border-emerald-500/20">{pageTitle}</span>
          <button onClick={toggleFullscreen} className="w-10 h-10 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center text-slate-400 hover:text-white transition-all">{isFullscreen ? <Minimize2 size={22} /> : <Maximize2 size={22} />}</button>
          <div className="w-10 h-10 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center text-slate-400"><ShieldCheck size={22} /></div>
        </div>
      </header>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {children}
      </main>

      {sidebarOpen && (
        <>
          <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[150]" onClick={() => setSidebarOpen(false)} />
          <div className="fixed inset-y-0 right-0 w-80 bg-[#0f172a] z-[151] flex flex-col animate-slide-in-right border-l border-white/10">
            <div className="p-8 border-b border-white/10 flex items-center justify-between">
              <div className="flex items-center gap-3"><FlyytiLogo className="w-12 h-12" /><span className="font-black text-white text-xl">القائمة</span></div>
              <button onClick={() => setSidebarOpen(false)} className="text-slate-400 hover:text-white"><X size={28} /></button>
            </div>
            <nav className="flex-1 p-6 space-y-2 overflow-y-auto custom-scrollbar">
              <NavItem to="/" icon={ShoppingCart} label="نقطة البيع" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/daily-reports" icon={LayoutDashboard} label="التقارير اليومية" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/inventory" icon={Package} label="المخزون" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/categories" icon={Tags} label="الأقسام" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/expenses" icon={Wallet} label="المصاريف" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/invoices" icon={FileText} label="سجل الفواتير" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/reports" icon={PieChart} label="التقارير المالية" onClick={() => setSidebarOpen(false)} />
              <NavItem to="/security" icon={ShieldCheck} label="إعدادات النظام" onClick={() => setSidebarOpen(false)} />
            </nav>
            <div className="p-8 border-t border-white/10">
              <button onClick={handleLogout} className="w-full py-5 text-rose-400 bg-rose-400/10 rounded-2xl font-black flex items-center justify-center gap-3 border border-rose-400/20 transition-all hover:bg-rose-500 hover:text-white"><LogOut size={22} /> خروج نهائي</button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  if (settings && !settings.login_protection_enabled) return <>{children}</>;
  const loggedUser = localStorage.getItem('flyyti_user');
  if (!loggedUser) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) setSettings(data);
    } catch (err) { console.error(err); }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) setConfigMissing(true);
    else fetchSettings();
  }, [fetchSettings]);

  if (configMissing) return (
    <div className="min-h-screen bg-[#0f172a] flex items-center justify-center p-6 text-white" dir="rtl">
      <div className="bg-white/5 backdrop-blur-xl p-10 rounded-[2.5rem] border border-white/10 w-full max-w-md space-y-8">
        <div className="text-center">
          <div className="w-20 h-20 bg-emerald-600 rounded-3xl flex items-center justify-center mx-auto mb-6"><Database size={36} /></div>
          <h1 className="text-3xl font-black">Flyyti Engine</h1>
          <p className="text-slate-400 mt-2">اتصال قاعدة البيانات</p>
        </div>
        <form onSubmit={(e: any) => { e.preventDefault(); const url = e.target.url.value; const key = e.target.key.value; if (url && key) saveSupabaseConfig(url, key); }} className="space-y-5">
          <input name="url" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none" placeholder="URL" />
          <input name="key" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none" placeholder="Key" />
          <button className="w-full py-5 bg-emerald-600 text-white font-black rounded-2xl">دخول</button>
        </form>
      </div>
    </div>
  );

  if (loading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-[#0f172a] gap-6">
      <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
      <p className="text-white font-black text-lg">جاري التحميل...</p>
    </div>
  );

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
        <Route path="/*" element={
          <ProtectedRoute settings={settings}>
            <Layout settings={settings}>
              <Routes>
                <Route path="/" element={<PageGuard pageId="pos" pageLabel="نقطة البيع" settings={settings}><POS /></PageGuard>} />
                <Route path="/daily-reports" element={<PageGuard pageId="daily_reports" pageLabel="التقارير اليومية" settings={settings}><DailyReports /></PageGuard>} />
                <Route path="/inventory" element={<PageGuard pageId="inventory" pageLabel="المخزون" settings={settings}><Inventory /></PageGuard>} />
                <Route path="/categories" element={<PageGuard pageId="categories" pageLabel="التصنيفات" settings={settings}><Categories /></PageGuard>} />
                <Route path="/expenses" element={<PageGuard pageId="expenses" pageLabel="المصاريف" settings={settings}><Expenses settings={settings} onUpdateSettings={fetchSettings} /></PageGuard>} />
                <Route path="/invoices" element={<PageGuard pageId="invoices" pageLabel="سجل الفواتير" settings={settings}><Invoices settings={settings} onUpdateSettings={fetchSettings} /></PageGuard>} />
                <Route path="/reports" element={<PageGuard pageId="reports" pageLabel="التقارير المالية" settings={settings}><GeneralReports /></PageGuard>} />
                <Route path="/security" element={<PageGuard pageId="security" pageLabel="إعدادات النظام" settings={settings}><Security settings={settings} onUpdate={fetchSettings} /></PageGuard>} />
              </Routes>
            </Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

export default App;

