    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    const { data: ex } = await supabase.from('expenses').select('*').order('date', { ascending: false });
    const { data: pu } = await supabase.from('purchases').select('*').order('date', { ascending: false });
    const { data: inv } = await supabase.from('invoices').select('profit');
