export const printThermalReceipt = (invoice: any) => {
  const printWindow = window.open('', '_blank');
  if (!printWindow) return;

  const date = new Date(invoice.created_at);
  const formattedDate = date.toLocaleDateString('en-GB').replace(/\//g, '-');
  const formattedTime = date.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', hour12: false });

  // Handle both database-style (invoice_items) and local-style (items) structures
  const items = invoice.invoice_items || invoice.items || [];
  const services = invoice.extra_services || invoice.services || [];

  const itemsHtml = items.map((it: any) => `
    <div class="item-row">
      <div class="item-name">${it.product_name}<br/><small>${it.variant_name || ''}</small></div>
      <div class="item-qty">${it.quantity}</div>
      <div class="item-price">${Math.round(it.sale_price * it.quantity)}</div>
    </div>
  `).join('');

  const servicesHtml = services.map((ser: any) => `
    <div class="item-row">
      <div class="item-name">${ser.name || ser.product_name}<br/><small>خدمة إضافية</small></div>
      <div class="item-qty">${ser.quantity}</div>
      <div class="item-price">${Math.round(ser.sale_price * ser.quantity)}</div>
    </div>
  `).join('');

  printWindow.document.write(`
    <html dir="rtl">
    <head>
      <meta charset="UTF-8">
      <title>فاتورة #${invoice.id?.slice(0, 8)}</title>
      <style>
        @font-face {
          font-family: 'Tajawal';
          font-style: normal;
          font-weight: 400;
          src: local('Tajawal'), url(https://fonts.gstatic.com/s/tajawal/v9/I0at66FPh9Jp7Xo4JQ.woff2) format('woff2');
        }
        @page { 
          size: 58mm auto; 
          margin: 0; 
        }
        body { 
          font-family: 'Tajawal', 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; 
          width: 48mm; /* Adjusting for 58mm roll width minus margins */
          margin: 0 auto; 
          padding: 4mm 2mm; 
          font-size: 11px;
          line-height: 1.3;
          color: #000;
        }
        .center { text-align: center; }
        .bold { font-weight: bold; }
        .divider { border-top: 1px dashed #000; margin: 4px 0; width: 100%; }
        .header-title { font-size: 14px; margin-bottom: 2px; }
        .item-row { display: flex; justify-content: space-between; margin-bottom: 4px; border-bottom: 0.5px solid #eee; padding-bottom: 2px; }
        .item-row:last-child { border-bottom: none; }
        .item-name { flex: 2; text-align: right; word-wrap: break-word; }
        .item-qty { flex: 0.5; text-align: center; }
        .item-price { flex: 1; text-align: left; }
        .total-section { margin-top: 8px; }
        .total-row { display: flex; justify-content: space-between; margin-bottom: 2px; }
        .grand-total { font-size: 15px; border-top: 1px dashed #000; padding-top: 4px; margin-top: 4px; }
        .footer { font-size: 9px; margin-top: 12px; font-weight: bold; }
        small { font-size: 9px; color: #555; }
        @media print {
          body { width: 48mm; }
        }
      </style>
    </head>
    <body>
      <div class="center">
        <div class="header-title bold">Flyyti Mobile</div>
        <div class="bold">بيع وصيانة الجوالات</div>
        <div>نابلس – رأس العين</div>
        <div class="divider"></div>
        <div class="bold">فاتورة رقم: #${invoice.id?.slice(0, 8)}</div>
        <div>التاريخ: ${formattedDate}</div>
        <div>الوقت: ${formattedTime}</div>
        <div class="divider"></div>
      </div>

      <div class="item-row bold" style="border-bottom: 1px solid #000;">
        <div class="item-name">الصنف</div>
        <div class="item-qty">كم</div>
        <div class="item-price">السعر</div>
      </div>

      ${itemsHtml}
      ${servicesHtml}

      <div class="total-section">
        <div class="divider"></div>
        <div class="total-row">
          <span>المجموع:</span>
          <span>${Math.round(invoice.total_amount || 0)} ₪</span>
        </div>
        <div class="total-row">
          <span>الخصم:</span>
          <span>${Math.round(invoice.discount || 0)} ₪</span>
        </div>
        <div class="total-row grand-total bold">
          <span>الإجمالي:</span>
          <span>${Math.round(invoice.net_amount || 0)} ₪</span>
        </div>
      </div>

      <div class="center footer">
        <div class="divider"></div>
        <div class="bold">شكرًا لزيارتكم ❤</div>
        <div style="margin-top: 4px; line-height: 1.2;">الفاتورة غير قابلة للاسترجاع او التبديل بعد 24 ساعة</div>
      </div>

      <script>
        window.onload = function() {
          window.print();
          setTimeout(function() { window.close(); }, 500);
        };
      </script>
    </body>
    </html>
  `);
  printWindow.document.close();
};

