import React, { useState, useEffect, useCallback } from 'react';
import { 
  FileText, 
  Edit2, 
  Trash2, 
  Printer, 
  Search, 
  X, 
  Save, 
  Plus, 
  Minus, 
  Search as SearchIcon,
  ShoppingBag,
  CheckCircle2,
  AlertTriangle,
  Calendar as CalendarIcon,
  ChevronDown,
  Filter,
  RefreshCw,
  Clock,
  Layers,
  CalendarDays,
  CalendarRange,
  ChevronLeft
} from 'lucide-react';
import { supabase } from '../supabase';
import type { AppSettings } from '../types';
import { printThermalReceipt } from '../utils/printThermal';

type FilterMode = 'day' | 'month' | 'year';

const Invoices: React.FC<{ settings: AppSettings | null, onUpdateSettings: () => void }> = ({ settings, onUpdateSettings }) => {
  const [invoices, setInvoices] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  // Delete Confirmation State
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTargetId, setDeleteTargetId] = useState<string | null>(null);

  const [filterMode, setFilterMode] = useState<FilterMode>('day');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth());
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());

  const fetchInvoices = useCallback(async () => {
    setLoading(true);
    let start, end;
    if (filterMode === 'day') { start = `${selectedDate}T00:00:00.000Z`; end = `${selectedDate}T23:59:59.999Z`; } 
    else if (filterMode === 'month') { const firstDay = new Date(selectedYear, selectedMonth, 1); const lastDay = new Date(selectedYear, selectedMonth + 1, 0); start = firstDay.toISOString(); end = lastDay.toISOString().split('T')[0] + 'T23:59:59.999Z'; } 
    else { const firstDay = new Date(selectedYear, 0, 1); const lastDay = new Date(selectedYear, 11, 31); start = firstDay.toISOString(); end = lastDay.toISOString().split('T')[0] + 'T23:59:59.999Z'; }

    const { data, error } = await supabase.from('invoices').select(`*, invoice_items (*), extra_services (*)`).gte('created_at', start).lte('created_at', end).order('created_at', { ascending: false });
    if (!error) setInvoices(data || []);
    setLoading(false);
  }, [filterMode, selectedDate, selectedMonth, selectedYear]);

  useEffect(() => { fetchInvoices(); }, [fetchInvoices]);

  const requestDelete = (id: string) => {
    setDeleteTargetId(id);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async () => {
    if (!deleteTargetId) return;
    await supabase.from('invoices').delete().eq('id', deleteTargetId);
    setShowDeleteConfirm(false);
    setDeleteTargetId(null);
    fetchInvoices();
  };

  const handlePrint = (invoice: any) => {
    printThermalReceipt(invoice);
  };

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-6 overflow-hidden font-['Tajawal']" dir="rtl">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <FileText className="text-slate-900" />
          سجل الفواتير
        </h2>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
           <div className="relative flex-1 md:flex-none">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="بحث برقم الفاتورة..." 
                className="w-full md:w-64 pr-12 pl-4 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold outline-none focus:border-slate-900"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col flex-1 relative">
        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-900 text-white z-10">
              <tr>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-right">المعرف / التوقيت</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">إجمالي القيمة</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الخصم</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">صافي المدفوع</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الربح</th>
