بصفتي مهندس برمجيات أول، سأقوم بإعادة بناء هيكلية قاعدة البيانات (SQL) والربط مع Supabase لضمان أقصى درجات الأداء والاستقرار لنظام **Flyyti Mobile POS**.

### المواصفات الفنية للتحديث:
1.  **SQL Rebuild**: هيكلية متطورة تعتمد على `UUID` للمفاتيح الأساسية، مع علاقات متينة تضمن سلامة البيانات (Cascading Deletes) وفهارس (Indexes) سريعة جداً للبحث بالباركود والوقت.
2.  **Robust Supabase Client**: تحديث ملف `supabase.ts` ليكون المحرك المركزي للاتصال، مع دعم استرداد الإعدادات من `localStorage` أو المتغيرات البيئية، وضمان عدم انقطاع الجلسة.
3.  **RLS Policies**: إعداد سياسات أمان تسمح بالوصول العام (Public) لتسهيل التشغيل في البيئات المحلية والمحمولة دون تعقيدات تسجيل الدخول لكل طلب.

---

### 1. إعادة بناء قاعدة البيانات (SQL)
قم بنسخ هذا الكود بالكامل وصقه في **Supabase SQL Editor** ثم اضغط **Run**:

```sql
-- Flyyti Mobile POS - الـهيكلية الـمطورة V3.0
-- تـنبيه: هـذا الـسكربت يـقوم بـحذف الـجداول الـقديمة وإعـادة بـنائها

-- 1. تصفية الجداول
DROP TABLE IF EXISTS extra_services CASCADE;
DROP TABLE IF EXISTS invoice_items CASCADE;
DROP TABLE IF EXISTS invoices CASCADE;
DROP TABLE IF EXISTS expenses CASCADE;
DROP TABLE IF EXISTS purchases CASCADE;
DROP TABLE IF EXISTS variants CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS settings CASCADE;

-- 2. إعدادات النظام والأمان
CREATE TABLE settings (
    id INTEGER PRIMARY KEY DEFAULT 1,
    username TEXT NOT NULL DEFAULT 'admin',
    password TEXT NOT NULL DEFAULT 'admin',
    page_password TEXT NOT NULL DEFAULT '1234',
    capital DECIMAL(15,2) DEFAULT 0,
    savings DECIMAL(15,2) DEFAULT 0,
    protection_enabled BOOLEAN DEFAULT TRUE,
    login_protection_enabled BOOLEAN DEFAULT TRUE,
    page_locks JSONB DEFAULT '{
        "pos": false, 
        "daily_reports": true, 
        "inventory": true, 
        "categories": true, 
        "expenses": true, 
        "invoices": true, 
        "reports": true, 
        "security": true
    }',
    profit_shares JSONB DEFAULT '{
        "mujahed": 25, 
        "abboud": 25, 
        "shop": 40, 
        "special": 10
    }',
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT single_row CHECK (id = 1)
);

-- إدراج بيانات المصنع
INSERT INTO settings (id, username, password, page_password) 
VALUES (1, 'admin', 'admin', '1234')
ON CONFLICT (id) DO NOTHING;

-- 3. هيكلية المخزون
CREATE TABLE categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    parent_id UUID REFERENCES categories(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE products (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    barcode TEXT UNIQUE,
    category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
    sub_category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
    supplier TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE variants (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    name TEXT NOT NULL DEFAULT 'افتراضي',
    cost_price DECIMAL(15,2) DEFAULT 0,
    sale_price DECIMAL(15,2) DEFAULT 0,
    stock_quantity INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 4. المبيعات (المحرك الرئيسي)
CREATE TABLE invoices (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    total_amount DECIMAL(15,2) NOT NULL DEFAULT 0,
    discount DECIMAL(15,2) DEFAULT 0,
    net_amount DECIMAL(15,2) NOT NULL DEFAULT 0,
    total_cost DECIMAL(15,2) DEFAULT 0,
    profit DECIMAL(15,2) DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE invoice_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    invoice_id UUID NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
    variant_id UUID REFERENCES variants(id) ON DELETE SET NULL,
    product_name TEXT NOT NULL,
    variant_name TEXT,
    quantity INTEGER NOT NULL DEFAULT 1,
    cost_price DECIMAL(15,2) NOT NULL,
    sale_price DECIMAL(15,2) NOT NULL
);

CREATE TABLE extra_services (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    invoice_id UUID NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    cost_price DECIMAL(15,2) NOT NULL DEFAULT 0,
    sale_price DECIMAL(15,2) NOT NULL DEFAULT 0,
    quantity INTEGER DEFAULT 1
);

-- 5. المالية والمشتريات
CREATE TABLE expenses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    type TEXT NOT NULL,
    amount DECIMAL(15,2) NOT NULL,
    date DATE DEFAULT CURRENT_DATE,
    note TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE purchases (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    amount DECIMAL(15,2) NOT NULL,
    supplier TEXT,
    date DATE DEFAULT CURRENT_DATE,
    note TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 6. فهارس السرعة (Performance Indexes)
CREATE INDEX idx_products_barcode ON products(barcode);
CREATE INDEX idx_invoices_date ON invoices(created_at);
CREATE INDEX idx_variants_pid ON variants(product_id);

-- 7. تفعيل الوصول العام (Row Level Security)
ALTER TABLE settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON settings FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON categories FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON products FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE variants ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON variants FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON invoices FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE invoice_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON invoice_items FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE extra_services ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON extra_services FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE expenses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON expenses FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE purchases ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public" ON purchases FOR ALL USING (true) WITH CHECK (true);
```

