             </div>
             <div className="flex gap-3">
                <button 
                  onClick={confirmDeleteAction}
                  className="flex-1 py-4 bg-rose-500 text-white font-black rounded-2xl shadow-lg shadow-rose-200 active:scale-95 transition-all"
                >
                  نعم، حذف
                </button>
                <button 
                  onClick={() => setShowDeleteConfirm(false)}
                  className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl active:scale-95 transition-all"
                >
                  إلغاء
                </button>
             </div>
          </div>
        </div>
      )}

      {/* Unified Modal (Add/Edit) */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl shadow-xl text-white ${modalMode === 'add' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-blue-600 shadow-blue-200'}`}>
                  {modalMode === 'add' ? <Plus size={28} /> : <Edit3 size={28} />}
                </div>
                <h3 className="text-xl font-black text-slate-900">{modalMode === 'add' ? 'إضافة صنف جديد' : 'تعديل بيانات الصنف'}</h3>
              </div>
              <button onClick={() => setShowModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar max-h-[70vh]">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم الصنف *</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.name} onChange={(e) => setForm({...form, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">الباركود</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.barcode} onChange={(e) => setForm({...form, barcode: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">المورد</label>
                  <div className="relative">
                    <input type="text" className="w-full p-4 pr-12 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.supplier} onChange={(e) => setForm({...form, supplier: e.target.value})} />
                    <Truck className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الرئيسي</label>
                  <select 
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all" 
                    value={form.category_id} 
                    onChange={(e) => setForm({...form, category_id: e.target.value, sub_category_id: ''})}
                  >
                    <option value="">اختر القسم الرئيسي...</option>
                    {mainCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الفرعي</label>
                  <select 
                    disabled={!form.category_id}
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all disabled:opacity-50" 
                    value={form.sub_category_id} 
                    onChange={(e) => setForm({...form, sub_category_id: e.target.value})}
                  >
                    <option value="">اختر القسم الفرعي...</option>
                    {subCategoriesForForm.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-xs font-black text-slate-900 uppercase tracking-widest">تخصيص الأنواع والكميات</p>
                  <button onClick={() => setForm({...form, variants: [...form.variants, { id: undefined, name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]})} className="px-5 py-2.5 bg-blue-50 text-blue-600 font-black rounded-xl text-xs flex items-center gap-2 border border-blue-100 transition-all hover:bg-blue-100">
                    <Plus size={16} /> إضافة نوع
                  </button>
                </div>
                <div className="space-y-4">
                  {form.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-3 p-5 bg-slate-50 rounded-3xl border-2 border-slate-100 relative group">
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 mr-2">اسم النوع</label>
                        <input placeholder="اسم النوع" className="w-full p-3 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.name} onChange={(e) => { const vs = [...form.variants]; vs[idx].name = e.target.value; setForm({...form, variants: vs}); }} />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black text-slate-400 mr-2">التكلفة (₪)</label>
                         <input type="number" lang="en" dir="ltr" inputMode="decimal" className="w-full p-3 bg-white rounded-xl border border-slate-200 font-black text-xs appearance-none" value={v.cost_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].cost_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black text-emerald-600 mr-2">البيع (₪)</label>
                         <input type="number" lang="en" dir="ltr" inputMode="decimal" className="w-full p-3 bg-white rounded-xl border-2 border-emerald-100 text-emerald-600 font-black text-xs appearance-none" value={v.sale_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].sale_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black text-slate-400 mr-2">الكمية</label>
                         <input type="number" lang="en" dir="ltr" inputMode="numeric" className="w-full p-3 bg-white rounded-xl border border-slate-200 font-black text-xs appearance-none" value={v.stock_quantity || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].stock_quantity = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      </div>
                      <div className="flex items-center justify-end pt-5">
                        {form.variants.length > 1 && (
                          <button onClick={() => setForm({...form, variants: form.variants.filter((_, i) => i !== idx)})} className="p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors">
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3 text-amber-600">
                <AlertCircle size={20} />
                <p className="text-xs font-black">سيتم حفظ التغييرات فوراً في المخزون.</p>
              </div>
              <button 
                onClick={handleSave}
                disabled={!form.name || saving}
                className={`px-12 py-4.5 text-white font-black text-lg rounded-[1.8rem] shadow-2xl flex items-center gap-3 transition-all active:scale-95 ${modalMode === 'add' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} />}
                <span>{saving ? 'جاري الحفظ...' : modalMode === 'add' ? 'إضافة الصنف' : 'تحديث البيانات'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingBag,
  X,
  CheckCircle2,
  Loader2,
  PlusCircle,
  Barcode,
  Layers,
  Printer,
  AlertCircle,
  AlertTriangle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';
import { printThermalReceipt } from '../utils/printThermal';
import { playScanBeep } from '../utils/audio';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(true);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [selectedProductForVariants, setSelectedProductForVariants] = useState<any>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  // تنبيه تجاوز المخزون
  const [stockError, setStockError] = useState<{id: string, msg: string} | null>(null);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState<number | string>(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<any>(null);
  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
    setTimeout(() => searchInputRef.current?.focus(), 500);
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const triggerStockError = (id: string) => {
    setStockError({ id, msg: "لا يمكن إضافة أكثر من الكمية المتوفرة" });
    setTimeout(() => setStockError(null), 2500);
  };

  const addToCart = (variant: Variant, product: any) => {
    // 1. التأكد أن الصنف متوفر أصلاً
    if (variant.stock_quantity <= 0) return;

    // 2. التحقق من الكمية الحالية في السلة
    const existingInCart = cart.find(item => item.variant_id === variant.id);
    const currentQtyInCart = existingInCart ? existingInCart.quantity : 0;

    if (currentQtyInCart + 1 > variant.stock_quantity) {
      triggerStockError(variant.id);
      return;
    }

    playScanBeep();
    setIsCartOpen(true);
    setCart(prev => {
      if (existingInCart) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
    setSelectedProductForVariants(null);
    setTimeout(() => searchInputRef.current?.focus(), 100);
  };

  const handleProductClick = (product: any) => {
    if (!product.variants || product.variants.length === 0) return;

    // تصفية الخيارات المتوفرة فقط
    const availableVariants = product.variants.filter((v: any) => v.stock_quantity > 0);

    if (availableVariants.length === 0) return;

    if (availableVariants.length === 1) {
      addToCart(availableVariants[0], product);
    } else {
      setSelectedProductForVariants(product);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && searchTerm.trim()) {
      const barcode = searchTerm.trim();
      const exactMatch = products.find(p => p.barcode === barcode);
      if (exactMatch) {
        handleProductClick(exactMatch);
        setSearchTerm('');
      }
    }
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    playScanBeep();
    setIsCartOpen(true);
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
    setTimeout(() => searchInputRef.current?.focus(), 100);
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);

        // التحقق من المخزون عند زيادة الكمية من السلة
        if (delta > 0 && variantId) {
          const product = products.find(p => p.variants.some((v: any) => v.id === variantId));
          const variant = product?.variants.find((v: any) => v.id === variantId);
          if (variant && newQty > variant.stock_quantity) {
             triggerStockError(variantId);
             return item;
          }
        }

        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const discNum = Number(discount) || 0;
    const netAmount = Math.max(0, subtotal - discNum);
    return { subtotal, netAmount };
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    try {
      const { subtotal, netAmount } = calculateTotals();
      const discNum = Number(discount) || 0;
      const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);

      const { data: invoice, error: invError } = await supabase.from('invoices').insert({
        total_amount: subtotal, discount: discNum, net_amount: netAmount, total_cost: totalCost, profit: netAmount - totalCost
      }).select().single();

      if (invError) throw invError;

      const items = cart.filter(c => c.type === 'product');
      const services = cart.filter(c => c.type === 'service');

      if (items.length > 0) {
        await supabase.from('invoice_items').insert(items.map(item => ({
          invoice_id: invoice.id, variant_id: item.variant_id, product_name: item.product_name, variant_name: item.variant_name, quantity: item.quantity, cost_price: item.cost_price, sale_price: item.sale_price
        })));
        for (const item of items) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }
      if (services.length > 0) {
        await supabase.from('extra_services').insert(services.map(ser => ({
          invoice_id: invoice.id, name: ser.product_name, cost_price: ser.cost_price, sale_price: ser.sale_price, quantity: ser.quantity
        })));
      }

      setLastInvoice({ ...invoice, invoice_items: items, extra_services: services });
      setIsCartOpen(false);
      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      fetchData();
    } catch (e) { alert("خطأ في إتمام الطلب"); } finally { setIsProcessing(false); }
  };

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      // 1. البحث النصي
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));

      // 2. الفلترة حسب القسم
      const matchMainCat = selectedMainCat ? p.category_id === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? p.sub_category_id === selectedSubCat : true;

      // 3. قاعدة المخزون: إخفاء الأصناف التي مجموع مخزونها 0 تماماً
      const totalStock = p.variants?.reduce((s: number, v: any) => s + v.stock_quantity, 0) || 0;
      const hasStock = totalStock > 0;

      return matchSearch && matchMainCat && matchSubCat && hasStock;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);
  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row h-full font-['Tajawal'] bg-[#f8fafc] overflow-hidden" dir="rtl">

      {/* تنبيه تجاوز المخزون (Floating Toast) */}
      {stockError && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[400] bg-rose-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-4 duration-300">
          <AlertTriangle size={20} className="animate-pulse" />
          <span className="font-black text-sm">{stockError.msg}</span>
        </div>
      )}

      <aside className="hidden lg:flex flex-col w-44 shrink-0 overflow-y-auto custom-scrollbar p-5 gap-2 z-10">
        <div className="mb-2 px-1 shrink-0"><p className="text-[#0f172a] font-black text-[9px] uppercase tracking-widest opacity-30">الأقسام</p></div>
        <button onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }} className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${!selectedMainCat ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-transparent border-slate-200 text-slate-500'}`}>كافة الأصناف</button>
        {mainCategories.map(cat => (
          <button key={cat.id} onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }} className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${selectedMainCat === cat.id ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-transparent border-slate-200 text-slate-500'}`}>{cat.name}</button>
        ))}
      </aside>

      <div className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] border-r border-slate-200 overflow-hidden relative">
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm shrink-0">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input ref={searchInputRef} type="text" placeholder="البحث بالاسم أو الباركود..." className="w-full pr-14 pl-14 py-4 bg-slate-50 border-2 border-slate-300 focus:border-[#0f172a] rounded-[1.5rem] outline-none font-black text-lg transition-all" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} onKeyDown={handleKeyDown} />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-[#0f172a]" size={24} />
              <Barcode className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-500 transition-colors" size={24} />
            </div>
            <div className="flex gap-2 w-full sm:w-auto">
              <button onClick={() => setShowExtraModal(true)} className="px-6 py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-all flex-1 shadow-lg"><PlusCircle size={20} /><span>خدمة</span></button>
              <button onClick={() => setIsCartOpen(!isCartOpen)} className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-[#0f172a] border-slate-300'}`}><ShoppingBag size={24} /></button>
            </div>
          </div>
          {selectedMainCat && (
            <div className="flex items-center gap-2 overflow-x-auto mt-4 pb-2 no-scrollbar border-t border-slate-100 pt-4">
              {subCategories.map(sub => (
                <button key={sub.id} onClick={() => setSelectedSubCat(sub.id)} className={`px-5 py-2.5 rounded-xl font-black text-[10px] whitespace-nowrap border-2 transition-all ${selectedSubCat === sub.id ? 'bg-[#0f172a] text-white' : 'bg-transparent text-slate-500 border-slate-200'}`}>{sub.name}</button>
              ))}
            </div>
          )}
        </div>

        <div className="p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">
          {filteredProducts.map(p => {
            const totalStock = p.variants?.reduce((s: number, v: any) => s + v.stock_quantity, 0) || 0;

            return (
              <button 
                key={p.id} 
                onClick={() => handleProductClick(p)} 
                className="group bg-white p-5 rounded-[1.8rem] border-2 border-slate-200 hover:border-emerald-600 hover:shadow-2xl transition-all duration-300 text-right flex flex-col gap-3 relative h-fit active:scale-95 shadow-sm"
              >
                <div className="flex justify-between items-center"><span className={`text-[9px] font-black px-2 py-1 rounded-lg bg-slate-50 text-slate-500 border border-slate-100`}>{totalStock} قطعة</span><Plus size={18} className="text-slate-300 group-hover:text-emerald-600" /></div>
                <div className="flex-1"><h3 className="font-black text-[#0f172a] text-sm leading-tight line-clamp-2">{p.name}</h3>{p.variants?.length > 1 && <p className="text-[9px] text-blue-500 font-bold mt-1 uppercase opacity-70">متعدد الخيارات ({p.variants.length})</p>}{p.barcode && <p className="text-[8px] font-mono text-slate-400 mt-1">CODE: {p.barcode}</p>}</div>
                <div className="pt-3 border-t border-slate-100 flex items-center justify-between"><span className="text-lg font-black text-[#0f172a]">{Math.round(p.variants?.[0]?.sale_price || 0)} {p.variants?.length > 1 && '...'} <span className="text-[10px]">₪</span></span></div>
              </button>
            );
          })}
        </div>
      </div>

      <div className={`fixed lg:relative inset-y-0 left-0 bg-white border-r border-slate-300 shadow-2xl transition-all duration-500 z-[80] overflow-hidden flex flex-col h-full ${isCartOpen ? 'w-[320px]' : 'w-0'}`}>
        <div className="p-6 bg-[#0f172a] text-white flex items-center justify-between shrink-0"><div className="flex items-center gap-3"><ShoppingBag size={20} className="text-emerald-500" /><span className="font-black text-lg">الفاتورة</span></div><button onClick={() => setIsCartOpen(false)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button></div>
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
          {cart.length === 0 ? <div className="h-full flex flex-col items-center justify-center opacity-10 py-10"><ShoppingBag size={50} /><p className="font-black mt-4 text-sm">السلة فارغة</p></div> : 
            cart.map((item, idx) => (
              <div key={idx} className={`bg-white p-4 rounded-2xl border-2 transition-all duration-300 flex flex-col gap-2 shadow-sm animate-slide-in-right ${stockError?.id === item.variant_id ? 'border-rose-500 bg-rose-50 scale-[1.02]' : 'border-slate-200'}`}>
                <div className="flex justify-between items-start gap-2"><h4 className="font-black text-[#0f172a] text-[11px] line-clamp-2 flex-1">{item.product_name}</h4><p className="font-black text-emerald-600 text-[12px]">{Math.round(item.sale_price * item.quantity)} ₪</p></div>
                <p className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center shadow-sm active:scale-90"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center shadow-sm active:scale-90"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="text-slate-300 hover:text-rose-500 p-1"><Trash2 size={16} /></button>
                </div>
                {stockError?.id === item.variant_id && <p className="text-[8px] font-black text-rose-600 animate-pulse text-center">الكمية القصوى المتاحة</p>}
              </div>
            ))
          }
        </div>
        <div className="p-6 bg-white border-t-2 border-slate-200 space-y-4 shrink-0 shadow-lg mt-auto z-10">
          <div className="space-y-2"><div className="flex justify-between text-[10px] font-black text-slate-500 px-1 uppercase tracking-tight"><span>تطبيق خصم</span><span>الإجمالي: {Math.round(subtotal)} ₪</span></div><input type="number" lang="en" dir="ltr" inputMode="decimal" className="w-full py-3 bg-slate-50 border-2 border-slate-200 focus:border-[#0f172a] rounded-xl text-center font-black text-xl outline-none appearance-none" value={discount === 0 ? '' : discount} placeholder="0" onChange={(e) => setDiscount(e.target.value)} /></div>
          <div className="pt-2 flex justify-between items-center border-t border-slate-100"><span className="text-[#0f172a] font-black text-xs opacity-60">الصافي للدفع</span><span className="text-2xl font-black text-emerald-600">{Math.round(netAmount)} ₪</span></div>
          <button onClick={handleFinishOrder} disabled={cart.length === 0 || isProcessing} className="w-full py-4.5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-500 disabled:bg-slate-200 flex items-center justify-center gap-2">
             {isProcessing ? <Loader2 className="animate-spin" /> : <>إتمام الفاتورة <CheckCircle2 size={20} /></>}
