      {showSuccess && (
        <div className="fixed inset-0 z-[300] bg-emerald-600/90 backdrop-blur-sm flex items-center justify-center animate-in fade-in duration-300">
          <div className="bg-white p-10 rounded-[3rem] shadow-2xl flex flex-col items-center gap-6 text-center animate-in zoom-in-95 duration-300 max-w-sm">
            <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center shadow-inner"><CheckCircle2 size={60} /></div>
            <div><h2 className="text-2xl font-black text-slate-900">تم إتمام الفاتورة!</h2><p className="text-slate-500 font-bold mt-1">رقم الفاتورة: {lastInvoice?.id}</p></div>
            <div className="flex flex-col gap-3 w-full">
               <button onClick={() => { if(lastInvoice) printThermalReceipt(lastInvoice); }} className="w-full py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-3 shadow-lg hover:bg-black transition-all"><Printer size={20} className="text-emerald-500" /><span>طباعة الفاتورة</span></button>
               <button onClick={() => { setShowSuccess(false); setTimeout(() => searchInputRef.current?.focus(), 100); }} className="w-full py-4 bg-slate-100 text-slate-600 font-black rounded-2xl hover:bg-slate-200 transition-all">متابعة العمل</button>
            </div>
          </div>
        </div>
      )}

      {selectedProductForVariants && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[250] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-slide-in-right">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between"><div className="flex items-center gap-4"><div className="p-2.5 bg-blue-600 rounded-xl"><Layers size={24} /></div><h3 className="text-xl font-black">{selectedProductForVariants.name}</h3></div><button onClick={() => { setSelectedProductForVariants(null); setTimeout(() => searchInputRef.current?.focus(), 100); }} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button></div>
            <div className="p-8 space-y-3 overflow-y-auto max-h-[60vh] custom-scrollbar">
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">يرجى اختيار النوع المطلوب:</p>
              {selectedProductForVariants.variants?.filter((v: any) => v.stock_quantity > 0).map((v: any) => (
                <button 
                  key={v.id} 
                  onClick={() => addToCart(v, selectedProductForVariants)} 
                  className={`w-full p-5 bg-slate-50 border-2 rounded-2xl flex items-center justify-between hover:border-emerald-500 hover:bg-white transition-all group shadow-sm active:scale-95 ${stockError?.id === v.id ? 'border-rose-500 bg-rose-50' : 'border-slate-100'}`}
                >
                  <div className="text-right"><p className="font-black text-slate-800 text-sm">{v.name}</p><p className="text-[10px] text-slate-400 font-bold">الكمية المتوفرة: {v.stock_quantity} قطعة</p></div><span className="font-black text-emerald-600 text-lg">{Math.round(v.sale_price)} ₪</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden border border-slate-200">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between"><div className="flex items-center gap-4"><div className="p-2.5 bg-emerald-600 rounded-xl"><PlusCircle size={24} /></div><h3 className="text-xl font-black">إضافة خدمة يدوية</h3></div><button onClick={() => { setShowExtraModal(false); setTimeout(() => searchInputRef.current?.focus(), 100); }} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button></div>
            <div className="p-8 space-y-6">
              <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">وصف الخدمة</label><input type="text" autoFocus className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" placeholder="مثال: رسوم شحن..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-5">
                <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">التكلفة (₪)</label><input type="number" lang="en" dir="ltr" inputMode="decimal" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(e.target.value)})} /></div>
                <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">البيع (₪)</label><input type="number" lang="en" dir="ltr" inputMode="decimal" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold text-emerald-600" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(e.target.value)})} /></div>
              </div>
              <button onClick={handleAddExtraService} disabled={!extraService.name || extraService.sale_price <= 0} className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-700 active:scale-95 transition-all flex items-center justify-center gap-3">إدراج في السلة</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Trash2, 
  Copy, 
  ChevronDown,
  Package,
  Layers,
  Filter,
  X,
  DollarSign,
  Save,
  AlertCircle,
  Loader2,
  Edit3,
  CheckSquare,
  Square,
  RotateCcw,
  AlertTriangle,
  CheckCircle2,
  Truck,
  PackageX
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Category, Product, Variant } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{id: string | null, type: 'single' | 'bulk'}>({id: null, type: 'single'});

  // States for Filtering
  const [filterMainCategory, setFilterMainCategory] = useState<string>('all');
  const [filterSubCategory, setFilterSubCategory] = useState<string>('all');
  const [filterSupplier, setFilterSupplier] = useState<string>('');
  const [showFilters, setShowFilters] = useState(false);

  const [form, setForm] = useState({
    name: '',
    barcode: '',
    supplier: '',
    category_id: '',
    sub_category_id: '',
    variants: [{ id: undefined as string | undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
  });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: prods, error: pErr } = await supabase
        .from('products')
        .select('*, variants(*)')
        .order('created_at', { ascending: false });

      const { data: cats, error: cErr } = await supabase
        .from('categories')
        .select('*')
        .order('name');

      if (pErr) throw pErr;
      if (cErr) throw cErr;

      setProducts(prods || []);
      setCategories(cats || []);
    } catch (err) {
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const sanitizeUUID = (id: string | null | undefined) => {
    if (!id || id.trim() === "" || id === "all") return null;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id) ? id : null;
  };

  const handleOpenAdd = () => {
    setModalMode('add');
    setEditingId(null);
    setForm({
      name: '',
      barcode: '',
      supplier: '',
      category_id: '',
      sub_category_id: '',
      variants: [{ id: undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }]
    });
    setShowModal(true);
  };

  const handleOpenEdit = (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    setModalMode('edit');
    setEditingId(product.id);

    const mappedVariants = product.variants && product.variants.length > 0 
      ? product.variants.map((v: any) => ({
          id: v.id,
          name: v.name,
          cost_price: v.cost_price,
          sale_price: v.sale_price,
          stock_quantity: v.stock_quantity
        }))
      : [{ id: undefined, name: 'افتراضي', cost_price: 0, sale_price: 0, stock_quantity: 0 }];

    setForm({
      name: product.name,
      barcode: product.barcode || '',
      supplier: product.supplier || '',
      category_id: product.category_id || '',
      sub_category_id: product.sub_category_id || '',
      variants: mappedVariants
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.name || saving) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        barcode: form.barcode?.trim() || null,
        supplier: form.supplier?.trim() || null,
        category_id: sanitizeUUID(form.category_id),
        sub_category_id: sanitizeUUID(form.sub_category_id)
      };

      let prodId = editingId;

      if (modalMode === 'add') {
        const { data: prodData, error: pError } = await supabase.from('products').insert(payload).select().single();
        if (pError) {
            if (pError.code === '23505') throw new Error("الباركود مستخدم بالفعل");
            throw pError;
        }
        prodId = prodData.id;
      } else {
        const { error: pError } = await supabase.from('products').update(payload).eq('id', prodId);
        if (pError) {
             if (pError.code === '23505') throw new Error("الباركود مستخدم بالفعل");
             throw pError;
        }
      }

      if (modalMode === 'edit') {
        const currentVariantIds = form.variants.filter(v => v.id).map(v => v.id);
        const { data: existingVariants } = await supabase.from('variants').select('id').eq('product_id', prodId);
        const idsToDelete = existingVariants?.filter(ev => !currentVariantIds.includes(ev.id)).map(ev => ev.id) || [];
        if (idsToDelete.length > 0) {
          await supabase.from('variants').delete().in('id', idsToDelete);
        }
      }

      const variantsToUpsert = form.variants.map(v => {
        const base: any = {
          product_id: prodId,
          name: v.name || 'افتراضي',
          cost_price: Number(v.cost_price) || 0,
          sale_price: Number(v.sale_price) || 0,
          stock_quantity: Number(v.stock_quantity) || 0
        };
        if (v.id) base.id = v.id;
        return base;
      });

      const { error: vError } = await supabase.from('variants').upsert(variantsToUpsert);
      if (vError) throw vError;

      setShowModal(false);
      showToast(modalMode === 'add' ? "تم إضافة الصنف بنجاح" : "تم تحديث البيانات بنجاح", "success");
      await fetchData();
    } catch (err: any) {
      console.error("Inventory Save Error:", err);
      showToast(err.message || "حدث خطأ غير متوقع أثناء الحفظ", "error");
    } finally {
      setSaving(false);
    }
  };

  const requestDeleteOne = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setDeleteTarget({id, type: 'single'});
    setShowDeleteConfirm(true);
  };

  const requestBulkDelete = () => {
    setDeleteTarget({id: null, type: 'bulk'});
    setShowDeleteConfirm(true);
  };

  const confirmDeleteAction = async () => {
    setLoading(true);
    setShowDeleteConfirm(false);
    try {
      if (deleteTarget.type === 'single' && deleteTarget.id) {
        await supabase.from('products').delete().eq('id', deleteTarget.id);
        setProducts(prev => prev.filter(p => p.id !== deleteTarget.id));
        setSelectedIds(prev => prev.filter(sid => sid !== deleteTarget.id));
        showToast("تم حذف الصنف");
      } else if (deleteTarget.type === 'bulk') {
        const { error } = await supabase.from('products').delete().in('id', selectedIds);
        if (error) throw error;
        await fetchData();
        setSelectedIds([]);
        showToast(`تم حذف ${selectedIds.length} أصناف`);
      }
    } catch (err: any) {
      console.error(err);
      showToast("فشل الحذف", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleDuplicate = async (e: React.MouseEvent, product: any) => {
    e.stopPropagation();
    try {
      const { data: prodData, error: pError } = await supabase.from('products').insert({
        name: `${product.name} (نسخة)`,
        supplier: product.supplier,
        category_id: product.category_id,
        sub_category_id: product.sub_category_id
      }).select().single();

      if (pError) throw pError;
      const vars = product.variants.map((v: any) => ({
        name: v.name,
        cost_price: v.cost_price,
        sale_price: v.sale_price,
        stock_quantity: v.stock_quantity,
        product_id: prodData.id
      }));
      await supabase.from('variants').insert(vars);
      showToast("تم تكرار الصنف بنجاح");
      await fetchData();
    } catch (err: any) { 
        console.error(err); 
        showToast("خطأ في تكرار الصنف", "error");
    }
  };

  const toggleSelectAll = (list: any[]) => {
    const listIds = list.map(p => p.id);
    if (listIds.every(id => selectedIds.includes(id))) {
      setSelectedIds(prev => prev.filter(id => !listIds.includes(id)));
    } else {
      setSelectedIds(prev => Array.from(new Set([...prev, ...listIds])));
    }
  };

  const toggleSelectItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        (p.barcode && p.barcode.includes(searchTerm));

      const matchMain = filterMainCategory === 'all' || p.category_id === filterMainCategory;
      const matchSub = filterSubCategory === 'all' || p.sub_category_id === filterSubCategory;
      const matchSupplier = filterSupplier === '' || (p.supplier && p.supplier.toLowerCase().includes(filterSupplier.toLowerCase()));

      return matchSearch && matchMain && matchSub && matchSupplier;
    });
  }, [products, searchTerm, filterMainCategory, filterSubCategory, filterSupplier]);

  // تقسيم الأصناف لمتوفرة ونافدة
  const inStock = useMemo(() => filtered.filter(p => (p.variants?.reduce((s: number, v: any) => s + v.stock_quantity, 0) || 0) > 0), [filtered]);
  const outOfStock = useMemo(() => filtered.filter(p => (p.variants?.reduce((s: number, v: any) => s + v.stock_quantity, 0) || 0) <= 0), [filtered]);

  const stockValue = filtered.reduce((sum, p) => sum + (p.variants?.reduce((vs: number, v: any) => vs + (v.cost_price * v.stock_quantity), 0) || 0), 0);

  const mainCategories = useMemo(() => categories.filter(c => !c.parent_id), [categories]);
  const subCategoriesForFilter = useMemo(() => categories.filter(c => c.parent_id === filterMainCategory), [categories, filterMainCategory]);
  const subCategoriesForForm = useMemo(() => categories.filter(c => c.parent_id === form.category_id), [categories, form.category_id]);

  const ProductTable = ({ list, title, icon: Icon, colorClass, emptyMsg }: { list: any[], title: string, icon: any, colorClass: string, emptyMsg: string }) => (
    <div className={`bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col mb-6`}>
      <div className={`p-5 flex justify-between items-center text-white shrink-0 ${colorClass}`}>
        <div className="flex items-center gap-4">
          <Icon size={20} />
          <h3 className="font-black text-lg">{title}</h3>
        </div>
        <span className="px-3 py-1 bg-white/20 rounded-lg text-xs font-black">عدد الأصناف: {list.length}</span>
      </div>
      <div className="overflow-x-auto flex-1 custom-scrollbar">
        <table className="w-full text-right border-collapse min-w-[1000px]">
          <thead className="sticky top-0 bg-slate-50 z-10 border-b border-slate-200">
            <tr>
              <th className="p-5 w-14 text-right">
                <button onClick={() => toggleSelectAll(list)} className="text-slate-400 hover:text-slate-900 transition-colors">
                  {list.length > 0 && list.every(p => selectedIds.includes(p.id)) ? <CheckSquare size={22} className="text-slate-900" /> : <Square size={22} />}
                </button>
              </th>
              <th className="p-5 text-xs font-black text-slate-400 uppercase">اسم الصنف / الباركود</th>
              <th className="p-5 text-xs font-black text-slate-400 uppercase">المورد</th>
              <th className="p-5 text-xs font-black text-slate-400 uppercase">التصنيف</th>
              <th className="p-5 text-xs font-black text-slate-400 uppercase text-center">التكلفة</th>
              <th className="p-5 text-xs font-black text-slate-400 uppercase text-center">البيع</th>
              <th className="p-5 text-xs font-black text-slate-400 uppercase text-center">الكمية</th>
              <th className="p-5 text-xs font-black text-slate-400 uppercase text-left">الإجراءات</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {list.map(p => {
              const primaryVariant = p.variants?.[0];
              const totalQuantity = p.variants?.reduce((acc: number, v: any) => acc + v.stock_quantity, 0) || 0;
              const isOutOfStock = totalQuantity <= 0;
              const mainCategory = categories.find(c => c.id === p.category_id)?.name || 'بدون قسم';
              const subCategory = categories.find(c => c.id === p.sub_category_id)?.name;

              return (
                <React.Fragment key={p.id}>
                  <tr 
                    onClick={() => setExpandedProduct(expandedProduct === p.id ? null : p.id)}
                    className={`transition-all cursor-pointer group ${expandedProduct === p.id ? 'bg-slate-50' : 'hover:bg-slate-50/80'} ${selectedIds.includes(p.id) ? 'bg-emerald-50' : ''} ${isOutOfStock ? 'border-r-4 border-rose-500' : ''}`}
                  >
                    <td className="p-5" onClick={(e) => toggleSelectItem(e, p.id)}>
                      <div className={`transition-all ${selectedIds.includes(p.id) ? 'text-emerald-600' : 'text-slate-300'}`}>
                        {selectedIds.includes(p.id) ? <CheckSquare size={22} /> : <Square size={22} />}
                      </div>
                    </td>
                    <td className="p-5">
                      <div className="flex items-center gap-4">
                        <div className={`transition-all duration-300 ${expandedProduct === p.id ? 'rotate-180 text-emerald-600' : 'text-slate-300'}`}><ChevronDown size={18} /></div>
                        <div>
                          <p className={`font-black text-sm ${isOutOfStock ? 'text-rose-900' : 'text-slate-900'}`}>{p.name}</p>
                          {p.barcode && <p className="text-[10px] font-mono text-slate-400">{p.barcode}</p>}
                        </div>
                      </div>
                    </td>
                    <td className="p-5">
                      <div className="flex items-center gap-2">
                        <Truck size={14} className="text-slate-300" />
                        <span className="text-xs font-bold text-slate-600">{p.supplier || '-'}</span>
                      </div>
                    </td>
                    <td className="p-5">
                      <div className="flex flex-col gap-1">
                        <span className="bg-blue-50 text-blue-600 text-[9px] font-black px-2 py-0.5 rounded-md border border-blue-100 w-fit">
                          {mainCategory}
                        </span>
                        {subCategory && (
                          <span className="bg-indigo-50 text-indigo-600 text-[8px] font-bold px-2 py-0.5 rounded-md border border-indigo-100 w-fit">
                            {subCategory}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="p-5 text-center font-bold text-slate-500 text-sm">
                      {Math.round(primaryVariant?.cost_price || 0)} <span className="text-[10px]">₪</span>
                    </td>
                    <td className="p-5 text-center font-black text-emerald-600 text-sm">
                      {Math.round(primaryVariant?.sale_price || 0)} <span className="text-[10px]">₪</span>
                    </td>
                    <td className="p-5 text-center">
                      <div className={`inline-flex items-center justify-center px-3 py-1 rounded-full text-xs font-black ${totalQuantity > 0 ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-rose-600 text-white shadow-lg shadow-rose-100 animate-pulse'}`}>
                        {totalQuantity > 0 ? totalQuantity : 'نفد المخزون'}
                      </div>
                    </td>
                    <td className="p-5 text-left" onClick={(e) => e.stopPropagation()}>
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={(e) => handleOpenEdit(e, p)} className="p-2 text-slate-400 hover:text-emerald-600 transition-colors" title="تعديل"><Edit3 size={18} /></button>
                        <button onClick={(e) => handleDuplicate(e, p)} className="p-2 text-slate-400 hover:text-blue-600 transition-colors" title="تكرار"><Copy size={18} /></button>
                        <button onClick={(e) => requestDeleteOne(e, p.id)} className="p-2 text-slate-400 hover:text-rose-600 transition-colors" title="حذف"><Trash2 size={18} /></button>
                      </div>
                    </td>
                  </tr>
                  {expandedProduct === p.id && (
                    <tr className="bg-slate-50/40 animate-in slide-in-from-top-2">
                      <td colSpan={8} className="p-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                          <div className="md:col-span-4 mb-2"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">الأنواع المتاحة للصنف:</p></div>
                          {p.variants?.map((v: any) => (
                            <div key={v.id} className={`p-4 rounded-2xl border flex justify-between items-center shadow-sm ${v.stock_quantity <= 0 ? 'bg-rose-50 border-rose-200' : 'bg-white border-slate-200'}`}>
                              <div>
                                <p className={`font-black text-xs ${v.stock_quantity <= 0 ? 'text-rose-900' : 'text-slate-800'}`}>{v.name}</p>
                                <p className={`text-[10px] font-bold ${v.stock_quantity <= 0 ? 'text-rose-500' : 'text-slate-400'}`}>المخزون: {v.stock_quantity}</p>
                              </div>
                              <div className="text-left">
                                <p className={`font-black ${v.stock_quantity <= 0 ? 'text-rose-400' : 'text-emerald-600'}`}>{Math.round(v.sale_price)} ₪</p>
                                <p className="text-[9px] text-slate-400">التكلفة: {Math.round(v.cost_price)} ₪</p>
                              </div>
                            </div>
                          ))}
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              );
            })}
            {list.length === 0 && (
              <tr>
                <td colSpan={8} className="p-16 text-center">
                  <p className="font-black text-slate-300 text-lg uppercase tracking-widest">{emptyMsg}</p>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 flex flex-col h-full overflow-hidden relative" dir="rtl">
      {/* Toast Notification */}
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[300] flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl animate-in slide-in-from-top-10 duration-300 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-rose-600 border-rose-500 text-white'}`}>
          {toast.type === 'success' ? <CheckCircle2 size={24} /> : <AlertTriangle size={24} />}
          <span className="font-black text-sm">{toast.message}</span>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 px-2 pt-2">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
          <Package className="text-emerald-600" />
          المخزون
        </h2>
        <div className="flex gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button 
              onClick={requestBulkDelete}
              className="px-6 py-3 bg-rose-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-rose-200 animate-in fade-in zoom-in"
            >
              <Trash2 size={20} />
              <span>حذف المحددة ({selectedIds.length})</span>
            </button>
          )}
          <button 
            onClick={handleOpenAdd}
            className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg hover:bg-emerald-700 transition-all active:scale-95"
          >
            <Plus size={20} />
            <span>إضافة صنف</span>
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 shrink-0 px-2">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-blue-50 text-blue-600 rounded-2xl"><Package size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">إجمالي الأصناف</p><p className="text-xl font-black">{filtered.length}</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="hidden sm:block p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><DollarSign size={22} /></div>
          <div><p className="text-[10px] font-black text-slate-400 uppercase">قيمة المخزون</p><p className="text-xl font-black text-emerald-600">{Math.round(stockValue)} ₪</p></div>
        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4 hidden sm:flex">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-2xl"><PackageX size={22} /></div>
          <div><p className="text-[10px] font-black text-rose-600 uppercase">أصناف نافدة</p><p className="text-xl font-black text-rose-600">{outOfStock.length}</p></div>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm shrink-0 mx-2 z-50">
        <div className="p-4 flex items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input
              type="text"
              placeholder="البحث بالاسم أو الباركود..."
              className="w-full pr-12 pl-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-emerald-500 outline-none font-black text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-3.5 rounded-2xl transition-all border-2 flex items-center gap-2 font-black text-sm ${showFilters ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-100 text-slate-500'}`}
          >
            <Filter size={18} />
            <span className="hidden sm:inline">تصفية</span>
          </button>
        </div>

        {showFilters && (
          <div className="p-4 border-t border-slate-100 grid grid-cols-1 md:grid-cols-4 gap-4 animate-in slide-in-from-top-2">
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1">المورد</label>
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="بحث بالمورد..." 
                  className="w-full p-3 pr-10 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs outline-none focus:border-emerald-500"
                  value={filterSupplier}
                  onChange={(e) => setFilterSupplier(e.target.value)}
                />
                <Truck className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1">القسم الرئيسي</label>
              <select 
                className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs outline-none focus:border-emerald-500" 
                value={filterMainCategory} 
                onChange={(e) => {
                  setFilterMainCategory(e.target.value);
                  setFilterSubCategory('all');
                }}
              >
                <option value="all">كل الأقسام الرئيسية</option>
                {mainCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1">القسم الفرعي</label>
              <select 
                disabled={filterMainCategory === 'all'}
                className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl font-black text-xs outline-none focus:border-emerald-500 disabled:opacity-50" 
                value={filterSubCategory} 
                onChange={(e) => setFilterSubCategory(e.target.value)}
              >
                <option value="all">كل الأقسام الفرعية</option>
                {subCategoriesForFilter.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="flex items-end">
              <button 
                onClick={() => { 
                  setFilterMainCategory('all'); 
                  setFilterSubCategory('all'); 
                  setFilterSupplier('');
                  setSearchTerm('');
                  setShowFilters(false); 
                }} 
                className="w-full py-3 bg-rose-50 text-rose-600 rounded-xl text-xs font-black flex items-center justify-center gap-2 hover:bg-rose-100 transition-colors"
              >
                <RotateCcw size={14} />
                إعادة ضبط الفلاتر
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Table Sections */}
      <div className="flex-1 overflow-y-auto custom-scrollbar px-2 space-y-6">
        {loading ? (
          <div className="h-full flex flex-col items-center justify-center gap-4"><Loader2 className="animate-spin text-emerald-600" size={40} /><p className="font-black text-slate-400">جاري التحميل...</p></div>
        ) : (
          <>
            {/* 1. In Stock Section */}
            <ProductTable 
              list={inStock} 
              title="الأصناف المتوفرة" 
              icon={Package} 
              colorClass="bg-[#0f172a]"
              emptyMsg="لا توجد أصناف متوفرة حالياً"
            />

            {/* 2. Out of Stock Section */}
            <ProductTable 
              list={outOfStock} 
              title="أصناف نفد مخزونها" 
              icon={PackageX} 
              colorClass="bg-rose-600"
              emptyMsg="لا توجد أصناف نافدة"
            />
          </>
        )}
      </div>

      {/* Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center z-[200] p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-sm overflow-hidden p-8 space-y-6 border border-slate-200 animate-in zoom-in-95 duration-200">
             <div className="flex flex-col items-center gap-4 text-center">
                <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center shadow-inner">
                   <AlertTriangle size={40} />
                </div>
                <div>
                   <h3 className="text-xl font-black text-slate-900">تأكيد عملية الحذف</h3>
                   <p className="text-slate-500 text-sm mt-2 font-bold leading-relaxed">
                     {deleteTarget.type === 'single' ? 'هل أنت متأكد من حذف هذا الصنف نهائياً؟' : `هل أنت متأكد من حذف ${selectedIds.length} أصناف نهائياً؟`}
                     <br /> لا يمكن التراجع عن هذا الإجراء.
                   </p>
                </div>
             </div>
             <div className="flex gap-3">
                <button 
                  onClick={confirmDeleteAction}
                  className="flex-1 py-4 bg-rose-500 text-white font-black rounded-2xl shadow-lg shadow-rose-200 active:scale-95 transition-all"
                >
                  نعم، حذف
                </button>
                <button 
                  onClick={() => setShowDeleteConfirm(false)}
                  className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl active:scale-95 transition-all"
                >
                  إلغاء
                </button>
             </div>
          </div>
        </div>
      )}

      {/* Unified Modal (Add/Edit) */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl flex items-center justify-center z-[100] p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl my-auto overflow-hidden flex flex-col border border-white/10 animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl shadow-xl text-white ${modalMode === 'add' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-blue-600 shadow-blue-200'}`}>
                  {modalMode === 'add' ? <Plus size={28} /> : <Edit3 size={28} />}
                </div>
                <h3 className="text-xl font-black text-slate-900">{modalMode === 'add' ? 'إضافة صنف جديد' : 'تعديل بيانات الصنف'}</h3>
              </div>
              <button onClick={() => setShowModal(false)} className="p-3 bg-slate-200 text-slate-500 rounded-2xl hover:bg-slate-300 transition-all"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar max-h-[70vh]">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">اسم الصنف *</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.name} onChange={(e) => setForm({...form, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">الباركود</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.barcode} onChange={(e) => setForm({...form, barcode: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">المورد</label>
                  <div className="relative">
                    <input type="text" className="w-full p-4 pr-12 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-black transition-all" value={form.supplier} onChange={(e) => setForm({...form, supplier: e.target.value})} />
                    <Truck className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الرئيسي</label>
                  <select 
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all" 
                    value={form.category_id} 
                    onChange={(e) => setForm({...form, category_id: e.target.value, sub_category_id: ''})}
                  >
                    <option value="">اختر القسم الرئيسي...</option>
                    {mainCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest px-1">القسم الفرعي</label>
                  <select 
                    disabled={!form.category_id}
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black transition-all disabled:opacity-50" 
                    value={form.sub_category_id} 
                    onChange={(e) => setForm({...form, sub_category_id: e.target.value})}
                  >
                    <option value="">اختر القسم الفرعي...</option>
                    {subCategoriesForForm.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <p className="text-xs font-black text-slate-900 uppercase tracking-widest">تخصيص الأنواع والكميات</p>
                  <button onClick={() => setForm({...form, variants: [...form.variants, { id: undefined, name: '', cost_price: 0, sale_price: 0, stock_quantity: 0 }]})} className="px-5 py-2.5 bg-blue-50 text-blue-600 font-black rounded-xl text-xs flex items-center gap-2 border border-blue-100 transition-all hover:bg-blue-100">
                    <Plus size={16} /> إضافة نوع
                  </button>
                </div>
                <div className="space-y-4">
                  {form.variants.map((v, idx) => (
                    <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-3 p-5 bg-slate-50 rounded-3xl border-2 border-slate-100 relative group">
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 mr-2">اسم النوع</label>
                        <input placeholder="اسم النوع" className="w-full p-3 bg-white rounded-xl border border-slate-200 font-black text-xs" value={v.name} onChange={(e) => { const vs = [...form.variants]; vs[idx].name = e.target.value; setForm({...form, variants: vs}); }} />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black text-slate-400 mr-2">التكلفة (₪)</label>
                         <input type="number" lang="en" dir="ltr" inputMode="decimal" className="w-full p-3 bg-white rounded-xl border border-slate-200 font-black text-xs appearance-none" value={v.cost_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].cost_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black text-emerald-600 mr-2">البيع (₪)</label>
                         <input type="number" lang="en" dir="ltr" inputMode="decimal" className="w-full p-3 bg-white rounded-xl border-2 border-emerald-100 text-emerald-600 font-black text-xs appearance-none" value={v.sale_price || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].sale_price = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black text-slate-400 mr-2">الكمية</label>
                         <input type="number" lang="en" dir="ltr" inputMode="numeric" className="w-full p-3 bg-white rounded-xl border border-slate-200 font-black text-xs appearance-none" value={v.stock_quantity || ''} onChange={(e) => { const vs = [...form.variants]; vs[idx].stock_quantity = Number(e.target.value); setForm({...form, variants: vs}); }} />
                      </div>
                      <div className="flex items-center justify-end pt-5">
                        {form.variants.length > 1 && (
                          <button onClick={() => setForm({...form, variants: form.variants.filter((_, i) => i !== idx)})} className="p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors">
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3 text-amber-600">
                <AlertCircle size={20} />
                <p className="text-xs font-black">سيتم حفظ التغييرات فوراً في المخزون.</p>
              </div>
              <button 
                onClick={handleSave}
                disabled={!form.name || saving}
                className={`px-12 py-4.5 text-white font-black text-lg rounded-[1.8rem] shadow-2xl flex items-center gap-3 transition-all active:scale-95 ${modalMode === 'add' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
              >
                {saving ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} />}
                <span>{saving ? 'جاري الحفظ...' : modalMode === 'add' ? 'إضافة الصنف' : 'تحديث البيانات'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingBag,
  X,
  CheckCircle2,
  Loader2,
  PlusCircle,
  Barcode,
  Layers,
  Printer,
  AlertCircle,
  AlertTriangle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';
import { printThermalReceipt } from '../utils/printThermal';
import { playScanBeep } from '../utils/audio';

// Helper to convert Arabic numerals to Latin
const toLatinDigits = (val: string | number): string => {
  const s = String(val);
  return s.replace(/[٠-٩]/g, (d) => "0123456789"["٠١٢٣٤٥٦٧٨٩".indexOf(d)]);
};

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(true);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [selectedProductForVariants, setSelectedProductForVariants] = useState<any>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  // تنبيه تجاوز المخزون
  const [stockError, setStockError] = useState<{id: string, msg: string} | null>(null);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState<number | string>(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<any>(null);
  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', 
    cost_price: 0, 
    sale_price: 0, 
    quantity: 1 
  });

  useEffect(() => {
    fetchData();
    setTimeout(() => searchInputRef.current?.focus(), 500);
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const triggerStockError = (id: string) => {
    setStockError({ id, msg: "لا يمكن إضافة أكثر من الكمية المتوفرة" });
    setTimeout(() => setStockError(null), 2500);
  };

  const addToCart = (variant: Variant, product: any) => {
    if (variant.stock_quantity <= 0) return;
    const existingInCart = cart.find(item => item.variant_id === variant.id);
    const currentQtyInCart = existingInCart ? existingInCart.quantity : 0;
    if (currentQtyInCart + 1 > variant.stock_quantity) {
      triggerStockError(variant.id);
      return;
    }
    playScanBeep();
    setIsCartOpen(true);
    setCart(prev => {
      if (existingInCart) {
        return prev.map(item => 
          item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        variant_id: variant.id, 
        product_name: product.name, 
        variant_name: variant.name, 
        cost_price: variant.cost_price, 
        sale_price: variant.sale_price, 
        quantity: 1, 
        type: 'product' 
      }];
    });
    setSelectedProductForVariants(null);
    setTimeout(() => searchInputRef.current?.focus(), 100);
  };

  const handleProductClick = (product: any) => {
    if (!product.variants || product.variants.length === 0) return;
    const availableVariants = product.variants.filter((v: any) => v.stock_quantity > 0);
    if (availableVariants.length === 0) return;
    if (availableVariants.length === 1) {
      addToCart(availableVariants[0], product);
    } else {
      setSelectedProductForVariants(product);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && searchTerm.trim()) {
      const barcode = toLatinDigits(searchTerm.trim());
      const exactMatch = products.find(p => p.barcode === barcode);
      if (exactMatch) {
        handleProductClick(exactMatch);
        setSearchTerm('');
      }
    }
  };

  const handleAddExtraService = () => {
    if (!extraService.name || extraService.sale_price <= 0) return;
    playScanBeep();
    setIsCartOpen(true);
    setCart(prev => [...prev, {
      ...extraService,
      product_name: extraService.name,
      variant_name: 'خدمة إضافية',
      type: 'service',
      variant_id: null
    }]);
    setShowExtraModal(false);
    setExtraService({ name: '', cost_price: 0, sale_price: 0, quantity: 1 });
    setTimeout(() => searchInputRef.current?.focus(), 100);
  };

  const updateQuantity = (variantId: string | null, delta: number, index: number) => {
    setCart(prev => prev.map((item, i) => {
      if ((variantId && item.variant_id === variantId) || (!variantId && i === index)) {
        const newQty = Math.max(1, item.quantity + delta);
        if (delta > 0 && variantId) {
          const product = products.find(p => p.variants.some((v: any) => v.id === variantId));
          const variant = product?.variants.find((v: any) => v.id === variantId);
          if (variant && newQty > variant.stock_quantity) {
             triggerStockError(variantId);
             return item;
          }
        }
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const calculateTotals = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
    const discNum = Number(toLatinDigits(String(discount))) || 0;
    const netAmount = Math.max(0, subtotal - discNum);
    return { subtotal, netAmount };
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    try {
      const { subtotal, netAmount } = calculateTotals();
      const discNum = Number(toLatinDigits(String(discount))) || 0;
      const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);

      const { data: invoice, error: invError } = await supabase.from('invoices').insert({
        total_amount: subtotal, discount: discNum, net_amount: netAmount, total_cost: totalCost, profit: netAmount - totalCost
      }).select().single();

      if (invError) throw invError;

      const items = cart.filter(c => c.type === 'product');
      const services = cart.filter(c => c.type === 'service');

      if (items.length > 0) {
        await supabase.from('invoice_items').insert(items.map(item => ({
          invoice_id: invoice.id, variant_id: item.variant_id, product_name: item.product_name, variant_name: item.variant_name, quantity: item.quantity, cost_price: item.cost_price, sale_price: item.sale_price
        })));
        for (const item of items) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }
      if (services.length > 0) {
        await supabase.from('extra_services').insert(services.map(ser => ({
          invoice_id: invoice.id, name: ser.product_name, cost_price: ser.cost_price, sale_price: ser.sale_price, quantity: ser.quantity
        })));
      }

      setLastInvoice({ ...invoice, invoice_items: items, extra_services: services });
      setIsCartOpen(false);
      setCart([]);
      setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      fetchData();
    } catch (e) { alert("خطأ في إتمام الطلب"); } finally { setIsProcessing(false); }
  };

  const filteredProducts = useMemo(() => {
    const term = toLatinDigits(searchTerm.toLowerCase());
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(term) || (p.barcode && p.barcode.includes(term));
      const matchMainCat = selectedMainCat ? p.category_id === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? p.sub_category_id === selectedSubCat : true;
      const totalStock = p.variants?.reduce((s: number, v: any) => s + v.stock_quantity, 0) || 0;
      const hasStock = totalStock > 0;
      return matchSearch && matchMainCat && matchSubCat && hasStock;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const mainCategories = categories.filter(c => !c.parent_id);
  const subCategories = categories.filter(c => c.parent_id === selectedMainCat);
  const { netAmount, subtotal } = calculateTotals();

  return (
    <div className="flex flex-col lg:flex-row h-full font-['Tajawal'] bg-[#f8fafc] overflow-hidden" dir="rtl">
      {stockError && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[400] bg-rose-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-4 duration-300">
          <AlertTriangle size={20} className="animate-pulse" />
          <span className="font-black text-sm">{stockError.msg}</span>
        </div>
      )}

      <aside className="hidden lg:flex flex-col w-44 shrink-0 overflow-y-auto custom-scrollbar p-5 gap-2 z-10">
        <div className="mb-2 px-1 shrink-0"><p className="text-[#0f172a] font-black text-[9px] uppercase tracking-widest opacity-30">الأقسام</p></div>
        <button onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }} className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${!selectedMainCat ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-transparent border-slate-200 text-slate-500'}`}>كافة الأصناف</button>
        {mainCategories.map(cat => (
          <button key={cat.id} onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }} className={`w-full px-4 py-2.5 text-right font-black text-[11px] rounded-xl transition-all border-2 shrink-0 ${selectedMainCat === cat.id ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-transparent border-slate-200 text-slate-500'}`}>{cat.name}</button>
        ))}
      </aside>

      <div className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] border-r border-slate-200 overflow-hidden relative">
        <div className="bg-white p-6 border-b border-slate-300 shadow-sm shrink-0">
          <div className="flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 group w-full">
              <input 
                ref={searchInputRef} 
                type="text" 
                placeholder="البحث بالاسم أو الباركود..." 
                className="w-full pr-14 pl-14 py-4 bg-slate-50 border-2 border-slate-300 focus:border-[#0f172a] rounded-[1.5rem] outline-none font-black text-lg transition-all" 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(toLatinDigits(e.target.value))} 
                onKeyDown={handleKeyDown} 
              />
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-[#0f172a]" size={24} />
              <Barcode className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-500 transition-colors" size={24} />
            </div>
            <div className="flex gap-2 w-full sm:w-auto">
              <button onClick={() => setShowExtraModal(true)} className="px-6 py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-all flex-1 shadow-lg"><PlusCircle size={20} /><span>خدمة</span></button>
              <button onClick={() => setIsCartOpen(!isCartOpen)} className={`p-4 border-2 rounded-2xl transition-all flex items-center gap-2 font-black ${isCartOpen ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-[#0f172a] border-slate-300'}`}><ShoppingBag size={24} /></button>
            </div>
          </div>
          {selectedMainCat && (
            <div className="flex items-center gap-2 overflow-x-auto mt-4 pb-2 no-scrollbar border-t border-slate-100 pt-4">
              {subCategories.map(sub => (
                <button key={sub.id} onClick={() => setSelectedSubCat(sub.id)} className={`px-5 py-2.5 rounded-xl font-black text-[10px] whitespace-nowrap border-2 transition-all ${selectedSubCat === sub.id ? 'bg-[#0f172a] text-white' : 'bg-transparent text-slate-500 border-slate-200'}`}>{sub.name}</button>
              ))}
            </div>
          )}
        </div>

        <div className="p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">
          {filteredProducts.map(p => {
            const totalStock = p.variants?.reduce((s: number, v: any) => s + v.stock_quantity, 0) || 0;
            return (
              <button 
                key={p.id} 
                onClick={() => handleProductClick(p)} 
                className="group bg-white p-5 rounded-[1.8rem] border-2 border-slate-200 hover:border-emerald-600 hover:shadow-2xl transition-all duration-300 text-right flex flex-col gap-3 relative h-fit active:scale-95 shadow-sm"
              >
                <div className="flex justify-between items-center"><span className="text-[9px] font-black px-2 py-1 rounded-lg bg-slate-50 text-slate-500 border border-slate-100">{totalStock} قطعة</span><Plus size={18} className="text-slate-300 group-hover:text-emerald-600" /></div>
                <div className="flex-1"><h3 className="font-black text-[#0f172a] text-sm leading-tight line-clamp-2">{p.name}</h3>{p.variants?.length > 1 && <p className="text-[9px] text-blue-500 font-bold mt-1 uppercase opacity-70">متعدد الخيارات ({p.variants.length})</p>}{p.barcode && <p className="text-[8px] font-mono text-slate-400 mt-1">CODE: {p.barcode}</p>}</div>
                <div className="pt-3 border-t border-slate-100 flex items-center justify-between"><span className="text-lg font-black text-[#0f172a]">{Math.round(p.variants?.[0]?.sale_price || 0)} {p.variants?.length > 1 && '...'} <span className="text-[10px]">₪</span></span></div>
              </button>
            );
          })}
        </div>
      </div>

      <div className={`fixed lg:relative inset-y-0 left-0 bg-white border-r border-slate-300 shadow-2xl transition-all duration-500 z-[80] overflow-hidden flex flex-col h-full ${isCartOpen ? 'w-[320px]' : 'w-0'}`}>
        <div className="p-6 bg-[#0f172a] text-white flex items-center justify-between shrink-0"><div className="flex items-center gap-3"><ShoppingBag size={20} className="text-emerald-500" /><span className="font-black text-lg">الفاتورة</span></div><button onClick={() => setIsCartOpen(false)} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button></div>
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
          {cart.length === 0 ? <div className="h-full flex flex-col items-center justify-center opacity-10 py-10"><ShoppingBag size={50} /><p className="font-black mt-4 text-sm">السلة فارغة</p></div> : 
            cart.map((item, idx) => (
              <div key={idx} className={`bg-white p-4 rounded-2xl border-2 transition-all duration-300 flex flex-col gap-2 shadow-sm animate-slide-in-right ${stockError?.id === item.variant_id ? 'border-rose-500 bg-rose-50 scale-[1.02]' : 'border-slate-200'}`}>
                <div className="flex justify-between items-start gap-2"><h4 className="font-black text-[#0f172a] text-[11px] line-clamp-2 flex-1">{item.product_name}</h4><p className="font-black text-emerald-600 text-[12px]">{Math.round(item.sale_price * item.quantity)} ₪</p></div>
                <p className="text-[9px] text-slate-400 font-bold uppercase">{item.variant_name}</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => updateQuantity(item.variant_id, -1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center shadow-sm active:scale-90"><Minus size={12} /></button>
                    <span className="font-black text-xs w-6 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.variant_id, 1, idx)} className="w-6 h-6 bg-white rounded flex items-center justify-center shadow-sm active:scale-90"><Plus size={12} /></button>
                  </div>
                  <button onClick={() => removeFromCart(idx)} className="text-slate-300 hover:text-rose-500 p-1"><Trash2 size={16} /></button>
                </div>
                {stockError?.id === item.variant_id && <p className="text-[8px] font-black text-rose-600 animate-pulse text-center">الكمية القصوى المتاحة</p>}
              </div>
            ))
          }
        </div>
        <div className="p-6 bg-white border-t-2 border-slate-200 space-y-4 shrink-0 shadow-lg mt-auto z-10">
          <div className="space-y-2"><div className="flex justify-between text-[10px] font-black text-slate-500 px-1 uppercase tracking-tight"><span>تطبيق خصم</span><span>الإجمالي: {Math.round(subtotal)} ₪</span></div><input type="text" inputMode="decimal" className="w-full py-3 bg-slate-50 border-2 border-slate-200 focus:border-[#0f172a] rounded-xl text-center font-black text-xl outline-none" value={discount === 0 ? '' : discount} placeholder="0" onChange={(e) => setDiscount(toLatinDigits(e.target.value))} /></div>
          <div className="pt-2 flex justify-between items-center border-t border-slate-100"><span className="text-[#0f172a] font-black text-xs opacity-60">الصافي للدفع</span><span className="text-2xl font-black text-emerald-600">{Math.round(netAmount)} ₪</span></div>
          <button onClick={handleFinishOrder} disabled={cart.length === 0 || isProcessing} className="w-full py-4.5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-700 active:scale-95 transition-all flex items-center justify-center gap-3">
             {isProcessing ? <Loader2 className="animate-spin" /> : <>إتمام الفاتورة <CheckCircle2 size={20} /></>}
          </button>
        </div>
      </div>

      {showSuccess && (
        <div className="fixed inset-0 z-[300] bg-emerald-600/90 backdrop-blur-sm flex items-center justify-center animate-in fade-in duration-300">
          <div className="bg-white p-10 rounded-[3rem] shadow-2xl flex flex-col items-center gap-6 text-center animate-in zoom-in-95 duration-300 max-w-sm">
            <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center shadow-inner"><CheckCircle2 size={60} /></div>
            <div><h2 className="text-2xl font-black text-slate-900">تم إتمام الفاتورة!</h2><p className="text-slate-500 font-bold mt-1">رقم الفاتورة: {lastInvoice?.id}</p></div>
            <div className="flex flex-col gap-3 w-full">
               <button onClick={() => { if(lastInvoice) printThermalReceipt(lastInvoice); }} className="w-full py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-3 shadow-lg hover:bg-black transition-all"><Printer size={20} className="text-emerald-500" /><span>طباعة الفاتورة</span></button>
               <button onClick={() => { setShowSuccess(false); setTimeout(() => searchInputRef.current?.focus(), 100); }} className="w-full py-4 bg-slate-100 text-slate-600 font-black rounded-2xl hover:bg-slate-200 transition-all">متابعة العمل</button>
            </div>
          </div>
        </div>
      )}

      {selectedProductForVariants && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[250] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-md overflow-hidden animate-slide-in-right">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between"><div className="flex items-center gap-4"><div className="p-2.5 bg-blue-600 rounded-xl"><Layers size={24} /></div><h3 className="text-xl font-black">{selectedProductForVariants.name}</h3></div><button onClick={() => { setSelectedProductForVariants(null); setTimeout(() => searchInputRef.current?.focus(), 100); }} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button></div>
            <div className="p-8 space-y-3 overflow-y-auto max-h-[60vh] custom-scrollbar">
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">يرجى اختيار النوع المطلوب:</p>
              {selectedProductForVariants.variants?.filter((v: any) => v.stock_quantity > 0).map((v: any) => (
                <button 
                  key={v.id} 
                  onClick={() => addToCart(v, selectedProductForVariants)} 
                  className={`w-full p-5 bg-slate-50 border-2 rounded-2xl flex items-center justify-between hover:border-emerald-500 hover:bg-white transition-all group shadow-sm active:scale-95 ${stockError?.id === v.id ? 'border-rose-500 bg-rose-50' : 'border-slate-100'}`}
                >
                  <div className="text-right"><p className="font-black text-slate-800 text-sm">{v.name}</p><p className="text-[10px] text-slate-400 font-bold">الكمية المتوفرة: {v.stock_quantity} قطعة</p></div><span className="font-black text-emerald-600 text-lg">{Math.round(v.sale_price)} ₪</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {showExtraModal && (
        <div className="fixed inset-0 bg-[#0f172a]/95 backdrop-blur-md flex items-center justify-center z-[200] p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-md overflow-hidden border border-slate-200">
            <div className="p-8 bg-[#0f172a] text-white flex items-center justify-between"><div className="flex items-center gap-4"><div className="p-2.5 bg-emerald-600 rounded-xl"><PlusCircle size={24} /></div><h3 className="text-xl font-black">إضافة خدمة يدوية</h3></div><button onClick={() => { setShowExtraModal(false); setTimeout(() => searchInputRef.current?.focus(), 100); }} className="p-2 bg-white/10 rounded-lg"><X size={20} /></button></div>
            <div className="p-8 space-y-6">
              <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">وصف الخدمة</label><input type="text" autoFocus className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" placeholder="مثال: رسوم شحن..." value={extraService.name} onChange={(e) => setExtraService({...extraService, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-5">
                <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">التكلفة (₪)</label><input type="text" inputMode="decimal" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold" value={extraService.cost_price || ''} onChange={(e) => setExtraService({...extraService, cost_price: Number(toLatinDigits(e.target.value))})} /></div>
                <div className="space-y-2"><label className="text-sm font-black text-slate-700 opacity-60">البيع (₪)</label><input type="text" inputMode="decimal" className="w-full p-4.5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-emerald-600 font-bold text-emerald-600" value={extraService.sale_price || ''} onChange={(e) => setExtraService({...extraService, sale_price: Number(toLatinDigits(e.target.value))})} /></div>
              </div>
              <button onClick={handleAddExtraService} disabled={!extraService.name || extraService.sale_price <= 0} className="w-full py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl hover:bg-emerald-700 active:scale-95 transition-all flex items-center justify-center gap-3">إدراج في السلة</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  Target, 
  ChevronDown, 
  X, 
  FileText, 
  Edit2, 
  Trash2, 
  Plus, 
  Minus, 
  Search,
  PlusCircle,
  Receipt,
  Eye,
  Info,
  AlertTriangle,
  CheckCircle2,
  Loader2,
  Zap,
  LayoutList,
  ChevronUp,
  BarChart3,
  ShoppingCart,
  Save,
  Scissors
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [expandedInvoiceId, setExpandedInvoiceId] = useState<string | null>(null);
  const [showFinancials, setShowFinancials] = useState(false);
  const [hoveredTip, setHoveredTip] = useState<string | null>(null);

  const [openSections, setOpenSections] = useState({
    sales: false,
    services: false,
    invoices: true
  });

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTargetId, setDeleteTargetId] = useState<string | null>(null);

  const [editingInvoice, setEditingInvoice] = useState<any>(null);
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [itemSearchTerm, setItemSearchTerm] = useState('');
  const [isSavingEdit, setIsSavingEdit] = useState(false);

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());

  const [data, setData] = useState({
    totalSales: 0,
    totalCost: 0,
    totalProfit: 0,
    itemsCount: 0,
    discounts: 0,
    invoices: [] as any[]
  });

  const [loading, setLoading] = useState(true);

  // Helper for English numbers in Arabic locale
  const formatDateArabicLatin = (date: Date, options: Intl.DateTimeFormatOptions) => {
    return date.toLocaleDateString('ar-EG-u-nu-latn', options);
  };

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();

    const { data: invoices } = await supabase
      .from('invoices')
      .select(`*, invoice_items (*), extra_services (*)`)
      .gte('created_at', start)
      .lte('created_at', end)
      .order('created_at', { ascending: false });

    if (invoices) {
      calculateTotals(invoices);
    }
    setLoading(false);
  };

  const calculateTotals = (invoices: any[]) => {
    let productSales = 0, productCost = 0, extraServiceProfit = 0, totalDiscounts = 0, itemsCount = 0;
    invoices.forEach(inv => {
      totalDiscounts += Number(inv.discount);
      inv.invoice_items.forEach((item: any) => { 
        itemsCount += item.quantity; 
        productSales += (item.sale_price * item.quantity); 
        productCost += (item.cost_price * item.quantity); 
      });
      inv.extra_services.forEach((ser: any) => { 
        itemsCount += ser.quantity; 
        extraServiceProfit += (ser.sale_price - ser.cost_price) * ser.quantity; 
      });
    });
    const totalSales = (productSales - totalDiscounts) + extraServiceProfit;
    const totalProfit = (productSales - productCost - totalDiscounts) + extraServiceProfit;
    setData({ totalSales, totalCost: productCost, totalProfit, itemsCount, discounts: totalDiscounts, invoices });
  };

  const fetchProducts = async () => {
    const { data } = await supabase.from('products').select('*, variants(*)');
    setAllProducts(data || []);
  };

  useEffect(() => { 
    fetchDailyData(selectedDay); 
    fetchProducts();
  }, [selectedDay]);

  const aggregatedStats = useMemo(() => {
    const itemsMap: Record<string, any> = {};
    const servicesMap: Record<string, any> = {};

    data.invoices.forEach(inv => {
      inv.invoice_items.forEach((it: any) => {
        const key = `${it.product_name}-${it.variant_name}`;
        if (!itemsMap[key]) {
          itemsMap[key] = { name: it.product_name, variant: it.variant_name, qty: 0, cost: 0, sale: 0 };
        }
        itemsMap[key].qty += it.quantity;
        itemsMap[key].cost += it.cost_price * it.quantity;
        itemsMap[key].sale += it.sale_price * it.quantity;
      });

      inv.extra_services.forEach((ser: any) => {
        const key = ser.name;
        if (!servicesMap[key]) {
          servicesMap[key] = { name: ser.name, qty: 0, cost: 0, sale: 0 };
        }
        servicesMap[key].qty += ser.quantity;
        servicesMap[key].cost += ser.cost_price * ser.quantity;
        servicesMap[key].sale += ser.sale_price * ser.quantity;
      });
    });

    return {
      products: Object.values(itemsMap).sort((a, b) => b.qty - a.qty),
      services: Object.values(servicesMap).sort((a, b) => b.qty - a.qty)
    };
  }, [data.invoices]);

  const toggleSection = (section: keyof typeof openSections) => {
    setOpenSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const handleStartEdit = (invoice: any) => {
    setEditingInvoice(JSON.parse(JSON.stringify(invoice))); 
    setItemSearchTerm('');
  };

  const updateEditItemQty = (id: string, delta: number, type: 'product' | 'service') => {
    setEditingInvoice((prev: any) => {
      const next = { ...prev };
      if (type === 'product') {
        next.invoice_items = next.invoice_items.map((it: any) => 
          it.id === id ? { ...it, quantity: Math.max(1, it.quantity + delta) } : it
        );
      } else {
        next.extra_services = next.extra_services.map((it: any) => 
          it.id === id ? { ...it, quantity: Math.max(1, it.quantity + delta) } : it
        );
      }
      return next;
    });
  };

  const addProductToEdit = (variant: any, product: any) => {
    setEditingInvoice((prev: any) => {
      const next = { ...prev };
      const existing = next.invoice_items.find((it: any) => it.variant_id === variant.id);
      if (existing) {
        existing.quantity += 1;
      } else {
        next.invoice_items.push({
          id: `new-${Date.now()}`,
          invoice_id: prev.id,
          variant_id: variant.id,
          product_name: product.name,
          variant_name: variant.name,
          quantity: 1,
          cost_price: variant.cost_price,
          sale_price: variant.sale_price
        });
      }
      return next;
    });
    setItemSearchTerm('');
  };

  const removeEditItem = (id: string, type: 'product' | 'service') => {
    setEditingInvoice((prev: any) => {
      const next = { ...prev };
      if (type === 'product') {
        next.invoice_items = next.invoice_items.filter((it: any) => it.id !== id);
      } else {
        next.extra_services = next.extra_services.filter((it: any) => it.id !== id);
      }
      return next;
    });
  };

  const saveInvoiceEdits = async () => {
    if (!editingInvoice || isSavingEdit) return;
    setIsSavingEdit(true);
    try {
      const productTotal = editingInvoice.invoice_items.reduce((s: number, i: any) => s + (i.sale_price * i.quantity), 0);
      const serviceTotal = editingInvoice.extra_services.reduce((s: number, i: any) => s + (i.sale_price * i.quantity), 0);
      const totalAmount = productTotal + serviceTotal;
      const totalCost = editingInvoice.invoice_items.reduce((s: number, i: any) => s + (i.cost_price * i.quantity), 0) + 
                        editingInvoice.extra_services.reduce((s: number, i: any) => s + (i.cost_price * i.quantity), 0);
      const netAmount = totalAmount - Number(editingInvoice.discount);
      const profit = netAmount - totalCost;

      await supabase.from('invoices').update({
        total_amount: totalAmount,
        discount: Number(editingInvoice.discount),
        net_amount: netAmount,
        total_cost: totalCost,
        profit: profit
      }).eq('id', editingInvoice.id);

      await supabase.from('invoice_items').delete().eq('invoice_id', editingInvoice.id);
      await supabase.from('extra_services').delete().eq('invoice_id', editingInvoice.id);

      const itemsToInsert = editingInvoice.invoice_items.map((it: any) => ({
        invoice_id: editingInvoice.id,
        variant_id: it.variant_id,
        product_name: it.product_name,
        variant_name: it.variant_name,
        quantity: it.quantity,
        cost_price: it.cost_price,
        sale_price: it.sale_price
      }));

      const servicesToInsert = editingInvoice.extra_services.map((s: any) => ({
        invoice_id: editingInvoice.id,
        name: s.name || s.product_name,
        cost_price: s.cost_price,
        sale_price: s.sale_price,
        quantity: s.quantity
      }));

      if (itemsToInsert.length > 0) await supabase.from('invoice_items').insert(itemsToInsert);
      if (servicesToInsert.length > 0) await supabase.from('extra_services').insert(servicesToInsert);

      setEditingInvoice(null);
      fetchDailyData(selectedDay);
    } catch (err) {
      console.error(err);
      alert("خطأ أثناء حفظ التعديلات");
    } finally {
      setIsSavingEdit(false);
    }
  };

  const handleDeleteInvoice = async () => {
    if (!deleteTargetId) return;
    setLoading(true);
    await supabase.from('invoices').delete().eq('id', deleteTargetId);
    setShowDeleteConfirm(false);
    setDeleteTargetId(null);
    fetchDailyData(selectedDay);
  };

  const Tooltip = ({ title, formula }: { title: string, formula: string }) => (
    <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 w-48 p-3 bg-[#0f172a] text-white rounded-xl shadow-2xl z-50 animate-in fade-in zoom-in duration-200 border border-emerald-500/30">
      <p className="text-[8px] font-black text-emerald-400 uppercase tracking-widest mb-1">{title}</p>
      <p className="text-[9px] font-bold leading-relaxed opacity-90">{formula}</p>
      <div className="absolute top-full left-1/2 -translate-x-1/2 border-[6px] border-transparent border-t-[#0f172a]"></div>
    </div>
  );

  const filteredProducts = useMemo(() => {
    if (!itemSearchTerm) return [];
    return allProducts.filter(p => p.name.toLowerCase().includes(itemSearchTerm.toLowerCase())).slice(0, 5);
  }, [allProducts, itemSearchTerm]);

  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = formatDateArabicLatin(new Date(year, month), { month: 'long' });

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-4 space-y-4 overflow-hidden font-['Tajawal']" dir="rtl">
      <div className="flex items-center justify-between shrink-0">
        <h2 className="text-lg font-black text-[#0f172a] flex items-center gap-2">
          <BarChart3 className="text-emerald-600" size={20} />
          التقارير اليومية
        </h2>
        <div className="relative">
          <button onClick={() => setShowDayPicker(!showDayPicker)} className="flex items-center gap-2 bg-[#0f172a] text-white px-4 py-2 rounded-xl shadow-lg font-black text-xs">
            <Calendar size={14} className="text-emerald-400" />
            <span className="digit-latin">{selectedDay} {monthName}</span>
            <ChevronDown size={14} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <>
              <div className="fixed inset-0 z-[110]" onClick={() => setShowDayPicker(false)} />
              <div className="absolute top-12 left-0 w-56 bg-white rounded-2xl shadow-2xl border border-slate-200 p-3 z-[111]">
                <div className="grid grid-cols-7 gap-1">
                  {daysInMonth.map(day => (
                    <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-7 h-7 rounded-lg flex items-center justify-center font-bold text-[10px] digit-latin ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      <div className="relative shrink-0 overflow-hidden rounded-2xl">
        <div className={`grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-3 transition-all duration-500 ${!showFinancials ? 'blur-md grayscale opacity-40 select-none pointer-events-none' : ''}`}>
          {[
            { id: 'sales', label: 'المبيعات', value: data.totalSales, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50', formula: 'المبيعات = (بيع المنتجات - الخصم) + (ربح الخدمات)' },
            { id: 'cost', label: 'التكاليف', value: data.totalCost, icon: DollarSign, color: 'text-slate-500', bg: 'bg-slate-50', formula: 'مجموع جملة تكلفة المنتجات فقط' },
            { id: 'profit', label: 'صافي الربح', value: data.totalProfit, icon: Target, color: 'text-emerald-600', bg: 'bg-emerald-50', formula: 'صافي الربح = (ربح المنتجات - الخصم) + (ربح الخدمات)' },
            { id: 'items', label: 'القطع', value: data.itemsCount, icon: Package, color: 'text-blue-600', bg: 'bg-blue-50', formula: 'عدد القطع والخدمات المباعة' },
            { id: 'discounts', label: 'الخصومات', value: data.discounts, icon: Receipt, color: 'text-rose-600', bg: 'bg-rose-50', formula: 'مجموع الخصومات الممنوحة' }
          ].map((stat) => (
            <div key={stat.id} className="p-3 bg-white rounded-xl border border-slate-200 shadow-sm flex flex-col gap-1 relative group">
              <div className="flex justify-between items-start">
                <div className={`p-1.5 rounded-lg ${stat.bg} ${stat.color}`}><stat.icon size={16} /></div>
                <div className="relative"><Info size={12} className="text-slate-300 hover:text-[#0f172a] cursor-help" onMouseEnter={() => setHoveredTip(stat.id)} onMouseLeave={() => setHoveredTip(null)} />{hoveredTip === stat.id && <Tooltip title={stat.label} formula={stat.formula} />}</div>
              </div>
              <div><p className="text-[8px] font-black uppercase opacity-60">{stat.label}</p><p className="text-sm font-black truncate digit-latin">{Math.round(stat.value)} ₪</p></div>
            </div>
          ))}
        </div>
        {!showFinancials && (
          <div className="absolute inset-0 z-20 flex items-center justify-center">
            <div className="absolute inset-0 bg-white/40 backdrop-blur-[2px]" />
            <button onClick={() => setShowFinancials(true)} className="relative z-30 flex flex-col items-center gap-1.5 bg-[#0f172a] text-white px-8 py-3 rounded-2xl shadow-2xl hover:bg-slate-800 transition-all">
              <Eye size={20} className="text-emerald-500" />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">كشف البيانات المالية</span>
            </button>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar space-y-4 pb-10">
        <div className="bg-white border border-slate-200 rounded-[1.8rem] shadow-sm overflow-hidden">
          <button onClick={() => toggleSection('sales')} className="w-full p-5 flex items-center justify-between hover:bg-slate-50 transition-colors">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-emerald-100 text-emerald-600 rounded-xl"><LayoutList size={20} /></div>
              <div className="text-right"><h3 className="font-black text-slate-900 text-sm">ملخص المنتجات المباعة</h3><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Aggregate Product Sales</p></div>
            </div>
            {openSections.sales ? <ChevronUp size={20} className="text-slate-400" /> : <ChevronDown size={20} className="text-slate-400" />}
          </button>
          {openSections.sales && (
            <div className="p-5 pt-0 border-t border-slate-50 animate-in slide-in-from-top-2">
              <div className="overflow-x-auto mt-4">
                <table className="w-full text-right border-collapse">
                  <thead><tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest"><th className="p-3">الصنف / النوع</th><th className="p-3 text-center">الكمية</th><th className="p-3 text-center">إجمالي التكلفة</th><th className="p-3 text-center">إجمالي البيع</th><th className="p-3 text-left text-emerald-600">الربح الصافي</th></tr></thead>
                  <tbody className="divide-y divide-slate-100">
                    {aggregatedStats.products.map((p, i) => (
                      <tr key={i} className="text-[11px] font-bold text-slate-700"><td className="p-3"><span className="block font-black text-slate-900">{p.name}</span><span className="text-[9px] text-slate-400">{p.variant}</span></td><td className="p-3 text-center font-black digit-latin">x{p.qty}</td><td className="p-3 text-center text-slate-400 digit-latin">{Math.round(p.cost)} ₪</td><td className="p-3 text-center digit-latin">{Math.round(p.sale)} ₪</td><td className="p-3 text-left font-black text-emerald-600 digit-latin">+{Math.round(p.sale - p.cost)} ₪</td></tr>
                    ))}
                    {aggregatedStats.products.length === 0 && <tr><td colSpan={5} className="p-10 text-center text-slate-400 font-bold">لا يوجد مبيعات منتجات اليوم</td></tr>}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        <div className="bg-white border border-slate-200 rounded-[1.8rem] shadow-sm overflow-hidden">
          <button onClick={() => toggleSection('services')} className="w-full p-5 flex items-center justify-between hover:bg-slate-50 transition-colors">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-blue-100 text-blue-600 rounded-xl"><Zap size={20} /></div>
              <div className="text-right"><h3 className="font-black text-slate-900 text-sm">ملخص الخدمات المقدمة</h3><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Aggregate Services Sold</p></div>
            </div>
            {openSections.services ? <ChevronUp size={20} className="text-slate-400" /> : <ChevronDown size={20} className="text-slate-400" />}
          </button>
          {openSections.services && (
            <div className="p-5 pt-0 border-t border-slate-50 animate-in slide-in-from-top-2">
              <div className="overflow-x-auto mt-4">
                <table className="w-full text-right border-collapse">
                  <thead><tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest"><th className="p-3 text-right">اسم الخدمة</th><th className="p-3 text-center">الكمية</th><th className="p-3 text-center">إجمالي التكلفة</th><th className="p-3 text-center">إجمالي البيع</th><th className="p-3 text-left text-blue-600">الربح</th></tr></thead>
                  <tbody className="divide-y divide-slate-100">
                    {aggregatedStats.services.map((s, i) => (
                      <tr key={i} className="text-[11px] font-bold text-slate-700">
                        <td className="p-3"><span className="block font-black text-slate-900">{s.name}</span></td>
                        <td className="p-3 text-center font-black digit-latin">x{s.qty}</td>
                        <td className="p-3 text-center text-slate-400 digit-latin">{Math.round(s.cost)} ₪</td>
                        <td className="p-3 text-center digit-latin">{Math.round(s.sale)} ₪</td>
                        <td className="p-3 text-left font-black text-blue-600 digit-latin">+{Math.round(s.sale - s.cost)} ₪</td>
                      </tr>
                    ))}
                    {aggregatedStats.services.length === 0 && <tr><td colSpan={5} className="p-10 text-center text-slate-400 font-bold">لم يتم تقديم خدمات اليوم</td></tr>}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        <div className="bg-white border border-slate-200 rounded-[1.8rem] shadow-sm overflow-hidden">
          <button onClick={() => toggleSection('invoices')} className="w-full p-5 flex items-center justify-between hover:bg-slate-50 transition-colors">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-slate-900 text-white rounded-xl"><Receipt size={20} /></div>
              <div className="text-right"><h3 className="font-black text-slate-900 text-sm">سجل الفواتير الصادرة</h3><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Individual Invoice Logs</p></div>
            </div>
            {openSections.invoices ? <ChevronUp size={20} className="text-slate-400" /> : <ChevronDown size={20} className="text-slate-400" />}
          </button>
          {openSections.invoices && (
            <div className="p-5 pt-0 border-t border-slate-50 space-y-3 animate-in slide-in-from-top-2">
              <div className="mt-4 space-y-3">
                {data.invoices.map((inv) => (
                  <div key={inv.id} className="bg-slate-50/50 border border-slate-200 rounded-2xl overflow-hidden flex flex-col transition-all">
                    <div className="p-4 flex items-center justify-between group">
                      <button onClick={() => setExpandedInvoiceId(expandedInvoiceId === inv.id ? null : inv.id)} className="flex items-center gap-4 flex-1 text-right">
                        <div className={`p-2 rounded-xl ${expandedInvoiceId === inv.id ? 'bg-emerald-600 text-white' : 'bg-white text-slate-400'}`}><FileText size={18} /></div>
                        <div><p className="font-mono text-[9px] text-slate-400 digit-latin">#{inv.id.slice(0, 8)}</p><p className="font-black text-[11px] text-slate-900 digit-latin">{new Date(inv.created_at).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}</p></div>
                      </button>
                      <div className="flex items-center gap-4">
                        <div className="text-left"><p className="text-[9px] font-black text-slate-400 line-through digit-latin">{Math.round(inv.total_amount)} ₪</p><p className="font-black text-emerald-600 text-sm digit-latin">{Math.round(inv.net_amount)} ₪</p></div>
                        <div className="flex items-center gap-1">
                          <button onClick={() => handleStartEdit(inv)} className="p-2 text-slate-300 hover:text-emerald-600 transition-all"><Edit2 size={16} /></button>
                          <button onClick={() => { setDeleteTargetId(inv.id); setShowDeleteConfirm(true); }} className="p-2 text-slate-300 hover:text-rose-600 transition-all"><Trash2 size={16} /></button>
                        </div>
                        <ChevronDown size={18} className={`text-slate-300 transition-transform ${expandedInvoiceId === inv.id ? 'rotate-180' : ''}`} />
                      </div>
                    </div>
                    {expandedInvoiceId === inv.id && (
                      <div className="p-4 bg-white border-t border-slate-100">
                        <div className="flex justify-between items-center text-[10px] mb-4 p-2 bg-slate-50 rounded-xl">
                           <span className="text-slate-500 font-bold">صافي الربح لهذه الفاتورة:</span>
                           <span className="text-emerald-600 font-black digit-latin">{Math.round(inv.profit)} ₪</span>
                        </div>
                        <table className="w-full text-right text-[10px]">
                           <thead><tr className="text-slate-400 font-black"><th>الصنف</th><th className="text-center">الكمية</th><th className="text-left">المجموع</th></tr></thead>
                           <tbody className="divide-y divide-slate-50">
                              {inv.invoice_items.map((it: any) => (<tr key={it.id} className="text-slate-700"><td className="py-2">{it.product_name} <span className="text-slate-400">({it.variant_name})</span></td><td className="text-center font-black digit-latin">x{it.quantity}</td><td className="text-left font-black digit-latin">{Math.round(it.sale_price * it.quantity)} ₪</td></tr>))}
                              {inv.extra_services.map((ser: any) => (<tr key={ser.id} className="text-blue-600 italic"><td className="py-2">{ser.name} (خدمة)</td><td className="text-center font-black digit-latin">x{ser.quantity}</td><td className="text-left font-black digit-latin">{Math.round(ser.sale_price * ser.quantity)} ₪</td></tr>))}
                           </tbody>
                        </table>
                      </div>
                    )}
                  </div>
                ))}
                {data.invoices.length === 0 && <div className="p-20 text-center text-slate-300 font-bold">لا يوجد فواتير مسجلة اليوم</div>}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

