        <div className="flex items-center gap-5 relative z-10">
          <div className="p-4 bg-emerald-600 rounded-2xl shadow-xl shadow-emerald-900/40 text-white">
            <PieChart size={28} />
          </div>
          <div>
            <h2 className="text-2xl font-black text-white tracking-tight">التقارير والذكاء المالي</h2>
            <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em] mt-1">Flyyti Business Intelligence</p>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row items-center gap-3 w-full lg:w-auto relative z-10">
          <div className="flex bg-white/5 p-1 rounded-2xl border border-white/10 w-full sm:w-auto">
            {(['day', 'month', 'year', 'custom'] as const).map((p) => (
              <button
                key={p}
                onClick={() => handlePeriodChange(p)}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black transition-all ${period === p ? 'bg-white text-[#0f172a] shadow-lg' : 'text-slate-400 hover:text-white'}`}
              >
                {p === 'day' ? 'اليوم' : p === 'month' ? 'الشهر' : p === 'year' ? 'السنة' : 'مخصص'}
