type FilterMode = 'day' | 'month' | 'year';

// Helper for Arabic locale with Latin digits
const formatDateTimeArabicLatin = (date: Date) => {
  return date.toLocaleTimeString('ar-EG-u-nu-latn', { hour: '2-digit', minute: '2-digit', hour12: true });
};

const Invoices: React.FC<{ settings: AppSettings | null, onUpdateSettings: () => void }> = ({ settings, onUpdateSettings }) => {
  const [invoices, setInvoices] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteTargetId, setDeleteTargetId] = useState<string | null>(null);

  const [filterMode] = useState<FilterMode>('day');
  const [selectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [selectedMonth] = useState<number>(new Date().getMonth());
  const [selectedYear] = useState<number>(new Date().getFullYear());

  const fetchInvoices = useCallback(async () => {
    setLoading(true);
    let start, end;
    if (filterMode === 'day') { start = `${selectedDate}T00:00:00.000Z`; end = `${selectedDate}T23:59:59.999Z`; } 
    else if (filterMode === 'month') { const firstDay = new Date(selectedYear, selectedMonth, 1); const lastDay = new Date(selectedYear, selectedMonth + 1, 0); start = firstDay.toISOString(); end = lastDay.toISOString().split('T')[0] + 'T23:59:59.999Z'; } 
    else { const firstDay = new Date(selectedYear, 0, 1); const lastDay = new Date(selectedYear, 11, 31); start = firstDay.toISOString(); end = lastDay.toISOString().split('T')[0] + 'T23:59:59.999Z'; }

    const { data, error } = await supabase.from('invoices').select(`*, invoice_items (*), extra_services (*)`).order('created_at', { ascending: false });
    if (!error) setInvoices(data || []);
    setLoading(false);
  }, [filterMode, selectedDate, selectedMonth, selectedYear]);

  useEffect(() => { fetchInvoices(); }, [fetchInvoices]);

  const requestDelete = (id: string) => {
    setDeleteTargetId(id);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async () => {
    if (!deleteTargetId) return;
    await supabase.from('invoices').delete().eq('id', deleteTargetId);
    setShowDeleteConfirm(false);
    setDeleteTargetId(null);
    fetchInvoices();
  };

  const handlePrint = (invoice: any) => {
    printThermalReceipt(invoice);
  };

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-6 space-y-6 overflow-hidden font-['Tajawal']" dir="rtl">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0">
        <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3"><FileText className="text-slate-900" />سجل الفواتير</h2>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
           <div className="relative flex-1 md:flex-none">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="بحث برقم الفاتورة..." 
                className="w-full md:w-64 pr-12 pl-4 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold outline-none focus:border-slate-900" 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(e.target.value)} 
              />
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col flex-1 relative">
        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-right border-collapse">
            <thead className="sticky top-0 bg-slate-900 text-white z-10">
              <tr>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-right">رقم الفاتورة / التوقيت</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">إجمالي القيمة</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الخصم</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">صافي المدفوع</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-center">الربح</th>
                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-left">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {invoices.filter(i => i.id.toLowerCase().includes(searchTerm.toLowerCase())).map(i => (
                <tr key={i.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="p-6"><div className="flex flex-col gap-1"><span className="font-mono text-sm font-black text-slate-900 digit-latin">{i.id}</span><div className="flex items-center gap-2 text-slate-400 font-bold text-[10px] digit-latin"><Clock size={12} />{formatDateTimeArabicLatin(new Date(i.created_at))}</div></div></td>
                  <td className="p-6 text-center"><span className="font-bold text-slate-400 text-xs digit-latin">{Math.round(i.total_amount)} ₪</span></td>
                  <td className="p-6 text-center"><span className={`px-3 py-1 rounded-lg text-[10px] font-black digit-latin ${Number(i.discount) > 0 ? 'bg-rose-50 text-rose-500 border border-rose-100' : 'text-slate-300'}`}>{Number(i.discount) > 0 ? `-${Math.round(i.discount)} ₪` : '0'}</span></td>
                  <td className="p-6 text-center"><span className="font-black text-emerald-600 text-lg digit-latin">{Math.round(i.net_amount)} ₪</span></td>
                  <td className="p-6 text-center"><div className="inline-flex items-center justify-center gap-1.5 px-3 py-1 bg-slate-900 text-white rounded-xl text-xs font-black shadow-lg shadow-slate-200 digit-latin">{Math.round(i.profit)} ₪</div></td>
                  <td className="p-6 text-left"><div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all"><button onClick={() => handlePrint(i)} className="p-3 text-emerald-600 hover:bg-emerald-50 bg-slate-50 rounded-xl"><Printer size={18} /></button><button onClick={() => requestDelete(i.id)} className="p-3 text-rose-600 hover:bg-rose-50 bg-slate-50 rounded-xl"><Trash2 size={18} /></button></div></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

