const LowStockIndicator: React.FC = () => {
  const [lowStockItems, setLowStockItems] = useState<any[]>([]);
  const [showList, setShowList] = useState(false);

  const fetchLowStock = async () => {
    const { data } = await supabase
      .from('variants')
      .select('*, products(name, barcode)')
      .lte('stock_quantity', 0);
    setLowStockItems(data || []);
  };

  useEffect(() => {
    fetchLowStock();
    const interval = setInterval(fetchLowStock, 60000);
    return () => clearInterval(interval);
  }, []);

  if (lowStockItems.length === 0) return null;

  return (
    <div className="relative">
      <button 
        onClick={() => setShowList(!showList)}
        className="relative p-2 bg-rose-500/10 text-rose-500 rounded-xl hover:bg-rose-500/20 transition-all border border-rose-500/20"
      >
        <Bell size={20} />
        <span className="absolute -top-1 -left-1 w-5 h-5 bg-rose-600 text-white text-[10px] font-black rounded-full flex items-center justify-center border-2 border-[#0f172a] animate-pulse">
          {lowStockItems.length}
        </span>
      </button>

      {showList && (
        <>
          <div className="fixed inset-0 z-[110]" onClick={() => setShowList(false)} />
          <div className="absolute top-14 left-0 w-64 sm:w-72 bg-white rounded-2xl shadow-2xl border border-slate-200 z-[111] overflow-hidden animate-in fade-in slide-in-from-top-2">
            <div className="p-4 bg-rose-600 text-white flex items-center gap-3">
              <AlertTriangle size={18} />
              <span className="font-black text-xs">أصناف نفدت من المخزون</span>
            </div>
            <div className="max-h-64 overflow-y-auto custom-scrollbar p-2 space-y-1">
              {lowStockItems.map((item, idx) => (
                <div key={idx} className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                  <p className="font-black text-[11px] text-slate-900 leading-tight">{item.products?.name}</p>
                  <p className="text-[9px] text-slate-400 font-bold">{item.name} | {item.products?.barcode || 'بدون باركود'}</p>
                </div>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

