const PageAuthOverlay: React.FC<{ expectedPin: string, onUnlock: () => void, pageLabel: string }> = ({ expectedPin, onUnlock, pageLabel }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (password === expectedPin) {
      setTimeout(() => { onUnlock(); setLoading(false); }, 300);
    } else {
      setTimeout(() => { setError('رمز الدخول غير صحيح'); setLoading(false); setPassword(''); }, 200);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-[#0f172a] flex items-center justify-center p-4 sm:p-6 overflow-hidden">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] sm:rounded-[3rem] shadow-2xl overflow-hidden relative z-10 border border-white/10 animate-in zoom-in duration-300">
        <div className="p-8 sm:p-10 text-center bg-slate-50 border-b border-slate-100">
          <div className="inline-flex items-center justify-center w-16 h-16 sm:w-20 sm:h-20 bg-[#0f172a] rounded-[1.5rem] sm:rounded-[1.8rem] shadow-2xl mb-4 sm:mb-6">
            <Lock className="text-emerald-500" size={30} />
          </div>
          <h2 className="text-xl sm:text-2xl font-black text-[#0f172a] tracking-tight">منطقة محمية</h2>
          <div className="mt-2 px-4 py-1.5 bg-emerald-50 text-emerald-600 rounded-xl inline-block text-[10px] sm:text-[11px] font-black uppercase tracking-widest border border-emerald-100">
            {pageLabel}
          </div>
        </div>

        <div className="p-8 sm:p-10">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="p-4 bg-rose-50 border-r-4 border-rose-500 text-rose-700 text-xs font-black animate-shake rounded-xl flex items-center gap-2">
                <ShieldAlert size={16} />
                {error}
              </div>
            )}
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 mr-2 uppercase tracking-widest">رمز مرور الصفحة</label>
              <input
                type="password"
                required
                autoFocus
                inputMode="numeric"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full py-4 sm:py-5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-[#0f172a] outline-none font-black text-slate-900 text-center text-2xl sm:text-3xl tracking-[0.5em]"
                placeholder="••••"
              />
            </div>
            <button
              type="submit"
              disabled={loading}
              className="w-full py-4 sm:py-5 bg-[#0f172a] text-white font-black text-lg rounded-2xl shadow-xl hover:bg-black transition-all flex items-center justify-center gap-3"
            >
              {loading ? <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin" /> : <><span>تأكيد الدخول</span><ArrowLeft size={20} /></>}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

const PageGuard: React.FC<{ children: React.ReactNode, pageId: string, pageLabel: string, settings: AppSettings | null }> = ({ children, pageId, pageLabel, settings }) => {
  const [isUnlocked, setIsUnlocked] = useState(false);
  const location = useLocation();

  useEffect(() => { setIsUnlocked(false); }, [location.pathname]);

  const needsProtection = useMemo(() => settings?.protection_enabled && settings?.page_locks?.[pageId], [settings, pageId]);

  if (!needsProtection || isUnlocked) return <>{children}</>;

  return <PageAuthOverlay expectedPin={settings?.page_password || '1234'} pageLabel={pageLabel} onUnlock={() => setIsUnlocked(true)} />;
};

const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  if (settings && !settings.login_protection_enabled) return <>{children}</>;
  const loggedUser = localStorage.getItem('flyyti_user');
  if (!loggedUser) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

