import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingBag,
  X,
  CheckCircle2,
  Loader2,
  PlusCircle,
  Barcode,
  Layers,
  Printer,
  AlertTriangle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';
import { printThermalReceipt } from '../utils/printThermal';
import { playScanBeep } from '../utils/audio';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [selectedSubCat, setSelectedSubCat] = useState<string | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(true);
  const [showExtraModal, setShowExtraModal] = useState(false);
  const [selectedProductForVariants, setSelectedProductForVariants] = useState<any>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [stockError, setStockError] = useState<{id: string, msg: string} | null>(null);

  const [cart, setCart] = useState<any[]>(() => {
    const saved = localStorage.getItem('flyyti_current_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState<number | string>(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<any>(null);
  const [extraService, setExtraService] = useState<ExtraService>({ 
    name: '', cost_price: 0, sale_price: 0, quantity: 1 
  });

  useEffect(() => {
    fetchData();
    setTimeout(() => searchInputRef.current?.focus(), 500);
  }, []);

  useEffect(() => {
    localStorage.setItem('flyyti_current_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const triggerStockError = (id: string) => {
    setStockError({ id, msg: "لا يمكن إضافة أكثر من الكمية المتوفرة" });
    setTimeout(() => setStockError(null), 2500);
  };

  const addToCart = (variant: Variant, product: any) => {
    if (variant.stock_quantity <= 0) return;
    const existingInCart = cart.find(item => item.variant_id === variant.id);
    const currentQtyInCart = existingInCart ? existingInCart.quantity : 0;

    if (currentQtyInCart + 1 > variant.stock_quantity) {
      triggerStockError(variant.id);
      return;
    }

    playScanBeep();
    setCart(prev => {
      if (existingInCart) {
        return prev.map(item => item.variant_id === variant.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { 
        variant_id: variant.id, product_name: product.name, variant_name: variant.name, 
        cost_price: variant.cost_price, sale_price: variant.sale_price, quantity: 1, type: 'product' 
      }];
    });
    setSelectedProductForVariants(null);
    if (window.innerWidth >= 1024) searchInputRef.current?.focus();
  };

  const handleProductClick = (product: any) => {
    if (!product.variants || product.variants.length === 0) return;
    const availableVariants = product.variants.filter((v: any) => v.stock_quantity > 0);
    if (availableVariants.length === 0) return;
    if (availableVariants.length === 1) addToCart(availableVariants[0], product);
    else setSelectedProductForVariants(product);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && searchTerm.trim()) {
      const exactMatch = products.find(p => p.barcode === searchTerm.trim());
      if (exactMatch) { handleProductClick(exactMatch); setSearchTerm(''); }
    }
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    try {
      const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
      const discNum = Number(discount) || 0;
      const netAmount = Math.max(0, subtotal - discNum);
      const totalCost = cart.reduce((sum, item) => sum + (item.cost_price * item.quantity), 0);

      const { data: invoice, error: invError } = await supabase.from('invoices').insert({
        total_amount: subtotal, discount: discNum, net_amount: netAmount, total_cost: totalCost, profit: netAmount - totalCost
      }).select().single();

      if (invError) throw invError;

      const items = cart.filter(c => c.type === 'product');
      if (items.length > 0) {
        await supabase.from('invoice_items').insert(items.map(item => ({
          invoice_id: invoice.id, variant_id: item.variant_id, product_name: item.product_name, 
          variant_name: item.variant_name, quantity: item.quantity, cost_price: item.cost_price, sale_price: item.sale_price
        })));
        for (const item of items) {
          const { data: v } = await supabase.from('variants').select('stock_quantity').eq('id', item.variant_id).single();
          if (v) await supabase.from('variants').update({ stock_quantity: v.stock_quantity - item.quantity }).eq('id', item.variant_id);
        }
      }
      setLastInvoice({ ...invoice, invoice_items: items });
      setCart([]); setDiscount(0);
      localStorage.removeItem('flyyti_current_cart');
      setShowSuccess(true);
      fetchData();
    } catch (e) { alert("خطأ في إتمام الطلب"); } finally { setIsProcessing(false); }
  };

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchMainCat = selectedMainCat ? p.category_id === selectedMainCat : true;
      const matchSubCat = selectedSubCat ? p.sub_category_id === selectedSubCat : true;
      const hasStock = (p.variants?.reduce((s: number, v: any) => s + v.stock_quantity, 0) || 0) > 0;
      return matchSearch && matchMainCat && matchSubCat && hasStock;
    });
  }, [products, searchTerm, selectedMainCat, selectedSubCat]);

  const subtotal = cart.reduce((sum, item) => sum + (item.sale_price * item.quantity), 0);
  const netAmount = Math.max(0, subtotal - Number(discount));

  return (
    <div className="flex flex-col lg:flex-row h-full font-['Tajawal'] bg-[#f8fafc] overflow-hidden" dir="rtl">

      {/* 1. Products Area */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        {/* Search & Categories Bar */}
        <div className="bg-white p-4 sm:p-6 border-b border-slate-200 shadow-sm shrink-0 z-20">
          <div className="flex flex-col sm:flex-row gap-4">
            <div className="relative flex-1 group">
              <input 
                ref={searchInputRef} 
                type="text" 
                placeholder="البحث بالاسم أو الباركود..." 
                className="w-full pr-12 pl-12 py-3.5 sm:py-4 bg-slate-50 border-2 border-slate-200 focus:border-emerald-600 rounded-2xl outline-none font-black text-sm sm:text-lg transition-all" 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(e.target.value)} 
                onKeyDown={handleKeyDown} 
              />
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-emerald-600" size={20} />
              <Barcode className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
            </div>
            <div className="flex gap-2">
              <button onClick={() => setShowExtraModal(true)} className="flex-1 sm:flex-none px-6 py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-2 hover:bg-black transition-all shadow-lg">
                <PlusCircle size={20} /> <span className="hidden sm:inline">خدمة يدوية</span> <span className="sm:hidden">خدمة</span>
              </button>
              <button onClick={() => setIsCartOpen(!isCartOpen)} className="lg:hidden p-4 bg-emerald-600 text-white rounded-2xl shadow-lg active:scale-95">
                <ShoppingBag size={24} />
              </button>
            </div>
          </div>

          <div className="flex items-center gap-2 overflow-x-auto mt-4 pb-2 no-scrollbar scroll-smooth">
            <button 
              onClick={() => { setSelectedMainCat(null); setSelectedSubCat(null); }}
              className={`px-5 py-2 rounded-xl text-xs font-black whitespace-nowrap border-2 transition-all ${!selectedMainCat ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-slate-200 text-slate-400'}`}
            >
              الكل
            </button>
            {categories.filter(c => !c.parent_id).map(cat => (
              <button 
                key={cat.id} 
                onClick={() => { setSelectedMainCat(cat.id); setSelectedSubCat(null); }}
                className={`px-5 py-2 rounded-xl text-xs font-black whitespace-nowrap border-2 transition-all ${selectedMainCat === cat.id ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-slate-200 text-slate-400'}`}
              >
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        {/* Products Grid */}
        <div className="flex-1 p-4 sm:p-6 grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-3 sm:gap-4 overflow-y-auto custom-scrollbar bg-slate-50/50">
          {filteredProducts.map(p => (
            <button 
              key={p.id} 
              onClick={() => handleProductClick(p)}
              className="group bg-white p-4 sm:p-5 rounded-[1.8rem] border border-slate-200 hover:border-emerald-600 hover:shadow-xl transition-all duration-300 text-right flex flex-col gap-3 relative h-fit active:scale-95 shadow-sm"
            >
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-black px-2 py-1 rounded-lg bg-emerald-50 text-emerald-600 border border-emerald-100">
                  {p.variants?.reduce((s:number, v:any)=>s+v.stock_quantity,0)} قطعة
                </span>
                <Plus size={18} className="text-slate-300 group-hover:text-emerald-600" />
              </div>
              <div className="flex-1">
                <h3 className="font-black text-[#0f172a] text-xs sm:text-sm leading-tight line-clamp-2">{p.name}</h3>
