        </div>
      </div>

      {/* 2. Cart Area (Invoice) */}
      <div className={`
        fixed lg:relative inset-y-0 left-0 lg:w-[360px] xl:w-[400px] bg-white border-r border-slate-200 shadow-2xl lg:shadow-none 
        transition-all duration-300 z-[150] lg:z-10 flex flex-col
        ${isCartOpen ? 'translate-x-0 w-full sm:w-[360px]' : 'translate-x-full lg:translate-x-0 lg:w-0 overflow-hidden'}
      `}>
        <div className="p-6 bg-[#0f172a] text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <ShoppingBag size={22} className="text-emerald-500" />
            <span className="font-black text-lg">الفاتورة الحالية</span>
          </div>
          <button onClick={() => setIsCartOpen(false)} className="lg:hidden p-2 bg-white/10 rounded-lg"><X size={24} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-10 py-10">
              <ShoppingBag size={64} />
              <p className="font-black mt-4">السلة فارغة</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={idx} className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col gap-3">
                <div className="flex justify-between items-start gap-2">
                  <div className="flex-1">
                    <h4 className="font-black text-[#0f172a] text-xs line-clamp-2">{item.product_name}</h4>
                    <span className="text-[10px] text-slate-400 font-bold uppercase">{item.variant_name}</span>
                  </div>
                  <p className="font-black text-emerald-600 text-sm whitespace-nowrap">{Math.round(item.sale_price * item.quantity)} ₪</p>
                </div>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 bg-slate-100 p-1.5 rounded-xl">
                    <button onClick={() => {
                       if (item.quantity > 1) {
                         setCart(prev => prev.map((it, i) => i === idx ? { ...it, quantity: it.quantity - 1 } : it));
                       }
                    }} className="w-8 h-8 bg-white rounded-lg flex items-center justify-center shadow-sm active:scale-90"><Minus size={14} /></button>
                    <span className="font-black text-sm w-6 text-center">{item.quantity}</span>
                    <button onClick={() => {
                      const p = products.find(prod => prod.variants.some((v:any)=>v.id === item.variant_id));
                      const v = p?.variants.find((v:any)=>v.id === item.variant_id);
                      if (v && item.quantity + 1 > v.stock_quantity) triggerStockError(item.variant_id);
                      else setCart(prev => prev.map((it, i) => i === idx ? { ...it, quantity: it.quantity + 1 } : it));
                    }} className="w-8 h-8 bg-white rounded-lg flex items-center justify-center shadow-sm active:scale-90"><Plus size={14} /></button>
                  </div>
                  <button onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))} className="p-2 text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-white border-t border-slate-200 space-y-4 shrink-0 shadow-lg mt-auto">
          <div className="space-y-3">
            <div className="flex justify-between items-center px-1">
              <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">تطبيق خصم (₪)</span>
              <span className="text-xs font-black text-slate-600">الإجمالي: {Math.round(subtotal)} ₪</span>
            </div>
            <input 
              type="number" 
              className="w-full py-3 bg-slate-50 border-2 border-slate-100 rounded-xl text-center font-black text-xl outline-none focus:border-emerald-600 shadow-inner" 
              value={discount || ''} 
              placeholder="0" 
              onChange={(e) => setDiscount(e.target.value)} 
            />
          </div>
          <div className="pt-2 flex justify-between items-center border-t border-slate-100">
            <span className="text-[#0f172a] font-black text-xs opacity-60">الصافي للدفع</span>
            <span className="text-3xl font-black text-emerald-600">{Math.round(netAmount)} ₪</span>
          </div>
          <button 
            onClick={handleFinishOrder} 
            disabled={cart.length === 0 || isProcessing} 
            className="w-full py-5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl hover:bg-emerald-500 disabled:bg-slate-200 transition-all active:scale-[0.98] flex items-center justify-center gap-3"
          >
             {isProcessing ? <Loader2 className="animate-spin" /> : <>إتمام الفاتورة <CheckCircle2 size={24} /></>}
          </button>
        </div>
      </div>

      {/* Tilted Modal for Stock Errors */}
      {stockError && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[400] bg-rose-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-4">
          <AlertTriangle size={24} className="animate-pulse" />
          <span className="font-black text-sm">{stockError.msg}</span>
        </div>
      )}

      {/* Modals remain structurally same but with responsive p-4/p-8 */}
      {showSuccess && (
        <div className="fixed inset-0 z-[300] bg-emerald-600/90 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white p-8 sm:p-10 rounded-[2.5rem] shadow-2xl flex flex-col items-center gap-6 text-center animate-in zoom-in duration-300 max-w-sm w-full">
            <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center shadow-inner"><CheckCircle2 size={48} /></div>
            <div><h2 className="text-2xl font-black text-slate-900">تم إتمام العملية!</h2><p className="text-slate-500 font-bold mt-1">رقم الفاتورة: {lastInvoice?.id.slice(0,8)}</p></div>
            <div className="flex flex-col gap-3 w-full">
               <button onClick={() => { if(lastInvoice) printThermalReceipt(lastInvoice); }} className="w-full py-4 bg-[#0f172a] text-white font-black rounded-2xl flex items-center justify-center gap-3 shadow-lg hover:bg-black transition-all"><Printer size={20} /><span>طباعة الفاتورة</span></button>
               <button onClick={() => { setShowSuccess(false); if(window.innerWidth>=1024) searchInputRef.current?.focus(); }} className="w-full py-4 bg-slate-100 text-slate-600 font-black rounded-2xl hover:bg-slate-200">متابعة البيع</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

