        </div>
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-2xl"><PackageX size={24} /></div>
          <div><p className="text-[10px] font-black text-rose-600 uppercase tracking-widest">أصناف نافدة</p><p className="text-xl font-black text-rose-600">{outOfStock.length}</p></div>
