import React, { useState, useEffect, useMemo } from 'react';
import { 
  Calendar, TrendingUp, DollarSign, Package, Target, ChevronDown, FileText, Edit2, Trash2, Info, Receipt, Eye, LayoutList, Zap, BarChart3, ChevronUp
} from 'lucide-react';
import { supabase } from '../supabase';

const DailyReports: React.FC = () => {
  const [selectedDay, setSelectedDay] = useState(new Date().getDate());
  const [showDayPicker, setShowDayPicker] = useState(false);
  const [expandedInvoiceId, setExpandedInvoiceId] = useState<string | null>(null);
  const [showFinancials, setShowFinancials] = useState(false);
  const [openSections, setOpenSections] = useState({ sales: false, services: false, invoices: true });

  const [month] = useState(new Date().getMonth());
  const [year] = useState(new Date().getFullYear());
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState({ totalSales: 0, totalCost: 0, totalProfit: 0, itemsCount: 0, discounts: 0, invoices: [] as any[] });

  const fetchDailyData = async (day: number) => {
    setLoading(true);
    const start = new Date(year, month, day, 0, 0, 0).toISOString();
    const end = new Date(year, month, day, 23, 59, 59).toISOString();
    const { data: invoices } = await supabase.from('invoices').select(`*, invoice_items (*), extra_services (*)`).gte('created_at', start).lte('created_at', end).order('created_at', { ascending: false });
    if (invoices) calculateTotals(invoices);
    setLoading(false);
  };

  const calculateTotals = (invoices: any[]) => {
    let pSales = 0, pCost = 0, sProfit = 0, totalDisc = 0, items = 0;
    invoices.forEach(inv => {
      totalDisc += Number(inv.discount);
      inv.invoice_items.forEach((it: any) => { items += it.quantity; pSales += (it.sale_price * it.quantity); pCost += (it.cost_price * it.quantity); });
      inv.extra_services.forEach((ser: any) => { items += ser.quantity; sProfit += (ser.sale_price - ser.cost_price) * ser.quantity; });
    });
    setData({ totalSales: (pSales - totalDisc) + sProfit, totalCost: pCost, totalProfit: (pSales - pCost - totalDisc) + sProfit, itemsCount: items, discounts: totalDisc, invoices });
  };

  useEffect(() => { fetchDailyData(selectedDay); }, [selectedDay]);

  const toggleSection = (section: keyof typeof openSections) => setOpenSections(p => ({ ...p, [section]: !p[section] }));
  const daysInMonth = new Array(new Date(year, month + 1, 0).getDate()).fill(0).map((_, i) => i + 1);
  const monthName = new Date(year, month).toLocaleDateString('ar-EG', { month: 'long' });

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] p-4 sm:p-6 space-y-4 sm:space-y-6 overflow-hidden font-['Tajawal']" dir="rtl">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 shrink-0">
        <h2 className="text-xl font-black text-[#0f172a] flex items-center gap-3"><BarChart3 className="text-emerald-600" /> التقارير اليومية</h2>
        <div className="relative w-full sm:w-auto">
          <button onClick={() => setShowDayPicker(!showDayPicker)} className="w-full sm:w-auto flex items-center justify-between gap-3 bg-[#0f172a] text-white px-5 py-3 rounded-2xl shadow-lg font-black text-xs">
            <div className="flex items-center gap-2"><Calendar size={16} className="text-emerald-400" /><span>{selectedDay} {monthName}</span></div>
            <ChevronDown size={14} className={showDayPicker ? 'rotate-180' : ''} />
          </button>
          {showDayPicker && (
            <div className="absolute top-14 left-0 w-full sm:w-64 bg-white rounded-2xl shadow-2xl border border-slate-200 p-4 z-[111] grid grid-cols-7 gap-1">
              {daysInMonth.map(day => (
                <button key={day} onClick={() => { setSelectedDay(day); setShowDayPicker(false); }} className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-[10px] ${selectedDay === day ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 text-slate-600'}`}>{day}</button>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-3 sm:gap-4 shrink-0 relative">
        {!showFinancials && <div className="absolute inset-0 z-20 flex items-center justify-center bg-white/40 backdrop-blur-sm rounded-3xl"><button onClick={() => setShowFinancials(true)} className="bg-[#0f172a] text-white px-8 py-3 rounded-2xl font-black shadow-2xl flex items-center gap-2 active:scale-95 transition-all"><Eye size={20} className="text-emerald-500" /> عرض الأرقام المالية</button></div>}
        <div className={`contents transition-all duration-500 ${!showFinancials ? 'blur-md grayscale opacity-30 select-none' : ''}`}>
          {[
            { label: 'المبيعات', val: data.totalSales, icon: TrendingUp, col: 'text-emerald-600', bg: 'bg-emerald-50' },
