const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) setSettings(data);
    } catch (err) { console.error(err); }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) setConfigMissing(true);
    else fetchSettings();
  }, [fetchSettings]);

  if (configMissing) return (
    <div className="min-h-screen bg-[#0f172a] flex items-center justify-center p-6 text-white" dir="rtl">
      <div className="bg-white/5 backdrop-blur-xl p-10 rounded-[2.5rem] border border-white/10 w-full max-w-md space-y-8 text-center">
        <Database size={50} className="mx-auto text-emerald-500 mb-4" />
        <h1 className="text-3xl font-black">Flyyti POS</h1>
        <p className="text-slate-400">يرجى إعداد الاتصال بقاعدة البيانات</p>
        <form onSubmit={(e: any) => { e.preventDefault(); const url = e.target.url.value; const key = e.target.key.value; if (url && key) saveSupabaseConfig(url, key); }} className="space-y-5 text-right">
          <input name="url" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none" placeholder="Supabase URL" />
          <input name="key" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none" placeholder="Anon Key" />
          <button className="w-full py-5 bg-emerald-600 text-white font-black rounded-2xl shadow-lg">حفظ والبدء</button>
        </form>
      </div>
    </div>
  );

  if (loading) return null;

  return (
    <Routes>
      <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
      <Route path="/*" element={
        <ProtectedRoute settings={settings}>
          <Layout settings={settings}>
            <Routes>
              <Route path="/" element={<POS />} />
              <Route path="/daily-reports" element={<DailyReports />} />
              <Route path="/inventory" element={<Inventory />} />
              <Route path="/categories" element={<Categories />} />
              <Route path="/expenses" element={<Expenses settings={settings} onUpdateSettings={fetchSettings} />} />
              <Route path="/invoices" element={<Invoices settings={settings} onUpdateSettings={fetchSettings} />} />
              <Route path="/reports" element={<GeneralReports />} />
              <Route path="/security" element={<Security settings={settings} onUpdate={fetchSettings} />} />
            </Routes>
          </Layout>
        </ProtectedRoute>
      } />
    </Routes>
  );
};

