import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, Plus, Minus, Trash2, ShoppingBag, X, CheckCircle2, Loader2, PlusCircle, Barcode, Layers, Printer, AlertTriangle
} from 'lucide-react';
import { supabase } from '../supabase';
import type { Variant, Category, ExtraService } from '../types';
import { printThermalReceipt } from '../utils/printThermal';
import { playScanBeep } from '../utils/audio';

const POS: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedMainCat, setSelectedMainCat] = useState<string | null>(null);
  const [cart, setCart] = useState<any[]>([]);
  const [discount, setDiscount] = useState<number | string>(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<any>(null);
  const [stockError, setStockError] = useState<{id: string, msg: string} | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchData();
    searchInputRef.current?.focus();
  }, []);

  const fetchData = async () => {
    const { data: prods } = await supabase.from('products').select('*, variants(*)');
    const { data: cats } = await supabase.from('categories').select('*').order('name');
    setProducts(prods || []);
    setCategories(cats || []);
  };

  const addToCart = (variant: Variant, product: any) => {
    if (variant.stock_quantity <= 0) return;
    playScanBeep();
    setCart(prev => {
      const exists = prev.find(i => i.variant_id === variant.id);
      if (exists) return prev.map(i => i.variant_id === variant.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { variant_id: variant.id, product_name: product.name, variant_name: variant.name, sale_price: variant.sale_price, cost_price: variant.cost_price, quantity: 1 }];
    });
  };

  const handleFinishOrder = async () => {
    if (cart.length === 0 || isProcessing) return;
    setIsProcessing(true);
    const subtotal = cart.reduce((s, i) => s + (i.sale_price * i.quantity), 0);
    const net = Math.max(0, subtotal - Number(discount));
    const totalCost = cart.reduce((s, i) => s + (i.cost_price * i.quantity), 0);

    const { data: inv, error } = await supabase.from('invoices').insert({
      total_amount: subtotal, discount: Number(discount), net_amount: net, total_cost: totalCost, profit: net - totalCost
    }).select().single();

    if (!error) {
      await supabase.from('invoice_items').insert(cart.map(i => ({
        invoice_id: inv.id, variant_id: i.variant_id, product_name: i.product_name, quantity: i.quantity, cost_price: i.cost_price, sale_price: i.sale_price
      })));
      setLastInvoice(inv);
      setCart([]);
      setShowSuccess(true);
      fetchData();
    }
    setIsProcessing(false);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm))
  );

  return (
    <div className="flex h-full bg-[#f8fafc]" dir="rtl">
      <div className="flex-1 flex flex-col overflow-hidden">
        <div className="p-6 bg-white border-b flex gap-4 shrink-0">
          <div className="relative flex-1">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" />
            <input 
              ref={searchInputRef}
              type="text" 
              placeholder="البحث..." 
              className="w-full pr-12 pl-4 py-4 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-emerald-600 font-black"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="flex-1 p-6 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 overflow-y-auto">
          {filteredProducts.map(p => (
            <button key={p.id} onClick={() => addToCart(p.variants[0], p)} className="p-5 bg-white rounded-[2rem] border shadow-sm hover:shadow-xl transition-all text-right flex flex-col gap-2">
              <h3 className="font-black text-slate-900 line-clamp-2">{p.name}</h3>
              <p className="text-emerald-600 font-black text-lg">{Math.round(p.variants[0].sale_price)} ₪</p>
            </button>
          ))}
        </div>
      </div>

      <div className="w-96 bg-white border-r flex flex-col shrink-0">
        <div className="p-6 bg-slate-900 text-white font-black text-xl">الفاتورة</div>
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50">
          {cart.map((item, idx) => (
            <div key={idx} className="p-4 bg-white rounded-2xl border shadow-sm flex justify-between items-center">
              <div><p className="font-black text-xs">{item.product_name}</p><p className="text-emerald-600 font-black">{Math.round(item.sale_price * item.quantity)} ₪</p></div>
              <div className="flex items-center gap-2">
                <button onClick={() => setCart(cart.filter((_, i) => i !== idx))} className="text-rose-500"><Trash2 size={18} /></button>
              </div>
            </div>
          ))}
        </div>
        <div className="p-6 border-t space-y-4">
           <div className="flex justify-between font-black"><span>الصافي</span><span className="text-2xl text-emerald-600">{cart.reduce((s,i)=>s+(i.sale_price*i.quantity),0) - Number(discount)} ₪</span></div>
           <button onClick={handleFinishOrder} className="w-full py-4 bg-emerald-600 text-white font-black rounded-2xl">إتمام الفاتورة</button>
        </div>
      </div>

      {showSuccess && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[500]">
          <div className="bg-white p-10 rounded-[3rem] text-center space-y-6 animate-in zoom-in">
             <CheckCircle2 size={60} className="mx-auto text-emerald-600" />
             <h2 className="text-2xl font-black">تم إتمام البيع!</h2>
             <button onClick={() => setShowSuccess(false)} className="w-full py-4 bg-slate-900 text-white font-black rounded-2xl">متابعة</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default POS;

