// Fix for missing components
const PageAuthOverlay: React.FC<{ onVerify: () => void, correctPin: string }> = ({ onVerify, correctPin }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (pin === correctPin) {
      onVerify();
    } else {
      setError(true);
      setPin('');
      setTimeout(() => setError(false), 500);
    }
  };

  return (
    <div className="absolute inset-0 z-[200] bg-slate-900/60 backdrop-blur-xl flex items-center justify-center p-6" dir="rtl">
      <div className={`bg-white p-10 rounded-[2.5rem] shadow-2xl w-full max-w-sm text-center space-y-8 border border-white/20 transition-all ${error ? 'animate-bounce' : ''}`}>
        <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center mx-auto shadow-xl">
          <Lock className="text-emerald-500" size={32} />
        </div>
        <div className="space-y-2">
          <h2 className="text-2xl font-black text-slate-900">منطقة محمية</h2>
          <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">يرجى إدخال رمز PIN للمتابعة</p>
        </div>
        <form onSubmit={handleSubmit} className="space-y-6">
          <input 
            autoFocus
            type="password" 
            maxLength={4}
            value={pin}
            onChange={(e) => setPin(e.target.value)}
            className="w-full text-center text-4xl font-black tracking-[0.5em] p-5 bg-slate-50 border-2 border-slate-100 rounded-2xl outline-none focus:border-slate-900 focus:bg-white transition-all"
            placeholder="****"
          />
          <button type="submit" className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl shadow-xl hover:bg-black transition-all">تأكيد الدخول</button>
        </form>
      </div>
    </div>
  );
};

// Fix for missing components
const PageGuard: React.FC<{ children: React.ReactNode, pageId: string, settings: AppSettings | null }> = ({ children, pageId, settings }) => {
  const [isAuthorized, setIsAuthorized] = useState(false);
  const isLocked = settings?.protection_enabled && settings?.page_locks?.[pageId];

  if (!isLocked || isAuthorized) return <>{children}</>;

  return <PageAuthOverlay correctPin={settings?.page_password || '0000'} onVerify={() => setIsAuthorized(true)} />;
};

// Fix for missing components
const ProtectedRoute: React.FC<{ children: React.ReactNode, settings: AppSettings | null }> = ({ children, settings }) => {
  const user = localStorage.getItem('flyyti_user');
  if (settings?.login_protection_enabled && !user) {
    return <Navigate to="/login" replace />;
  }
  return <>{children}</>;
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [configMissing, setConfigMissing] = useState(false);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase.from('settings').select('*').eq('id', 1).single();
      if (!error) setSettings(data);
    } catch (err) { console.error(err); }
    setLoading(false);
  }, []);

  useEffect(() => {
    const config = getSupabaseConfig();
    if (!config.isValid) setConfigMissing(true);
    else fetchSettings();
  }, [fetchSettings]);

  if (configMissing) return (
    <div className="min-h-screen bg-[#0f172a] flex items-center justify-center p-6 text-white" dir="rtl">
      <div className="bg-white/5 backdrop-blur-xl p-10 rounded-[2.5rem] border border-white/10 w-full max-w-md space-y-8 text-center">
        <Database size={50} className="mx-auto text-emerald-500 mb-4" />
        <h1 className="text-3xl font-black">Flyyti POS</h1>
        <p className="text-slate-400">يرجى إعداد الاتصال بقاعدة البيانات</p>
        <form onSubmit={(e: any) => { e.preventDefault(); const url = e.target.url.value; const key = e.target.key.value; if (url && key) saveSupabaseConfig(url, key); }} className="space-y-5 text-right">
          <input name="url" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none" placeholder="Supabase URL" />
          <input name="key" required className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl outline-none" placeholder="Anon Key" />
          <button className="w-full py-5 bg-emerald-600 text-white font-black rounded-2xl shadow-lg">حفظ والبدء</button>
        </form>
      </div>
    </div>
  );

  if (loading) return null;

  return (
    <Routes>
      <Route path="/login" element={<Login onLoginSuccess={fetchSettings} />} />
      <Route path="/*" element={
        <ProtectedRoute settings={settings}>
          <Layout settings={settings}>
            <Routes>
              <Route path="/" element={<PageGuard pageId="pos" settings={settings}><POS /></PageGuard>} />
              <Route path="/daily-reports" element={<PageGuard pageId="daily_reports" settings={settings}><DailyReports /></PageGuard>} />
              <Route path="/inventory" element={<PageGuard pageId="inventory" settings={settings}><Inventory /></PageGuard>} />
              <Route path="/categories" element={<PageGuard pageId="categories" settings={settings}><Categories /></PageGuard>} />
              <Route path="/expenses" element={<PageGuard pageId="expenses" settings={settings}><Expenses settings={settings} onUpdateSettings={fetchSettings} /></PageGuard>} />
              <Route path="/invoices" element={<PageGuard pageId="invoices" settings={settings}><Invoices settings={settings} onUpdateSettings={fetchSettings} /></PageGuard>} />
              <Route path="/reports" element={<PageGuard pageId="reports" settings={settings}><GeneralReports /></PageGuard>} />
              <Route path="/security" element={<PageGuard pageId="security" settings={settings}><Security settings={settings} onUpdate={fetchSettings} /></PageGuard>} />
            </Routes>
          </Layout>
        </ProtectedRoute>
      } />
    </Routes>
  );
};

const Root = () => (
  <HashRouter>
    <App />
  </HashRouter>
);

export default Root;
